function __FixVss2-SetServiceState {
        param([string]$Name, [switch]$Start)
        $svc = Get-Service -Name $Name -ErrorAction SilentlyContinue
        if ($null -eq $svc) { Write-Host "  $Name : service not installed, skipped"; return }
        $wantRunning = [bool]$Start
        $isRunning = ($svc.Status -eq [System.ServiceProcess.ServiceControllerStatus]::Running)
        if ($isRunning -eq $wantRunning) {
            if ($wantRunning) { Write-Host "  $Name : already running, skipped" }
            else { Write-Host "  $Name : already stopped, skipped" }
            return
        }
        if ($Start) { & $net start $Name 2>$null } else { & $net stop $Name /y 2>$null }
        $check = Get-Service -Name $Name -ErrorAction SilentlyContinue
        $nowRunning = ($null -ne $check) -and ($check.Status -eq [System.ServiceProcess.ServiceControllerStatus]::Running)
        if ($nowRunning -eq $wantRunning) {
            if ($wantRunning) { Write-Host "  $Name : started" } else { Write-Host "  $Name : stopped" }
        } else {
            if ($wantRunning) { Write-Host "  $Name : could not start (see Service Control Manager event log)" }
            else { Write-Host "  $Name : could not stop (see Service Control Manager event log)" }
        }
    }

