function 7zit {
    $archives = Get-ChildItem -Path "F:\Downloads" -Include *.zip,*.rar,*.7z,*.tar,*.gz -File -Recurse
    if (-not $archives) { Write-Host "7zit: No archives found in F:\Downloads" -ForegroundColor Yellow; return }
    foreach ($archive in $archives) {
        $destDir = Join-Path $archive.DirectoryName $archive.BaseName
        Write-Host "Extracting: $($archive.Name) -> $destDir" -ForegroundColor Cyan
        7z x $archive.FullName "-o$destDir" -p123 -y
        if ($LASTEXITCODE -ne 0) {
            Write-Host "FAILED: $($archive.Name) (exit $LASTEXITCODE)   skipping delete" -ForegroundColor Red
        } elseif (-not (Test-Path -LiteralPath $destDir) -or (Get-ChildItem -LiteralPath $destDir -Recurse -File).Count -eq 0) {
            Write-Host "FAILED: $($archive.Name)   output folder empty or missing   skipping delete" -ForegroundColor Red
        } else {
            Write-Host "OK: $($archive.Name)" -ForegroundColor Green
        }
    }
}

function 8gg {
    param([string]$GamesPath = 'E:\games')
    $folders = Get-ChildItem -Path $GamesPath -Directory
    $sized = foreach ($f in $folders) {
        $size = (Get-ChildItem -Path $f.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        [PSCustomObject]@{ Name = $f.Name; FullName = $f.FullName; SizeBytes = if ($size) { $size } else { 0 } }
    }
    $lightest = $sized | Sort-Object SizeBytes | Select-Object -First 8
    Write-Host '=== 8 Lightest Games ===' -ForegroundColor Cyan
    foreach ($g in $lightest) {
        $gb = [math]::Round($g.SizeBytes / 1GB, 2)
        Write-Host "  $($g.Name) - $gb GB" -ForegroundColor Green
    }
    Write-Host ''
    Write-Host 'Launching 3dd menu2 for each...' -ForegroundColor Yellow
    foreach ($g in $lightest) {
        & {
    if ($args.Count -eq 0) { Write-Host "Usage: 3dd <command> [args...]" -ForegroundColor Yellow; return }
    $parts = foreach ($a in $args) { if ($a -match '\s') { "'$a'" } else { $a } }
    $cmd = $parts -join ' '
    $profilePath = $PROFILE
    $tempScript = [System.IO.Path]::GetTempFileName() + ".ps1"
    Set-Content -Path $tempScript -Value ". '$profilePath'; $cmd"
    wt new-tab powershell.exe -NoExit -ExecutionPolicy Bypass -File $tempScript
} menu2 $g.FullName
    }
}

