function Add-ProfileFunctionDependency {
        param([string]$Name)

        $normalizedName = $Name -replace '^(?i:global:)', ''
        if (-not $functionMap.ContainsKey($normalizedName)) { return }
        if (-not $visited.Add($normalizedName)) { return }

        foreach ($dependencyName in Get-ProfileFunctionDependencyNames -FunctionAst $functionMap[$normalizedName] -FunctionMap $functionMap) {
            Add-ProfileFunctionDependency -Name $dependencyName
        }

        $ordered.Add($normalizedName) | Out-Null
    }

 function Get-ProfileFunctionMutationGeneratedModulePath {
     return 'C:\Users\micha\Documents\WindowsPowerShell\Modules\CodexProfileFunctions\CodexProfileFunctions.psm1'
 }

 function Get-ProfileFunctionMutationGeneratedWrapperMatches {
     param(
         [Parameter(Mandatory)]$Document,
         [Parameter(Mandatory)][string[]]$Name
     )

     @($Document.Functions | Where-Object {
         $functionAst = $_
         $functionName = $functionAst.Name -replace '^(?i:global:)', ''
         $requestedNames = @($Name | Where-Object { $_ -ieq $functionName })
         if ($requestedNames.Count -eq 0) {
             return $false
         }
         $requestedName = $requestedNames[0]

         $escapedName = [regex]::Escape($requestedName)
         $pattern = "(?is)\bInvoke-ProfileLazyFunction\s+-Name\s+['`"]$escapedName['`"]"
         $functionAst.Body.Extent.Text -match $pattern
     } | Sort-Object { $_.Extent.StartOffset })
 }

 function Add-ProfileFunctionMutationGeneratedWrapperRemoval {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Changes,
        [Parameter(Mandatory)][string[]]$Name
    )

    $modulePath = Get-ProfileFunctionMutationGeneratedModulePath
    if (-not (Test-Path -LiteralPath $modulePath -PathType Leaf)) {
        return
    }

    $document = Get-ProfileFunctionMutationDocument -Path $modulePath
    $matches = @(Get-ProfileFunctionMutationGeneratedWrapperMatches -Document $document -Name $Name)
    if ($matches.Count -eq 0) {
        return
    }

    $updated = $document.Source
    foreach ($match in @($matches | Sort-Object { $_.Extent.StartOffset } -Descending)) {
        $updated = $updated.Remove($match.Extent.StartOffset, $match.Extent.EndOffset - $match.Extent.StartOffset)
    }
    $Changes.Add([pscustomobject]@{
        Path = $document.Path
        OriginalSource = $document.Source
        UpdatedSource = $updated
        Encoding = $document.Encoding
        Verification = [pscustomobject]@{
            PresentName = $null
            ExpectedBody = $null
            AbsentNames = $Name
        }
    }) | Out-Null
}

