function afitgirl {
    [CmdletBinding()]
    param(
        [Parameter(Position=0, ValueFromRemainingArguments=$true)]
        [string[]] $Games,
        [switch] $SavedOnly,
        [switch] $Queue,
        [switch] $Launch,
        [switch] $VerifyOnly,
        [switch] $NoScrape,
        [ValidateSet('smart','all','first')]
        [string] $Mode = 'smart',
        [int] $QueueTimeoutSeconds = 900,
        [int] $MetadataTimeoutSeconds = 8,
        [int] $MinimumActiveDownloads = 16,
        [int] $MinimumTotalSpeedMBps = 40
    )

    $ErrorActionPreference = 'Stop'
    $ps5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $ps5Profile = 'C:\Users\micha\Documents\WindowsPowerShell\Microsoft.PowerShell_profile.ps1'

    function Invoke-AfitgirlPs5Code {
& 'F:\study\Platforms\windows\functions\Invoke-AfitgirlPs5Code.ps1' @args
}

    function Invoke-AfitgirlDurableRepair {
& 'F:\study\Platforms\windows\functions\Invoke-AfitgirlDurableRepair.ps1' @args
}

    $Games = @($Games | ForEach-Object { ('' + $_).Trim() } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if (-not $Games -or $Games.Count -eq 0) {
        Write-Host 'Usage: afitgirl "GAME 1" "GAME 2" [-SavedOnly] [-Launch] [-VerifyOnly] [-NoScrape] [-Mode smart|all|first]'
        Write-Host 'This final PS5 wrapper runs bridge self-tests, max-speed policy, daemon/watchdog auto-install handoff, queue update, and post-queue repair.'
        $global:LASTEXITCODE = 2
        return
    }

    $repo = 'F:\study\Windows\Applications\Gaming\Launchers\FitLauncher\Automation\fit-download-list-terminal'
    $script = Join-Path $repo 'tools\fit_download_list.py'
    $db = Join-Path $env:APPDATA 'com.fitlauncher.carrotrub\sitemaps\search.db'
    $downloadList = Join-Path $env:APPDATA 'com.fitlauncher.carrotrub\library\collections\games_to_download.json'
    $fitLauncher = 'F:\backup\windowsapps\installed\Fit Launcher\Fit Launcher.exe'
    foreach ($required in @($repo,$script,$db,$fitLauncher)) {
        if (-not (Test-Path -LiteralPath $required)) { throw "Missing required Fit Launcher path: $required" }
    }
    if (-not (Test-Path -LiteralPath $downloadList -PathType Leaf)) {
        $dlDir = Split-Path -Parent $downloadList
        if (-not (Test-Path -LiteralPath $dlDir -PathType Container)) { New-Item -ItemType Directory -Force -Path $dlDir | Out-Null }
        Set-Content -LiteralPath $downloadList -Encoding UTF8 -Force -Value '[]'
    }
    $py = Get-Command py.exe -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $py) { throw 'py.exe was not found. Install/repair Windows Python launcher first.' }

    Write-Host '[afitgirl] immediate queue first: launching Fit Launcher if needed, arming auto-install first, then handing requested games to Fit Launcher.'
    try {
        $fitLauncherProc = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { ('' + $_.Name) -ieq 'Fit Launcher.exe' })
        if ($fitLauncherProc.Count -eq 0) {
            Start-Process -FilePath $fitLauncher -WindowStyle Minimized | Out-Null
            Write-Host ("[afitgirl] Fit Launcher started before queue: {0}" -f $fitLauncher)
            Start-Sleep -Seconds 3
        } else {
            Write-Host ("[afitgirl] Fit Launcher already running before queue pid={0}" -f (($fitLauncherProc | Select-Object -First 1).ProcessId))
        }
    } catch {
        throw ("Fit Launcher launch/check failed before queue: {0}" -f $_.Exception.Message)
    }
    try { Start-AfitgirlInstallerAutoClicker -LifetimeMinutes 720 | Out-Null; Write-Host '[afitgirl] installer auto-clicker/rescue armed for 720 minutes' } catch { Write-Host ("[afitgirl] installer offline-rescue warning: {0}" -f $_.Exception.Message) }
    Invoke-AfitgirlDurableRepair -Phase 'before queue'

    $runtimeScript = Join-Path $env:TEMP ('afitgirl_fit_download_list_runtime_' + [guid]::NewGuid().ToString('N') + '.py')
    try {
        $src = Get-Content -LiteralPath $script -Raw
        $src = $src.Replace('path.open("r", encoding="utf-8")', 'path.open("r", encoding="utf-8-sig")')
        $src = $src.Replace('if normalize_title(title) == "pathfinder kingmaker":', 'if False and normalize_title(title) == "pathfinder kingmaker":')
        if ($src -match 'SKIPPED_LEGACY_MAGNET') { Write-Host '[afitgirl] runtime patch: disabled stale Pathfinder legacy skip so real manager queue is attempted.' }
        Set-Content -LiteralPath $runtimeScript -Value $src -Encoding UTF8 -Force
        $script = $runtimeScript

        $oldEncoding = $env:PYTHONIOENCODING
        $oldUtf8 = $env:PYTHONUTF8
        $oldPreflightGames = $env:AFITGIRL_PREFLIGHT_GAMES
        try {
            $env:PYTHONIOENCODING = 'utf-8'
            $env:PYTHONUTF8 = '1'
            $env:AFITGIRL_PREFLIGHT_GAMES = (ConvertTo-Json -InputObject @($Games) -Compress)
            $preflightCode = @'
import json, os, sys
sys.path.insert(0, r"F:\study\Windows\Applications\Gaming\Launchers\FitLauncher\Automation\fit-download-list-terminal\tools")
import fit_download_list as f
queries = json.loads(os.environ.get("AFITGIRL_PREFLIGHT_GAMES", "[]"))
available = []
for q in queries:
    matches = f.search_games(f.DEFAULT_DB, q, mode="smart")
    if matches:
        available.append(q)
        print("[afitgirl] available: {0} -> {1}".format(q, "; ".join(str(g.get("title", "")) for g in matches)))
    else:
        print("[afitgirl] unavailable: {0}".format(q))
print("AFITGIRL_AVAILABLE_JSON=" + json.dumps(available, ensure_ascii=False))
'@
            $preflightFile = Join-Path $env:TEMP ('afitgirl_preflight_' + [guid]::NewGuid().ToString('N') + '.py')
            try {
                Set-Content -LiteralPath $preflightFile -Value $preflightCode -Encoding UTF8 -Force
                $preflightOutput = @(& $py.Source -3 $preflightFile)
            } finally {
                Remove-Item -LiteralPath $preflightFile -Force -ErrorAction SilentlyContinue
            }
            $preflightOutput | Where-Object { $_ -notlike 'AFITGIRL_AVAILABLE_JSON=*' } | ForEach-Object { Write-Host $_ }
            $jsonLine = @($preflightOutput | Where-Object { $_ -like 'AFITGIRL_AVAILABLE_JSON=*' } | Select-Object -Last 1)
            if (-not $jsonLine -or $LASTEXITCODE -ne 0) { throw 'Local catalog preflight failed before the Fit Launcher handoff.' }
            $availableGames = @((($jsonLine -replace '^AFITGIRL_AVAILABLE_JSON=','') | ConvertFrom-Json))
            if (-not $availableGames -or $availableGames.Count -eq 0) {
                Write-Host '[afitgirl] no requested titles are available in the local Fit Launcher catalog; nothing to queue.'
                $global:LASTEXITCODE = 0
                return
            }
            $Games = @($availableGames | ForEach-Object { '' + $_ })
        } finally {
            if ($null -eq $oldEncoding) { Remove-Item Env:\PYTHONIOENCODING -ErrorAction SilentlyContinue } else { $env:PYTHONIOENCODING = $oldEncoding }
            if ($null -eq $oldUtf8) { Remove-Item Env:\PYTHONUTF8 -ErrorAction SilentlyContinue } else { $env:PYTHONUTF8 = $oldUtf8 }
            if ($null -eq $oldPreflightGames) { Remove-Item Env:\AFITGIRL_PREFLIGHT_GAMES -ErrorAction SilentlyContinue } else { $env:AFITGIRL_PREFLIGHT_GAMES = $oldPreflightGames }
        }

        $cli = @('-3', $script, '--db', $db, '--download-list', $downloadList, '--fit-launcher', $fitLauncher, '--mode', $Mode, '--metadata-timeout-ms', ([string]([Math]::Max(1000, $MetadataTimeoutSeconds * 1000))))
        if ($VerifyOnly) { $cli += '--verify-only' }
        if ($NoScrape) { $cli += '--no-scrape' }
        if ($SavedOnly) { $cli += '--no-queue' }
        if ($Launch) { $cli += '--launch' }
        $line = (($Games | ForEach-Object { '"' + (($_ -replace '"','\"')) + '"' }) -join ' ')
        $cli += @('--line', $line)

        Write-Host ("[afitgirl] Games: {0}" -f (($Games | ForEach-Object { '"' + $_ + '"' }) -join ' '))
        Write-Host ("[afitgirl] Mode={0}; Queue={1}; SavedOnly={2}; Launch={3}; VerifyOnly={4}; NoScrape={5}; ActiveSlots={6}; SpeedTarget={7}MB/s" -f $Mode,(-not [bool]$SavedOnly),([bool]$SavedOnly),([bool]$Launch),([bool]$VerifyOnly),([bool]$NoScrape),$MinimumActiveDownloads,$MinimumTotalSpeedMBps)

        $oldQueueEncoding = $env:PYTHONIOENCODING
        $oldQueueUtf8 = $env:PYTHONUTF8
        Push-Location -LiteralPath $repo
        try {
            $env:PYTHONIOENCODING = 'utf-8'
            $env:PYTHONUTF8 = '1'
            $code = Invoke-AfitgirlPythonProcess -FilePath $py.Source -Arguments $cli -WorkingDirectory $repo -TimeoutSeconds $QueueTimeoutSeconds
        } finally {
            if ($null -eq $oldQueueEncoding) { Remove-Item Env:\PYTHONIOENCODING -ErrorAction SilentlyContinue } else { $env:PYTHONIOENCODING = $oldQueueEncoding }
            if ($null -eq $oldQueueUtf8) { Remove-Item Env:\PYTHONUTF8 -ErrorAction SilentlyContinue } else { $env:PYTHONUTF8 = $oldQueueUtf8 }
            Pop-Location
        }

        if ($VerifyOnly) {
            if ($code -ne 0) { Write-Host ("[afitgirl] verify-only search returned exit code {0}; no live download queue was requested." -f $code) }
            else { Write-Host '[afitgirl] verify-only search completed; no live download queue was requested.' }
            $global:LASTEXITCODE = 0
            return
        }

        Write-Host '[afitgirl] post-queue: forcing visible Downloads refresh before heavyweight repair continues'
        try { Invoke-AfitgirlVisibleDownloadsRepair -Reason 'afitgirl immediate post-queue' } catch { Write-Host ("[afitgirl] visible repair warning: {0}" -f $_.Exception.Message) }
        Write-Host '[afitgirl] post-queue: reapplying max-speed, anti-freeze, visible Downloads repair, and completion auto-install handoff'
        Invoke-AfitgirlDurableRepair -Phase 'after queue'
        try { Invoke-AfitgirlVisibleDownloadsRepair -Reason 'afitgirl final post-queue' } catch { Write-Host ("[afitgirl] final visible repair warning: {0}" -f $_.Exception.Message) }
        if ($code -ne 0) {
            $queuedEvidence = $false
            try {
                $savedRecords = @(Get-Content -LiteralPath $downloadList -Raw | ConvertFrom-Json)
                $missingSaved = @()
                foreach ($g in @($Games)) {
                    $needle = ('' + $g).Trim()
                    if ($needle -and -not @($savedRecords | Where-Object { ('' + $_.title) -like ('*' + $needle + '*') }).Count) { $missingSaved += $needle }
                }
                if ($missingSaved.Count -eq 0) {
                    $queuedEvidence = $true
                    Write-Host ("[afitgirl] queue command returned code {0}, but all requested games are present in Fit Launcher saved-download collection." -f $code)
                }
            } catch {
                Write-Host ("[afitgirl] saved-download evidence check warning: {0}" -f $_.Exception.Message)
            }
            try {
                $policy = Invoke-AfitgirlDownloadPolicy -MinimumActive $MinimumActiveDownloads -MinimumTotalSpeedMBps $MinimumTotalSpeedMBps
                if ($policy -and (([int]$policy.Active -gt 0) -or ([int]$policy.Waiting -gt 0) -or ([double]$policy.TotalSpeedMBps -gt 0))) {
                    $queuedEvidence = $true
                    Write-Host ("[afitgirl] queue command returned code {0}, but live Downloads evidence exists: active={1}; waiting={2}; speed={3} MB/s. Treating as queued success." -f $code,$policy.Active,$policy.Waiting,$policy.TotalSpeedMBps)
                }
            } catch {
                Write-Host ("[afitgirl] post-queue evidence check warning: {0}" -f $_.Exception.Message)
            }
            if (-not $queuedEvidence) { throw "fit_download_list.py failed with exit code $code" }
        }
        Write-Host '[afitgirl] OK: available requested games were queued/saved; 16-active unlimited aria2 policy, anti-stall monitor, daemon, completion hook, and auto-install watchdog are active.'
        $global:LASTEXITCODE = 0
    } finally {
        Remove-Item -LiteralPath $runtimeScript -Force -ErrorAction SilentlyContinue
    }
}

function ahk2ps {
    param([string]$ahkPath)
    if (-not (Test-Path $ahkPath)) {
        Write-Host "? AHK file does not exist: $ahkPath" -ForegroundColor Red
        return
    }
    $ps1Path = [System.IO.Path]::ChangeExtension($ahkPath, ".ps1")
    $ahkContent = Get-Content $ahkPath | Where-Object { $_ -match '^Run,' }
    if (-not $ahkContent) {
        Write-Host "? No 'Run,' line found in the AHK file." -ForegroundColor Red
        return
    }
    $commandLine = $ahkContent -replace '^Run,\s*', ''
    $commandLine = $commandLine -replace '`"', '"'  # Unescape quotes if present
    $ps1Content = "Start-Process $commandLine"
    $ps1Content | Out-File -FilePath $ps1Path -Encoding UTF8
