function ass {
[CmdletBinding()]
    param(
        [switch]$SelfTest,
        [Parameter(ValueFromRemainingArguments = $true)][object[]]$RemainingArgs
    )

    $exe = @(
        'F:\study\projects\SystemMonitor\PSProcLasso\Windows\Applications\Gaming\SaveData\AssLatestGameBackup\dist\AssLatestGameBackup.exe',
        (Join-Path ([Environment]::GetFolderPath([Environment+SpecialFolder]::MyDocuments)) 'WindowsPowerShell\legacy-safe-functions\AssLatestGameBackup\AssLatestGameBackup.exe')
    ) | Where-Object {[IO.File]::Exists($_)} | Select-Object -First 1
    if (-not $exe) {
        if ($SelfTest) {
            throw "ass executable not found: $exe"
        }
        Write-Warning "ASS_SKIPPED reason=executable_missing path=$exe"
        return
    }

    if ($SelfTest) {
        $item = Get-Item -LiteralPath $exe -ErrorAction Stop
        & $exe --self-test
        $selfTestExitCode = [int]$LASTEXITCODE
        if ($selfTestExitCode -ne 0) {
            throw "ass detector self-test failed with exit code $selfTestExitCode"
        }
        Write-Output ("ASS_SELFTEST_OK exe={0} bytes={1} detectorSelfTest=passed" -f $exe, $item.Length)
        return
    }

    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        Write-Host ("ASS_WRAPPER_PROGRESS stage=starting exe={0}" -f $exe) -ForegroundColor Cyan
        & $exe @RemainingArgs
        $exitCode = [int]$LASTEXITCODE
        if ($exitCode -ne 0) {
            throw "ass backup failed with exit code $exitCode"
        }
        $watch.Stop()
        $global:LASTEXITCODE = 0
        Write-Host ("ASS_WRAPPER_OK elapsed_ms={0}" -f $watch.ElapsedMilliseconds) -ForegroundColor Green
    } catch {
        $watch.Stop()
        $global:LASTEXITCODE = 1
        Write-Host ("ASS_WRAPPER_FAILED elapsed_ms={0} message=[{1}]" -f $watch.ElapsedMilliseconds, $_.Exception.Message) -ForegroundColor Red
        throw
    }
}

function Assert-BackupfNotReparse {
        param(
            [Parameter(Mandatory)][string]$Path,
            [Parameter(Mandatory)][string]$Description
        )
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        if (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) {
            Throw-BackupfFailure ("{0} is a reparse point: {1}" -f $Description, $Path)
        }
        return $item
    }

function Assert-ProfileFunctionMutationCommittedChanges {
    param([Parameter(Mandatory)][object[]]$Changes)
    foreach ($change in $Changes) {
        if ($null -eq $change.Verification) { continue }
        Write-ProfileFunctionMutationProgress -Stage 'verifying-profile' -Detail $change.Path
        $document = Get-ProfileFunctionMutationDocument -Path $change.Path
        foreach ($name in @($change.Verification.AbsentNames)) {
            if (Get-ProfileFunctionMutationMatch -Document $document -Name $name) {
                throw "Saved profile '$($change.Path)' still contains removed function '$name'."
            }
        }
        if (-not [string]::IsNullOrWhiteSpace($change.Verification.PresentName)) {
            $savedFunctions = @(Get-ProfileFunctionMutationMatches -Document $document -Name $change.Verification.PresentName)
            if ($savedFunctions.Count -ne 1) {
                throw "Saved profile '$($change.Path)' has $($savedFunctions.Count) definitions for '$($change.Verification.PresentName)' after mutation."
            }
            $savedFunction = $savedFunctions[0]
            if (-not $savedFunction) {
                throw "Saved profile '$($change.Path)' does not contain function '$($change.Verification.PresentName)' after mutation."
            }
            $actualBody = ConvertTo-ProfileFunctionMutationNormalizedBody -BodyText $savedFunction.Body.Extent.Text
            $expectedBody = ConvertTo-ProfileFunctionMutationNormalizedBody -BodyText $change.Verification.ExpectedBody
            if ($actualBody -cne $expectedBody) {
                throw "Saved profile '$($change.Path)' did not retain the requested body for '$($change.Verification.PresentName)'."
            }
        }
    }
}

function Assert-ProfileFunctionMutationName {
    param([Parameter(Mandatory)][string]$Name)
    $normalized = $Name.Trim() -replace '^(?i:global:)', ''
    if ($normalized -notmatch '^[A-Za-z0-9_][A-Za-z0-9_.-]*$') {
        throw "Invalid function name '$Name'. Use letters, digits, underscores, dots, or hyphens, beginning with a letter, underscore, or digit."
    }
    $normalized
}

function Assert-ZapfTarget {
    param([Parameter(Mandatory = $true)][string]$ExtendedTarget)

    $actualTarget = [System.IO.Path]::GetFullPath($target).TrimEnd('\')
    if (
        $actualTarget -cne $expectedTarget -or
        -not $actualTarget.StartsWith('C:\', [System.StringComparison]::OrdinalIgnoreCase) -or
        $actualTarget -ieq 'C:'
    ) {
        throw 'ZAPF_FAILURE: refusing a target other than the literal C:\fdrive.'
    }
    if (-not [System.IO.Directory]::Exists($ExtendedTarget)) {
        throw 'ZAPF_FAILURE: C:\fdrive does not exist; nothing was deleted.'
    }

    $attributes = Get-ZapfAttributes -Path $ExtendedTarget
    if (Test-ZapfReparsePoint -Attributes $attributes) {
        throw 'ZAPF_FAILURE: refusing to delete C:\fdrive because it is a reparse point.'
    }
}

function Assert-ZapfTreeSafe {
    param([Parameter(Mandatory = $true)][string]$ExtendedTarget)

    $pending = New-Object 'System.Collections.Generic.Stack[string]'
    $pending.Push($ExtendedTarget)
    while ($pending.Count -gt 0) {
        $directory = $pending.Pop()
        try {
            $directoryAttributes = Get-ZapfAttributes -Path $directory
            if (Test-ZapfReparsePoint -Attributes $directoryAttributes) {
                [void]$reparsePoints.Add((ConvertFrom-ZapfExtendedPath $directory))
                continue
            }

            foreach ($entry in [System.IO.Directory]::EnumerateFileSystemEntries($directory)) {
                try {
                    $attributes = Get-ZapfAttributes -Path $entry
                    if (Test-ZapfReparsePoint -Attributes $attributes) {
                        [void]$reparsePoints.Add((ConvertFrom-ZapfExtendedPath $entry))
                        continue
                    }
                    if (($attributes -band [System.IO.FileAttributes]::Directory) -ne 0) {
                        $pending.Push($entry)
                    }
                } catch {
                    Add-ZapfFailure -Path $entry -Operation 'PreflightAttributes' -Exception $_.Exception
                }
            }
        } catch {
            Add-ZapfFailure -Path $directory -Operation 'PreflightEnumeration' -Exception $_.Exception
        }
    }

    if ($reparsePoints.Count -gt 0) {
        $paths = @($reparsePoints | Select-Object -Unique) -join [Environment]::NewLine
        throw ("ZAPF_FAILURE: refusing to traverse reparse points under C:\fdrive. Preserved paths:{0}{1}" -f
            [Environment]::NewLine,
            $paths)
    }
    if ($failures.Count -gt 0) {
        $summary = @(
            $failures | ForEach-Object {
                "Preflight $($_.Operation) [$($_.NativeError)] $($_.Path): $($_.Message)"
            }
        ) -join [Environment]::NewLine
        throw ("ZAPF_FAILURE: preflight could not safely inspect C:\fdrive.{0}{1}" -f
            [Environment]::NewLine,
            $summary)
    }
}

function audio {
    Import-Module AudioDeviceCmdlets -Force
    $desiredDevice = Get-AudioDevice -Playback | Where-Object { $_.Name -like '*Realtek*' } | Select-Object -First 1
    if ($desiredDevice) {
        try {
            Set-AudioDevice -Id $desiredDevice.Id
            Write-Host "Switched audio output to: $($desiredDevice.Name)" -ForegroundColor Green
        }
        catch {
            Write-Host "Failed to set audio device. Error: $_" -ForegroundColor Red
        }
    }
    else {
        Write-Host "Could not find a playback device containing 'Realtek' in its name." -ForegroundColor Yellow
        Write-Host "Available playback devices:" -ForegroundColor Cyan
        try {
            Get-AudioDevice -Playback | ForEach-Object { Write-Output " - $($_.Name)" }
        }
        catch {
            Write-Host "Failed to retrieve playback devices. Error: $_" -ForegroundColor Red
        }
    }
}

