function be {
[CmdletBinding()]param()
if ($global:_BeWorkflowActive) { return }
$global:_BeWorkflowActive = $true
try {
function Get-BeFunctionDefinitionMap {
    param(
        [Parameter(Mandatory)][string]$Path
    )
    $definitions = @{}
    if (-not (Test-Path -LiteralPath $Path)) { return $definitions }
    $item = Microsoft.PowerShell.Management\Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if ($item.PSIsContainer) {
        $rootPath = [IO.Path]::GetFullPath($item.FullName).TrimEnd('\')
        $files = @(Microsoft.PowerShell.Management\Get-ChildItem -LiteralPath $rootPath -Filter '*.ps1' -File -Recurse -ErrorAction Stop | Sort-Object FullName)
    } else {
        $rootPath = [IO.Path]::GetDirectoryName($item.FullName)
        $files = @($item)
    }
    foreach ($file in $files) {
        $tokens = $null; $parseErrors = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile($file.FullName, [ref]$tokens, [ref]$parseErrors)
        $syntaxErrors = @($parseErrors | Where-Object { $_.ErrorId -ne 'ModuleNotFoundDuringParse' })
        if ($syntaxErrors.Count -gt 0) { throw "BE: cannot count functions because '$($file.FullName)' does not parse: $($syntaxErrors[0].Message)" }
        $relativePath = if ($item.PSIsContainer) { $file.FullName.Substring($rootPath.Length).TrimStart('\') } else { $file.Name }
        $relativePath = $relativePath.ToLowerInvariant()
        foreach ($definition in @($ast.EndBlock.Statements | Where-Object { $_ -is [System.Management.Automation.Language.FunctionDefinitionAst] })) {
            $name = $definition.Name -replace '^(?i:(?:global|script|local|private):)+', ''
            $definitionText = (($definition.Extent.Text.Trim() -replace "`r`n", "`n") -replace "`r", "`n")
            $part = "$relativePath`n$definitionText"
            if ($definitions.ContainsKey($name)) { $definitions[$name] = @($definitions[$name]) + $part } else { $definitions[$name] = @($part) }
        }
    }
    foreach ($name in @($definitions.Keys)) { $definitions[$name] = @($definitions[$name] | Sort-Object) -join "`n`0`n" }
    return $definitions
}
function Get-BeSourceFingerprint {
    param([Parameter(Mandatory)][string[]]$Path)
    $entries = New-Object System.Collections.Generic.List[string]
    $fileHasher = [Security.Cryptography.SHA256]::Create()
    try {
        foreach ($entry in $Path) {
            if (-not (Test-Path -LiteralPath $entry)) {
                $entries.Add(("missing|{0}" -f $entry.ToLowerInvariant()))
                continue
            }
            $item = Microsoft.PowerShell.Management\Get-Item -LiteralPath $entry -Force -ErrorAction Stop
            $files = if ($item.PSIsContainer) {
                @(Microsoft.PowerShell.Management\Get-ChildItem -LiteralPath $item.FullName -Filter '*.ps1' -File -Recurse -ErrorAction Stop | Sort-Object FullName)
            } else {
                @($item)
            }
            foreach ($file in $files) {
                $stream = [IO.File]::OpenRead($file.FullName)
                try { $hash = [BitConverter]::ToString($fileHasher.ComputeHash($stream)) -replace '-', '' }
                finally { $stream.Dispose() }
                $entries.Add(("{0}|{1}|{2}" -f $file.FullName.ToLowerInvariant(), $file.Length, $hash))
            }
        }
    } finally {
        $fileHasher.Dispose()
    }
    $combinedHasher = [Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [Text.Encoding]::UTF8.GetBytes(($entries -join "`n"))
        return ([BitConverter]::ToString($combinedHasher.ComputeHash($bytes)) -replace '-', '')
    } finally {
        $combinedHasher.Dispose()
    }
}
# ---- count functions changed since the previous be run (before any step can alter state) ----
$countPaths = @(
    'C:\Users\micha\Documents\WindowsPowerShell\Microsoft.PowerShell_profile.ps1',
    'C:\Users\micha\Documents\PowerShell\Microsoft.PowerShell_profile.ps1',
    'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\Microsoft.PowerShell_profile.runtime.ps1',
    'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\Microsoft.PowerShell_profile.full.ps1',
    'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\Microsoft.PowerShell_profile.full.definitions.ps1',
    'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\Microsoft.PowerShell_profile.ps1',
    'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\legacy-safe-functions',
    'C:\Users\micha\Documents\WindowsPowerShell\Modules\CodexProfileFunctions\CodexProfileFunctions.psm1'
)
# The backup child owns the authoritative source fingerprint and function
# comparison. Repeating both here made be hash ~20 MB and sometimes parse every
# saved definition before it printed any progress.
$functionsChanged = 0

# ---- the four steps, in the user's exact order ----
Write-Host 'BE: [1/4] Reloading current profile (verified fast cache)...' -ForegroundColor Cyan
$fastProfileStart = 'C:\Users\micha\AppData\Local\Codex\PowerShellFastStartup\Start-FastProfile.ps1'
if (Test-Path -LiteralPath $fastProfileStart -PathType Leaf) {
    . $fastProfileStart
}
else {
    . $profile
}
Write-Host 'BE: [2/4] Backing up profile files (latest functions)...' -ForegroundColor Cyan
$backupScript = 'F:\backup\windowsapps\profile\profile.ps1'
if (-not (Test-Path -LiteralPath $backupScript -PathType Leaf)) { throw "BE: profile backup script is missing: $backupScript" }
$profileBackupHost = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
$previousProfileProgress = $env:PROFILE_PROGRESS
$profileProgressExisted = Test-Path Env:\PROFILE_PROGRESS
$backupResultLine = $null
try {
    $env:PROFILE_PROGRESS = '1'
    & $profileBackupHost -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $backupScript 2>&1 | ForEach-Object {
        $backupLine = [string]$_
        if ($backupLine -match '^PROFILE_BACKUP_OK\b') {
            $backupResultLine = $backupLine
        }
        elseif ($backupLine -match '^PROFILE_BACKUP_') {
            # The backup already emits readable live progress; hide its duplicate
            # machine receipt rows from normal interactive output.
        }
        elseif (-not [string]::IsNullOrWhiteSpace($backupLine)) {
            Write-Host $backupLine
        }
    }
    $backupExitCode = $LASTEXITCODE
    if ($backupExitCode -ne 0) { throw "profile backup child exit code: $backupExitCode" }
    if ([string]::IsNullOrWhiteSpace($backupResultLine)) { throw 'profile backup did not report a completion receipt' }
    if ($backupResultLine -match '(?:^|\s)changed_functions=(\d+)(?:\s|$)') {
        $functionsChanged = [int]$Matches[1]
    }
    else {
        throw "profile backup receipt is missing changed_functions: $backupResultLine"
    }
} catch { throw "BE: profile backup failed: $($_.Exception.Message)" }
finally {
    if ($profileProgressExisted) { $env:PROFILE_PROGRESS = $previousProfileProgress }
    else { Microsoft.PowerShell.Management\Remove-Item Env:\PROFILE_PROGRESS -ErrorAction SilentlyContinue }
}
Write-Host 'BE: [3/4] Syncing PowerShell 7 profile (ps527)...' -ForegroundColor Cyan
$ps527Command = Get-Command ps527 -CommandType Function -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $ps527Command) { throw 'BE: ps527 function is unavailable after profile reload.' }
& $ps527Command
Write-Host 'BE: [4/4] Done.' -ForegroundColor Cyan

Write-Output "BE_OK functions_changed=$functionsChanged"
} finally {
    $global:_BeWorkflowActive = $false
}
}

