function before {
[CmdletBinding()]
    param(
        [switch]$Full,
        [switch]$Quick,
        [switch]$WrapperSelfTest
    )

    if ($Full -and $Quick) {
        throw 'before: use either -Full or -Quick, not both.'
    }

    $profileBackupScript = 'F:\backup\windowsapps\profile\profile.ps1'
    $getServicingState = {
        $pending = New-Object System.Collections.Generic.List[string]
        if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { $pending.Add('CBS RebootPending') }
        if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { $pending.Add('Windows Update RebootRequired') }
        $sessionManager = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -ErrorAction SilentlyContinue
        if ($sessionManager -and ($sessionManager.PSObject.Properties.Name -contains 'PendingFileRenameOperations') -and $sessionManager.PendingFileRenameOperations) {
            $pending.Add('PendingFileRenameOperations')
        }
        $active = @(Get-Process TiWorker,TrustedInstaller,MoUsoCoreWorker,msiexec,dism,sfc -ErrorAction SilentlyContinue | Select-Object -ExpandProperty ProcessName -Unique)
        [pscustomobject]@{
            Pending = @($pending)
            ActiveServicing = @($active)
        }
    }

    if ($WrapperSelfTest) {
        if (-not (Test-Path -LiteralPath $profileBackupScript -PathType Leaf)) {
            throw "before: profile backup script is missing: $profileBackupScript"
        }
        $tokens = $null
        $errors = $null
        [void][System.Management.Automation.Language.Parser]::ParseFile($profileBackupScript, [ref]$tokens, [ref]$errors)
        if (@($errors).Count -gt 0) {
            throw "before: profile backup parser error: $($errors[0].Message)"
        }
        backcod -SelfTest
        ass -SelfTest
        fff -SelfTest
        Write-Output 'BEFORE_SELFTEST_OK defaultMode=full explicitStatusMode=-Quick steps=4'
        return
    }

    $preflight = & $getServicingState
    if ($Quick) {
        Write-Output ("BEFORE_QUICK_OK pending=[{0}] activeServicing=[{1}] fullWorkflowSkipped=true reason=explicit-Quick" -f ($preflight.Pending -join '; '), ($preflight.ActiveServicing -join '; '))
        $global:LASTEXITCODE = 0
        return
    }

    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw 'before requires an elevated Windows PowerShell 5.1 session for its DISM and SFC repair stage.'
    }

    $steps = @(
        [pscustomobject]@{ Name = 'Profile backup'; Action = { if (Test-Path -LiteralPath $profileBackupScript -PathType Leaf) { $backupHost = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'; & $backupHost -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $profileBackupScript; if ($LASTEXITCODE -ne 0) { throw "before: profile backup child exit code: $LASTEXITCODE" } } else { Write-Warning "before: profile backup script not found, skipping: $profileBackupScript" } } },
        [pscustomobject]@{ Name = 'Codex backup'; Action = { backcod } },
        [pscustomobject]@{ Name = 'Latest game backup'; Action = { ass } },
        [pscustomobject]@{ Name = 'DISM and SFC repair'; Action = { fff } }
    )

    $overall = [System.Diagnostics.Stopwatch]::StartNew()
    $currentStepName = 'preflight'
    $currentStepNumber = 0
    try {
        Write-Host ("BEFORE_PROGRESS stage=preflight pending=[{0}] activeServicing=[{1}] mode=full" -f ($preflight.Pending -join '; '), ($preflight.ActiveServicing -join '; ')) -ForegroundColor Cyan
        for ($index = 0; $index -lt $steps.Count; $index++) {
            $step = $steps[$index]
            $currentStepName = $step.Name
            $currentStepNumber = $index + 1
            $stepWatch = [System.Diagnostics.Stopwatch]::StartNew()
            Write-Host ("BEFORE_PROGRESS stage=starting step={0}/{1} name=[{2}] elapsed_ms={3}" -f $currentStepNumber, $steps.Count, $step.Name, $overall.ElapsedMilliseconds) -ForegroundColor Cyan
            & $step.Action
            if (-not $?) { throw "before: $($step.Name) reported failure." }
            $stepWatch.Stop()
            Write-Host ("BEFORE_PROGRESS stage=completed step={0}/{1} name=[{2}] step_elapsed_ms={3} total_elapsed_ms={4}" -f $currentStepNumber, $steps.Count, $step.Name, $stepWatch.ElapsedMilliseconds, $overall.ElapsedMilliseconds) -ForegroundColor Green
        }

        $postflight = & $getServicingState
        $overall.Stop()
        $global:LASTEXITCODE = 0
        Write-Host ("BEFORE_OK steps={0} elapsed_ms={1} pending=[{2}] activeServicing=[{3}]" -f $steps.Count, $overall.ElapsedMilliseconds, ($postflight.Pending -join '; '), ($postflight.ActiveServicing -join '; ')) -ForegroundColor Green
    } catch {
        $overall.Stop()
        $global:LASTEXITCODE = 1
        Write-Host ("BEFORE_FAILED step={0}/{1} name=[{2}] elapsed_ms={3} message=[{4}]" -f $currentStepNumber, $steps.Count, $currentStepName, $overall.ElapsedMilliseconds, $_.Exception.Message) -ForegroundColor Red
        throw
    }
}

function beforere {
    [CmdletBinding()]
    param(
        [int]$IdleSeconds = 60,
        [int]$HeartbeatSeconds = 5,
        [int]$HardTimeoutMinutes = 240,
        [switch]$Full,
        [switch]$WrapperSelfTest,
        [switch]$WatchdogSelfTest,
        [Parameter(ValueFromRemainingArguments = $true)]
        [string[]]$ScriptArguments
    )

    $scriptPath = 'F:\study\Platforms\windows\system-administration\scripts\powershell\repair\boot\win11\WindowsRebootSafetyGate\a.ps1'
    if (-not (Test-Path -LiteralPath $scriptPath -PathType Leaf)) { throw "beforere target script not found: $scriptPath" }
    if ($HeartbeatSeconds -lt 1) { $HeartbeatSeconds = 1 }
    if ($WatchdogSelfTest) { if ($IdleSeconds -lt 2) { $IdleSeconds = 2 } } else { if ($IdleSeconds -lt 30) { $IdleSeconds = 30 } }
    if ($HardTimeoutMinutes -lt 1) { $HardTimeoutMinutes = 1 }
    if ($WrapperSelfTest) {
        Write-Output "beforere wrapper OK: quick non-mutating status is default; -Full enables the deep repair gate with watchdog and hard timeout. target=$scriptPath"
        return
    }

    if (-not $Full -and -not $WatchdogSelfTest) {
        $pending = New-Object System.Collections.Generic.List[string]
        if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { $pending.Add('CBS RebootPending') }
        if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { $pending.Add('Windows Update RebootRequired') }
        $sessionManager = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -ErrorAction SilentlyContinue
        if ($sessionManager -and ($sessionManager.PSObject.Properties.Name -contains 'PendingFileRenameOperations') -and $sessionManager.PendingFileRenameOperations) {
            $pending.Add('PendingFileRenameOperations')
        }
        $active = @(Get-Process TiWorker,TrustedInstaller,MoUsoCoreWorker,msiexec,dism,sfc -ErrorAction SilentlyContinue | Select-Object -ExpandProperty ProcessName -Unique)
        Write-Output ("BEFORERE_QUICK_OK pending=[{0}] activeServicing=[{1}] deepRepairSkipped=true" -f ($pending -join '; '),($active -join '; '))
        $global:LASTEXITCODE = 0
        return 0
    }

    function Quote-BeforeReArg([string]$Value) {
        if ($null -eq $Value) { return '\"\"' }
        if ($Value -match '^[A-Za-z0-9_./:\\=-]+$') { return $Value }
        return '\"' + ($Value -replace '\"','\\\"') + '\"'
    }
    function Read-BeforeReNewLogText {
        param([string]$Path, [ref]$Offset, [switch]$IsError)
        if (-not (Test-Path -LiteralPath $Path)) { return $false }
        $fs = $null
        try {
            $fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            if ($fs.Length -le $Offset.Value) { return $false }
            [void]$fs.Seek([int64]$Offset.Value, [System.IO.SeekOrigin]::Begin)
            $count = [int]($fs.Length - $Offset.Value)
            $bytes = New-Object byte[] $count
            [void]$fs.Read($bytes, 0, $count)
            $Offset.Value = $fs.Length
            $text = [System.Text.Encoding]::UTF8.GetString($bytes)
            if ($text) {
                if ($IsError) { Write-Host $text -NoNewline -ForegroundColor Yellow } else { Write-Host $text -NoNewline }
                return $true
            }
        } catch { } finally { if ($fs) { $fs.Dispose() } }
        return $false
    }
    function Get-BeforeReLastLine {
        param([string]$Path)
        try {
            if (Test-Path -LiteralPath $Path) {
                $tail = Get-Content -LiteralPath $Path -Tail 10 -ErrorAction SilentlyContinue | Where-Object { $_ -and $_.ToString().Trim() } | Select-Object -Last 1
                if ($tail) { return $tail.ToString().Trim() }
            }
        } catch { }
        return 'waiting for first child output'
    }
    function Stop-BeforeReChildProcess {
        param($Process, [string]$NeedlePath)
        if ($null -ne $Process) {
            try { if (-not $Process.HasExited) { $Process.Kill(); [void]$Process.WaitForExit(5000) } } catch { try { Stop-Process -Id $Process.Id -Force -ErrorAction SilentlyContinue } catch { } }
        }
        try {
            $escaped = [regex]::Escape($NeedlePath)
            Get-CimInstance Win32_Process -Filter "name='powershell.exe'" -ErrorAction SilentlyContinue |
                Where-Object { $_.ProcessId -ne $PID -and ($_.CommandLine -match $escaped -or $_.CommandLine -like '*WindowsRebootSafetyGate*') } |
                ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }
        } catch { }
    }

    $powershell = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $runRoot = 'C:\Temp\beforere-watchdog'
    New-Item -ItemType Directory -Force -Path $runRoot | Out-Null
    $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
    $stdout = Join-Path $runRoot "beforere_$stamp.out.log"
    $stderr = Join-Path $runRoot "beforere_$stamp.err.log"
    $childScript = $scriptPath
    if ($WatchdogSelfTest) {
        $childScript = Join-Path $runRoot "beforere_stall_child_$stamp.ps1"
        @('Write-Host "SELFTEST child started"','Start-Sleep -Seconds 60','Write-Host "SELFTEST child should have been killed"') | Set-Content -LiteralPath $childScript -Encoding UTF8
        Write-Host "[SELFTEST] using deliberate silent child to prove watchdog returns and cleans up" -ForegroundColor Cyan
    }
    $argList = @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Quote-BeforeReArg $childScript))
    if (-not $WatchdogSelfTest) { foreach ($a in @($ScriptArguments)) { $argList += (Quote-BeforeReArg $a) } }

    Write-Host ("[START] beforere reboot-safety gate {0}" -f (Get-Date -Format 'HH:mm:ss')) -ForegroundColor Cyan
    Write-Host ("[LIVE] heartbeat={0}s idle-watchdog={1}s hard-timeout={2}m; every heartbeat proves the wrapper is alive and will return to this prompt" -f $HeartbeatSeconds,$IdleSeconds,$HardTimeoutMinutes) -ForegroundColor Cyan
    Write-Host ("[LOG] stdout={0}" -f $stdout) -ForegroundColor DarkGray
    Write-Host ("[LOG] stderr={0}" -f $stderr) -ForegroundColor DarkGray

    $started = Get-Date; $lastActivity = Get-Date; $lastBeat = (Get-Date).AddSeconds(-999)
    $outOffset = [int64]0; $errOffset = [int64]0; $proc = $null; $spin = 0
    $spinner = @('|','/','-','\')
    try {
        $proc = Start-Process -FilePath $powershell -ArgumentList $argList -RedirectStandardOutput $stdout -RedirectStandardError $stderr -NoNewWindow -PassThru
        Write-Host ("[LIVE] child pid={0}; monitoring output and process state" -f $proc.Id) -ForegroundColor DarkCyan
        while ($true) {
            Microsoft.PowerShell.Utility\Start-Sleep -Milliseconds 250
            if ($proc) { $proc.Refresh() }
            $now = Get-Date; $hadOutput = $false
            if (Read-BeforeReNewLogText -Path $stdout -Offset ([ref]$outOffset)) { $hadOutput = $true }
            if (Read-BeforeReNewLogText -Path $stderr -Offset ([ref]$errOffset) -IsError) { $hadOutput = $true }
            if ($hadOutput) { $lastActivity = $now }
            if (($now - $lastBeat).TotalSeconds -ge $HeartbeatSeconds) {
                $last = Get-BeforeReLastLine -Path $stdout
                if ($last.Length -gt 150) { $last = $last.Substring(0,150) }
                Write-Host ("[LIVE {0}] elapsed={1:hh\:mm\:ss} no-new-output={2:n0}s pid={3} last='{4}'" -f $spinner[$spin % $spinner.Count],($now-$started),($now-$lastActivity).TotalSeconds,$proc.Id,$last) -ForegroundColor DarkGray
                $spin++; $lastBeat = $now
            }
            if ($proc.HasExited) { break }
            if (($now - $lastActivity).TotalSeconds -ge $IdleSeconds) { Stop-BeforeReChildProcess -Process $proc -NeedlePath $childScript; throw "beforere watchdog returned to shell after $IdleSeconds seconds without new child output. Logs: $stdout ; $stderr" }
            if (($now - $started).TotalMinutes -ge $HardTimeoutMinutes) { Stop-BeforeReChildProcess -Process $proc -NeedlePath $childScript; throw "beforere hard timeout returned to shell after $HardTimeoutMinutes minutes. Logs: $stdout ; $stderr" }
        }
        try { [void]$proc.WaitForExit() } catch { }
        Microsoft.PowerShell.Utility\Start-Sleep -Milliseconds 250
        [void](Read-BeforeReNewLogText -Path $stdout -Offset ([ref]$outOffset))
        [void](Read-BeforeReNewLogText -Path $stderr -Offset ([ref]$errOffset) -IsError)
        $exit = [int]$proc.ExitCode
        if ($exit -eq 0) { Write-Host "[DONE] beforere finished and returned to PowerShell. Gate exit=0." -ForegroundColor Green } else { Write-Host "[DONE] beforere returned to PowerShell. Gate exit=$exit; check blockers/warnings above and logs." -ForegroundColor Red }
        $global:LASTEXITCODE = $exit
        return $exit
    } finally {
        if ($proc) { try { $proc.Dispose() } catch { } }
        if ($WatchdogSelfTest -and (Test-Path -LiteralPath $childScript)) { Remove-Item -LiteralPath $childScript -Force -ErrorAction SilentlyContinue }
    }
}

function bergres {
    param([Parameter(Mandatory=$true)][string]$Path)
    $targetDir = Split-Path -Leaf $Path
    if (Test-Path $targetDir) { Remove-Item -Recurse -Force $targetDir }
    git clone --filter=blob:none --sparse https://codeberg.org/mishaelovsky5/study.git $targetDir
    Push-Location $targetDir
    git sparse-checkout set $Path
    $items = Get-ChildItem -Path $Path -Force
    foreach ($item in $items) { Move-Item -Path $item.FullName -Destination . -Force }
    Remove-Item -Recurse -Force $Path.Split('/')[0]
    Remove-Item -Recurse -Force .git
    Pop-Location
    Write-Host "Done: $targetDir" -ForegroundColor Green
}

function bin {
    try {
        $shell = New-Object -ComObject Shell.Application
        $recycleBin = $shell.Namespace(10)
        if ($recycleBin) {
            $itemCount = $recycleBin.Items().Count
            if ($itemCount -eq 0) {
                Write-Host "Recycle Bin is already empty." -ForegroundColor Green
            } else {
                Write-Host "Emptying Recycle Bin ($itemCount items)..." -ForegroundColor Yellow
                Clear-RecycleBin -Force -ErrorAction SilentlyContinue
                Write-Host "Recycle Bin emptied." -ForegroundColor Green
            }
        } else {
            Write-Host "Could not access Recycle Bin, trying Clear-RecycleBin..." -ForegroundColor Yellow
            Clear-RecycleBin -Force -ErrorAction SilentlyContinue
        }
        if ($shell) { [System.Runtime.Interopservices.Marshal]::ReleaseComObject($shell) | Out-Null }
    } catch {
        Write-Host "bin: $($_.Exception.Message)" -ForegroundColor Red
        Clear-RecycleBin -Force -ErrorAction SilentlyContinue
    }
}

function bios {
    Add-Type -TypeDefinition @"
    using System;
    using System.Runtime.InteropServices;
    public class FirmwareBoot {
        [DllImport("kernel32.dll", SetLastError = true)]
        static extern IntPtr GetCurrentProcess();
        [DllImport("advapi32.dll", SetLastError = true)]
        static extern bool OpenProcessToken(IntPtr ProcessHandle, uint DesiredAccess, out IntPtr TokenHandle);
        [DllImport("advapi32.dll", SetLastError = true)]
        static extern bool LookupPrivilegeValue(string lpSystemName, string lpName, out long lpLuid);
        [DllImport("advapi32.dll", SetLastError = true)]
        static extern bool AdjustTokenPrivileges(IntPtr TokenHandle, bool DisableAllPrivileges, ref TOKEN_PRIVILEGES NewState, uint BufferLength, IntPtr PreviousState, IntPtr ReturnLength);
        [DllImport("ntdll.dll", SetLastError = true)]
        static extern int NtSetSystemPowerState(int SystemAction, int MinSystemState, int Flags);
        [StructLayout(LayoutKind.Sequential)]
        struct TOKEN_PRIVILEGES { public uint PrivilegeCount; public long Luid; public uint Attributes; }
        public static void RebootToFirmware() {
            IntPtr token;
            OpenProcessToken(GetCurrentProcess(), 0x28, out token);
            TOKEN_PRIVILEGES tp = new TOKEN_PRIVILEGES { PrivilegeCount = 1, Attributes = 2 };
            LookupPrivilegeValue(null, "SeShutdownPrivilege", out tp.Luid);
            AdjustTokenPrivileges(token, false, ref tp, 0, IntPtr.Zero, IntPtr.Zero);
        }
    }
"@
    shutdown /r /fw /t 0
}

function bios2 {
    $biosFile = "F:\Downloads\X870EAORUSPRO11.FB1a"
    $usb = Get-Volume | Where-Object { $_.DriveType -eq 'Removable' } | Select-Object -First 1
    if (-not $usb -or -not $usb.DriveLetter) { Write-Host "[bios2] No USB drive found. Insert a USB stick." -ForegroundColor Red; return }
    $usbRoot = "$($usb.DriveLetter):\"
    if ($usb.FileSystemType -ne 'FAT32') {
        Write-Host "[bios2] Formatting $($usb.DriveLetter): as FAT32..." -ForegroundColor Yellow
        Format-Volume -DriveLetter $usb.DriveLetter -FileSystem FAT32 -NewFileSystemLabel "BIOS" -Confirm:$false -Force
    }
    if (-not (Test-Path $biosFile)) { Write-Host "[bios2] BIOS file not found: $biosFile" -ForegroundColor Red; return }
    Write-Host "[bios2] Copying BIOS to $usbRoot ..." -ForegroundColor Cyan
    Copy-Item $biosFile $usbRoot -Force
    Write-Host "[bios2] BIOS file on USB. Rebooting into UEFI in 5 seconds..." -ForegroundColor Green
    Write-Host "[bios2] In BIOS: Q-Flash > Update BIOS > select X870EAORUSPRO11.FB1a > flash." -ForegroundColor Yellow
    shutdown /r /fw /t 5
}

