function bootfast1 {
    [CmdletBinding()]
    param()

    $helperPath = 'C:\Users\micha\Documents\WindowsPowerShell\legacy-safe-functions\Invoke-BootFast1.ps1'
    if (-not (Test-Path -LiteralPath $helperPath -PathType Leaf)) {
        throw "bootfast1: helper script not found: $helperPath"
    }

    Write-Progress -Id 774 -Activity 'Configuring Microsoft Defender scan settings' -Status 'Checking elevation' -PercentComplete 2
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    $isAdministrator = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

    if (-not $isAdministrator) {
        Write-Host 'BOOTFAST1_PROGRESS stage=requesting-elevation' -ForegroundColor Cyan
        $argumentList = "-NoProfile -ExecutionPolicy Bypass -File `"$helperPath`""
        $process = Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -Verb RunAs -ArgumentList $argumentList -PassThru -Wait -ErrorAction Stop
        if ($process.ExitCode -ne 0) {
            throw "bootfast1: elevated helper failed with exit code $($process.ExitCode)."
        }

        Write-Progress -Id 774 -Activity 'Configuring Microsoft Defender scan settings' -Completed
        Write-Host 'BOOTFAST1_OK stage=elevated-helper-completed' -ForegroundColor Green
        return
    }

    Write-Host 'BOOTFAST1_PROGRESS stage=running-elevated-helper' -ForegroundColor Cyan
    try {
        & $helperPath
    }
    finally {
        Write-Progress -Id 774 -Activity 'Configuring Microsoft Defender scan settings' -Completed
    }
}

