function cfun {
[CmdletBinding()]
    param(
        [Parameter(Position = 0)]
        [AllowEmptyString()]
        [string]$FunctionName
    )

    $stateKey = 'CodexProfileFunctions.RuntimeState.6476b887-1198-4d61-897e-f4535f8986ef.v2'
    $state = [AppDomain]::CurrentDomain.GetData($stateKey)
    if (-not ($state -is [hashtable])) {
        throw 'CodexProfileFunctions runtime state is unavailable.'
    }

    $sourcePaths = @([string]$state.RuntimeSnapshotPath) + @($state.SupplementalRuntimePaths)
    $functionMap = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($sourcePath in $sourcePaths) {
        if ([string]::IsNullOrWhiteSpace($sourcePath) -or -not [System.IO.File]::Exists($sourcePath)) {
            throw "PowerShell function source is missing: $sourcePath"
        }

        $tokens = $null
        $parseErrors = $null
        $sourceAst = [System.Management.Automation.Language.Parser]::ParseFile($sourcePath, [ref]$tokens, [ref]$parseErrors)
        if ($parseErrors -and $parseErrors.Count -gt 0) {
            throw "Unable to parse PowerShell function source '$sourcePath': $($parseErrors[0].Message)"
        }

        foreach ($functionAst in @($sourceAst.FindAll({
            param($node)
            $node -is [System.Management.Automation.Language.FunctionDefinitionAst]
        }, $true))) {
            $name = $functionAst.Name -replace '^(?i:(global|script|local|private):)+', ''
            if (-not [string]::IsNullOrWhiteSpace($name)) {
                $functionMap[$name] = $functionAst
            }
        }
    }

    if ([string]::IsNullOrWhiteSpace($FunctionName)) {
        $entries = @($functionMap.GetEnumerator()) | Sort-Object -Property @(
            @{ Expression = { $_.Value.Extent.Text.Length }; Descending = $true },
            @{ Expression = { $_.Key }; Descending = $false }
        )
        foreach ($entry in $entries) {
            [pscustomobject]@{
                Name = $entry.Key
                Length = $entry.Value.Extent.Text.Length
                Source = $entry.Value.Extent.File
            }
        }
        return
    }

    $lookupName = $FunctionName -replace '^(?i:(global|script|local|private):)+', ''
    if ($functionMap.ContainsKey($lookupName)) {
        Write-Output $functionMap[$lookupName].Extent.Text.TrimEnd()
        return
    }

    Write-Warning "Function '$FunctionName' is not defined in the saved PowerShell profile sources."
}

