function Clear-DKillFastSettingsSnapshots {
    [CmdletBinding()]
    param()

    $removed = 0; $failures = 0
    try { $snapshots = @(Get-ChildItem -LiteralPath 'C:\Temp' -Directory -Filter 'dkill-docker-settings-*' -ErrorAction Stop) }
    catch { Write-DKillFastLine ("DKILL_SETTINGS_CLEAR_FAIL enumerate snapshots: {0}" -f $_.Exception.Message) Red; return $false }
    foreach($snapshot in $snapshots) {
        try { Remove-Item -LiteralPath $snapshot.FullName -Recurse -Force -ErrorAction Stop; if(Test-Path -LiteralPath $snapshot.FullName){throw 'snapshot deletion was not verified'}; $removed++; Write-DKillFastLine ("DKILL_SETTINGS_CLEAR_OK {0}" -f $snapshot.FullName) DarkGray }
        catch { $failures++; Write-DKillFastLine ("DKILL_SETTINGS_CLEAR_FAIL path={0}: {1}" -f $snapshot.FullName,$_.Exception.Message) Red }
    }
    $succeeded=$failures -eq 0; Write-DKillFastLine ("DKILL_SETTINGS_CLEAR_{0} removed={1} failures={2}" -f $(if($succeeded){'OK'}else{'INCOMPLETE'}),$removed,$failures) $(if($succeeded){'Green'}else{'Yellow'}); return $succeeded
}

