function clip {
[CmdletBinding()]param([switch]$NoOpen,[switch]$AllowPartialScrollback)
$ErrorActionPreference='Continue'
$dir=Join-Path $env:TEMP 'PowerShellSessionCopies'
$out=Join-Path $dir ("PowerShell-session-copy-pid{0}.txt" -f $PID)
$keep=New-Object System.Collections.Generic.List[string]
$kind='unknown'
$captureNote=$null
try { [void][System.IO.Directory]::CreateDirectory($dir) } catch { $captureNote=$_.Exception.Message }
$st=$null
try {
    $v=Get-Variable -Name CopyCurrentPowerShellSessionTranscriptState -Scope Global -ErrorAction SilentlyContinue
    if($v -and $v.Value.Path -and (Test-Path -LiteralPath $v.Value.Path -PathType Leaf)){ $st=[string]$v.Value.Path }
} catch { $captureNote=$_.Exception.Message }
if(-not $st){
    try {
        $m=Join-Path $env:TEMP ("PowerShellSessionRecordings\PowerShell-session-manifest-pid{0}.json" -f $PID)
        if(Test-Path -LiteralPath $m){ $st=((Get-Content -LiteralPath $m -Raw | ConvertFrom-Json).TranscriptPath) }
    } catch { $captureNote=$_.Exception.Message }
}
if(-not $st -or -not (Test-Path -LiteralPath $st -PathType Leaf)){
    $st=$null
    try {
        $rd=Join-Path $env:TEMP 'PowerShellSessionRecordings'
        if(Test-Path -LiteralPath $rd){
            $f=Get-ChildItem -LiteralPath $rd -Filter ("*pid{0}.txt" -f $PID) -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^PowerShell-session-\d{8}-\d{6}-\d{3}-pid\d+\.txt$' } | Sort-Object LastWriteTime -Descending | Select-Object -First 1
            if($f){ $st=$f.FullName }
        }
    } catch { $captureNote=$_.Exception.Message }
}
if($st -and (Test-Path -LiteralPath $st -PathType Leaf)){
    try {
        $txt=''
        $fs=[System.IO.File]::Open($st,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::ReadWrite)
        try { $rd=New-Object System.IO.StreamReader($fs,[System.Text.Encoding]::UTF8,$true); try { $txt=$rd.ReadToEnd() } finally { $rd.Dispose() } } finally { $fs.Dispose() }
        for($i=0;$i -lt 5;$i++){
            Start-Sleep -Milliseconds 60
            $t2=''
            $fs2=[System.IO.File]::Open($st,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::ReadWrite)
            try { $rd2=New-Object System.IO.StreamReader($fs2,[System.Text.Encoding]::UTF8,$true); try { $t2=$rd2.ReadToEnd() } finally { $rd2.Dispose() } } finally { $fs2.Dispose() }
            if($t2.Length -eq $txt.Length){ break }
            $txt=$t2
        }
        $lines=@($txt -split "`r?`n")
        $idx=New-Object System.Collections.Generic.List[int]
        for($i=0;$i -lt $lines.Count;$i++){ if($lines[$i] -match '^\*{20,}'){ [void]$idx.Add($i) } }
        $footer=-1
        for($i=0;$i -lt $lines.Count;$i++){ if($lines[$i] -match '^\*{20,}' -and $i+1 -lt $lines.Count -and $lines[$i+1] -match 'transcript end'){ $footer=$i; break } }
        $start=if($idx.Count -ge 2){ $idx[1]+1 } else { 0 }
        $end=if($footer -ge 0){ $footer } else { $lines.Count }
        for($i=$start;$i -lt $end -and $i -lt $lines.Count;$i++){
            $ln=$lines[$i]
            if($ln -match '^(Start time|End time|Username|RunAs User|Configuration Name|Machine|Host Application|Process ID|PSVersion|PSEdition|PSCompatibleVersions|BuildVersion|CLRVersion|WSManStackVersion|PSRemotingProtocolVersion|SerializationVersion|GitCommitId|OS|Platform):'){ continue }
            [void]$keep.Add($ln)
        }
        $kind=('full session transcript (' + $keep.Count + ' lines)')
    } catch { $captureNote=$_.Exception.Message; $st=$null }
}
if($keep.Count -eq 0){
    $kind='partial (no session transcript was running)'
    $scrollback=New-Object System.Collections.Generic.List[string]
    try {
        if($Host.Name -eq 'ConsoleHost'){
            if(-not ('NativeConsole' -as [type])){
                Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
using System.Text;
public static class NativeConsole {
    [DllImport("kernel32.dll", SetLastError=true)]
    public static extern IntPtr GetStdHandle(int nStdHandle);
    [DllImport("kernel32.dll", SetLastError=true)]
    public static extern bool GetConsoleScreenBufferInfo(IntPtr hConsoleOutput, out CONSOLE_SCREEN_BUFFER_INFO lpConsoleScreenBufferInfo);
    [DllImport("kernel32.dll", SetLastError=true)]
    public static extern bool ReadConsoleOutputCharacter(IntPtr hConsoleOutput, StringBuilder lpCharacter, uint nLength, COORD dwReadCoord, out uint lpNumberOfCharsRead);
    [StructLayout(LayoutKind.Sequential)]
    public struct COORD { public short X; public short Y; }
    [StructLayout(LayoutKind.Sequential)]
    public struct SMALL_RECT { public short Left; public short Top; public short Right; public short Bottom; }
    [StructLayout(LayoutKind.Sequential)]
    public struct CONSOLE_SCREEN_BUFFER_INFO { public COORD dwSize; public COORD dwCursorPosition; public ushort wAttributes; public SMALL_RECT srWindow; public COORD dwMaximumWindowSize; }
}
"@ -ErrorAction Stop
            }
            $handle=[NativeConsole]::GetStdHandle(-11)
            $info=New-Object NativeConsole+CONSOLE_SCREEN_BUFFER_INFO
            if([NativeConsole]::GetConsoleScreenBufferInfo($handle,[ref]$info)){
                $w=[int]$info.dwSize.X
                $h=[int]$info.dwSize.Y
                $sb=New-Object System.Text.StringBuilder ($w+1)
                $charsRead=0
                for($y=0;$y -lt $h;$y++){
                    [void]$sb.Clear()
                    $coord=New-Object NativeConsole+COORD
                    $coord.X=0
                    $coord.Y=$y
                    if([NativeConsole]::ReadConsoleOutputCharacter($handle,$sb,[uint32]$w,$coord,[ref]$charsRead)){
                        [void]$scrollback.Add($sb.ToString().TrimEnd())
                    }
                }
            }
        }
    } catch { $captureNote=$_.Exception.Message }
    if($scrollback.Count -gt 0){
        foreach($ln in $scrollback){ [void]$keep.Add($ln) }
        $kind=('console scrollback (' + $keep.Count + ' lines)')
    }
}
if($keep.Count -eq 0){
    try {
        $hist=@(Get-History -ErrorAction SilentlyContinue)
        foreach($entry in $hist){ [void]$keep.Add(('PS> ' + $entry.CommandLine)) }
        if($keep.Count -gt 0){ $kind=('session command history (' + $keep.Count + ' entries)') }
    } catch { $captureNote=$_.Exception.Message }
}
if($keep.Count -eq 0){ $keep.Add('(No session history was available to capture.)') }
$writeError=''
try { [System.IO.File]::WriteAllLines($out,$keep.ToArray(),(New-Object System.Text.UTF8Encoding($false))) } catch { $writeError=$_.Exception.Message }
try { Set-Clipboard -Value ([System.IO.File]::ReadAllText($out)) -ErrorAction SilentlyContinue } catch { }
if(-not $NoOpen){
    try { Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\notepad.exe') -ArgumentList ('"{0}"' -f $out) | Out-Null } catch { $writeError=($writeError + ' notepad:' + $_.Exception.Message) }
}
$bytes=0
try { $bytes=(Get-Item -LiteralPath $out).Length } catch { }
if($captureNote){ Write-Host ("clip note: {0}" -f $captureNote) }
if($writeError){ Write-Host ("clip warning: {0}" -f $writeError) }
Write-Host ("Saved and opened the {0} for this PowerShell session (pid {1}) : {2} ({3:N0} bytes)" -f $kind,$PID,$out,$bytes)
}

