function Convert-MmenuDockerSizeToBytes {
        param([string]$Text)
        if ([string]::IsNullOrWhiteSpace($Text)) { return $null }
        if ($Text -match '^\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|B)\s*$') {
            $n=[double]$matches[1]; $u=$matches[2].ToUpperInvariant()
            switch -Regex ($u) {
                '^B$' { return [int64]$n }
                '^KB$' { return [int64]($n*1000) }
                '^KIB$' { return [int64]($n*1KB) }
                '^MB$' { return [int64]($n*1000*1000) }
                '^MIB$' { return [int64]($n*1MB) }
                '^GB$' { return [int64]($n*1000*1000*1000) }
                '^GIB$' { return [int64]($n*1GB) }
                '^TB$' { return [int64]($n*1000*1000*1000*1000) }
                '^TIB$' { return [int64]($n*1TB) }
            }
        }
        return $null
    }

