function ConvertTo-BackupDockerBindMountPath {
    param([Parameter(Mandatory)][string]$Path)

    $fullPath = [System.IO.Path]::GetFullPath($Path)
    if ($fullPath -notmatch '^(?<Drive>[A-Za-z]):(?<Rest>(\\.*)?)$') {
        throw "Only local Windows drive paths are supported for Docker restore mounts: $Path"
    }

    $drive = $matches.Drive.ToLowerInvariant()
    $rest = ($matches.Rest -replace '\\', '/').Trim('/')

    if ($rest) {
        return "/$drive/$rest"
    }

    return "/$drive"
}

function ConvertTo-BackupDockerSlug {
    param([Parameter(Mandatory)][string]$Value)

    $slug = $Value.ToLowerInvariant()
    $slug = $slug -replace '[^a-z0-9._-]+', '-'
    $slug = $slug.Trim('-._')

    if (-not $slug) {
        throw "Could not derive a Docker-safe repo slug from '$Value'."
    }

    if ($slug.Length -lt 2) {
        $slug = "$slug-b"
    }

    $slug
}

function ConvertTo-NvidMarketingVersion {
    param([string]$DriverVersion)
    if ([string]::IsNullOrWhiteSpace($DriverVersion)) {
        return $null
    }
    $digits = $DriverVersion -replace '[^\d]', ''
    if ($digits.Length -lt 5) {
        return $null
    }
    $tail = $digits.Substring($digits.Length - 5)
    return ('{0}.{1}' -f $tail.Substring(0, 3), $tail.Substring(3, 2))
}

