function Copy-DKillFastIfExists {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$DestRoot)
    if([string]::IsNullOrWhiteSpace($Source) -or -not(Test-Path -LiteralPath $Source)){Write-DKillFastLine ("DKILL_SNAPSHOT_COPY_INFO absent source: {0}" -f $Source) DarkGray;return $true}
    try{$name=(($Source-replace'^[A-Za-z]:\\','')-replace'[\\/:*?"<>|]','_');$destination=Join-Path $DestRoot $name;New-Item -ItemType Directory -Force -Path $DestRoot -ErrorAction Stop|Out-Null;Copy-Item -LiteralPath $Source -Destination $destination -Recurse -Force -ErrorAction Stop;if(-not(Test-Path -LiteralPath $destination)){throw 'copy was not verified'};Write-DKillFastLine ("DKILL_SNAPSHOT_COPY_OK source={0} destination={1}" -f $Source,$destination) DarkGray;return $true}catch{Write-DKillFastLine ("DKILL_SNAPSHOT_COPY_FAIL source={0}: {1}" -f $Source,$_.Exception.Message) Red;return $false}
}

function Copy-DKillFastSettingsFile {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$SnapshotRoot)

    if([string]::IsNullOrWhiteSpace($Source) -or -not (Test-Path -LiteralPath $Source -PathType Leaf)) {
        return $false
    }
    try {
        $resolved = (Resolve-Path -LiteralPath $Source -ErrorAction Stop).ProviderPath
        if($resolved -notmatch '^(?i)C:\\') {
            Write-DKillFastLine ("DKILL_SETTINGS_SNAPSHOT_REJECT outside C drive: {0}" -f $resolved) Yellow
            return $false
        }
        $relative = $resolved.Substring(3)
        $destination = Join-Path $SnapshotRoot $relative
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) -ErrorAction Stop | Out-Null
        Copy-Item -LiteralPath $resolved -Destination $destination -Force -ErrorAction Stop
        $sourceHash = (Get-FileHash -LiteralPath $resolved -Algorithm SHA256 -ErrorAction Stop).Hash
        $destinationHash = (Get-FileHash -LiteralPath $destination -Algorithm SHA256 -ErrorAction Stop).Hash
        if($sourceHash -ne $destinationHash) { throw 'SHA256 mismatch after snapshot copy' }
        Write-DKillFastLine ("DKILL_SETTINGS_SNAPSHOT_OK {0}" -f $relative) DarkGray
        return $true
    } catch {
        Write-DKillFastLine ("DKILL_SETTINGS_SNAPSHOT_FAIL source={0}: {1}" -f $Source,$_.Exception.Message) Red
        return $false
    }
}

function Copy-DKillFastSettingsSnapshot {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$SnapshotRoot)

    $copied = 0
    $failures = 0
    try {
        New-Item -ItemType Directory -Force -Path $SnapshotRoot -ErrorAction Stop | Out-Null
    } catch {
        Write-DKillFastLine ("DKILL_SETTINGS_SNAPSHOT_FAIL root={0}: {1}" -f $SnapshotRoot,$_.Exception.Message) Red
        return $false
    }
    foreach($directory in @((Join-Path $env:USERPROFILE '.docker'),(Join-Path $env:APPDATA 'Docker'),(Join-Path $env:APPDATA 'Docker Desktop'))) {
        if([string]::IsNullOrWhiteSpace($directory) -or -not (Test-Path -LiteralPath $directory)) { continue }
        try {
            $files = @(Get-ChildItem -LiteralPath $directory -File -Force -ErrorAction Stop | Where-Object {
                $_.Extension -ieq '.json' -or $_.Name -match '^(config|daemon|windows-daemon|settings-store|settings|features|login-info)(\..*)?$'
            })
            foreach($file in $files) {
                if(Copy-DKillFastSettingsFile -Source $file.FullName -SnapshotRoot $SnapshotRoot) { $copied++ } else { $failures++ }
            }
        } catch {
            $failures++
            Write-DKillFastLine ("DKILL_SETTINGS_SNAPSHOT_WARN enumerate path={0}: {1}" -f $directory,$_.Exception.Message) Yellow
        }
    }
    $succeeded = $failures -eq 0
    Write-DKillFastLine ("DKILL_SETTINGS_SNAPSHOT_{0} files={1} failures={2} root={3}" -f $(if($succeeded){'OK'}else{'INCOMPLETE'}),$copied,$failures,$SnapshotRoot) $(if($succeeded){'Green'}else{'Yellow'})
    return $succeeded
}

