function Copy-ReassTree {
    param(
        [Parameter(Mandatory)]
        [string]$Source,

        [Parameter(Mandatory)]
        [string]$Destination,

        [Parameter(Mandatory)]
        [string]$Stage,

        [Parameter(Mandatory)]
        [int]$ProgressStart,

        [Parameter(Mandatory)]
        [int]$ProgressEnd
    )

    $sourceRoot = [IO.Path]::GetFullPath($Source).TrimEnd('\')
    $files = Get-ReassFiles -Path $sourceRoot
    $totalBytes = [int64]0
    foreach ($file in $files) {
        $totalBytes += $file.Length
    }

    New-Item -ItemType Directory -Path $Destination -Force -ErrorAction Stop | Out-Null
    $copiedBytes = [int64]0
    $buffer = New-Object byte[] (4MB)

    foreach ($file in $files) {
        $relative = $file.FullName.Substring($sourceRoot.Length).TrimStart('\')
        $target = Join-Path $Destination $relative
        $targetParent = Split-Path -Parent $target
        New-Item -ItemType Directory -Path $targetParent -Force -ErrorAction Stop | Out-Null

        $sourceStream = $null
        $targetStream = $null
        try {
            $sourceStream = [IO.File]::Open($file.FullName, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
            $targetStream = [IO.File]::Open($target, [IO.FileMode]::Create, [IO.FileAccess]::Write, [IO.FileShare]::None)

            while (($read = $sourceStream.Read($buffer, 0, $buffer.Length)) -gt 0) {
                $targetStream.Write($buffer, 0, $read)
                $copiedBytes += $read
                $ratio = if ($totalBytes -gt 0) { $copiedBytes / [double]$totalBytes } else { 1 }
                $percent = $ProgressStart + [Math]::Floor(($ProgressEnd - $ProgressStart) * $ratio)
                Write-Progress -Id 776 -Activity 'Restoring High On Life 2 save data' -Status ("{0}: {1}" -f $Stage, $relative) -PercentComplete $percent
            }
        }
        finally {
            if ($targetStream) { $targetStream.Dispose() }
            if ($sourceStream) { $sourceStream.Dispose() }
        }

        [IO.File]::SetLastWriteTimeUtc($target, $file.LastWriteTimeUtc)
    }

    return [pscustomobject]@{
        FileCount = $files.Count
        Bytes     = $totalBytes
    }
}

function Copy-RedockerSafeDir {
        param([string]$Source,[string]$Dest)
        if([string]::IsNullOrWhiteSpace($Source) -or -not (Test-Path -LiteralPath $Source)){ return $false }
        try {
            New-Item -ItemType Directory -Force -Path $Dest | Out-Null
            $sourceItem = Get-Item -LiteralPath $Source -Force -ErrorAction Stop
            if(-not $sourceItem.PSIsContainer){
                Copy-Item -LiteralPath $Source -Destination $Dest -Force -ErrorAction Stop
                return $true
            }
            $copied = 0
            Get-ChildItem -LiteralPath $Source -Force -Recurse -ErrorAction SilentlyContinue | ForEach-Object {
                $rel = $_.FullName.Substring($Source.Length).TrimStart('\')
                if([string]::IsNullOrWhiteSpace($rel)){ return }
                $target = Join-Path $Dest $rel
                try {
                    if($_.PSIsContainer){
                        New-Item -ItemType Directory -Force -Path $target | Out-Null
                    } else {
                        $sourceFile = $_.FullName
                        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
                        Copy-Item -LiteralPath $sourceFile -Destination $target -Force -ErrorAction Stop
                        $script:RedockerSafeCopiedFiles++
                        $copied++
                    }
                } catch {
                    Write-RedockerSafeLine ("snapshot skipped locked file {0}" -f $sourceFile) DarkYellow
                }
            }
            return ($copied -gt 0 -or (Test-Path -LiteralPath $Dest))
        } catch { Write-RedockerSafeLine ("snapshot copy failed {0}: {1}" -f $Source,$_.Exception.Message) Yellow; return $false }
    }

function Copy-RedockerSnapshotTree {
        param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$Destination)
        if(-not (Test-Path -LiteralPath $Source -PathType Container)){ return 0 }
        $copied = 0
        New-Item -ItemType Directory -Force -Path $Destination | Out-Null
        foreach($item in @(Get-ChildItem -LiteralPath $Source -Force -Recurse -ErrorAction SilentlyContinue)){
            $relative = $item.FullName.Substring($Source.Length).TrimStart('\')
            if([string]::IsNullOrWhiteSpace($relative)){ continue }
            if($relative -match '(?i)(^|\\)(wsl|logs?|cache|tmp)(\\|$)' -or $item.Name -match '(?i)\.(vhdx|log|lock)$'){ continue }
            $target = Join-Path $Destination $relative
            if($item.PSIsContainer){
                New-Item -ItemType Directory -Force -Path $target | Out-Null
            } else {
                New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
                try {
                    Copy-Item -LiteralPath $item.FullName -Destination $target -Force -ErrorAction Stop
                    $copied++
                } catch {
                    Write-RedockerSafeLine ("snapshot skipped locked or unavailable file: {0}" -f $item.FullName) DarkYellow
                }
            }
        }
        return $copied
    }

function CopyClip {
    [CmdletBinding()]
    param(
        [Parameter(ValueFromRemainingArguments = $true)]
        [string[]] $Args
    )
    $distro = 'Ubuntu'   # change once if you ever rename
    $user   = 'root'
    $core   = @('-d', $distro, '-u', $user, '--')  # common WSL flags
    if (-not $Args) {
        & "$env:SystemRoot\System32\wsl.exe" @core bash -li
    }
    else {
        $raw     = [string]::Join(' ', $Args)
        $escaped = $raw -replace '"', '\"'  # keep internal quotes intact
        & "$env:SystemRoot\System32\wsl.exe" @core bash -li -c "$escaped"
    }
    if ($LASTEXITCODE -ne $null) { $global:LASTEXITCODE = $LASTEXITCODE }
}

