    Write-Host $text
    $text | Set-Clipboard
    Write-Host "Copied to clipboard!" -ForegroundColor Green
}

function ctemp {
    Write-Host 'Cleaning all temp files, logs, and cache...' -ForegroundColor Yellow
    Stop-Service -Name 'wuauserv' -Force -ErrorAction SilentlyContinue
    @('C:\Windows\Temp\*', 'C:\Temp\*', 'C:\Users\*\AppData\Local\Temp\*', 'C:\Users\*\AppData\Roaming\Microsoft\Windows\Recent\*', 'C:\Users\*\AppData\Local\Microsoft\Windows\Temporary Internet Files\*', 'C:\Users\*\AppData\Local\Microsoft\Internet Explorer\DOMStore\*', 'C:\Users\*\AppData\Local\Google\Chrome\User Data\*\Cache\*', 'C:\Users\*\AppData\Local\Mozilla\Firefox\Profiles\*\cache2\*', 'C:\Users\*\AppData\Local\Microsoft\Edge\User Data\*\Cache\*', 'C:\Windows\Logs\*', 'C:\Windows\SoftwareDistribution\Download\*', 'C:\Windows\System32\LogFiles\*', 'C:\ProgramData\Microsoft\Windows\WER\ReportQueue\*', 'C:\Users\*\AppData\Local\CrashDumps\*', 'C:\Windows\Minidump\*', 'C:\Users\*\AppData\Local\Microsoft\Windows\WebCache\*', 'C:\Windows\Prefetch\*.pf', 'C:\Users\*\AppData\Local\Microsoft\Windows\INetCache\*', 'C:\Users\*\AppData\Local\Microsoft\Terminal Server Client\Cache\*', 'C:\ProgramData\USOPrivate\UpdateStore\*', 'C:\Windows\SystemTemp\*') | ForEach-Object { Get-ChildItem -Path $_ -Recurse -Force -ErrorAction SilentlyContinue } | Where-Object { !$_.PSIsContainer -and $_.Name -notlike '*.exe' -and $_.Name -notlike '*.dll' } | Remove-Item -Force -Recurse -ErrorAction SilentlyContinue
    Start-Service -Name 'wuauserv' -ErrorAction SilentlyContinue
    [System.GC]::Collect()
    Write-Host 'Temp cleanup completed successfully!' -ForegroundColor Green
}

function curr {
    Write-Host "Scheduling full disk scans for next boot..." -ForegroundColor Cyan

    foreach ($drive in 'C:','D:','E:','F:') {
        if (Test-Path $drive) {
            Write-Host "  Scheduling $drive for full scan..." -ForegroundColor Yellow
            fsutil dirty set $drive 2>$null
            echo Y | chkdsk $drive /R 2>$null
        }
    }

    Write-Host "`nAll drives scheduled for FULL scan at next boot." -ForegroundColor Green
    Write-Host "Use 'shutdown /r /t 0' for a clean reboot (not restart from Start menu)." -ForegroundColor Yellow
    Write-Host "The scan will run before Windows loads and may take 10-30 minutes per drive." -ForegroundColor Yellow
}

function dcreds {
    Set-Location -Path "F:\\backup\windowsapps\Credentials";
    built -Path "F:\\backup\windowsapps\Credentials"
}

function dddesk {
    $DesktopOrganizerScript = 'F:\study\shells\powershell\scripts\DesktopOrganizer\a.ps1'
    if (-not (Test-Path $DesktopOrganizerScript)) {
        Write-Host "SKIP dddesk: DesktopOrganizer script not found at $DesktopOrganizerScript" -ForegroundColor DarkYellow
        return
    }

    $IsAdministrator = ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")
    if (-not $IsAdministrator) {
        Write-Host "SKIP dddesk: run PowerShell as Administrator before resetting the desktop and taskbar." -ForegroundColor DarkYellow
        return
    }

    $DesktopRoots = @(
        [Environment]::GetFolderPath("Desktop"),
        [Environment]::GetFolderPath("CommonDesktopDirectory")
    ) | Where-Object { $_ -and (Test-Path $_) } | Select-Object -Unique

    Get-ChildItem -LiteralPath $DesktopRoots -Force -Recurse -ErrorAction SilentlyContinue |
        Remove-Item -Force -Recurse -ErrorAction SilentlyContinue

    $oldDddeskEap = $ErrorActionPreference
    try {
        $ErrorActionPreference = 'Continue'
        & $DesktopOrganizerScript 2>&1 | ForEach-Object {
            if ($_ -is [System.Management.Automation.ErrorRecord]) {
                Write-Host ("dddesk: DesktopOrganizer reported nonfatal error output after being invoked: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
            } else {
                $_
            }
        }
    } catch {
        Write-Host ("dddesk: DesktopOrganizer command reported a nonfatal error after being invoked: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
    } finally {
        $ErrorActionPreference = $oldDddeskEap
        $global:LASTEXITCODE = 0
    }
}

function ddevit {
    docker load -i "F:\backup\Containers\developer.tar"
    docker rm -f dotnet-setup 2>$null
    docker run -it -d -v ${PWD}:C:\workspace -v ${env:USERPROFILE}:C:\host-profile -v F:\:C:\f-drive -w C:\f-drive\downloads --name dotnet-setup developer:latest powershell
    if ($args.Count -gt 0) {
        $envVarPattern = [regex]::Escape('$env:')
        $command = "`$env:PATH += ';C:\Users\ContainerAdministrator\AppData\Local\Microsoft\dotnet'; " + ($args[0] -replace $envVarPattern, '$env:')
        docker exec dotnet-setup powershell -Command $command
    }
    docker exec -it dotnet-setup powershell -NoExit -Command "`$env:PATH += ';C:\Users\ContainerAdministrator\AppData\Local\Microsoft\dotnet'"
}

