function disdis {
    $script = 'F:\study\Learning\01\01\Shells\powershell\profile-functions\shells\powershell\profile-helpers\Disdis\Invoke-disdis.ps1'
    if (-not (Test-Path -LiteralPath $script)) {
        throw "disdis script not found: $script"
