        return
    }
    . $script @args
}

function dism++ {
    $zip = "$env:TEMP\DismPP.zip"
    $dst = "$env:TEMP\DismPP"
    try {
        Write-Host "Downloading Dism++..." -ForegroundColor Cyan
        Invoke-WebRequest -Uri "https://github.com/Chuyu-Team/Dism-Multi-language/releases/download/v10.1.1002.2/Dism%2B%2B10.1.1002.1B.zip" -OutFile $zip -UseBasicParsing
        Write-Host "Extracting..." -ForegroundColor Cyan
        Expand-Archive $zip -DestinationPath $dst -Force
        $exe = Get-ChildItem $dst -Filter "Dism++x64.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($exe) { & $exe.FullName } else { Write-Host "Dism++x64.exe not found in extracted folder: $dst" -ForegroundColor Red }
    } catch {
        Write-Host "dism++ failed: $_" -ForegroundColor Red
    }
}



function dkill2 {
    [CmdletBinding()]
    param(
        [switch]$NoRestart,
        [switch]$Preserve,
        [switch]$FactoryReset,
        [string]$ConfirmFactoryReset = '',
        [switch]$SelfTest
    )
    $scriptPath = 'F:\study\Platforms\windows\functions\dkill.ps1'
    if (-not (Test-Path -LiteralPath $scriptPath -PathType Leaf)) { throw "Canonical dkill script not found: $scriptPath" }
    $forward = @{}
    foreach ($name in 'NoRestart','Preserve','FactoryReset','ConfirmFactoryReset','SelfTest') {
        if ($PSBoundParameters.ContainsKey($name)) { $forward[$name] = $PSBoundParameters[$name] }
    }
    $global:LASTEXITCODE = 0
    & $scriptPath @forward
    $ok = $?
    $exitCode = [int]$LASTEXITCODE
    $global:LASTEXITCODE = $exitCode
    if (-not $ok -or $exitCode -ne 0) { throw "dkill2 canonical Docker recovery failed with exit $exitCode." }
}

