function fixvss2 {
    $system32 = Join-Path $env:SystemRoot 'System32'
    $net = Join-Path $system32 'net.exe'
    $sc = Join-Path $system32 'sc.exe'
    $reg = Join-Path $system32 'reg.exe'
    $regsvr32 = Join-Path $system32 'regsvr32.exe'
    $vssvc = Join-Path $system32 'vssvc.exe'
    $vssadmin = Join-Path $system32 'vssadmin.exe'

    # Start/stop a service only when its state actually needs to change, and
    # never let net.exe's stderr surface as a PowerShell error. Covers the
    # "already started" / "not started" races and missing services.
    function __FixVss2-SetServiceState {
        param([string]$Name, [switch]$Start)
        $svc = Get-Service -Name $Name -ErrorAction SilentlyContinue
        if ($null -eq $svc) { Write-Host "  $Name : service not installed, skipped"; return }
        $wantRunning = [bool]$Start
        $isRunning = ($svc.Status -eq [System.ServiceProcess.ServiceControllerStatus]::Running)
        if ($isRunning -eq $wantRunning) {
            if ($wantRunning) { Write-Host "  $Name : already running, skipped" }
            else { Write-Host "  $Name : already stopped, skipped" }
            return
        }
        if ($Start) { & $net start $Name 2>$null } else { & $net stop $Name /y 2>$null }
        $check = Get-Service -Name $Name -ErrorAction SilentlyContinue
        $nowRunning = ($null -ne $check) -and ($check.Status -eq [System.ServiceProcess.ServiceControllerStatus]::Running)
        if ($nowRunning -eq $wantRunning) {
            if ($wantRunning) { Write-Host "  $Name : started" } else { Write-Host "  $Name : stopped" }
        } else {
            if ($wantRunning) { Write-Host "  $Name : could not start (see Service Control Manager event log)" }
            else { Write-Host "  $Name : could not stop (see Service Control Manager event log)" }
        }
    }

    __FixVss2-SetServiceState vss
    __FixVss2-SetServiceState swprv
    __FixVss2-SetServiceState bits
    __FixVss2-SetServiceState wuauserv
    __FixVss2-SetServiceState cryptsvc
    & $sc config vss start= demand 2>$null
    & $sc config swprv start= demand 2>$null
    & $reg delete 'HKLM\SYSTEM\CurrentControlSet\Services\VSS\Diag' /f 2>$null
    $dlls = 'vss_ps.dll','swprv.dll','eventcls.dll','es.dll','stdprov.dll','vssui.dll','msxml.dll','msxml3.dll','msxml4.dll'
    foreach ($d in $dlls) { Start-Process -FilePath $regsvr32 -ArgumentList "/s `"$system32\$d`"" -Wait -ErrorAction SilentlyContinue }
    & $vssvc /register 2>$null
    __FixVss2-SetServiceState cryptsvc -Start
    __FixVss2-SetServiceState wuauserv -Start
    __FixVss2-SetServiceState bits -Start
    __FixVss2-SetServiceState swprv -Start
    __FixVss2-SetServiceState vss -Start
    & $vssadmin delete shadows /all /quiet 2>$null
}

