function Get-22scSourceDefinition {
    param([string] $FunctionName, [string[]] $Paths)

    foreach ($path in $Paths) {
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { continue }
        $tokens = $null
        $errors = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile($path, [ref] $tokens, [ref] $errors)
        if ($errors -and $errors.Count -gt 0) {
            throw "22sc: cannot parse '$path': $($errors[0].Message)"
        }
        $match = @($ast.FindAll({
            param($node)
            $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and
            (($node.Name -replace '^(?i:(global|script|local):)+', '') -ieq $FunctionName)
        }, $true) | Select-Object -First 1)
        if ($match.Count -gt 0) {
            return [pscustomobject]@{ Definition = $match[0].Extent.Text; Source = $path }
        }
    }
    return $null
}

function Get-AmdInstallerUrl {
    $page = Invoke-WebRequest -UseBasicParsing -Uri $amdSupportPage -TimeoutSec 30 -UserAgent $amdUserAgent
    $match = [regex]::Match(
        $page.Content,
        'https://drivers\.amd\.com/drivers/(?:installer/)?[^"''<>\s]*?(?:minimalsetup|autodetect)[^"''<>\s]*?\.exe',
        [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if (-not $match.Success) {
        throw 'AMD did not publish an auto-detect installer link on its official support page.'
    }
    $uri = [Uri]$match.Value
    if ($uri.Scheme -ne 'https' -or $uri.Host -ne 'drivers.amd.com') {
        throw "Refusing unexpected AMD installer URL: $uri"
    }
    return $uri.AbsoluteUri
}

function Get-BackupComparablePath {
    param([Parameter(Mandatory)][string]$Path)

    try {
