function Get-BackupMenuRepoSlug {
    param([Parameter(Mandatory)][string]$Path)

    $projectPath = Resolve-BackupDockerProjectPath -Path $Path
    $folderName = Split-Path -Leaf $projectPath
    if (-not $folderName) {
        throw "Could not derive a menu repo slug from path '$projectPath'."
    }

    $slug = $folderName.ToLowerInvariant() -replace '[^a-z0-9]+', ''
    if (-not $slug) {
        throw "Could not derive a menu repo slug from folder name '$folderName'."
    }

    if ($slug.Length -lt 2) {
        $slug = "$slug" + 'b'
    }

    return $slug
}

