function Get-BeFunctionDefinitionMap {
    param(
        [Parameter(Mandatory)][string]$Path
    )
    $definitions = @{}
    if (-not (Test-Path -LiteralPath $Path)) { return $definitions }
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if ($item.PSIsContainer) {
        $rootPath = [IO.Path]::GetFullPath($item.FullName).TrimEnd('\')
        $files = @(Get-ChildItem -LiteralPath $rootPath -Filter '*.ps1' -File -Recurse -ErrorAction Stop | Sort-Object FullName)
    } else {
        $rootPath = [IO.Path]::GetDirectoryName($item.FullName)
        $files = @($item)
    }
    foreach ($file in $files) {
        $tokens = $null; $parseErrors = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile($file.FullName, [ref]$tokens, [ref]$parseErrors)
        $syntaxErrors = @($parseErrors | Where-Object { $_.ErrorId -ne 'ModuleNotFoundDuringParse' })
        if ($syntaxErrors.Count -gt 0) { throw "BE: cannot count functions because '$($file.FullName)' does not parse: $($syntaxErrors[0].Message)" }
        $relativePath = if ($item.PSIsContainer) { $file.FullName.Substring($rootPath.Length).TrimStart('\') } else { $file.Name }
        $relativePath = $relativePath.ToLowerInvariant()
        foreach ($definition in @($ast.EndBlock.Statements | Where-Object { $_ -is [System.Management.Automation.Language.FunctionDefinitionAst] })) {
            $name = $definition.Name -replace '^(?i:(?:global|script|local|private):)+', ''
            $definitionText = (($definition.Extent.Text.Trim() -replace "`r`n", "`n") -replace "`r", "`n")
            $part = "$relativePath`n$definitionText"
            if ($definitions.ContainsKey($name)) { $definitions[$name] = @($definitions[$name]) + $part } else { $definitions[$name] = @($part) }
        }
    }
    foreach ($name in @($definitions.Keys)) { $definitions[$name] = @($definitions[$name] | Sort-Object) -join "`n`0`n" }
    return $definitions
}

