function Get-CleancRootInventoryLocal {
        param([Parameter(Mandatory=$true)][string]$ResolvedRootPath)
        $rootPrefix = $ResolvedRootPath.TrimEnd('\') + '\'
        Get-ChildItem -LiteralPath $ResolvedRootPath -Force -ErrorAction Stop | ForEach-Object {
            if (-not $_.FullName.StartsWith($rootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) { return }
            $name = $_.FullName.Substring($rootPrefix.Length).TrimStart('\')
            if ([string]::IsNullOrWhiteSpace($name) -or $name.Contains('\')) { return }
            [pscustomobject]@{
                Name = $name
                FullName = $_.FullName
                ItemType = if ($_.PSIsContainer) { 'Directory' } else { 'File' }
                Attributes = [string]$_.Attributes
                IsDirectory = [bool]$_.PSIsContainer
                IsReparsePoint = [bool]($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint)
            }
        }
    }

function Get-CodexExecutableCandidateVersion {
        if ([string]::IsNullOrWhiteSpace($Path)) { return $null }

        try {
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        } catch {
            return $null
        }

        foreach ($rawVersion in @(
            $item.VersionInfo.ProductVersion,
            $item.VersionInfo.FileVersion
        )) {
            if ([string]::IsNullOrWhiteSpace($rawVersion)) { continue }

            $match = [regex]::Match([string]$rawVersion, '\d+(?:\.\d+){1,3}')
            if (-not $match.Success) { continue }

            try {
                return [version]$match.Value
            } catch {}
        }

        return $null
    }

function Get-ContentLength {
    param([string]$Url, [int]$TimeoutSec)

    try {
        $request = [Net.HttpWebRequest]::Create($Url)
        $request.Method = 'HEAD'
        $request.Timeout = $TimeoutSec * 1000
        $request.ReadWriteTimeout = $TimeoutSec * 1000
        $request.AllowAutoRedirect = $true
        $request.Referer = $amdSupportPage
        $request.UserAgent = $amdUserAgent
        $response = $request.GetResponse()
        try { return [int64]$response.ContentLength } finally { $response.Close() }
    } catch {
        return [int64]-1
    }
}

function Get-DKillFastPathBytes {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path)
    if([string]::IsNullOrWhiteSpace($Path) -or -not(Test-Path -LiteralPath $Path)){return 0L}
    try {
        $item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        if(-not$item.PSIsContainer){return [int64]$item.Length}
        $total=0L
        Get-ChildItem -LiteralPath $Path -Force -Recurse -ErrorAction Stop|ForEach-Object{if(-not $_.PSIsContainer){$total+=[int64]$_.Length}}
        return [int64]$total
    } catch { Write-DKillFastLine ("DKILL_MEASURE_WARN path={0}: {1}" -f $Path,$_.Exception.Message) Yellow; return 0L }
}

function Get-DKillFastRemainingMilliseconds {
