        } catch { return 0 }
    }

function Get-DKillPathBytes {
        param([string]$Path)
        $total = [Int64]0
        try {
            if (Test-Path -LiteralPath $Path) {
                $item = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
                if ($item -and -not $item.PSIsContainer) { return [Int64]$item.Length }
                Get-ChildItem -LiteralPath $Path -Force -Recurse -ErrorAction SilentlyContinue | ForEach-Object { if (-not $_.PSIsContainer) { $total += [Int64]$_.Length } }
            }
        } catch {}
        return $total
    }

function global:Get-FileHash {
        [CmdletBinding(DefaultParameterSetName = 'Path')]
        param(
            [Parameter(Mandatory = $true, Position = 0, ParameterSetName = 'Path')]
            [string[]]$Path,

            [Parameter(Mandatory = $true, ParameterSetName = 'LiteralPath')]
            [Alias('PSPath')]
            [string[]]$LiteralPath,

            [ValidateSet('SHA1', 'SHA256', 'SHA384', 'SHA512', 'MD5')]
            [string]$Algorithm = 'SHA256'
        )

        $inputPaths = if ($PSCmdlet.ParameterSetName -eq 'LiteralPath') { $LiteralPath } else { $Path }
        foreach ($inputPath in $inputPaths) {
            $resolvedPaths = if ($PSCmdlet.ParameterSetName -eq 'LiteralPath') {
                Resolve-Path -LiteralPath $inputPath -ErrorAction Stop
            } else {
                Resolve-Path -Path $inputPath -ErrorAction Stop
            }

            foreach ($resolvedPath in $resolvedPaths) {
                $stream = [System.IO.File]::OpenRead($resolvedPath.ProviderPath)
                $hashAlgorithm = [System.Security.Cryptography.HashAlgorithm]::Create($Algorithm)
                try {
                    $hashBytes = $hashAlgorithm.ComputeHash($stream)
                    $hash = ([System.BitConverter]::ToString($hashBytes) -replace '-', '').ToUpperInvariant()
                    [pscustomobject]@{
                        Algorithm = $Algorithm.ToUpperInvariant()
                        Hash = $hash
                        Path = $resolvedPath.ProviderPath
                    }
                } finally {
                    if ($hashAlgorithm) { $hashAlgorithm.Dispose() }
                    $stream.Dispose()
                }
            }
        }
    }

function Get-GitlogTokenCandidate {
    param([string]$ExplicitToken)

    if ($ExplicitToken) {
        return [pscustomobject]@{ Token = $ExplicitToken; Source = 'argument' }
    }

    foreach ($envName in @('GH_TOKEN','GITHUB_TOKEN','GIT_PAT')) {
        foreach ($scope in @('User','Process','Machine')) {
            $candidate = [Environment]::GetEnvironmentVariable($envName, $scope)
            if ($candidate) {
                return [pscustomobject]@{ Token = $candidate; Source = "$scope environment $envName" }
            }
        }
    }

    $managerCandidate = Get-GitlogTokenFromManager
    if ($managerCandidate) {
        return $managerCandidate
    }

    if (Test-Path -LiteralPath $credentialPath) {
        $credentialText = [System.IO.File]::ReadAllText($credentialPath)
        $match = [regex]::Match($credentialText, 'https://[^:]+:([^@]+)@github\.com')
        if ($match.Success) {
            return [pscustomobject]@{ Token = $match.Groups[1].Value; Source = '.git-credentials' }
        }
    }

    return $null
}

function Get-GitlogTokenFromManager {
    $bashPath = 'C:\Program Files\Git\bin\bash.exe'
    if (-not (Test-Path -LiteralPath $bashPath -PathType Leaf)) { return $null }

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $bashPath
    $psi.Arguments = "-lc ""printf 'protocol=https\nhost=github.com\nusername=Michaelunkai\n\n' | git -c credential.helper=manager credential fill"""
    $psi.UseShellExecute = $false
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true

    $process = New-Object System.Diagnostics.Process
    $process.StartInfo = $psi
    [void]$process.Start()
    $stdout = $process.StandardOutput.ReadToEnd()
    $process.StandardError.ReadToEnd() | Out-Null
    $process.WaitForExit()

    if ($process.ExitCode -ne 0 -or -not $stdout) { return $null }
    $tokenLine = @($stdout -split "`r?`n" | Where-Object { $_ -like 'password=*' } | Select-Object -First 1)
    if (-not $tokenLine) { return $null }
    $token = ($tokenLine -replace '^password=', '')
    if (-not $token) { return $null }

    return [pscustomobject]@{ Token = $token; Source = 'Git Credential Manager' }
}

