function Get-MmenuContextTotalBytes {
        $total=[int64]0; $count=0; $started=Get-Date; $last=Get-Date
        Write-Host "[mmenu][scan] START counting real source bytes" -ForegroundColor Cyan
        foreach($file in [IO.Directory]::EnumerateFiles($projectPath,'*',[IO.SearchOption]::AllDirectories)){
            try {
                $info=Get-Item -LiteralPath $file -Force -ErrorAction Stop
                $total += [int64]$info.Length; $count++
            } catch {
                Write-Host ("[mmenu][scan-warning] unreadable_reserved_or_phantom_path path={0} error={1}" -f $file,$_.Exception.Message) -ForegroundColor Yellow
                continue
            }
            if(((Get-Date)-$last).TotalSeconds -ge 1){ Write-Host ("[mmenu][scan] files={0} total={1}" -f $count,(Format-MmenuMB $total)) -ForegroundColor DarkCyan; $last=Get-Date }
        }
        Write-Host ("[mmenu][scan] DONE files={0} total={1} elapsed={2}s" -f $count,(Format-MmenuMB $total),[int][Math]::Ceiling(((Get-Date)-$started).TotalSeconds)) -ForegroundColor Cyan
        return $total
    }

