function Get-NvidAppLaunchState {
    param([string]$ExpectedVersion)

    $protocolInfo = Get-NvidProtocolCommand 'nvidiaapp'
    $installEntry = Get-NvidUninstallEntry 'NVIDIA App*'
    $defaultPath = 'C:\Program Files\NVIDIA Corporation\NVIDIA App\CEF\NVIDIA App.exe'
    $launchPath = @($protocolInfo.Path, $defaultPath) |
        Where-Object { $_ -and (Test-Path $_) } |
        Select-Object -First 1
    $launchVersion = if ($launchPath) { (Get-Item -LiteralPath $launchPath).VersionInfo.ProductVersion } else { $null }

    return [pscustomobject]@{
        Installed = ($null -ne $installEntry)
        InstalledVersion = if ($installEntry) { $installEntry.DisplayVersion } else { $null }
        ExpectedVersion = $ExpectedVersion
        ProtocolRegistered = $protocolInfo.Registered
        ProtocolCommand = $protocolInfo.Command
        ProtocolPath = $protocolInfo.Path
        LaunchPath = $launchPath
        PathExists = ($null -ne $launchPath)
        LaunchVersion = $launchVersion
        Healthy = ($installEntry -and $installEntry.DisplayVersion -eq $ExpectedVersion -and $launchPath -and $launchVersion -eq $ExpectedVersion)
        BrokenInstall = ($installEntry -and $installEntry.DisplayVersion -eq $ExpectedVersion -and -not $launchPath)
    }
}

function Get-NvidAppRuntimeSupport {
    $programFilesRoot = 'C:\Program Files\NVIDIA Corporation'
    $checks = @(
        [pscustomobject]@{ Name = 'NvContainer executable'; Path = (Join-Path $programFilesRoot 'NvContainer\nvcontainer.exe') }
        [pscustomobject]@{ Name = 'NvCpl DLL'; Path = (Join-Path $programFilesRoot 'NVIDIA App\NvCpl\nvcpl.dll') }
        [pscustomobject]@{ Name = 'NvBackend API'; Path = (Join-Path $programFilesRoot 'NVIDIA App\NvBackend\NvBackendAPI64.dll') }
        [pscustomobject]@{ Name = 'NvTelemetry API'; Path = (Join-Path $programFilesRoot 'NvTelemetry\NvTelemetryAPI64.dll') }
        [pscustomobject]@{ Name = 'NvTelemetry plugin'; Path = (Join-Path $programFilesRoot 'NvTelemetry\plugin\NvTelemetry64.dll') }
        [pscustomobject]@{ Name = 'ShadowPlay API'; Path = (Join-Path $programFilesRoot 'NVIDIA App\ShadowPlay\nvspapi64.dll') }
        [pscustomobject]@{ Name = 'NvCpl LocalSystem plugin'; Path = (Join-Path $programFilesRoot 'NvContainer\plugins\LocalSystem\NvCpl\NvXDCore.dll') }
        [pscustomobject]@{ Name = 'NvCpl Session plugin'; Path = (Join-Path $programFilesRoot 'NvContainer\plugins\Session\NvCpl\nvxdsyncplugin.dll') }
        [pscustomobject]@{ Name = 'NvTelemetry LocalSystem plugin'; Path = (Join-Path $programFilesRoot 'NvContainer\plugins\LocalSystem\NvTelemetry\NvTelemetry64.dll') }
        [pscustomobject]@{ Name = 'NvBackend User plugin'; Path = (Join-Path $programFilesRoot 'NvContainer\plugins\User\NvBackend\NvBackend64.dll') }
        [pscustomobject]@{ Name = 'ShadowPlay LocalSystem plugin'; Path = (Join-Path $programFilesRoot 'NvContainer\plugins\LocalSystem\ShadowPlay\_nvspserviceplugin64.dll') }
    )

    $missing = New-Object System.Collections.Generic.List[string]
    foreach ($check in $checks) {
        if (-not (Test-Path $check.Path)) {
            $missing.Add(("{0}: {1}" -f $check.Name, $check.Path)) | Out-Null
        }
    }

    $service = Get-Service -Name 'NvContainerLocalSystem' -ErrorAction SilentlyContinue
    return [pscustomobject]@{
        Healthy        = ($missing.Count -eq 0 -and $service)
        Missing        = @($missing)
        ServicePresent = ($null -ne $service)
        ServiceStatus  = if ($service) { $service.Status.ToString() } else { 'Missing' }
    }
}

function Get-NvidConnectedDisplayState {
    param([string]$InstanceId)

    $rawLines = @(pnputil /enum-devices /connected /class Display 2>&1)
    $currentInstanceId = $null
    $currentStatus = $null
    $matchedStatus = $null

    foreach ($line in $rawLines) {
        if ($line -match '^Instance ID:\s*(?<value>.+)$') {
            if ($currentInstanceId -eq $InstanceId) {
                $matchedStatus = $currentStatus
                break
            }
            $currentInstanceId = $matches['value'].Trim()
            $currentStatus = $null
            continue
        }

        if ($line -match '^Status:\s*(?<value>.+)$') {
            $currentStatus = $matches['value'].Trim()
        }
    }

    if (-not $matchedStatus -and $currentInstanceId -eq $InstanceId) {
        $matchedStatus = $currentStatus
    }

    return [pscustomobject]@{
        InstanceId = $InstanceId
        Status     = $matchedStatus
        Started    = ($matchedStatus -eq 'Started')
        RawOutput  = ($rawLines | Out-String).Trim()
    }
}

