function Get-ProfileFunctionDependencyNames {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Management.Automation.Language.FunctionDefinitionAst]$FunctionAst,

        [Parameter(Mandatory)]
        [hashtable]$FunctionMap
    )

    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $orderedNames = [System.Collections.Generic.List[string]]::new()

    $visitFunction = {
        param(
            [System.Management.Automation.Language.FunctionDefinitionAst]$CurrentFunctionAst
        )

        $commandAsts = $CurrentFunctionAst.Body.FindAll({ param($node) $node -is [System.Management.Automation.Language.CommandAst] }, $true)
        foreach ($commandAst in $commandAsts) {
            $commandName = $commandAst.GetCommandName()
            if ([string]::IsNullOrWhiteSpace($commandName)) {
                continue
            }
            if (-not $FunctionMap.ContainsKey($commandName)) {
                continue
            }
            if (-not $seen.Add($commandName)) {
                continue
            }

            $orderedNames.Add($commandName) | Out-Null
            & $visitFunction $FunctionMap[$commandName]
        }
    }

    & $visitFunction $FunctionAst
    return $orderedNames.ToArray()
}

function Get-ProfileFunctionMap {
[CmdletBinding()]
param(
    [string]$ProfilePath
)

if ([string]::IsNullOrWhiteSpace($ProfilePath) -or [string]::Equals($ProfilePath, $PROFILE, [System.StringComparison]::OrdinalIgnoreCase)) {
    $preferredPaths = @(
        $script:FullProfileDefinitionsPath,
        $script:ProfileRuntimeSnapshotPath,
        $PROFILE
    )
    $ProfilePath = @($preferredPaths | Where-Object {
        -not [string]::IsNullOrWhiteSpace($_) -and (Test-Path -LiteralPath $_ -PathType Leaf)
    } | Select-Object -First 1)
}

if ([string]::IsNullOrWhiteSpace($ProfilePath) -or -not (Test-Path -LiteralPath $ProfilePath -PathType Leaf)) {
    throw "Profile not found: $ProfilePath"
}

$tokens = $null
$errors = $null
$ast = [System.Management.Automation.Language.Parser]::ParseFile($ProfilePath, [ref]$tokens, [ref]$errors)
if ($errors -and $errors.Count -gt 0) {
    $parseSummary = ($errors | Select-Object -First 3 | ForEach-Object { $_.Message.Trim() }) -join ' | '
    throw "Unable to parse profile '$ProfilePath': $parseSummary"
}

$functionMap = @{}
foreach ($functionAst in $ast.FindAll({ param($node) $node -is [System.Management.Automation.Language.FunctionDefinitionAst] }, $true)) {
    $functionMap[$functionAst.Name] = $functionAst
}

return $functionMap
}

function Get-ProfileFunctionMutationDocument {
    param([Parameter(Mandatory)][string]$Path)
    $encoding = Get-ProfileFunctionMutationEncoding -Path $Path
    $source = [System.IO.File]::ReadAllText($Path, $encoding)
    $tokens = $null
    $errors = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseInput($source, [ref]$tokens, [ref]$errors)
    if (@($errors).Count -gt 0) {
        throw "Profile source '$Path' has syntax errors: $($errors[0].Message)"
    }
    [pscustomobject]@{
        Path = $Path
        Source = $source
        Encoding = $encoding
        Ast = $ast
        Functions = @(Get-ProfileFunctionMutationOuterFunctions -Ast $ast)
    }
}

function Get-ProfileFunctionMutationEncoding {
    param([Parameter(Mandatory)][string]$Path)
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
        return [System.Text.UTF8Encoding]::new($true)
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) {
        return [System.Text.Encoding]::Unicode
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) {
        return [System.Text.Encoding]::BigEndianUnicode
    }
    [System.Text.UTF8Encoding]::new($false)
}

function Get-ProfileFunctionMutationMatch {
    param([Parameter(Mandatory)]$Document, [Parameter(Mandatory)][string]$Name)
    $matches = @(Get-ProfileFunctionMutationMatches -Document $Document -Name $Name)
    if ($matches.Count -eq 0) {
        return $null
    }
    $matches[-1]
}

function Get-ProfileFunctionMutationMatches {
    param([Parameter(Mandatory)]$Document, [Parameter(Mandatory)][string]$Name)
    @($Document.Functions | Where-Object {
        (($_.Name -replace '^(?i:global:)', '') -ieq $Name)
    } | Sort-Object { $_.Extent.StartOffset })
}

function Get-ProfileFunctionMutationOuterFunctions {
    param([Parameter(Mandatory)][System.Management.Automation.Language.ScriptBlockAst]$Ast)
    @($Ast.FindAll({
        param($node)
        if (-not ($node -is [System.Management.Automation.Language.FunctionDefinitionAst])) {
            return $false
        }
        $parent = $node.Parent
        while ($null -ne $parent) {
            if ($parent -is [System.Management.Automation.Language.FunctionDefinitionAst]) {
                return $false
            }
            $parent = $parent.Parent
        }
        $true
    }, $true))
}

