        'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable'
        'C:\Users\micha\Documents\WindowsPowerShell\legacy-safe-functions'
    )
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($root in $roots) {
        if (-not [System.IO.Directory]::Exists($root)) { continue }
        foreach ($file in Get-ChildItem -LiteralPath $root -Filter *.ps1 -Recurse -File -ErrorAction SilentlyContinue) {
            $fullName = [System.IO.Path]::GetFullPath($file.FullName)
            if ($fullName -match '\\backups(?:\\|$)') { continue }
            if ($fullName -match '\.bak-(?:funcmutation|rmfunc|saved)-') { continue }
            if ($seen.Add($fullName)) { $fullName }
        }
    }
}

function Get-ProfileFunctionMutationSourceFileRemovals {
    param([Parameter(Mandatory)][string[]]$Names)
    $results = New-Object System.Collections.Generic.List[object]
    foreach ($path in @(Get-ProfileFunctionMutationProfileSourceFiles)) {
        try {
            $document = Get-ProfileFunctionMutationDocument -Path $path
        } catch {
            continue
        }
        $pathMatches = @(
            foreach ($name in $Names) {
                @(Get-ProfileFunctionMutationMatches -Document $document -Name $name)
            }
        )
        if ($pathMatches.Count -eq 0) { continue }
        $removedNames = @($Names | Where-Object {
            @(Get-ProfileFunctionMutationMatches -Document $document -Name $_).Count -gt 0
        })
        $updated = $document.Source
        foreach ($match in @($pathMatches | Sort-Object { $_.Extent.StartOffset } -Descending)) {
            $updated = $updated.Remove($match.Extent.StartOffset, $match.Extent.EndOffset - $match.Extent.StartOffset)
        }
        $results.Add([pscustomobject]@{
            Path = $path
            Document = $document
            RemovedNames = $removedNames
            UpdatedSource = $updated
        }) | Out-Null
    }
    $results.ToArray()
}

function Get-ProfileFunctionMutationUserModuleRemoval {
    param([Parameter(Mandatory)][string]$Name)

    $moduleRoot = Get-ProfileFunctionMutationUserModuleRoot
    if (-not [System.IO.Directory]::Exists($moduleRoot)) {
        return $null
    }

    $moduleRootPath = [System.IO.Path]::GetFullPath($moduleRoot).TrimEnd('\')
    $candidatePaths = @(
        Get-ChildItem -LiteralPath $moduleRootPath -Filter "$Name.ps1" -Recurse -File -ErrorAction Stop |
            Where-Object { -not ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) }
    )
    $removals = New-Object System.Collections.Generic.List[object]
    foreach ($candidate in $candidatePaths) {
        $candidatePath = [System.IO.Path]::GetFullPath($candidate.FullName)
        if (-not $candidatePath.StartsWith($moduleRootPath + '\', [System.StringComparison]::OrdinalIgnoreCase)) {
            continue
        }

        $document = Get-ProfileFunctionMutationDocument -Path $candidatePath
        $matches = @(Get-ProfileFunctionMutationMatches -Document $document -Name $Name)
        if ($matches.Count -eq 0) {
            continue
        }
        if ($matches.Count -ne 1 -or $document.Functions.Count -ne 1 -or @($document.Ast.EndBlock.Statements).Count -ne 1) {
            throw "Refusing to remove '$Name' from user module source '$candidatePath': it is not an isolated single-function source file."
        }

        $removals.Add([pscustomobject]@{
            Name = $Name
            Path = $candidatePath
        }) | Out-Null
    }

    if ($removals.Count -eq 0) {
        return $null
    }
    if ($removals.Count -ne 1) {
        throw "Refusing to remove '$Name': multiple user module source files define it: $($removals.Path -join '; ')"
    }
    $removals[0]
}

function Get-ProfileFunctionMutationUserModuleRemovalBackup {
    param([Parameter(Mandatory)][string]$Name)

    $moduleRoot = Get-ProfileFunctionMutationUserModuleRoot
    if (-not [System.IO.Directory]::Exists($moduleRoot)) {
        return $null
    }

    $moduleRootPath = [System.IO.Path]::GetFullPath($moduleRoot).TrimEnd('\')
    $candidatePaths = @(
        Get-ChildItem -LiteralPath $moduleRootPath -Filter "$Name.ps1.bak-rmfunc-module-*" -Recurse -File -ErrorAction Stop |
            Where-Object { -not ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) }
    )
    $backups = New-Object System.Collections.Generic.List[object]
    foreach ($candidate in $candidatePaths) {
        $candidatePath = [System.IO.Path]::GetFullPath($candidate.FullName)
        if (-not $candidatePath.StartsWith($moduleRootPath + '\', [System.StringComparison]::OrdinalIgnoreCase)) {
            continue
        }

        $document = Get-ProfileFunctionMutationDocument -Path $candidatePath
        $matches = @(Get-ProfileFunctionMutationMatches -Document $document -Name $Name)
        if ($matches.Count -eq 0) {
            continue
        }
        if ($matches.Count -ne 1 -or $document.Functions.Count -ne 1 -or @($document.Ast.EndBlock.Statements).Count -ne 1) {
            throw "Refusing to treat '$Name' as already removed from user module backup '$candidatePath': it is not an isolated single-function source file."
        }

        $backups.Add([pscustomobject]@{
            Name = $Name
            Path = $candidatePath
        }) | Out-Null
    }

    if ($backups.Count -eq 0) {
        return $null
    }
    if ($backups.Count -ne 1) {
        throw "Refusing to treat '$Name' as already removed: multiple user module removal backups match it: $($backups.Path -join '; ')"
    }
    $backups[0]
}

