function Get-ProfileInspectionFunctionMap {
    [CmdletBinding()]
    param()

    $sourcePaths = @(
        'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\Microsoft.PowerShell_profile.runtime.ps1',
        'C:\Users\micha\Documents\WindowsPowerShell\Microsoft.PowerShell_profile.ps1',
        'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\legacy-safe-functions\profile-wrappers.ps1',
        'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\legacy-safe-functions\before.ps1'
    )
    $functionMap = @{}
    foreach ($sourcePath in $sourcePaths) {
        if (-not (Test-Path -LiteralPath $sourcePath -PathType Leaf)) {
            throw "Profile inspection source is missing: $sourcePath"
        }
        $tokens = $null
        $errors = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile($sourcePath, [ref]$tokens, [ref]$errors)
        if ($errors.Count -gt 0) {
            throw "Profile inspection source has syntax errors '$sourcePath': $($errors[0].Message)"
        }
        foreach ($statement in $ast.EndBlock.Statements) {
            if ($statement -is [System.Management.Automation.Language.FunctionDefinitionAst]) {
                $name = $statement.Name -replace '^(global|script|local|private):', ''
                $functionMap[$name] = $statement
            }
        }
    }
    return $functionMap
}

function Get-ProfileManagedWebAppProcess {
    [CmdletBinding()]
    param([object]$State)

    if (-not $State -or -not $State.ProcessId) {
        return $null
    }

    $processId = [int]$State.ProcessId
    $process = Get-CimInstance -ClassName Win32_Process -Filter ("ProcessId = {0}" -f $processId) -ErrorAction SilentlyContinue
    if (-not $process) {
        return $null
    }

    $commandLine = [string]$process.CommandLine
    if ($commandLine -notmatch '(?i)(^|\s)-m\s+http\.server(\s|$)') {
        return $null
    }
    if ($State.Port -and $commandLine -notmatch ('(?<!\d){0}(?!\d)' -f [regex]::Escape([string]$State.Port))) {
        return $null
    }
    if ($State.ProcessStartedUtc) {
        $liveProcess = Get-Process -Id $processId -ErrorAction SilentlyContinue
        if (-not $liveProcess) {
            return $null
        }
        try {
            $expectedStart = [DateTime]::Parse([string]$State.ProcessStartedUtc).ToUniversalTime()
            $actualStart = $liveProcess.StartTime.ToUniversalTime()
            if ([Math]::Abs(($actualStart - $expectedStart).TotalSeconds) -gt 2) {
                return $null
            }
        } catch {
            return $null
        }
    }

    return $process
}

