function Get-RedockerManifestEntries {
        param([Parameter(Mandatory)][string]$ManifestPath)
        $raw = Get-Content -LiteralPath $ManifestPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if($raw -is [System.Array]){ return @($raw) }
        if($raw.Name -is [System.Array]){
            $entries = New-Object System.Collections.Generic.List[object]
            for($index = 0; $index -lt $raw.Name.Count; $index++){
                $entry = [ordered]@{ Name = [string]$raw.Name[$index] }
                if($raw.Source -is [System.Array] -and $index -lt $raw.Source.Count){ $entry.Source = [string]$raw.Source[$index] }
                if($raw.Registry -is [System.Array] -and $index -lt $raw.Registry.Count){ $entry.Registry = [string]$raw.Registry[$index] }
                if($raw.Files -is [System.Array] -and $index -lt $raw.Files.Count){ $entry.Files = $raw.Files[$index] }
                [void]$entries.Add([pscustomobject]$entry)
            }
            return $entries.ToArray()
        }
        return @($raw)
    }

function Get-RedockerSharedFileHash {
        param([Parameter(Mandatory)][string]$Path)
        $stream = $null
        $sha = $null
        try {
            $stream = [IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete)
            $sha = [Security.Cryptography.SHA256]::Create()
            return ([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','')
        } finally {
            if($sha){ $sha.Dispose() }
            if($stream){ $stream.Dispose() }
        }
    }

function Get-RestorePlan {
    param([Parameter(Mandatory)]$Backup)

    $backupFull = [IO.Path]::GetFullPath($Backup.Directory.FullName).TrimEnd('\') + '\'
    $payloadRoot = Join-Path $Backup.Directory.FullName 'SaveGames'
    if (-not (Test-Path -LiteralPath $payloadRoot -PathType Container)) {
        throw "reass: ass backup payload is missing: $payloadRoot"
    }

    $entries = @()
    for ($index = 0; $index -lt $Backup.Sources.Count; $index++) {
        $destination = [IO.Path]::GetFullPath([string]$Backup.Sources[$index])
        if (-not [IO.Path]::IsPathRooted($destination) -or $destination.StartsWith($backupFull, [StringComparison]::OrdinalIgnoreCase)) {
            throw "reass: refusing invalid backup destination: $destination"
        }

        $entries += [pscustomobject]@{
            Index       = $index
            Destination = $destination
        }
    }

    $plans = @()
    foreach ($entry in $entries | Sort-Object { $_.Destination.Length }) {
        $isNested = $entries | Where-Object {
            $_.Index -ne $entry.Index -and
            $entry.Destination.StartsWith($_.Destination.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)
        } | Select-Object -First 1
        if ($isNested) {
            continue
        }

        $destination = $entry.Destination
        $leaf = Split-Path -Leaf $destination.TrimEnd('\')
        $payload = if ($Backup.Sources.Count -eq 1) {
            $payloadRoot
        } else {
            Join-Path $payloadRoot ('{0:D2}_{1}' -f ($entry.Index + 1), $leaf)
        }
        if (-not (Test-Path -LiteralPath $payload -PathType Container)) {
            throw "reass: ass backup payload does not match recorded destination: $destination"
        }
        if ((Get-ReassFiles -Path $payload).Count -eq 0) {
            throw "reass: ass backup payload is empty for destination: $destination"
        }

        $parent = Split-Path -Parent $destination
        if ([string]::IsNullOrWhiteSpace($parent)) {
            throw "reass: refusing root destination: $destination"
        }
        $plans += [pscustomobject]@{
            Source      = $payload
            Destination = $destination
            Stage       = Join-Path $parent ((Split-Path -Leaf $destination) + '.reass-stage-' + $runId + '-' + $entry.Index)
            Rollback    = Join-Path $parent ((Split-Path -Leaf $destination) + '.reass-rollback-' + $runId + '-' + $entry.Index)
            Activated   = $false
        }
    }
    $plans
}

