function Get-RminsCurrentProcessIds {
    $ids = New-Object System.Collections.Generic.HashSet[int]
    $currentId = $PID
    $ids.Add($currentId) | Out-Null
    $processes = @(Get-CimInstance Win32_Process -ErrorAction Stop)
    $parentId = $currentId
    for ($depth = 0; $depth -lt 12; $depth++) {
        $parent = @($processes | Where-Object { $_.ProcessId -eq $parentId } | Select-Object -First 1)
        if ($parent.Count -ne 1 -or $parent[0].ParentProcessId -le 0) {
            break
        }
        $parentId = [int]$parent[0].ParentProcessId
        $ids.Add($parentId) | Out-Null
    }

    return ,$ids
}

function Get-RminsTargets {
    $targets = New-Object System.Collections.Generic.List[string]
    $temporary = Join-Path $root '.fitgirl_tmp'
    if (Test-Path -LiteralPath $temporary -PathType Container) {
        $targets.Add((Test-RminsTarget -Path $temporary))
    }

    foreach ($directory in @(Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction Stop | Where-Object { $_.Name -like '*[*Repack*]*' })) {
        $normalizedName = ($directory.Name -replace '\s*\[[^\]]*\]\s*$', '').Trim(' ', '.', '-', '_')
        if ([string]::IsNullOrWhiteSpace($normalizedName)) {
            continue
        }

        $normalizedTarget = Join-Path $root $normalizedName
        if ((Test-Path -LiteralPath $normalizedTarget -PathType Container) -and $normalizedTarget -ne $directory.FullName) {
            $targets.Add((Test-RminsTarget -Path $normalizedTarget))
        }
    }

    return @($targets | Select-Object -Unique)
}

function Get-RrminsProtectedProcessIds {
    $protected = New-Object System.Collections.Generic.HashSet[int]
    $processes = @(Get-CimInstance Win32_Process -ErrorAction Stop)
    $current = $PID

    for ($depth = 0; $depth -lt 12; $depth++) {
        if (-not $protected.Add([int]$current)) {
            break
        }

        $entry = @($processes | Where-Object { $_.ProcessId -eq $current } | Select-Object -First 1)
        if ($entry.Count -ne 1 -or $entry[0].ParentProcessId -le 0) {
            break
        }

        $current = [int]$entry[0].ParentProcessId
    }

    return ,$protected
}

function Get-RrmRootSummary {
        param([Parameter(Mandatory = $true)][string]$LiteralPath)

        if (-not (Test-Path -LiteralPath $LiteralPath)) {
            return [pscustomobject]@{ Exists = $false; ChildCount = 0; Sample = '' }
        }

        $sample = @()
        $childCount = 0
        foreach ($child in @(Get-ChildItem -LiteralPath $LiteralPath -Force -ErrorAction SilentlyContinue)) {
            $childCount++
            if ($sample.Count -lt 5) { $sample += $child.Name }
        }

        [pscustomobject]@{
            Exists = $true
            ChildCount = $childCount
            Sample = ($sample -join ', ')
        }
    }

