function Get-SpeedtestCliPath {
    $candidates = New-Object System.Collections.Generic.List[string]

    foreach ($command in @(Get-Command speedtest.exe -CommandType Application -All -ErrorAction SilentlyContinue)) {
        if ($command.Path) {
            $candidates.Add($command.Path)
        }
    }

    $wingetPackageRoot = Join-Path $env:LOCALAPPDATA 'Microsoft\WinGet\Packages'
    if (Test-Path -LiteralPath $wingetPackageRoot -PathType Container) {
        foreach ($match in @(Get-ChildItem -LiteralPath $wingetPackageRoot -Filter 'speedtest.exe' -Recurse -ErrorAction SilentlyContinue)) {
            $candidates.Add($match.FullName)
        }
    }

    foreach ($candidate in @($candidates | Where-Object { $_ } | Sort-Object -Unique)) {
        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) {
            continue
        }

        try {
            $null = & $candidate --version 2>$null
            if ($LASTEXITCODE -eq 0) {
                return $candidate
            }
        } catch {
            continue
        }
    }

    return $null
}

