function Get-ZapfLeftovers {
    param([Parameter(Mandatory = $true)][string]$ExtendedTarget)

    $results = New-Object 'System.Collections.Generic.List[string]'
    if (-not [System.IO.Directory]::Exists($ExtendedTarget)) {
        return @()
    }

    $pending = New-Object 'System.Collections.Generic.Stack[string]'
    $pending.Push($ExtendedTarget)
    while ($pending.Count -gt 0) {
        $path = $pending.Pop()
        [void]$results.Add((ConvertFrom-ZapfExtendedPath $path))
        try {
            $attributes = Get-ZapfAttributes -Path $path
            if (Test-ZapfReparsePoint -Attributes $attributes) {
                continue
            }
            if (($attributes -band [System.IO.FileAttributes]::Directory) -eq 0) {
                continue
            }
            foreach ($entry in [System.IO.Directory]::EnumerateFileSystemEntries($path)) {
                $entryAttributes = $null
                try {
                    $entryAttributes = Get-ZapfAttributes -Path $entry
                } catch {
                    [void]$results.Add((
                        'ENUMERATION_FAILED: {0} :: {1}' -f
                        (ConvertFrom-ZapfExtendedPath $entry),
                        $_.Exception.Message
                    ))
                    continue
                }
                [void]$results.Add((ConvertFrom-ZapfExtendedPath $entry))
                if (
                    -not (Test-ZapfReparsePoint -Attributes $entryAttributes) -and
                    (($entryAttributes -band [System.IO.FileAttributes]::Directory) -ne 0)
                ) {
                    $pending.Push($entry)
                }
            }
        } catch {
            [void]$results.Add((
                'ENUMERATION_FAILED: {0} :: {1}' -f
                (ConvertFrom-ZapfExtendedPath $path),
                $_.Exception.Message
            ))
        }
    }
    return @($results | Select-Object -Unique)
}

