function Initialize-NvidControlPanelBaseline {
        $base = 'F:\hermes\nvid\NVIDIAControlPanelBaseline'
        $current = Join-Path $base 'current'
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        if (Test-Path -LiteralPath $current) { return $current }
        $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
        $versioned = Join-Path $base $stamp
        New-Item -ItemType Directory -Path $versioned -Force | Out-Null
        $paths = @(
            'C:\ProgramData\NVIDIA Corporation\Drs',
            'C:\ProgramData\NVIDIA Corporation\NVIDIA App\NvBackend\config.xml',
            'C:\ProgramData\NVIDIA Corporation\NVIDIA App\NvConfig',
            'C:\ProgramData\NVIDIA Corporation\NVIDIA App\AcceptedEULA.txt',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\storage.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\overrides.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\config.xml',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\batteryboost2.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\nis2settings.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\QuietMode2SupportState.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\SHIM.json'
        )
        $copied = @()
        foreach($p in $paths) {
            if (Test-Path -LiteralPath $p) {
                $rel = ($p -replace '^[A-Za-z]:\\','') -replace '[\\/:*?""<>|]','_'
                $dest = Join-Path $versioned $rel
                if (Test-Path -LiteralPath $p -PathType Container) { Copy-Item -LiteralPath $p -Destination $dest -Recurse -Force }
                else { New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force | Out-Null; Copy-Item -LiteralPath $p -Destination $dest -Force }
                $copied += $p
            }
        }
        try { & reg.exe export 'HKCU\Software\NVIDIA Corporation' (Join-Path $versioned 'HKCU_NVIDIA_Corporation.reg') /y 2>$null | Out-Null } catch {}
        try { & reg.exe export 'HKLM\SOFTWARE\NVIDIA Corporation' (Join-Path $versioned 'HKLM_NVIDIA_Corporation.reg') /y 2>$null | Out-Null } catch {}
        $manifest = [ordered]@{ Created = (Get-Date).ToString('o'); BaselineRoot = $versioned; Copied = $copied; PortableRoot = $base }
        $manifest | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $versioned 'manifest.json') -Encoding UTF8
        Copy-Item -LiteralPath $versioned -Destination $current -Recurse -Force
        Write-NvidStep ("captured NVIDIA Control Panel/NVIDIA App settings baseline on F drive: {0}" -f $current)
        return $current
    }

function Initialize-ProfileCommandModeFunctions {
    if (-not $script:ProfileIsCommandMode) { return }

    $proxy = {
        $calledName = $MyInvocation.MyCommand.Name
        if (-not $calledName -or $calledName -eq '&') { $calledName = $MyInvocation.InvocationName }
        if (-not $calledName -or $calledName -eq '&') { throw 'Full profile proxy could not determine the command name to reload.' }

        $lookupName = $calledName -replace '^(?i:global:)', ''
        foreach ($sourcePath in Get-ProfileFunctionSourcePaths) {
            $functionMap = Get-ProfileFunctionMap -ProfilePath $sourcePath
            if (-not $functionMap.ContainsKey($lookupName)) { continue }
            . ([scriptblock]::Create("function global:$lookupName $($functionMap[$lookupName].Body.Extent.Text)"))
            $targetCommand = Get-Command $lookupName -CommandType Function -ErrorAction Stop
            & $targetCommand @args
            return
        }

        Write-Host "Function '$calledName' unavailable: no source definition was found." -ForegroundColor Yellow
    }

    $skip = @('Load-FullPowerShellProfile', 'fullprofile', 'nomouse', 'ps527', 'pps527', 'Get-ProfileFunctionMap', 'Get-ProfileFunctionSourcePaths', 'cfun', 'Repair-StandardWindowsProcessEnvironment',  'Initialize-FastProfilePsReadLineHistory', 'Initialize-ProfileCommandModeFunctions')
    foreach ($sourcePath in @($PROFILE)) {
        if ([string]::IsNullOrWhiteSpace($sourcePath) -or -not (Test-Path -LiteralPath $sourcePath -PathType Leaf)) { continue }
        $functionMap = Get-ProfileFunctionMap -ProfilePath $sourcePath
        foreach ($functionName in $functionMap.Keys) {
            $lookupName = $functionName -replace '^(?i:global:)', ''
            if ($lookupName -in $skip) { continue }
            if (Get-Command $lookupName -CommandType Function -ErrorAction SilentlyContinue) { continue }
            Set-Item -Path "Function:\global:$lookupName" -Value $proxy -Force
        }
    }
}

