function Invoke-AfitgirlAria2Rpc {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string] $Method,
        $Params = @(),
        [int] $TimeoutSec = 15
    )

    $configPath = Join-Path $env:APPDATA 'com.fitlauncher.carrotrub\config.json'
    $port = 6899
    $token = $null
    if (Test-Path -LiteralPath $configPath -PathType Leaf) {
        try {
            $cfg = Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json
            if ($cfg.rpc -and $cfg.rpc.port) { $port = [int]$cfg.rpc.port }
            if ($cfg.rpc -and $cfg.rpc.token) { $token = '' + $cfg.rpc.token }
        } catch {}
    }
    $p = @($Params)
    if ($token) { $p = @('token:' + $token) + $p }
    $body = @{ jsonrpc = '2.0'; id = ('afitgirl-' + [guid]::NewGuid().ToString('N')); method = $Method; params = $p } | ConvertTo-Json -Depth 64 -Compress
    $curl = Join-Path $env:SystemRoot 'System32\curl.exe'
    $effectiveTimeout = [Math]::Max(60, $TimeoutSec)
    $resp = Invoke-RestMethod -Uri ("http://127.0.0.1:{0}/jsonrpc" -f $port) -Method Post -ContentType 'application/json' -Body ([string]$body) -TimeoutSec $effectiveTimeout
    return ,$resp
}

