function Invoke-AfitgirlPythonProcess {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string] $FilePath,
        [Parameter(Mandatory=$true)][string[]] $Arguments,
        [Parameter(Mandatory=$true)][string] $WorkingDirectory,
        [int] $TimeoutSeconds = 900
    )

    $outFile = Join-Path $env:TEMP ("afitgirl_stdout_{0}.log" -f ([guid]::NewGuid().ToString('N')))
    $errFile = Join-Path $env:TEMP ("afitgirl_stderr_{0}.log" -f ([guid]::NewGuid().ToString('N')))
    $argText = (($Arguments | ForEach-Object { ConvertTo-AfitgirlCommandLineArgument $_ }) -join ' ')
    $proc = Start-Process -FilePath $FilePath -ArgumentList $argText -WorkingDirectory $WorkingDirectory -NoNewWindow -RedirectStandardOutput $outFile -RedirectStandardError $errFile -PassThru
    try {
        if (-not $proc.WaitForExit($TimeoutSeconds * 1000)) {
            try { Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue } catch {}
            if (Test-Path -LiteralPath $outFile) { Get-Content -LiteralPath $outFile -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ } }
            if (Test-Path -LiteralPath $errFile) { Get-Content -LiteralPath $errFile -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ } }
            throw "afitgirl queue command timed out after $TimeoutSeconds seconds; returned control to PowerShell and reran speed/auto-install repair."
        }
        $stdout = if (Test-Path -LiteralPath $outFile) { Get-Content -LiteralPath $outFile -ErrorAction SilentlyContinue } else { @() }
        $stderr = if (Test-Path -LiteralPath $errFile) { Get-Content -LiteralPath $errFile -ErrorAction SilentlyContinue } else { @() }
        $stdout | ForEach-Object { Write-Host $_ }
        $stderr | ForEach-Object { Write-Host $_ }
        $code = [int]$proc.ExitCode
        $combined = (($stdout + $stderr) -join "`n")
        if ($code -eq 0 -and ($combined -match 'fit_download_list\.py: error:|Traceback|SyntaxError|RuntimeError|failed with exit code|Fit Launcher manager queue failed|falling back to aria2 direct queue|manager verification failed|(?m)^- .+: MISSING\b|SKIPPED_METADATA_TIMEOUT|SKIPPED_LEGACY_MAGNET|NO_MAGNET|RPC_PENDING|Connection timed out|timed out after|aria2 RPC is not reachable')) {
            $code = 4
        }
        $global:LASTEXITCODE = $code
        return $code
    }
    finally {
        Remove-Item -LiteralPath $outFile,$errFile -Force -ErrorAction SilentlyContinue
    }
}

function Invoke-AfitgirlVisibleDownloadsRepair {
    [CmdletBinding()]
    param([string] $Reason = 'post-queue visible Downloads repair')

    $tool = 'F:\study\Windows\Applications\Gaming\Launchers\FitLauncher\Automation\fit-download-list-terminal\tools\fit_download_list.py'
    $fitLauncher = 'F:\backup\windowsapps\installed\Fit Launcher\Fit Launcher.exe'
    if (-not (Test-Path -LiteralPath $tool -PathType Leaf)) { return }
    if (-not (Test-Path -LiteralPath $fitLauncher -PathType Leaf)) { return }
    $py = Get-Command py.exe -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $py) { return }

    $oldEncoding = $env:PYTHONIOENCODING
    $oldLimit = $env:AFITGIRL_REHYDRATE_LIMIT
    $env:PYTHONIOENCODING = 'utf-8'
    $env:AFITGIRL_REHYDRATE_LIMIT = '16'
    $code = @'
from pathlib import Path
import sys
sys.path.insert(0, r"F:\study\Windows\Applications\Gaming\Launchers\FitLauncher\Automation\fit-download-list-terminal\tools")
import fit_download_list as f

try:
    if not f.webview_debug_available(9223):
        f.ensure_fit_launcher_debug(Path(r"F:\backup\windowsapps\installed\Fit Launcher\Fit Launcher.exe"), 9223, restart=True, timeout=35)
    changed = f.rehydrate_paused_manager_jobs_via_aria2("http://127.0.0.1:6899/jsonrpc")
    synced = f.sync_manager_status_from_aria2("http://127.0.0.1:6899/jsonrpc")
    try:
        f.force_downloads_tab_visible(9223)
    except Exception as exc:
        print(f"[afitgirl] Downloads-tab navigation warning: {exc}")
    f.force_downloads_ui_active_from_aria2("http://127.0.0.1:6899/jsonrpc", port=9223)
    client = f.TauriClient(9223)
    try:
        body = client.cdp("Runtime.evaluate", {"expression": "document.body.innerText", "returnByValue": True})
        text = str(body.get("result", {}).get("result", {}).get("value") or "")
        print(f"[afitgirl] visible Downloads repair: reason=live-refresh; changed={changed}; synced={synced}; resume={text.count('RESUME')}; pause={text.count('PAUSE')}; ready_empty={'Ready for Downloads' in text}")
    finally:
        client.close()
except Exception as exc:
    print(f"[afitgirl] visible Downloads repair warning: {exc}")
'@
    try {
        $visibleRepairFile = Join-Path $env:TEMP ('afitgirl_visible_repair_{0}.py' -f ([guid]::NewGuid().ToString('N')))
        try {
            Set-Content -LiteralPath $visibleRepairFile -Value $code -Encoding UTF8 -Force
            & $py.Source -3 $visibleRepairFile
        } finally {
            Remove-Item -LiteralPath $visibleRepairFile -Force -ErrorAction SilentlyContinue
        }
    } finally {
        if ($null -eq $oldEncoding) { Remove-Item Env:\PYTHONIOENCODING -ErrorAction SilentlyContinue } else { $env:PYTHONIOENCODING = $oldEncoding }
        if ($null -eq $oldLimit) { Remove-Item Env:\AFITGIRL_REHYDRATE_LIMIT -ErrorAction SilentlyContinue } else { $env:AFITGIRL_REHYDRATE_LIMIT = $oldLimit }
    }
}

