function Invoke-BackupDockerInstalledAppRestore {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Name)
    if ($Name -ieq 'todoist') {
        & 'F:\study\Platforms\windows\functions\Invoke-TodoistDockerRestore.ps1'
        return
    }
    $ErrorActionPreference='Stop'
    if([IO.Path]::GetFileName($Name) -ne $Name -or $Name -in @('.','..')){throw 'Invalid installed-app name'}
    $root='F:\backup\windowsapps\installed'
    $target=[IO.Path]::GetFullPath((Join-Path $root $Name))
    if([IO.Path]::GetDirectoryName($target) -ne $root){throw 'Restore target escaped installed-app root'}
    $dockerExe='C:\Program Files\Docker\Docker\resources\bin\docker.exe'
    # Per-app backup images are published as michadockermisha/<app> (the menu
    # folder-leaf slug), not as michadockermisha/windowsapps-installed-<app>.
    # Resolving by the app name keeps restore pointing at the real per-app repo
    # (e.g. michadockermisha/todoist) instead of a nonexistent prefixed repo.
    $repoSlug=Get-BackupDockerRepoSlug -Name $Name
    $remoteTag=Get-BackupDockerLatestRemoteTag -RepoSlug $repoSlug
    $imageRef="michadockermisha/${repoSlug}:$remoteTag"
    $localImage = @(& $dockerExe image ls --quiet $imageRef)
    # Pull even when cached so the repository remains the authoritative source.
    if($true){
        Write-Host "RESTORE_PROGRESS app=$Name stage=pulling image=$imageRef"
        & $dockerExe pull $imageRef | Out-Host
        if($LASTEXITCODE -ne 0){throw "Docker image pull failed for $Name; existing app preserved"}
    }
    $id=[guid]::NewGuid().ToString('N')
    $stage=Join-Path $root ('.docker-restore-'+$Name+'-'+$id)
    $backup=Join-Path $root ('.docker-previous-'+$Name+'-'+$id)
    $container='app-restore-'+$id
    $created=$false
    $movedPrevious=$false
    try {
        $containerId=& $dockerExe create --name $container $imageRef
        if($LASTEXITCODE -ne 0 -or -not $containerId){throw 'Docker restore container creation failed'}
        $created=$true
        [void][IO.Directory]::CreateDirectory($stage)
        Write-Host "RESTORE_PROGRESS app=$Name stage=copying-complete-payload"
        & $dockerExe cp ($container+':/home/.') $stage | Out-Host
        if($LASTEXITCODE -ne 0){throw "Docker payload copy failed for $Name"}
        $files=@(Get-ChildItem -LiteralPath $stage -File -Recurse -Force)
        if(-not $files.Count){throw "Docker image contained no app files for $Name"}
        if($Name -eq 'driverbooster' -and -not @($files | Where-Object Name -eq 'DriverBooster.exe').Count){throw 'DriverBooster.exe is missing from the image'}
        if($Name -eq 'ccleaner' -and -not [IO.File]::Exists((Join-Path $stage 'CCleaner64.exe'))){throw 'CCleaner64.exe is missing from the image'}
        $launchNames = @{
            chrome='chrome.exe'; firefox='firefox.exe'; driverbooster='DriverBooster.exe'
            playnite='Playnite.DesktopApp.exe'; revouninstaller='RevoUninPro.exe'
            stremio='stremio.exe'; ccleaner='CCleaner64.exe'; MacriumReflect='Reflect.exe'
        }
        $launchRelative = $null
        if ($launchNames.ContainsKey($Name)) {
            $launchFiles = @($files | Where-Object Name -ieq $launchNames[$Name])
            if ($launchFiles.Count -ne 1) { throw "Docker Hub payload for $Name must contain one unambiguous $($launchNames[$Name]); current app retained." }
            $launchRelative = $launchFiles[0].FullName.Substring($stage.Length + 1)
        } else { throw "No app launcher is configured for $Name; current app retained rather than reporting a file-only restore as ready." }
        foreach ($dataFolder in @('UserData','user_data','user-data','data','profile','profiles','portable_config')) {
            $savedData = Join-Path $target $dataFolder
            if (Test-Path -LiteralPath $savedData -PathType Container) {
                if ((Get-Item -LiteralPath $savedData -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Refusing redirected session data.' }
                & "$env:SystemRoot\System32\robocopy.exe" $savedData (Join-Path $stage $dataFolder) /MIR /COPY:DAT /DCOPY:DAT /R:2 /W:1 /NFL /NDL /NJH /NJS /NP | Out-Null
                if ($LASTEXITCODE -ge 8) { throw "Saved profile preservation failed for $Name" }
            }
        }
        if(Test-Path -LiteralPath $target){
            if((Get-Item -LiteralPath $target -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Restore refuses a redirected app directory'}
            [IO.Directory]::Move($target,$backup)
            $movedPrevious=$true
        }
        try{[IO.Directory]::Move($stage,$target)}catch{
            if($movedPrevious -and -not (Test-Path -LiteralPath $target)){[IO.Directory]::Move($backup,$target);$movedPrevious=$false}
            throw
        }
        $launchPath = Join-Path $target $launchRelative
        $launchOptions = @{FilePath=$launchPath;WorkingDirectory=(Split-Path -Parent $launchPath)}
        if ($Name -ieq 'chrome') {
            $launchOptions.FilePath = 'C:\Program Files\Google\Chrome\Application\chrome.exe'
            $launchOptions.ArgumentList = '--profile-directory="Profile 2"'
        }
        Start-Process @launchOptions -ErrorAction Stop | Out-Null
        $deadline=(Get-Date).AddSeconds(60)
        do {
            $readyProcess=Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Path -and $_.Path -ieq $launchOptions.FilePath -and $_.MainWindowHandle -ne 0 -and $_.Responding } | Select-Object -First 1
            if ($readyProcess) { break }
            Start-Sleep -Milliseconds 500
        } while ((Get-Date) -lt $deadline)
        if (-not $readyProcess) { throw "$Name restored but its app window did not become ready; previous installation retained." }
        Write-Host "RESTORE_APP_OPEN app=$Name pid=$($readyProcess.Id) image=$imageRef session=preserved login=unverified"
        if($movedPrevious){Write-Host "RESTORE_PREVIOUS_APP=$backup"}
    } finally {
        if($created){& $dockerExe rm $container *> $null}
        if(Test-Path -LiteralPath $stage){
            if([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($stage)) -ne $root){throw 'Invalid stage cleanup path'}
            Microsoft.PowerShell.Management\Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction Stop
        }
    }
}

