function Invoke-BackupMenuForPath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Path,

        [switch]$LegacySharedRepo
    )

    Initialize-BackupDockerEnvironment

    try {
        $projectPath = Resolve-BackupDockerProjectPath -Path $Path
    } catch {
        Write-Error $_.Exception.Message
        return $false
    }

    if ($LegacySharedRepo) {
        $folderName = Split-Path -Leaf $projectPath
        $imageRef = "michadockermisha/backup:$folderName"
        return (Invoke-BackupMenuBuildPush -ProjectPath $projectPath -ImageRef $imageRef -EnsureRepositoryName 'backup')
    }

    $repoSlug = Get-BackupMenuRepoSlug -Path $projectPath
    $repository = Get-BackupDockerRepositoryFromSlug -RepoSlug $repoSlug
    $imageRef = "${repository}:$(New-BackupDockerTag -RepoSlug $repoSlug)"
    $succeeded = Invoke-BackupMenuBuildPush -ProjectPath $projectPath -ImageRef $imageRef -EnsureRepositorySlug $repoSlug
    if ($succeeded) {
        Register-BackupDockerSourcePath -RepoSlug $repoSlug -Path $projectPath
    }
    return $succeeded
}

function Invoke-BackupMenuLogged {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$FunctionName
    )

    if (-not $Path) { Write-Error "Usage: $FunctionName <path>"; return }

    Register-BackupMenuInvocation -Path $Path -FunctionName $FunctionName
    $details = Get-BackupMenuInvocationDetails -FunctionName $FunctionName

    if ($details.LegacySharedRepo) {
        [void](Invoke-BackupMenuForPath -Path $Path -LegacySharedRepo)
        return
    }

    if ($details.Layer -le 1) {
        [void](Invoke-BackupMenuForPath -Path $Path)
        return
    }

    Invoke-BackupMenuAtLayer -Path $Path -Layer $details.Layer -SchemaVersion $details.SchemaVersion
}

function Invoke-Bounded {
    param([string]$FilePath, [string[]]$ArgumentList, [int]$Milliseconds = 5000)
    $result = [pscustomobject]@{ ExitCode = 1; Stdout = ''; Stderr = ''; TimedOut = $false }
    if ([string]::IsNullOrWhiteSpace($FilePath) -or -not (Test-Path -LiteralPath $FilePath)) {
        $result.Stderr = 'executable not found'
        return $result
    }
    $tempRoot = 'C:\Temp'
    try { if (-not (Test-Path -LiteralPath $tempRoot)) { New-Item -ItemType Directory -Path $tempRoot -Force -ErrorAction Stop | Out-Null } } catch { }
    $outFile = Join-Path $tempRoot ('dkill-out-' + [guid]::NewGuid().ToString('N') + '.log')
    $errFile = Join-Path $tempRoot ('dkill-err-' + [guid]::NewGuid().ToString('N') + '.log')
    try {
        $process = Start-Process -FilePath $FilePath -ArgumentList $ArgumentList -WindowStyle Hidden -PassThru -RedirectStandardOutput $outFile -RedirectStandardError $errFile -ErrorAction Stop
        if (-not $process.WaitForExit([Math]::Max(250, $Milliseconds))) {
            try { $process.Kill() } catch { }
            $result.ExitCode = 124
            $result.TimedOut = $true
            $result.Stderr = 'timed out'
            return $result
        }
        $result.ExitCode = [int]$process.ExitCode
        try { $result.Stdout = (Get-Content -LiteralPath $outFile -Raw -ErrorAction Stop).Trim() } catch { }
        try { $result.Stderr = (Get-Content -LiteralPath $errFile -Raw -ErrorAction Stop).Trim() } catch { }
        return $result
    } catch {
        $result.Stderr = $_.Exception.Message
        return $result
    } finally {
        foreach ($file in @($outFile, $errFile)) { try { Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue } catch { } }
    }
}

function Invoke-CcccTurboOriginalProfileChild {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [int]$TimeoutSeconds = 45,
        [object[]]$Arguments = @(),
        [string]$ProfileLibrary = 'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\Microsoft.PowerShell_profile.full.definitions.ps1'
    )
    $ps5 = Join-Path ([Environment]::SystemDirectory) 'WindowsPowerShell\v1.0\powershell.exe'
    if (-not (Test-Path -LiteralPath $ps5 -PathType Leaf)) {
        throw "Windows PowerShell 5 executable not found: $ps5"
    }
    if (-not (Test-Path -LiteralPath $ProfileLibrary -PathType Leaf)) {
        $ProfileLibrary = 'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\Microsoft.PowerShell_profile.full.ps1'
    }
    if (-not (Test-Path -LiteralPath $ProfileLibrary -PathType Leaf)) {
        throw "Full profile definitions not found: $ProfileLibrary"
    }
    $stdoutPath = Join-Path $env:TEMP ("ccccturbo-{0}-{1}-stdout.log" -f $Name, ([guid]::NewGuid().ToString('N')))
    $stderrPath = Join-Path $env:TEMP ("ccccturbo-{0}-{1}-stderr.log" -f $Name, ([guid]::NewGuid().ToString('N')))
    $escapedName = $Name -replace "'", "''"
    $escapedProfileLibrary = $ProfileLibrary -replace "'", "''"
    $normalizedArguments = @()
    foreach ($argument in $Arguments) {
        if ($argument -is [System.Array]) {
            $normalizedArguments += @($argument)
        } else {
            $normalizedArguments += $argument
        }
    }
    $argumentJson = if ($normalizedArguments.Count -gt 0) { ConvertTo-Json -InputObject $normalizedArguments -Depth 10 -Compress } else { '[]' }
    $escapedArgumentJson = $argumentJson -replace "'", "''"
    $childScript = @"
`$ErrorActionPreference = 'Stop'
`$ProgressPreference = 'SilentlyContinue'
`$global:LASTEXITCODE = `$null
`$name = '$escapedName'
`$profileLibrary = '$escapedProfileLibrary'
`$argumentJson = '$escapedArgumentJson'
try {
    if (-not (Test-Path -LiteralPath `$profileLibrary -PathType Leaf)) { throw "missing full profile library: `$profileLibrary" }
    `$tokens = `$null
    `$errors = `$null
    `$ast = [System.Management.Automation.Language.Parser]::ParseFile(`$profileLibrary, [ref]`$tokens, [ref]`$errors)
    if (`$errors -and `$errors.Count -gt 0) { throw ("parse errors in full profile library: {0}" -f ((`$errors | Select-Object -First 3 | ForEach-Object { `$_.Message }) -join '; ')) }
    `$functionAst = `$ast.Find({ param(`$node) `$node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and `$node.Name -ieq `$name }, `$true)
    if (-not `$functionAst) { throw "missing function `$name in full profile library" }
    . ([scriptblock]::Create("function global:`$name `$(`$functionAst.Body.Extent.Text)"))
    `$forwardedArguments = @()
    if (`$argumentJson -ne '[]') {
        foreach (`$argument in (ConvertFrom-Json -InputObject `$argumentJson)) {
            `$forwardedArguments += `$argument
        }
    }
    & `$name @forwardedArguments
    `$childExitCode = if (`$null -ne `$global:LASTEXITCODE) { [int]`$global:LASTEXITCODE } else { 0 }
    [Console]::Error.WriteLine("__CCCC_TURBO_EXIT__=`$childExitCode")
    exit `$childExitCode
} catch {
    [Console]::Error.WriteLine(`$_.Exception.Message)
    [Console]::Error.WriteLine('__CCCC_TURBO_EXIT__=1')
    exit 1
}
"@
    $encodedCommand = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($childScript))
    $commandLabel = "-EncodedCommand <ast-extract:$Name from $ProfileLibrary>"
    $timeoutLabel = if ($TimeoutSeconds -le 0) { 'none' } else { ('{0}s' -f $TimeoutSeconds) }
    Write-Host ("{0}: running generated profile function in PS5 child via AST extraction: {1} -NoLogo -NoProfile -ExecutionPolicy Bypass {2} (timeout={3})" -f $Name,$ps5,$commandLabel,$timeoutLabel) -ForegroundColor Cyan
    try {
        $process = Start-Process -FilePath $ps5 -ArgumentList @('-NoLogo','-NoProfile','-ExecutionPolicy','Bypass','-OutputFormat','Text','-EncodedCommand',$encodedCommand) -WindowStyle Hidden -PassThru -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -ErrorAction Stop
        $timedOut = $false
        if ($TimeoutSeconds -le 0) {
            $process.WaitForExit()
        } else {
            $watch = [Diagnostics.Stopwatch]::StartNew()
            while (-not $process.HasExited) {
                Start-Sleep -Seconds 2
                Write-Host ("{0}: still running elapsed={1:n0}s command={2} -NoLogo -NoProfile -ExecutionPolicy Bypass {3}" -f $Name,$watch.Elapsed.TotalSeconds,$ps5,$commandLabel)
                if ($watch.Elapsed.TotalSeconds -ge $TimeoutSeconds) {
                    $timedOut = $true
                    $taskkill = Join-Path $env:WINDIR 'System32\taskkill.exe'
                    try { & $taskkill /PID $process.Id /T /F 2>$null | Out-Null } catch { try { Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue } catch { } }
                    Write-Host ("{0}: timed out after {1}s; child process tree ended." -f $Name,$TimeoutSeconds) -ForegroundColor Yellow
                    break
                }
            }
        }
        $reportedExitCode = $null
        foreach ($path in @($stdoutPath,$stderrPath)) {
            if (Test-Path -LiteralPath $path -PathType Leaf) {
                Get-Content -LiteralPath $path -ErrorAction SilentlyContinue | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object {
                    if ($_ -match '^__CCCC_TURBO_EXIT__=(-?\d+)$') {
                        $reportedExitCode = [int]$Matches[1]
                    } else {
                        Write-Host ("{0}: {1}" -f $Name,$_)
                    }
                }
            }
        }
        $process.Refresh()
        $exitCode = if ($timedOut) { 146 } elseif ($null -ne $reportedExitCode) { $reportedExitCode } elseif ($process.HasExited -and $null -ne $process.ExitCode) { [int]$process.ExitCode } elseif ($process.HasExited) { 0 } else { 1 }
        $global:LASTEXITCODE = $exitCode
        if ($exitCode -ne 0) {
            Write-Host ("{0}: child exit={1}" -f $Name,$exitCode) -ForegroundColor Yellow
            throw ("{0}: child process failed with exit code {1}" -f $Name,$exitCode)
        }
    } catch {
        $global:LASTEXITCODE = 1
        throw
    } finally {
        Remove-Item -LiteralPath $stdoutPath,$stderrPath -Force -ErrorAction SilentlyContinue
    }
}

function Invoke-ChainedCommand {
    param([string]$Line)
    $segments = [regex]::Split($Line, '(?<!["''])(?:&&|\|\|)(?![^"'']*["''])')
    $operators = [regex]::Matches($Line, '(?<!["''])(&&|\|\|)(?![^"'']*["''])')
    $lastSuccess = $true
    for ($i = 0; $i -lt $segments.Count; $i++) {
        $seg = $segments[$i].Trim()
        if ([string]::IsNullOrWhiteSpace($seg)) { continue }
        if ($i -gt 0) {
            $op = $operators[$i - 1].Groups[1].Value
            if ($op -eq '&&' -and -not $lastSuccess) { continue }
            if ($op -eq '||' -and $lastSuccess) { continue }
        }
        try {
            Invoke-Expression $seg
            $lastSuccess = $LASTEXITCODE -eq 0 -and $?
        } catch {
            $lastSuccess = $false
        }
    }
}

function Invoke-CleancDeleteOneLocal {
        param([Parameter(Mandatory=$true)]$Item,[Parameter(Mandatory=$true)][string]$FallbackPath)
        $path = $Item.FullName
        $method = 'Failed'
        $escalated = $false
        try {
            $current = (Get-Location).ProviderPath
            if ($current) {
                $cur = [System.IO.Path]::GetFullPath($current).TrimEnd('\')
                $target = [System.IO.Path]::GetFullPath($path).TrimEnd('\')
                if ($cur.Equals($target,[System.StringComparison]::OrdinalIgnoreCase) -or $cur.StartsWith($target + '\',[System.StringComparison]::OrdinalIgnoreCase)) { Set-Location -LiteralPath $FallbackPath }
            }
        } catch {}
        if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Already absent.';Method='NoOp';PermissionEscalated=$false} }
        $quoted = '"' + $path + '"'
        $attempts = @()
        if ($Item.IsReparsePoint) {
            if ($Item.IsDirectory) { $attempts += @("rmdir $quoted >nul 2>&1") } else { $attempts += @("del /f /q $quoted >nul 2>&1") }
        } elseif ($Item.IsDirectory) {
            $attempts += @("rd /s /q $quoted >nul 2>&1")
        } else {
            $attempts += @("del /f /q $quoted >nul 2>&1")
        }
        foreach ($cmd in $attempts) { try { Invoke-CleancNativeLocal $cmd } catch {}; if (Test-CleancGoneLocal $path) { $method='QuickNative'; return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted with quick native delete.';Method=$method;PermissionEscalated=$false} } }
        try { if ($Item.IsDirectory -and -not $Item.IsReparsePoint) { Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop } else { Remove-Item -LiteralPath $path -Force -ErrorAction Stop } } catch {}
        if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted with Remove-Item.';Method='RemoveItem';PermissionEscalated=$false} }

        try {
            if ($Item.IsDirectory -and -not $Item.IsReparsePoint) {
                Invoke-CleancNativeLocal ("takeown /f $quoted /r /d y >nul 2>&1")
                Invoke-CleancNativeLocal ("icacls $quoted /grant `"$env:USERNAME`":F /t /c /q >nul 2>&1")
                Invoke-CleancNativeLocal ("icacls $quoted /grant Administrators:F /t /c /q >nul 2>&1")
                Invoke-CleancNativeLocal ("attrib -r -h -s $quoted /s /d >nul 2>&1")
            } else {
                Invoke-CleancNativeLocal ("takeown /f $quoted >nul 2>&1")
                Invoke-CleancNativeLocal ("icacls $quoted /grant `"$env:USERNAME`":F /c /q >nul 2>&1")
                Invoke-CleancNativeLocal ("icacls $quoted /grant Administrators:F /c /q >nul 2>&1")
                Invoke-CleancNativeLocal ("attrib -r -h -s $quoted >nul 2>&1")
            }
            $escalated = $true
        } catch {}
        try { if ($Item.IsDirectory) { Invoke-CleancNativeLocal ("rd /s /q $quoted >nul 2>&1") } else { Invoke-CleancNativeLocal ("del /f /q $quoted >nul 2>&1") } } catch {}
        if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted after ACL/attribute escalation.';Method='EscalatedNative';PermissionEscalated=$escalated} }
        try { if ($Item.IsDirectory -and -not $Item.IsReparsePoint) { Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop } else { Remove-Item -LiteralPath $path -Force -ErrorAction Stop } } catch {}
        if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted after escalation with Remove-Item.';Method='EscalatedRemoveItem';PermissionEscalated=$escalated} }
        if ($Item.IsDirectory -and -not $Item.IsReparsePoint) {
            try {
                $empty = Join-Path ([System.IO.Path]::GetTempPath()) ('cleanc-empty-' + [guid]::NewGuid().ToString('N'))
                New-Item -ItemType Directory -Path $empty -Force | Out-Null
                Invoke-CleancNativeLocal ("robocopy `"$empty`" $quoted /MIR /XJ /R:0 /W:0 /NFL /NDL /NJH /NJS /NC /NS >nul 2>&1")
                Remove-Item -LiteralPath $empty -Recurse -Force -ErrorAction SilentlyContinue
                Invoke-CleancNativeLocal ("rd /s /q $quoted >nul 2>&1")
            } catch {}
            if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted after robocopy mirror reset.';Method='RobocopyReset';PermissionEscalated=$escalated} }
        }
        return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$false;Reason='Item still exists after quick delete, Remove-Item, ACL/attribute escalation, and robocopy reset.';Method='Failed';PermissionEscalated=$escalated}
    }

function Invoke-CleancNativeLocal {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][string]$CommandLine)

    if ([string]::IsNullOrWhiteSpace($CommandLine)) {
        throw 'cleanc native command line is empty.'
    }

    Write-Host ("CLEANC_PROGRESS stage=native-command command={0}" -f $CommandLine) -ForegroundColor DarkCyan
    $output = & $env:ComSpec /d /c $CommandLine 2>&1
    $exitCode = $LASTEXITCODE
    if ($output) {
        $output | ForEach-Object { Write-Host ("CLEANC_NATIVE_OUTPUT {0}" -f $_) }
    }
    if ($exitCode -ne 0) {
        $message = "CLEANC_NATIVE_FAIL exit_code=$exitCode command=$CommandLine"
        Write-Host $message -ForegroundColor Yellow
        throw $message
    }

    Write-Host ("CLEANC_NATIVE_OK command={0}" -f $CommandLine) -ForegroundColor Green
    return $true
}

