function Invoke-DKillFastBoundedDocker {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$DockerExe,[Parameter(Mandatory)][string[]]$DockerArgs,[ValidateRange(1,120)][int]$Seconds = 4)

    if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)) {
        Write-DKillFastLine ("DKILL_DOCKER_CMD_FAIL executable not found: {0}" -f $DockerExe) Red
        return 127
    }
    $tempRoot = 'C:\Temp'
    try { if(-not (Test-Path -LiteralPath $tempRoot)){ New-Item -ItemType Directory -Path $tempRoot -Force -ErrorAction Stop | Out-Null } } catch { Write-DKillFastLine ("DKILL_DOCKER_CMD_FAIL temp root: {0}" -f $_.Exception.Message) Red; return 1 }
    $outFile = Join-Path $tempRoot ('dkill-docker-out-' + [guid]::NewGuid().ToString('N') + '.log')
    $errFile = Join-Path $tempRoot ('dkill-docker-err-' + [guid]::NewGuid().ToString('N') + '.log')
    $label = 'docker ' + ($DockerArgs -join ' ')
    Write-Progress -Activity 'Docker command' -Status $label -PercentComplete 20
    try {
        $process = Start-Process -FilePath $DockerExe -ArgumentList $DockerArgs -WindowStyle Hidden -PassThru -RedirectStandardOutput $outFile -RedirectStandardError $errFile -ErrorAction Stop
        Write-Progress -Activity 'Docker command' -Status ("Waiting up to {0}s" -f $Seconds) -PercentComplete 60
        if(-not $process.WaitForExit($Seconds * 1000)) {
            try { $process.Kill() } catch { Write-DKillFastLine ("DKILL_DOCKER_CMD_WARN timeout kill failed: {0}" -f $_.Exception.Message) Yellow }
            Write-DKillFastLine ("DKILL_DOCKER_CMD_TIMEOUT command={0} seconds={1}" -f $label,$Seconds) Yellow
            return 124
        }
        foreach($file in @($outFile,$errFile)) {
            if(Test-Path -LiteralPath $file) {
                try { Get-Content -LiteralPath $file -ErrorAction Stop | Select-Object -Last 12 | ForEach-Object { if(-not [string]::IsNullOrWhiteSpace([string]$_)){ Write-DKillFastLine ([string]$_) DarkGray } } }
                catch { Write-DKillFastLine ("DKILL_DOCKER_CMD_WARN output read failed: {0}" -f $_.Exception.Message) Yellow }
            }
        }
        $exitCode = [int]$process.ExitCode
        Write-DKillFastLine ("DKILL_DOCKER_CMD_{0} command={1} exit={2}" -f $(if($exitCode -eq 0){'OK'}else{'FAIL'}),$label,$exitCode) $(if($exitCode -eq 0){'Green'}else{'Yellow'})
        return $exitCode
    } catch {
        Write-DKillFastLine ("DKILL_DOCKER_CMD_FAIL command={0}: {1}" -f $label,$_.Exception.Message) Red
        return 1
    } finally {
        Write-Progress -Activity 'Docker command' -Completed
        foreach($file in @($outFile,$errFile)) { if(Test-Path -LiteralPath $file){ try { Remove-Item -LiteralPath $file -Force -ErrorAction Stop } catch { Write-DKillFastLine ("DKILL_DOCKER_CMD_WARN temp cleanup failed for {0}: {1}" -f $file,$_.Exception.Message) Yellow } } }
    }
}

function Invoke-DKillFastBoundedRemove {
