function Invoke-DKillFastSc {
    [CmdletBinding()]
    param([ValidateSet('start', 'stop')][string]$Action, [string]$ServiceName, [int]$Milliseconds = 900)

    $sc = Join-Path $env:SystemRoot 'System32\sc.exe'
    if (-not (Test-Path -LiteralPath $sc -PathType Leaf)) {
        Write-DKillFastLine "sc.exe missing: $sc" Red
        return $false
    }
    if ([string]::IsNullOrWhiteSpace($ServiceName)) {
        Write-DKillFastLine 'sc.exe skipped: empty service name' Yellow
        return $false
    }
    try {
        $process = Start-Process -FilePath $sc -ArgumentList @($Action, $ServiceName) -PassThru -WindowStyle Hidden -ErrorAction Stop
        if (-not $process.WaitForExit([Math]::Max(100, $Milliseconds))) {
            try { $process.Kill() } catch { Write-DKillFastLine ("sc timeout kill warning service={0} error={1}" -f $ServiceName, $_.Exception.Message) Yellow }
            Write-DKillFastLine ("sc timed out action={0} service={1} budget_ms={2}" -f $Action, $ServiceName, $Milliseconds) Yellow
            return $false
        }
        if ($process.ExitCode -ne 0) {
            Write-DKillFastLine ("sc failed action={0} service={1} exit_code={2}" -f $Action, $ServiceName, $process.ExitCode) Yellow
            return $false
        }
        Write-DKillFastLine ("sc completed action={0} service={1}" -f $Action, $ServiceName) Green
        return $true
    }
    catch {
        Write-DKillFastLine ("sc launch failed action={0} service={1} error={2}" -f $Action, $ServiceName, $_.Exception.Message) Yellow
        return $false
    }
}

