function Invoke-FastLiteralTransfer {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string[]]$SourcePaths,

        [Parameter(Mandatory = $true)]
        [string]$DestinationPath,

        [Parameter(Mandatory = $true)]
        [ValidateSet('Copy', 'Move')]
        [string]$Mode
    )

    if ($SourcePaths.Count -lt 1) {
        throw 'At least one source path is required.'
    }

    $destinationRoot = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($DestinationPath)
    if (-not (Test-Path -LiteralPath $destinationRoot -PathType Container)) {
        New-Item -ItemType Directory -Path $destinationRoot -Force | Out-Null
    }
    $destinationRoot = (Resolve-Path -LiteralPath $destinationRoot).ProviderPath

    $total = $SourcePaths.Count
    for ($index = 0; $index -lt $total; $index++) {
        $rawSource = $SourcePaths[$index]
        $sourcePath = Resolve-FastTransferLiteralPath -InputPath $rawSource
        $item = Get-Item -LiteralPath $sourcePath -Force
        $targetPath = Join-Path $destinationRoot $item.Name
        $sameVolume = [string]::Equals(
            [System.IO.Path]::GetPathRoot($sourcePath),
            [System.IO.Path]::GetPathRoot($destinationRoot),
            [System.StringComparison]::OrdinalIgnoreCase
        )

        if ($sourcePath.TrimEnd('\') -ieq $targetPath.TrimEnd('\')) {
            throw "Source and destination resolve to the same path: $sourcePath"
        }

        $progressPercent = [int](($index / [Math]::Max($total, 1)) * 100)
        $activity = '{0} {1} item(s)' -f $Mode, $total
        $status = '[{0}/{1}] {2} -> {3}' -f ($index + 1), $total, $sourcePath, $destinationRoot
        Write-Progress -Activity $activity -Status $status -PercentComplete $progressPercent
        Write-Host $status -ForegroundColor Cyan

        if ($Mode -eq 'Move' -and $sameVolume -and -not (Test-Path -LiteralPath $targetPath)) {
            Move-Item -LiteralPath $sourcePath -Destination $destinationRoot -Force
        } else {
            Invoke-FastTransferRobocopy -SourcePath $sourcePath -DestinationRoot $destinationRoot -Mode $Mode
        }

        if (-not (Test-Path -LiteralPath $targetPath)) {
            throw "Transfer target missing after ${Mode}: $targetPath"
        }
        if ($Mode -eq 'Copy' -and -not (Test-Path -LiteralPath $sourcePath)) {
            throw "Source disappeared during copy: $sourcePath"
        }
        if ($Mode -eq 'Move' -and (Test-Path -LiteralPath $sourcePath)) {
            if ($item.PSIsContainer) {
                $remaining = @(Get-ChildItem -LiteralPath $sourcePath -Force -ErrorAction SilentlyContinue)
                if ($remaining.Count -eq 0) {
                    Remove-Item -LiteralPath $sourcePath -Force -ErrorAction SilentlyContinue
                }
            }
            if (Test-Path -LiteralPath $sourcePath) {
                throw "Source still exists after move: $sourcePath"
            }
        }
    }

    Write-Progress -Activity ('{0} complete' -f $Mode) -Completed
}

function Invoke-FastTransferRobocopy {
    param(
        [Parameter(Mandatory = $true)]
        [string]$SourcePath,

        [Parameter(Mandatory = $true)]
        [string]$DestinationRoot,

        [Parameter(Mandatory = $true)]
        [ValidateSet('Copy', 'Move')]
        [string]$Mode
    )

    $robocopyPath = Join-Path $env:SystemRoot 'System32\robocopy.exe'
    if (-not (Test-Path -LiteralPath $robocopyPath -PathType Leaf)) {
        throw "robocopy.exe not found at $robocopyPath"
    }

    $item = Get-Item -LiteralPath $SourcePath -Force
    $targetPath = Join-Path $DestinationRoot $item.Name
    $threadCount = [Math]::Min(128, [Math]::Max(32, [Environment]::ProcessorCount * 8))

    function New-RobocopyArgumentLine {
        param([string[]]$Values)

        $quotedValues = foreach ($value in $Values) {
            if ($null -eq $value) { continue }
            if ($value -match '[\s"]') {
                '"' + $value.Replace('"', '\"') + '"'
            } else {
                $value
            }
        }
        return [string]::Join(' ', $quotedValues)
    }

    if ($item.PSIsContainer) {
        New-Item -ItemType Directory -Path $targetPath -Force | Out-Null
        $arguments = @(
            $SourcePath,
            $targetPath,
            '/E',
            '/R:0',
            '/W:0',
            '/XJ',
            ('/MT:{0}' -f $threadCount),
            '/DCOPY:DAT',
            '/COPY:DAT'
        )
        if ($Mode -eq 'Move') {
            $arguments += '/MOVE'
        }

        $argumentLine = New-RobocopyArgumentLine -Values $arguments
        $process = Start-Process -FilePath $robocopyPath -ArgumentList $argumentLine -Wait -NoNewWindow -PassThru
        $exitCode = $process.ExitCode
        if ($exitCode -gt 7) {
            throw "robocopy directory $Mode failed with exit code $exitCode for '$SourcePath'"
        }
        return
    }

    $sourceParent = Split-Path -Parent $SourcePath
    $filter = $item.Name
    $arguments = @(
        $sourceParent,
        $DestinationRoot,
        $filter,
        '/R:0',
        '/W:0',
        ('/MT:{0}' -f $threadCount),
        '/COPY:DAT'
    )
    if ($Mode -eq 'Move') {
        $arguments += '/MOV'
    }

    $argumentLine = New-RobocopyArgumentLine -Values $arguments
    $process = Start-Process -FilePath $robocopyPath -ArgumentList $argumentLine -Wait -NoNewWindow -PassThru
    $exitCode = $process.ExitCode
    if ($exitCode -gt 7) {
        throw "robocopy file $Mode failed with exit code $exitCode for '$SourcePath'"
    }
}

