function Invoke-GititProcess {
    param(
        [string]$Directory,
        [int]$Timeout = 120
    )

    $state = Start-GititProcess -Directory $Directory
    $deadline = (Get-Date).AddSeconds($Timeout)
    while (-not $state.Process.HasExited) {
        Write-GititLogDelta -State $state
        if ((Get-Date) -gt $deadline) {
            Stop-GititProcess -State $state
            return [PSCustomObject]@{
                Directory = $Directory
                ExitCode = $null
                Success = $false
                TimedOut = $true
            }
        }
        Start-Sleep -Milliseconds 250
    }
    return Complete-GititProcess -State $state
}

function Invoke-GitlogGh {
    param(
        [string[]]$ArgumentList,
        [string]$TokenForProcess,
        [string]$StandardInputText
    )

    $ghCommand = Get-Command gh -ErrorAction SilentlyContinue
    if (-not $ghCommand) {
        return [pscustomobject]@{ ExitCode = 127; Output = 'gh executable not found' }
    }

    $quotedArguments = @()
    foreach ($argument in $ArgumentList) {
        if ($argument -match '^[A-Za-z0-9._=:/-]+$') {
            $quotedArguments += $argument
        } else {
            $quotedArguments += ('"{0}"' -f ($argument -replace '"', '\"'))
        }
    }

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $ghCommand.Source
    $psi.Arguments = ($quotedArguments -join ' ')
    $psi.UseShellExecute = $false
    $psi.RedirectStandardInput = [bool]$StandardInputText
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true
    if ($TokenForProcess) {
        $psi.EnvironmentVariables['GH_TOKEN'] = $TokenForProcess
        $psi.EnvironmentVariables['GITHUB_TOKEN'] = $TokenForProcess
    }

    $process = New-Object System.Diagnostics.Process
    $process.StartInfo = $psi
    [void]$process.Start()
    if ($StandardInputText) {
        $process.StandardInput.Write($StandardInputText)
        $process.StandardInput.Close()
    }
    $stdout = $process.StandardOutput.ReadToEnd()
    $stderr = $process.StandardError.ReadToEnd()
    $process.WaitForExit()
    $output = (($stdout + "`n" + $stderr).Trim())
    return [pscustomobject]@{ ExitCode = $process.ExitCode; Output = $output }
}

