        $resolved = $null
        try { $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).ProviderPath } catch { $resolved = $Path }
        if($resolved -notmatch '^(?i)C:\\'){ return }
        if($resolved -notmatch '(?i)(\\Docker\\?|\\DockerDesktop\\?|\\Docker Desktop\\?|\\containerd\\?|\\\.docker\\?|docker-desktop|ext4\.vhdx|docker.*\.vhdx)'){ return }
        if($resolved -match '(?i)\.vhdx$'){ Write-RedockerSafeLine ("refusing to delete Docker virtual disk: {0}" -f $resolved) Yellow; return }
        Write-RedockerSafeLine ("purge {0}" -f $resolved) DarkCyan
        $preservedNames = New-Object System.Collections.Generic.List[string]
        if($PreserveWslData -and (Test-Path -LiteralPath (Join-Path $resolved 'wsl') -PathType Container)){ [void]$preservedNames.Add('wsl') }
        if($PreserveVmData -and (Test-Path -LiteralPath (Join-Path $resolved 'vm-data') -PathType Container)){ [void]$preservedNames.Add('vm-data') }
        if($preservedNames.Count -gt 0){
            Write-RedockerSafeLine ("preserving Docker virtual disk directories: {0}" -f (($preservedNames.ToArray()) -join ', ')) DarkCyan
            foreach($child in @(Get-ChildItem -LiteralPath $resolved -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin $preservedNames.ToArray() })){
                try { Remove-Item -LiteralPath $child.FullName -Recurse -Force -ErrorAction Stop } catch { try { Remove-Item -LiteralPath $child.FullName -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
            }
            return
        }
        try { Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction Stop } catch { try { Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
    }
    function Stop-RedockerSafeDocker {
        $processNames = @('Docker Desktop','Docker Desktop Installer','com.docker.backend','com.docker.build','com.docker.dev-envs','com.docker.extensions','com.docker.proxy','com.docker.sailor','com.docker.vpnkit','docker-agent','docker-sandbox','dockerd','docker','vpnkit','com.docker.service')
        foreach($name in $processNames){
            try { Get-Process -Name $name -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch { }
        }
        try { Stop-Service -Name 'com.docker.service' -Force -ErrorAction SilentlyContinue } catch { }
        try {
            if(Get-Command Get-VM -ErrorAction SilentlyContinue){
                $vm = Get-VM -Name 'DockerDesktopVM' -ErrorAction SilentlyContinue
                if($vm -and $vm.State -ne 'Off'){ Stop-VM -Name 'DockerDesktopVM' -TurnOff -Force -ErrorAction SilentlyContinue }
            }
        } catch { }
        $deadline = (Get-Date).AddSeconds(20)
        do {
            $alive = @($processNames | ForEach-Object { Get-Process -Name $_ -ErrorAction SilentlyContinue } | Select-Object -First 1)
            if(-not $alive){ break }
            Start-Sleep -Milliseconds 400
        } while((Get-Date) -lt $deadline)
    }
    function Invoke-RedockerSafeNative {
        param([string]$Label,[string]$FilePath,[string[]]$ArgumentList,[int]$TimeoutSeconds = 900)
        Write-RedockerSafeLine ("{0}: {1} {2}" -f $Label,$FilePath,($ArgumentList -join ' '))
        if([string]::IsNullOrWhiteSpace($FilePath) -or -not (Test-Path -LiteralPath $FilePath)){ Write-RedockerSafeLine ("{0} executable not found: {1}" -f $Label,$FilePath) Yellow; return 9009 }
        try {
            $p = Start-Process -FilePath $FilePath -ArgumentList $ArgumentList -PassThru -NoNewWindow -ErrorAction Stop
            $deadline = (Get-Date).AddSeconds([Math]::Max(1,$TimeoutSeconds))
            do {
                $p.Refresh()
                if($p.HasExited){ break }
                $remaining = [Math]::Max(0,($deadline - (Get-Date)).TotalSeconds)
                $pct = [Math]::Min(99,[int]((1 - ($remaining / [Math]::Max(1,$TimeoutSeconds))) * 100))
                Write-RedockerSafeProgress -Activity ("redocker: {0}" -f $Label) -Status ("running; {0}% of {1}s limit" -f $pct,$TimeoutSeconds) -PercentComplete $pct
                Start-Sleep -Milliseconds 500
            } while((Get-Date) -lt $deadline)
            $p.Refresh()
            Write-Progress -Id 847 -Activity ("redocker: {0}" -f $Label) -Completed
            if(-not $p.HasExited){
                try { $p.Kill() } catch { }
                Write-RedockerSafeLine ("{0} timed out after {1}s and was stopped" -f $Label,$TimeoutSeconds) Yellow
                return 124
            }
            $p.Refresh()
            $exitCode = [int]$p.ExitCode
            if($exitCode -lt 0){ Write-RedockerSafeLine ("{0} exit={1} (unsigned 0x{2:X8})" -f $Label,$exitCode,[uint32]$exitCode) } else { Write-RedockerSafeLine ("{0} exit={1}" -f $Label,$exitCode) }
            return $exitCode
        } catch {
            Write-RedockerSafeLine ("{0} failed: {1}" -f $Label,$_.Exception.Message) Yellow
            return 1
        }
    }
    function Find-RedockerSafeDockerPath {
        param([ValidateSet('Desktop','Cli')][string]$Kind)
        $names = if($Kind -eq 'Desktop'){ @('Docker Desktop.exe') } else { @('docker.exe') }
        $candidates = @()
        if($Kind -eq 'Desktop'){
            $candidates += (Join-Path ${env:ProgramFiles} 'Docker\Docker\Docker Desktop.exe')
            if($env:ProgramFiles -and (Test-Path -LiteralPath (Join-Path ${env:ProgramFiles} 'Docker'))){
                try {
                    $candidates += Get-ChildItem -LiteralPath (Join-Path ${env:ProgramFiles} 'Docker') -Filter 'Docker Desktop.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName
                } catch { }
            }
        } else {
            $candidates += (Join-Path ${env:ProgramFiles} 'Docker\Docker\resources\bin\docker.exe')
            $cmd = Get-Command docker.exe -ErrorAction SilentlyContinue | Select-Object -First 1
            if($cmd -and $cmd.Source){ $candidates += $cmd.Source }
            if($env:ProgramFiles -and (Test-Path -LiteralPath (Join-Path ${env:ProgramFiles} 'Docker'))){
                try {
                    $candidates += Get-ChildItem -LiteralPath (Join-Path ${env:ProgramFiles} 'Docker') -Filter 'docker.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName
                } catch { }
            }
        }
        foreach($candidate in ($candidates | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)){
            foreach($name in $names){
                if((Split-Path -Leaf $candidate) -ieq $name -and (Test-Path -LiteralPath $candidate)){ return $candidate }
            }
        }
        return $null
    }
    function Resolve-RedockerSafeWingetPath {
        $candidates = New-Object System.Collections.Generic.List[string]
        foreach($cmdName in @('winget.exe','winget')){
            try {
                foreach($cmd in @(Get-Command $cmdName -CommandType Application -ErrorAction SilentlyContinue)){
                    if($cmd.Source){ [void]$candidates.Add($cmd.Source) }
                    if($cmd.Path){ [void]$candidates.Add($cmd.Path) }
                }
            } catch { }
        }
        $windowsAppsWinget = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
        if($windowsAppsWinget){ [void]$candidates.Add($windowsAppsWinget) }
        try {
            $packageRoot = Join-Path ${env:ProgramFiles} 'WindowsApps'
            if(Test-Path -LiteralPath $packageRoot){
                foreach($wingetExe in @(Get-ChildItem -LiteralPath $packageRoot -Filter 'winget.exe' -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)){
                    [void]$candidates.Add($wingetExe.FullName)
                }
            }
        } catch { }
        foreach($candidate in ($candidates | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)){
            try {
                if((Test-Path -LiteralPath $candidate -PathType Leaf) -and ((Get-Item -LiteralPath $candidate -Force).Length -gt 0 -or $candidate -match '\\WindowsApps\\winget\.exe$')){
                    return $candidate
                }
            } catch { }
        }
        return $null
    }
    function Wait-RedockerSafeDockerFiles {
        param([int]$TimeoutSeconds = 180)
        $deadline = (Get-Date).AddSeconds([Math]::Max(5,$TimeoutSeconds))
        $last = -1
        do {
            $desktop = Find-RedockerSafeDockerPath -Kind Desktop
            $cli = Find-RedockerSafeDockerPath -Kind Cli
            if($desktop -and $cli){ return [pscustomobject]@{ DesktopExe = $desktop; DockerExe = $cli } }
            $elapsed = [int]([Math]::Max(0,((Get-Date).AddSeconds($TimeoutSeconds) - $deadline).TotalSeconds))
            $pct = [Math]::Min(99,[int](($elapsed / [Math]::Max(1,$TimeoutSeconds)) * 100))
            if($pct -ne $last){
                Write-RedockerSafeLine ("waiting for installed executables {0}% desktop={1} cli={2}" -f $pct,[bool]$desktop,[bool]$cli) DarkCyan
                Write-RedockerSafeProgress -Activity 'redocker: locating installed Docker executables' -Status ("desktop={0}; cli={1}" -f [bool]$desktop,[bool]$cli) -PercentComplete $pct
                $last = $pct
            }
            Start-Sleep -Milliseconds 500
        } while((Get-Date) -lt $deadline)
        Write-Progress -Id 847 -Activity 'redocker: locating installed Docker executables' -Completed
        return [pscustomobject]@{ DesktopExe = (Find-RedockerSafeDockerPath -Kind Desktop); DockerExe = (Find-RedockerSafeDockerPath -Kind Cli) }
    }
    function Test-RedockerSafeDockerReady {
        param([string]$DockerExe,[int]$Milliseconds = 1200)
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $false }
        $outFile = Join-Path 'C:\Temp' ('redocker-ready-out-' + [guid]::NewGuid().ToString('N') + '.log')
        $errFile = Join-Path 'C:\Temp' ('redocker-ready-err-' + [guid]::NewGuid().ToString('N') + '.log')
        try {
            $p = Start-Process -FilePath $DockerExe -ArgumentList @('version','--format','{{.Server.Version}}') -RedirectStandardOutput $outFile -RedirectStandardError $errFile -WindowStyle Hidden -PassThru -ErrorAction Stop
            if(-not $p.WaitForExit([Math]::Max(250,$Milliseconds))){ try { $p.Kill() } catch { }; return $false }
            if([int]$p.ExitCode -ne 0){ return $false }
            $stdout = ''
            $stderr = ''
            try { $stdout = (Get-Content -LiteralPath $outFile -Raw -ErrorAction SilentlyContinue).Trim() } catch { $stdout = '' }
            try { $stderr = (Get-Content -LiteralPath $errFile -Raw -ErrorAction SilentlyContinue).Trim() } catch { $stderr = '' }
            if([string]::IsNullOrWhiteSpace($stdout)){ return $false }
            if($stderr -match '(?i)failed to connect|daemon is not running|error during connect|cannot find'){ return $false }
            return $true
        } catch {
            return $false
        } finally {
            foreach($f in @($outFile,$errFile)){ try { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue } catch { } }
        }
    }
    function Wait-RedockerSafeDockerReady {
        param([string]$DockerExe,[int]$TimeoutSeconds = 180)
        $deadline = (Get-Date).AddSeconds([Math]::Max(5,$TimeoutSeconds))
        $last = -1
        do {
            if(Test-RedockerSafeDockerReady -DockerExe $DockerExe){ return $true }
            $elapsed = [int]([Math]::Max(0,((Get-Date).AddSeconds($TimeoutSeconds) - $deadline).TotalSeconds))
            $pct = [Math]::Min(99,[int](($elapsed / [Math]::Max(1,$TimeoutSeconds)) * 100))
            if($pct -ne $last){
                Write-RedockerSafeLine ("waiting for Docker daemon readiness {0}%" -f $pct) DarkCyan
                Write-RedockerSafeProgress -Activity 'redocker: waiting for Docker daemon' -Status 'checking docker version' -PercentComplete $pct
                $last = $pct
            }
            Start-Sleep -Milliseconds 750
        } while((Get-Date) -lt $deadline)
        Write-Progress -Id 847 -Activity 'redocker: waiting for Docker daemon' -Completed
        return (Test-RedockerSafeDockerReady -DockerExe $DockerExe -Milliseconds 2500)
    }
    function Save-RedockerSafeText {
        param([string]$Path,[string]$Text)
        $parent = Split-Path -Parent $Path
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
        $temporary = Join-Path $parent ('.' + [IO.Path]::GetFileName($Path) + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
        try {
            [IO.File]::WriteAllText($temporary,$Text,[Text.UTF8Encoding]::new($false))
            Move-Item -LiteralPath $temporary -Destination $Path -Force -ErrorAction Stop
        } finally {
            if(Test-Path -LiteralPath $temporary){ Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue }
        }
    }
    function Copy-RedockerSnapshotTree {
        param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$Destination)
        if(-not (Test-Path -LiteralPath $Source -PathType Container)){ return 0 }
        $copied = 0
        New-Item -ItemType Directory -Force -Path $Destination | Out-Null
        foreach($item in @(Get-ChildItem -LiteralPath $Source -Force -Recurse -ErrorAction SilentlyContinue)){
            $relative = $item.FullName.Substring($Source.Length).TrimStart('\')
            if([string]::IsNullOrWhiteSpace($relative)){ continue }
            if($relative -match '(?i)(^|\\)(wsl|logs?|cache|tmp)(\\|$)' -or $item.Name -match '(?i)\.(vhdx|log|lock)$'){ continue }
            $target = Join-Path $Destination $relative
            if($item.PSIsContainer){
                New-Item -ItemType Directory -Force -Path $target | Out-Null
            } else {
                New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
                try {
                    Copy-Item -LiteralPath $item.FullName -Destination $target -Force -ErrorAction Stop
                    $copied++
                } catch {
                    Write-RedockerSafeLine ("snapshot skipped locked or unavailable file: {0}" -f $item.FullName) DarkYellow
                }
            }
        }
        return $copied
    }
    function Restore-RedockerSnapshotTree {
        param([Parameter(Mandatory)][string]$Snapshot,[Parameter(Mandatory)][string]$Destination)
        if(-not (Test-Path -LiteralPath $Snapshot -PathType Container)){ return 0 }
        $restored = 0
        foreach($item in @(Get-ChildItem -LiteralPath $Snapshot -Force -Recurse -File -ErrorAction Stop)){
            $relative = $item.FullName.Substring($Snapshot.Length).TrimStart('\')
            $target = Join-Path $Destination $relative
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
            Copy-Item -LiteralPath $item.FullName -Destination $target -Force -ErrorAction Stop
            $restored++
        }
        return $restored
    }
    function Save-RedockerSettingsSnapshot {
        param([Parameter(Mandatory)][string]$SnapshotRoot)
        New-Item -ItemType Directory -Force -Path $SnapshotRoot | Out-Null
        $fileSources = @(
            [pscustomobject]@{ Name = 'AppData-Docker'; Path = (Join-Path $env:APPDATA 'Docker') },
            [pscustomobject]@{ Name = 'AppData-DockerDesktop'; Path = (Join-Path $env:APPDATA 'Docker Desktop') },
            [pscustomobject]@{ Name = 'LocalAppData-Docker'; Path = (Join-Path $env:LOCALAPPDATA 'Docker') },
            [pscustomobject]@{ Name = 'User-Docker'; Path = (Join-Path $env:USERPROFILE '.docker') },
            [pscustomobject]@{ Name = 'ProgramData-DockerDesktop'; Path = (Join-Path $env:ProgramData 'DockerDesktop') }
        )
        $manifest = New-Object System.Collections.Generic.List[object]
        foreach($source in $fileSources){
            $destination = Join-Path $SnapshotRoot ('files\' + $source.Name)
            $count = Copy-RedockerSnapshotTree -Source $source.Path -Destination $destination
            if($count -gt 0){ $manifest.Add([pscustomobject]@{ Name = $source.Name; Source = $source.Path; Files = $count }) }
        }
        $environment = @{}
        foreach($item in @(Get-ChildItem Env: | Where-Object { $_.Name -match '^(?i)(DOCKER|COMPOSE|BUILDKIT)_' })){
            $environment[$item.Name] = [string]$item.Value
        }
        Save-RedockerSafeText -Path (Join-Path $SnapshotRoot 'environment.json') -Text ($environment | ConvertTo-Json -Depth 4)
        $reg = Join-Path $SnapshotRoot 'registry'
        New-Item -ItemType Directory -Force -Path $reg | Out-Null
        $regExe = Join-Path $env:SystemRoot 'System32\reg.exe'
        foreach($key in @('HKCU\Software\Docker Inc.','HKCU\Software\Docker Desktop','HKLM\SOFTWARE\Docker Inc.')){
            $safeName = ($key -replace '[\\:]','_') + '.reg'
            $target = Join-Path $reg $safeName
            $providerKey = if($key -like 'HKCU\*'){ $key -replace '^HKCU\\','HKCU:\' } else { $key -replace '^HKLM\\','HKLM:\' }
            if(Test-Path -LiteralPath $providerKey){
                try {
                    & $regExe export $key $target /y 2>$null | Out-Null
                    if(Test-Path -LiteralPath $target -PathType Leaf){ $manifest.Add([pscustomobject]@{ Name = $key; Registry = $target }) }
                } catch {
                    Write-RedockerSafeLine ("registry snapshot skipped {0}: {1}" -f $key,$_.Exception.Message) DarkYellow
                }
            }
        }
        Save-RedockerSafeText -Path (Join-Path $SnapshotRoot 'manifest.json') -Text (ConvertTo-Json -InputObject ($manifest.ToArray()) -Depth 5)
        Write-RedockerSafeLine ("settings snapshot saved: {0} ({1} file groups)" -f $SnapshotRoot,$manifest.Count) Green
        return $SnapshotRoot
    }
    function Get-RedockerManifestEntries {
        param([Parameter(Mandatory)][string]$ManifestPath)
        $raw = Get-Content -LiteralPath $ManifestPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if($raw -is [System.Array]){ return @($raw) }
        if($raw.Name -is [System.Array]){
            $entries = New-Object System.Collections.Generic.List[object]
            for($index = 0; $index -lt $raw.Name.Count; $index++){
                $entry = [ordered]@{ Name = [string]$raw.Name[$index] }
                if($raw.Source -is [System.Array] -and $index -lt $raw.Source.Count){ $entry.Source = [string]$raw.Source[$index] }
                if($raw.Registry -is [System.Array] -and $index -lt $raw.Registry.Count){ $entry.Registry = [string]$raw.Registry[$index] }
                if($raw.Files -is [System.Array] -and $index -lt $raw.Files.Count){ $entry.Files = $raw.Files[$index] }
                [void]$entries.Add([pscustomobject]$entry)
            }
            return $entries.ToArray()
        }
        return @($raw)
    }
    function Restore-RedockerSettingsSnapshot {
        param([Parameter(Mandatory)][string]$SnapshotRoot)
        if(-not (Test-Path -LiteralPath $SnapshotRoot -PathType Container)){ throw "Docker settings snapshot not found: $SnapshotRoot" }
        $manifestPath = Join-Path $SnapshotRoot 'manifest.json'
        if(-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)){ throw "Docker settings snapshot manifest missing: $manifestPath" }
        $manifest = @(Get-RedockerManifestEntries -ManifestPath $manifestPath)
        $restored = 0
        foreach($entry in $manifest){
            $entryName = [string]$entry.Name
            $entrySource = [string]$entry.Source
            $entryRegistry = [string]$entry.Registry
            if(-not [string]::IsNullOrWhiteSpace($entrySource) -and $entryName -notmatch '\\'){
                $snapshot = Join-Path $SnapshotRoot ('files\' + $entryName)
                $restored += Restore-RedockerSnapshotTree -Snapshot $snapshot -Destination $entrySource
            } elseif(-not [string]::IsNullOrWhiteSpace($entryRegistry) -and (Test-Path -LiteralPath $entryRegistry -PathType Leaf)){
                $regExe = Join-Path $env:SystemRoot 'System32\reg.exe'
                & $regExe import $entryRegistry | Out-Null
                if($LASTEXITCODE -ne 0){ throw "Docker registry settings restore failed: $entryName" }
            }
        }
        $environmentPath = Join-Path $SnapshotRoot 'environment.json'
        if(Test-Path -LiteralPath $environmentPath -PathType Leaf){
            $environment = Get-Content -LiteralPath $environmentPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            foreach($property in $environment.PSObject.Properties){
                Set-Item -Path ('Env:{0}' -f $property.Name) -Value ([string]$property.Value)
                try { [Environment]::SetEnvironmentVariable($property.Name,[string]$property.Value,'User') } catch { }
            }
        }
        Write-RedockerSafeLine ("settings snapshot restored: {0} files" -f $restored) Green
        return $restored
    }
    function Get-RedockerSharedFileHash {
        param([Parameter(Mandatory)][string]$Path)
        $stream = $null
        $sha = $null
        try {
            $stream = [IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete)
            $sha = [Security.Cryptography.SHA256]::Create()
            return ([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','')
        } finally {
            if($sha){ $sha.Dispose() }
            if($stream){ $stream.Dispose() }
        }
    }
    function Test-RedockerSettingsSnapshot {
        param([Parameter(Mandatory)][string]$SnapshotRoot)
        $manifestPath = Join-Path $SnapshotRoot 'manifest.json'
        if(-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)){ return $false }
        $manifest = @(Get-RedockerManifestEntries -ManifestPath $manifestPath)
        foreach($entry in $manifest){
            $entryName = [string]$entry.Name
            $entrySource = [string]$entry.Source
            if(-not [string]::IsNullOrWhiteSpace($entrySource) -and $entryName -notmatch '\\'){
                $snapshot = Join-Path $SnapshotRoot ('files\' + $entryName)
                foreach($item in @(Get-ChildItem -LiteralPath $snapshot -Force -Recurse -File -ErrorAction Stop)){
                    $relative = $item.FullName.Substring($snapshot.Length).TrimStart('\')
                    $target = Join-Path $entrySource $relative
                    if(-not (Test-Path -LiteralPath $target -PathType Leaf)){ return $false }
                    $sourceHash = $null
                    $targetHash = $null
                    for($attempt = 0; $attempt -lt 5 -and ($null -eq $sourceHash -or $null -eq $targetHash); $attempt++){
                        try { $sourceHash = Get-RedockerSharedFileHash -Path $item.FullName } catch { }
                        try { $targetHash = Get-RedockerSharedFileHash -Path $target } catch { }
                        if($null -eq $sourceHash -or $null -eq $targetHash){ Start-Sleep -Milliseconds 100 }
                    }
                    if($null -eq $sourceHash -or $null -eq $targetHash){ continue }
                    if($sourceHash -ne $targetHash){ return $false }
                }
            }
        }
        $criticalFiles = @(
            [pscustomobject]@{ Name = 'AppData-Docker'; Source = (Join-Path $env:APPDATA 'Docker'); Relative = 'settings-store.json' },
            [pscustomobject]@{ Name = 'User-Docker'; Source = (Join-Path $env:USERPROFILE '.docker'); Relative = 'daemon.json' },
            [pscustomobject]@{ Name = 'User-Docker'; Source = (Join-Path $env:USERPROFILE '.docker'); Relative = 'config.json' },
            [pscustomobject]@{ Name = 'ProgramData-DockerDesktop'; Source = (Join-Path $env:ProgramData 'DockerDesktop'); Relative = 'install-settings.json' }
        )
        foreach($critical in $criticalFiles){
            $snapshotFile = Join-Path $SnapshotRoot ('files\' + $critical.Name + '\' + $critical.Relative)
            $targetFile = Join-Path $critical.Source $critical.Relative
            if(Test-Path -LiteralPath $snapshotFile -PathType Leaf){
                if(-not (Test-Path -LiteralPath $targetFile -PathType Leaf)){ return $false }
                try {
                    if((Get-RedockerSharedFileHash -Path $snapshotFile) -ne (Get-RedockerSharedFileHash -Path $targetFile)){ return $false }
                } catch { return $false }
            }
        }
        return $true
    }

    function Set-RedockerKnownSettings {
        $dockerRoaming = Join-Path $env:APPDATA 'Docker'
        $dotDocker = Join-Path $env:USERPROFILE '.docker'
        New-Item -ItemType Directory -Force -Path $dockerRoaming | Out-Null
        New-Item -ItemType Directory -Force -Path $dotDocker | Out-Null
        $settingsStore = Join-Path $dockerRoaming 'settings-store.json'
        $settingsJson = Join-Path $dockerRoaming 'settings.json'
        $daemonJson = Join-Path $dotDocker 'daemon.json'
        $windowsDaemonJson = Join-Path $dotDocker 'windows-daemon.json'
        $settingsVersion = 45
        $full = $null
        if(Test-Path -LiteralPath $settingsStore){
            try {
                $full = Get-Content -LiteralPath $settingsStore -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                $currentVersion = 0
                try { $currentVersion = [int]$full.SettingsVersion } catch { }
                if($currentVersion -gt $settingsVersion){ $settingsVersion = $currentVersion }
            } catch { }
        }
        if(-not $full){
            $full = [pscustomobject][ordered]@{
                AutoStart = $false
                DisplayedOnboarding = $true
                EnableCLIHints = $true
                EnableDockerAI = $true
                EnableIntegrationWithDefaultWslDistro = $false
                FilesharingDirectories = @($env:USERPROFILE)
                InferenceCanUseGPUVariant = $true
                LicenseTermsVersion = 2
                MemoryMiB = 33792
                OpenUIOnStartupDisabled = $true
                SettingsVersion = $settingsVersion
                SwapMiB = 3072
                ThemeSource = 'dark'
                UseBackgroundIndexing = $false
                UseContainerdSnapshotter = $true
                UseLibkrun = $true
                UseResourceSaver = $false
                UseVirtualizationFramework = $false
                WslEngineEnabled = $false
            }
        }

        function Set-RedockerSetting {
            param([Parameter(Mandatory)]$Settings,[Parameter(Mandatory)][string]$Name,$Value)
            $property = $Settings.PSObject.Properties[$Name]
            if($property){ $property.Value = $Value } else { $Settings | Add-Member -NotePropertyName $Name -NotePropertyValue $Value }
        }
        Set-RedockerSetting -Settings $full -Name 'AutoStart' -Value $false
        Set-RedockerSetting -Settings $full -Name 'EnableIntegrationWithDefaultWslDistro' -Value $false
        Set-RedockerSetting -Settings $full -Name 'MemoryMiB' -Value 33792
        Set-RedockerSetting -Settings $full -Name 'OpenUIOnStartupDisabled' -Value $true
        Set-RedockerSetting -Settings $full -Name 'SettingsVersion' -Value $settingsVersion
        Set-RedockerSetting -Settings $full -Name 'SwapMiB' -Value 3072
        Set-RedockerSetting -Settings $full -Name 'UseBackgroundIndexing' -Value $false
        Set-RedockerSetting -Settings $full -Name 'UseContainerdSnapshotter' -Value $true
        Set-RedockerSetting -Settings $full -Name 'AllowBetaFeatures' -Value $true
        Set-RedockerSetting -Settings $full -Name 'UseLibkrun' -Value $true
        Set-RedockerSetting -Settings $full -Name 'UseResourceSaver' -Value $false
        Set-RedockerSetting -Settings $full -Name 'UseVirtualizationFramework' -Value $false
        Set-RedockerSetting -Settings $full -Name 'WslEngineEnabled' -Value $false
        $driveShares = @([System.IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq [System.IO.DriveType]::Fixed -and $_.IsReady } | ForEach-Object { $_.RootDirectory.FullName })
        $safeShares = @(@($full.FilesharingDirectories) + @($driveShares) | Where-Object {
            -not [string]::IsNullOrWhiteSpace([string]$_) -and
            (Test-Path -LiteralPath ([string]$_) -PathType Container)
        } | Select-Object -Unique)
        if($safeShares.Count -eq 0){
            $safeShares = @(@($env:USERPROFILE,'C:\Temp','F:\study') | Where-Object {
                -not [string]::IsNullOrWhiteSpace([string]$_) -and
                (Test-Path -LiteralPath ([string]$_) -PathType Container)
            } | Select-Object -Unique)
        }
    $safeShares = @($safeShares | ForEach-Object { ([string]$_).Replace('\','/') } | Select-Object -Unique)
        Set-RedockerSetting -Settings $full -Name 'FilesharingDirectories' -Value $safeShares
        Save-RedockerSafeText -Path $settingsStore -Text ($full | ConvertTo-Json -Depth 5)
        Write-RedockerSafeLine ("applied Docker Desktop settings: Docker VMM, 33792 MiB memory, Resource Saver off, {0} explicit file shares, no startup" -f $safeShares.Count) Green
        if(Test-Path -LiteralPath $settingsJson -PathType Leaf){
            try {
                $desktop = Get-Content -LiteralPath $settingsJson -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                Set-RedockerSetting -Settings $desktop -Name 'UseLibkrun' -Value $true
                Set-RedockerSetting -Settings $desktop -Name 'WslEngineEnabled' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'UseVirtualizationFramework' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'EnableIntegrationWithDefaultWslDistro' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'UseResourceSaver' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'AutoStart' -Value $false
                Save-RedockerSafeText -Path $settingsJson -Text ($desktop | ConvertTo-Json -Depth 5)
            } catch { Write-RedockerSafeLine ("legacy settings.json update skipped: {0}" -f $_.Exception.Message) DarkYellow }
        }
        $daemon = [ordered]@{
            builder = [ordered]@{ gc = [ordered]@{ defaultKeepStorage = '20GB'; enabled = $true } }
            experimental = $false
            'max-concurrent-downloads' = 10
            'max-concurrent-uploads' = 10
            'max-download-attempts' = 5
            features = [ordered]@{ buildkit = $true }
        }
        Save-RedockerSafeText -Path $daemonJson -Text ($daemon | ConvertTo-Json -Depth 5)
        Write-RedockerSafeLine 'applied daemon performance settings' Green
        if(-not (Test-Path -LiteralPath $windowsDaemonJson -PathType Leaf)){
            Save-RedockerSafeText -Path $windowsDaemonJson -Text "{`r`n}"
        }
        foreach($var in @('DOCKER_BUILDKIT','COMPOSE_DOCKER_CLI_BUILD')){
            try { [Environment]::SetEnvironmentVariable($var,'1','Machine') } catch { }
            Set-Item -Path ("Env:{0}" -f $var) -Value '1' -ErrorAction SilentlyContinue
        }
        try { [Environment]::SetEnvironmentVariable('BUILDKIT_PROGRESS','plain','Machine'); $env:BUILDKIT_PROGRESS='plain' } catch { }
    }

    if($SelfTest){
        [pscustomobject]@{
            Function = 'redocker'
            Mode = 'SnapshotPreservingReinstall'
            ConfigurationSource = 'Current Docker files, registry settings, contexts, credentials, and environment'
            UninstallOnly = [bool]$UninstallOnly
            Plan = [bool]$Plan
            Installer = 'winget uninstall followed by noninteractive exact Docker Desktop install with up to three attempts and stale-state cleanup'
            DataPreservation = 'Docker WSL virtual disks, ProgramData Docker config, and containerd state are never deleted'
            WingetPath = Resolve-RedockerSafeWingetPath
            DaemonReadinessBeforeReturn = $true
            SnapshotExcludes = @('Docker WSL virtual disks','logs','cache','temporary lock files')
        }
        return
    }
    $snapshotBase = if(Test-Path -LiteralPath 'F:\backup' -PathType Container){ 'F:\backup\Docker\redocker-snapshots' } else { Join-Path $env:USERPROFILE 'redocker-snapshots' }
    $snapshotRoot = Join-Path $snapshotBase (Get-Date -Format 'yyyyMMdd-HHmmss')
    if($Plan){
        [pscustomobject]@{
            Function = 'redocker'
            Mode = 'Plan'
            SnapshotRoot = $snapshotRoot
            Purge = -not $NoPurge
            UninstallOnly = [bool]$UninstallOnly
            Install = -not $SkipInstall -and -not $UninstallOnly
            ReadinessVerification = $true
        }
        return
    }
    if(-not (Test-RedockerSafeAdmin)){ throw 'redocker must run from an elevated Windows PowerShell 5 console.' }

    Write-Host "`n=== REDOCKER: FULL REINSTALL + CURRENT SETTINGS PRESERVATION ===" -ForegroundColor Magenta
    if(Test-RedockerSafePendingReboot){ Write-RedockerSafeLine 'a Windows reboot is pending; Docker Desktop install may fail or hang. Reboot first if this run fails.' Yellow }
    Stop-RedockerSafeDocker
    Save-RedockerSettingsSnapshot -SnapshotRoot $snapshotRoot | Out-Null
    if(-not $NoPurge){
        $purgePaths = @(
            [pscustomobject]@{ Path = (Join-Path ${env:ProgramFiles} 'Docker'); PreserveWslData = $false },
            [pscustomobject]@{ Path = (Join-Path ${env:ProgramFiles(x86)} 'Docker'); PreserveWslData = $false },
            [pscustomobject]@{ Path = "$env:ProgramData\DockerDesktop"; PreserveWslData = $false; PreserveVmData = $true },
            [pscustomobject]@{ Path = "$env:APPDATA\Docker"; PreserveWslData = $false },
            [pscustomobject]@{ Path = "$env:APPDATA\Docker Desktop"; PreserveWslData = $false },
            [pscustomobject]@{ Path = (Join-Path $env:USERPROFILE '.docker'); PreserveWslData = $false },
            [pscustomobject]@{ Path = "$env:LOCALAPPDATA\Docker"; PreserveWslData = $true; PreserveVmData = $true }
        )
        for($index = 0; $index -lt $purgePaths.Count; $index++){
            $path = $purgePaths[$index].Path
            Write-RedockerSafeProgress -Activity 'redocker: purging Docker data' -Status $path -PercentComplete ([int](($index / [Math]::Max(1,$purgePaths.Count)) * 100))
            Remove-RedockerSafePath -Path $path -PreserveWslData:$purgePaths[$index].PreserveWslData -PreserveVmData:$purgePaths[$index].PreserveVmData
        }
        Write-Progress -Id 847 -Activity 'redocker: purging Docker data' -Completed
        foreach($rk in @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Docker Desktop','HKLM:\SOFTWARE\Docker Inc.')){
            try { Remove-Item -LiteralPath $rk -Recurse -Force -ErrorAction SilentlyContinue } catch { }
        }
    }

    if($UninstallOnly){
        if(-not $SkipInstall){
            $winget = Resolve-RedockerSafeWingetPath
            if(-not $winget){ throw 'winget is required to uninstall Docker Desktop and was not found.' }
            $uninstallCode = Invoke-RedockerSafeNative -Label 'winget uninstall Docker Desktop' -FilePath $winget -ArgumentList @('uninstall','--id','Docker.DockerDesktop','-e','--source','winget','--accept-source-agreements','--silent','--disable-interactivity') -TimeoutSeconds 300
            if($uninstallCode -ne 0){ throw ("Docker Desktop uninstall failed with exit {0}." -f $uninstallCode) }
        }
        Write-RedockerSafeLine ("uninstall-only complete; settings snapshot retained at {0}" -f $snapshotRoot) Green
        return
    }

    $desktopExe = Join-Path ${env:ProgramFiles} 'Docker\Docker\Docker Desktop.exe'
    $dockerExe = Join-Path ${env:ProgramFiles} 'Docker\Docker\resources\bin\docker.exe'
    if(-not $SkipInstall){
        $winget = Resolve-RedockerSafeWingetPath
        if(-not $winget){ throw 'winget is required to reinstall Docker Desktop and was not found.' }
        $uninstallCode = Invoke-RedockerSafeNative -Label 'winget uninstall Docker Desktop' -FilePath $winget -ArgumentList @('uninstall','--id','Docker.DockerDesktop','-e','--source','winget','--accept-source-agreements','--silent','--disable-interactivity') -TimeoutSeconds 300
        if($uninstallCode -ne 0){ Write-RedockerSafeLine ("winget uninstall exit={0}; continuing after filesystem/registry purge" -f $uninstallCode) Yellow }
        $installArgs = @('install','--id','Docker.DockerDesktop','-e','--source','winget','--accept-package-agreements','--accept-source-agreements','--silent','--force','--disable-interactivity')
        $maxAttempts = 3
        $installed = $false
        $lastCode = -1
        for($attempt = 1; $attempt -le $maxAttempts; $attempt++){
            Stop-RedockerSafeDocker
            if($attempt -gt 1){
                Write-RedockerSafeLine ("install attempt {0}: clearing stale install state from previous attempt" -f $attempt) Yellow
                Start-Sleep -Seconds 6
                try { Remove-Item -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Docker Desktop' -Recurse -Force -ErrorAction SilentlyContinue } catch { }
                Remove-RedockerSafePath -Path (Join-Path ${env:ProgramFiles} 'Docker')
            }
            $label = if($attempt -eq 1){ 'winget install Docker Desktop' } else { 'winget install Docker Desktop retry' }
            $lastCode = Invoke-RedockerSafeNative -Label $label -FilePath $winget -ArgumentList $installArgs -TimeoutSeconds 1200
            if($lastCode -eq 124){
                Write-RedockerSafeLine 'winget install was stopped on timeout; killing any lingering installer process before next attempt' Yellow
                Stop-RedockerSafeDocker
                Start-Sleep -Seconds 3
            }
            if($lastCode -eq -6 -or $lastCode -eq 4294967290){
                Write-RedockerSafeLine 'installer reported 0xFFFFFFFA (-6): usually a leftover installer instance or stale install state; deep cleanup will run before the next attempt' Yellow
            }
            $found = Wait-RedockerSafeDockerFiles -TimeoutSeconds $(if($lastCode -eq 0){ 180 } else { 45 })
            $desktopExe = $found.DesktopExe
            $dockerExe = $found.DockerExe
            if($lastCode -eq 0 -and $desktopExe -and $dockerExe -and (Test-Path -LiteralPath $desktopExe) -and (Test-Path -LiteralPath $dockerExe)){ $installed = $true; break }
        }
        if(-not $installed){ throw ("Docker Desktop reinstall failed after {0} attempts (last winget exit {1}). See installer logs under %TEMP%\Docker Installer*.log." -f $maxAttempts,$lastCode) }
        if(-not $desktopExe -or -not (Test-Path -LiteralPath $desktopExe)){ throw 'Docker Desktop executable missing after reinstall.' }
        if(-not $dockerExe -or -not (Test-Path -LiteralPath $dockerExe)){ throw 'Docker CLI executable missing after reinstall.' }
        Write-RedockerSafeLine ("installed executables: desktop={0}; cli={1}" -f $desktopExe,$dockerExe) Green
    }

    Write-RedockerSafeProgress -Activity 'redocker: restoring current configuration' -Status 'restoring Docker Desktop settings, credentials, contexts, and environment' -PercentComplete 75
    Restore-RedockerSettingsSnapshot -SnapshotRoot $snapshotRoot | Out-Null
    if(-not (Test-RedockerSettingsSnapshot -SnapshotRoot $snapshotRoot)){ throw 'Docker settings restoration verification failed.' }
    Write-Progress -Id 847 -Activity 'redocker: restoring recovered configuration' -Completed

    Set-RedockerKnownSettings

    if(Test-Path -LiteralPath $desktopExe){
        try { & 'F:\study\Platforms\windows\functions\Start-DockerVmmDesktop.ps1' | Out-Host; Write-RedockerSafeLine 'Docker Desktop launched' Green } catch { Write-RedockerSafeLine ("Docker Desktop launch failed: {0}" -f $_.Exception.Message) Yellow }
    }
    if(-not (Wait-RedockerSafeDockerReady -DockerExe $dockerExe -TimeoutSeconds 180)){
        throw 'Docker daemon was not ready after redocker reinstall/launch; returning failure instead of false success.'
    }
    & 'F:\study\Platforms\windows\functions\Invoke-DockerHubLogin.ps1'
    Write-RedockerSafeLine 'Docker daemon ready after reinstall/launch' Green
    $elapsed = [Math]::Round(((Get-Date)-$started).TotalSeconds,2)
    Write-Progress -Id 847 -Activity 'redocker' -Completed
    Write-RedockerSafeLine ("complete in {0}s; current settings snapshot restored and verified at {1}; returning to shell now" -f $elapsed,$snapshotRoot) Green
}

function Invoke-JobTrackerTotal {
        $env:PYTHONIOENCODING = 'utf-8'
        $totalText = & python $tracker total --workspace linkedin-auto-apply 2>$null
        if ($LASTEXITCODE -ne 0 -or [string]::IsNullOrWhiteSpace(($totalText | Select-Object -Last 1))) {
            $totalText = & $wslExe -e bash -lc 'USERPROFILE=/mnt/c/Users/micha python3 /mnt/c/Users/micha/.codex/skills/job/scripts/job_progress.py total --workspace linkedin-auto-apply' 2>$null
        }
        return [int](($totalText | Select-Object -Last 1).ToString().Trim())
    }

function Invoke-LegacySafeSwitchWrapper {
    param(
        [Parameter(Mandatory = $true)][string]$CommandName,
        [Parameter(Mandatory = $true)][string]$ScriptPath,
        [Parameter(Mandatory = $true)][hashtable]$Forward,
        [object[]]$RemainingArgs
    )
    . $ScriptPath
    if ($RemainingArgs -and $RemainingArgs.Count -gt 0) { & $CommandName @Forward @RemainingArgs } else { & $CommandName @Forward }
}

function Invoke-MegaFixNative {
        param([string]$Label,[string]$FilePath,[string[]]$Arguments)
        Write-MegaFixLine ("START: {0}" -f $Label)
        Write-MegaFixLine ("CMD: {0} {1}" -f $FilePath, ($Arguments -join ' '))
        $old = $ErrorActionPreference
        try {
            $ErrorActionPreference = 'Continue'
            & $FilePath @Arguments 2>&1 | ForEach-Object {
                $text = [string]$_
                Write-Host $text
                Add-Content -LiteralPath $log -Value $text -Encoding UTF8
            }
            $code = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
        } finally {
            $ErrorActionPreference = $old
        }
        Write-MegaFixLine ("END: {0}; exit={1}" -f $Label, $code)
        return $code
    }

function Invoke-MmenuCmdProgress {
        param([Parameter(Mandatory=$true)][string]$Label,[Parameter(Mandatory=$true)][string]$CommandLine,[int]$HeartbeatSeconds=1,[switch]$QuietOutput)
        $runId=[Guid]::NewGuid().ToString('N'); $outFile=Join-Path $progressRoot "$runId.out.log"; $errFile=Join-Path $progressRoot "$runId.err.log"; $exitFile=Join-Path $progressRoot "$runId.exit"
        $started=Get-Date; Write-Host "[mmenu][docker:$Label] START $(Get-Date -Format 'HH:mm:ss')" -ForegroundColor Cyan
        Push-Location $env:TEMP
        try {
            $wrappedCommand='('+$CommandLine+') & echo !ERRORLEVEL!>'+(Quote-MmenuCmdArg $exitFile)+' & exit /b !ERRORLEVEL!'
            $p=Start-Process -FilePath $cmdExe -ArgumentList @('/v:on','/d','/s','/c',$wrappedCommand) -RedirectStandardOutput $outFile -RedirectStandardError $errFile -WindowStyle Hidden -PassThru
            $outOffset=[int64]0; $errOffset=[int64]0; $tick=0
            while(-not $p.HasExited){
                Start-Sleep -Seconds $HeartbeatSeconds; $tick++
                if(-not $QuietOutput){ Write-MmenuNewLogBytes -File $outFile -Offset ([ref]$outOffset); Write-MmenuNewLogBytes -File $errFile -Offset ([ref]$errOffset) }
                $elapsed=[int][Math]::Floor(((Get-Date)-$started).TotalSeconds)
                Write-MmenuRealProgressLine -Label $Label -Elapsed $elapsed -ProcessId $p.Id -Tick $tick
            }
            $p.WaitForExit(); $p.Refresh()
            if(-not $QuietOutput){ Write-MmenuNewLogBytes -File $outFile -Offset ([ref]$outOffset); Write-MmenuNewLogBytes -File $errFile -Offset ([ref]$errOffset) }
            $code=$null
            if(Test-Path -LiteralPath $exitFile -PathType Leaf){ $exitRaw=Get-Content -LiteralPath $exitFile -Raw -ErrorAction SilentlyContinue; if(-not [string]::IsNullOrWhiteSpace($exitRaw)){ $parsedExit=0; if([int]::TryParse($exitRaw.Trim(),[ref]$parsedExit)){ $code=$parsedExit } } }
            if($null -eq $code){ $code=[int]$p.ExitCode }
            $elapsedFinal=[int][Math]::Ceiling(((Get-Date)-$started).TotalSeconds)
            Write-Host ("[mmenu][docker:{0}] EXIT code={1} elapsed={2}s" -f $Label,$code,$elapsedFinal) -ForegroundColor Cyan
            return [int]$code
        } finally { Pop-Location; Remove-Item -LiteralPath $outFile,$errFile,$exitFile -Force -ErrorAction SilentlyContinue }
    }

function Invoke-MmenuDockerLogin {
    [CmdletBinding()]
    param()
    $helper = 'C:\Program Files\Docker\Docker\resources\bin\docker-credential-desktop.exe'
    if (-not (Test-Path -LiteralPath $helper -PathType Leaf)) {
        Write-Warning "mmenu: Docker credential helper not found: $helper"
        return $false
    }
    $info = New-Object Diagnostics.ProcessStartInfo
    $info.FileName = $helper
    $info.Arguments = 'list'
    $info.UseShellExecute = $false
    $info.CreateNoWindow = $true
    $info.RedirectStandardOutput = $true
    $info.RedirectStandardError = $true
    $process = [Diagnostics.Process]::Start($info)
    if (-not $process.WaitForExit(3000)) {
        try { $process.Kill() } catch { }
        Write-Warning 'mmenu: Docker credential lookup timed out.'
        return $false
    }
    if ($process.ExitCode -ne 0) { return $false }
    try {
        $credentials = $process.StandardOutput.ReadToEnd() | ConvertFrom-Json -ErrorAction Stop
        return @($credentials.PSObject.Properties | Where-Object {
            $_.Name -in @('https://index.docker.io/v1/', 'https://dhi.io', 'index.docker.io')
        }).Count -gt 0
    } catch {
        Write-Warning ("mmenu: Docker credential lookup failed: {0}" -f $_.Exception.Message)
        return $false
    }
}

function Invoke-MmenuDockerPushInteractiveProgress {
        param([string]$Image)
        $sizeBytes = 0L
        try { $raw = & $dockerExe image inspect $Image --format '{{.Size}}' 2>$null; [void][int64]::TryParse(($raw | Select-Object -Last 1), [ref]$sizeBytes) } catch {}
        Write-Host ("[mmenu][docker:push] START {0} image-size={1}" -f (Get-Date -Format 'HH:mm:ss'),(Format-MmenuMB $sizeBytes)) -ForegroundColor Cyan
        Write-Host "[mmenu][docker:push] Docker's native live push progress below is intentionally attached to this console so layer MB current/total is real, not guessed." -ForegroundColor Cyan
        $started=Get-Date
        $p=Start-Process -FilePath $dockerExe -ArgumentList @('push',$Image) -NoNewWindow -PassThru
        $tick=0
        while(-not $p.HasExited){
            Start-Sleep -Seconds 1; $tick++
            $elapsed=[int][Math]::Floor(((Get-Date)-$started).TotalSeconds)
            Write-Host ("[mmenu][docker:push] progress elapsed={0}s pid={1} image-total={2}; see Docker layer current/total MB above" -f $elapsed,$p.Id,(Format-MmenuMB $sizeBytes)) -ForegroundColor DarkCyan
        }
        $p.WaitForExit(); $p.Refresh()
        $pushCode = $p.ExitCode
        if ($null -eq $pushCode) { $pushCode = 0 }
        $elapsedFinal=[int][Math]::Ceiling(((Get-Date)-$started).TotalSeconds)
        Write-Host ("[mmenu][docker:push] EXIT code={0} elapsed={1}s image-total={2}" -f $pushCode,$elapsedFinal,(Format-MmenuMB $sizeBytes)) -ForegroundColor Cyan
        return [int]$pushCode
    }

function Invoke-MmenuTarToDockerBuild {
        param([string[]]$DockerArgs)
        $scriptPath=Join-Path $progressRoot ('tarstream-'+[Guid]::NewGuid().ToString('N')+'.py')
        Write-MmenuTarStreamerScript -ScriptPath $scriptPath
        try {
            $dockerPart=Quote-MmenuCmdArg $dockerExe; foreach($arg in $DockerArgs){ $dockerPart+=' '+(Quote-MmenuCmdArg $arg) }
            $commandLine=(Quote-MmenuCmdArg $pythonExe)+$pythonArgsPrefix+' '+(Quote-MmenuCmdArg $scriptPath)+' '+(Quote-MmenuCmdArg $projectPath)+' | '+$dockerPart
            return (Invoke-MmenuCmdProgress -Label 'tar-import' -CommandLine $commandLine)
        } finally { Remove-Item -LiteralPath $scriptPath -Force -ErrorAction SilentlyContinue }
    }

