function Invoke-ProfileCluChild {
        param([object[]]$ChildArguments)

        $powerShell5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $powerShell5
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        $psi.WorkingDirectory = $env:USERPROFILE
        function Quote-ProfileCluArgument([string]$Value) {
            if ($null -eq $Value) { return '""' }
            return '"' + ($Value -replace '([\\"])', '\$1') + '"'
        }
        $argumentList = New-Object 'System.Collections.Generic.List[string]'
        [void]$argumentList.Add('-NoProfile')
        [void]$argumentList.Add('-ExecutionPolicy')
        [void]$argumentList.Add('Bypass')
        [void]$argumentList.Add('-File')
        [void]$argumentList.Add((Quote-ProfileCluArgument $scriptPath))
        foreach ($argument in @($ChildArguments)) {
            if ($null -ne $argument) { [void]$argumentList.Add((Quote-ProfileCluArgument ([string]$argument))) }
        }
        $psi.Arguments = ($argumentList -join ' ')

        $process = [System.Diagnostics.Process]::Start($psi)
        $stdout = $process.StandardOutput.ReadToEnd()
        $stderr = $process.StandardError.ReadToEnd()
        $process.WaitForExit()
        $combined = ($stdout + $stderr)
        if ($combined.Length -gt 0) { Write-Host $combined.TrimEnd() }
        [pscustomobject]@{ ExitCode = $process.ExitCode; Text = $combined }
    }

function Invoke-ProfileCodexResume {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$ShortcutName,
        [Parameter(ValueFromRemainingArguments = $true)][object[]]$CommandArguments
    )

    Write-Output ("CODEX_RESUME_PROGRESS command={0} stage=resolving" -f $ShortcutName)
    $codex = $null
    foreach ($candidateName in @('codex.exe', 'codex')) {
        $candidate = Get-Command -Name $candidateName -CommandType Application -ErrorAction SilentlyContinue |
            Select-Object -First 1
        if ($candidate -and $candidate.Source) {
            $codex = $candidate
            break
        }
    }
    if (-not $codex) {
        throw "CODEX_RESUME: the Codex executable is not available for $ShortcutName."
    }

    Write-Output ("CODEX_RESUME_PROGRESS command={0} stage=running executable=""{1}""" -f $ShortcutName, $codex.Source)
    $global:LASTEXITCODE = 0
    & $codex.Source 'resume' @CommandArguments
    $exitCode = if ($null -eq $LASTEXITCODE) { 0 } else { [int]$LASTEXITCODE }
    if ($exitCode -ne 0) {
        throw "CODEX_RESUME: Codex exited with code $exitCode."
    }
    Write-Output ("CODEX_RESUME_OK command={0}" -f $ShortcutName)
}

function Invoke-ProfileFixFRunner {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][ValidateSet('ffixe', 'ffixf')][string]$Name,
        [Parameter(Mandatory = $true)][string]$ArtifactPath
    )

    $portableRoot = 'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable'
    $workingDirectory = 'F:\study'
    if (-not (Test-Path -LiteralPath $ArtifactPath -PathType Leaf)) {
        throw "${Name}: repair artifact is missing: $ArtifactPath"
    }
    if (-not (Test-Path -LiteralPath $workingDirectory -PathType Container)) {
        throw "${Name}: working directory is missing: $workingDirectory"
    }

    $runnerDirectory = Join-Path $portableRoot 'temp'
    $runner = Join-Path $runnerDirectory ($Name + '-profile-launch.ps1')
    New-Item -ItemType Directory -Path $runnerDirectory -Force | Out-Null
    $payload = Get-Content -LiteralPath $ArtifactPath -Raw -ErrorAction Stop
    if ([string]::IsNullOrWhiteSpace($payload)) {
        throw "${Name}: repair artifact is empty: $ArtifactPath"
    }
    Set-Content -LiteralPath $runner -Value $payload -Encoding UTF8 -Force

    $systemRoot = [Environment]::GetEnvironmentVariable('SystemRoot', 'Process')
    if ([string]::IsNullOrWhiteSpace($systemRoot)) { $systemRoot = 'C:\Windows' }
    $powershell = Join-Path $systemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    if (-not (Test-Path -LiteralPath $powershell -PathType Leaf)) {
        throw "${Name}: Windows PowerShell 5 executable is missing: $powershell"
    }

    Write-Output ("{0}_PROGRESS stage=starting-runner path=""{1}""" -f $Name.ToUpperInvariant(), $runner)
    Set-Location -LiteralPath $workingDirectory
    [Environment]::CurrentDirectory = $workingDirectory
    $process = Start-Process -FilePath $powershell -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $runner) -WorkingDirectory $workingDirectory -WindowStyle Minimized -PassThru
    Write-Output ("{0}_OK pid={1} working_directory=""{2}""" -f $Name.ToUpperInvariant(), $process.Id, $workingDirectory)
}

function Invoke-ProfileFunctionAdd {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, Position = 0)][string]$Name,
        [Parameter(Mandatory, Position = 1)][scriptblock]$Body,
        [switch]$Force
    )
    $Name = Assert-ProfileFunctionMutationName -Name $Name
    $definition = New-ProfileFunctionMutationDefinition -Name $Name -Body $Body
    Write-ProfileFunctionMutationProgress -Stage 'validating-function' -Detail $Name
    $documents = @(foreach ($path in Get-ProfileFunctionMutationPaths) {
        Get-ProfileFunctionMutationDocument -Path $path
    })
    $existingDocuments = @($documents | Where-Object {
        $null -ne (Get-ProfileFunctionMutationMatch -Document $_ -Name $Name)
    })
    if ($existingDocuments.Count -eq 0) {
        $mutationPathSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($p in @(Get-ProfileFunctionMutationPaths)) {
            [void]$mutationPathSet.Add([System.IO.Path]::GetFullPath($p))
        }
        foreach ($path in @(Get-ProfileFunctionMutationProfileSourceFiles)) {
            if ($mutationPathSet.Contains([System.IO.Path]::GetFullPath($path))) { continue }
            if (-not (Test-ProfileFunctionMutationAddTarget -Path $path)) { continue }
            try {
                $extra = Get-ProfileFunctionMutationDocument -Path $path
            } catch {
                continue
            }
            if ($null -ne (Get-ProfileFunctionMutationMatch -Document $extra -Name $Name)) {
                $existingDocuments += $extra
            }
        }
    }
    if ($existingDocuments.Count -gt 0 -and -not $Force) {
        throw "Function '$Name' already exists in '$($existingDocuments[0].Path)'. Use 'addfunc $Name { ... } -Force' to replace it."
    }
    $targetDocuments = @(
        if ($existingDocuments.Count -gt 0) {
            $existingDocuments
        } else {
            @($documents | Where-Object { Test-ProfileFunctionMutationAddTarget -Path $_.Path })
        }
    )
    if ($targetDocuments.Count -eq 0) {
        throw "No writable saved profile sources are available for '$Name'."
    }
    $changes = New-Object System.Collections.Generic.List[object]
    foreach ($document in $targetDocuments) {
        $existingMatches = @(Get-ProfileFunctionMutationMatches -Document $document -Name $Name)
        $existing = if ($existingMatches.Count -gt 0) { $existingMatches[-1] } else { $null }
        $documentDefinition = if ($existing -and $existing.Name -match '^(?i:global:)') {
            New-ProfileFunctionMutationDefinition -Name $Name -Body $Body -Global
        } else {
            $definition
        }
        $updated = Replace-ProfileFunctionMutationDefinitions -Source $document.Source -Matches $existingMatches -Definition $documentDefinition
        $changes.Add([pscustomobject]@{
            Path = $document.Path
            OriginalSource = $document.Source
            UpdatedSource = $updated
            Encoding = $document.Encoding
            Verification = [pscustomobject]@{
                PresentName = $Name
                ExpectedBody = $Body.ToString()
                AbsentNames = @()
            }
        }) | Out-Null
    }
    Write-ProfileFunctionMutationProgress -Stage 'saving-function' -Detail $Name
    $backups = @(Set-ProfileFunctionMutationDocuments -Changes $changes.ToArray())
    Clear-ProfileFunctionMutationRuntimeCache
    Set-ProfileFunctionMutationCurrentDefinition -Name $Name -Definition $definition
    [pscustomobject]@{ Status = 'ADDFUNC_OK'; Name = $Name; Profiles = @($changes.Path); Backups = $backups }
}

function Invoke-ProfileFunctionMove {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, Position = 0)][string]$From,
        [Parameter(Mandatory, Position = 1)][string]$To,
        [switch]$Force
    )
    $From = Assert-ProfileFunctionMutationName -Name $From
    $To = Assert-ProfileFunctionMutationName -Name $To
    if ($From -ieq $To) { throw "Source and destination function names are both '$From'." }
    Write-ProfileFunctionMutationProgress -Stage 'validating-rename' -Detail "$From,$To"
    $changes = New-Object System.Collections.Generic.List[object]
    $currentDefinition = $null
    foreach ($path in Get-ProfileFunctionMutationPaths) {
        $document = Get-ProfileFunctionMutationDocument -Path $path
        $sourceFunctions = @(Get-ProfileFunctionMutationMatches -Document $document -Name $From)
        $sourceFunction = Get-ProfileFunctionMutationMatch -Document $document -Name $From
        if (-not $sourceFunction) { continue }
        $destinationFunctions = @(Get-ProfileFunctionMutationMatches -Document $document -Name $To)
        if ($destinationFunctions.Count -gt 0 -and -not $Force) {
            throw "Function '$To' already exists in '$path'. Use mvfunc $From $To -Force to replace it."
        }
        $declaration = [regex]::Match(
            $sourceFunction.Extent.Text,
            '^(?<prefix>\s*function\s+)(?<scope>(?:global:)?)?[A-Za-z_][A-Za-z0-9_.-]*',
            [System.Text.RegularExpressions.RegexOptions]::IgnoreCase
        )
        if (-not $declaration.Success) {
            throw "Could not rewrite the declaration for '$From' in '$path'."
        }
        $replacementDeclaration = $declaration.Groups['prefix'].Value + $declaration.Groups['scope'].Value + $To
        $renamed = $sourceFunction.Extent.Text.Remove(0, $declaration.Length).Insert(0, $replacementDeclaration)
        $removals = @($sourceFunctions + $destinationFunctions)
        $updated = Replace-ProfileFunctionMutationDefinitions -Source $document.Source -Matches $removals -Definition $renamed
        if ($null -eq $currentDefinition) { $currentDefinition = $renamed }
        $changes.Add([pscustomobject]@{
            Path = $path
            OriginalSource = $document.Source
            UpdatedSource = $updated
            Encoding = $document.Encoding
            Verification = [pscustomobject]@{
                PresentName = $To
                ExpectedBody = $sourceFunction.Body.Extent.Text
                AbsentNames = @($From)
            }
        }) | Out-Null
    }
    Add-ProfileFunctionMutationGeneratedWrapperRemoval -Changes $changes -Name @($From)
    if ($changes.Count -eq 0) {
        throw "Function '$From' is not a saved outer function in any active profile source."
    }
    Write-ProfileFunctionMutationProgress -Stage 'saving-rename' -Detail "$From,$To"
    $backups = @(Set-ProfileFunctionMutationDocuments -Changes $changes.ToArray())
    Clear-ProfileFunctionMutationRuntimeCache
    $generatedModulePath = Get-ProfileFunctionMutationGeneratedModulePath
    if (@($changes | Where-Object { $_.Path -ieq $generatedModulePath }).Count -gt 0) {
        Refresh-ProfileFunctionMutationGeneratedModule
    }
    Set-ProfileFunctionMutationCurrentDefinition -Name $To -Definition $currentDefinition
    Remove-Item -LiteralPath "Function:\$From" -Force -ErrorAction SilentlyContinue
    [pscustomobject]@{ Status = 'MVFUNC_OK'; From = $From; To = $To; Profiles = @($changes.Path); Backups = $backups }
}

function Invoke-ProfileFunctionRemove {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, Position = 0)][string[]]$Name,
        [switch]$Force
    )
    $names = @($Name | ForEach-Object { Assert-ProfileFunctionMutationName -Name $_ } | Select-Object -Unique)
    Write-ProfileFunctionMutationProgress -Stage 'validating-removal' -Detail ($names -join ',')
    $changes = New-Object System.Collections.Generic.List[object]
    $savedNames = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($removal in @(Get-ProfileFunctionMutationSourceFileRemovals -Names $names)) {
        foreach ($removedName in $removal.RemovedNames) {
            [void]$savedNames.Add($removedName)
        }
        $changes.Add([pscustomobject]@{
            Path = $removal.Path
            OriginalSource = $removal.Document.Source
            UpdatedSource = $removal.UpdatedSource
            Encoding = $removal.Document.Encoding
            Verification = [pscustomobject]@{
                PresentName = $null
                ExpectedBody = $null
                AbsentNames = $removal.RemovedNames
            }
        }) | Out-Null
    }
    $missingNames = @($names | Where-Object { -not $savedNames.Contains($_) })
    $moduleRemovals = New-Object System.Collections.Generic.List[object]
    $alreadyRemovedBackups = New-Object System.Collections.Generic.List[object]
    $liveOnlyNames = New-Object System.Collections.Generic.List[string]
    $unknownNames = New-Object System.Collections.Generic.List[string]
    if ($missingNames.Count -gt 0) {
        foreach ($missingName in $missingNames) {
            $moduleRemoval = Get-ProfileFunctionMutationUserModuleRemoval -Name $missingName
            if ($moduleRemoval) {
                $moduleRemovals.Add($moduleRemoval) | Out-Null
                continue
            }
            $moduleBackup = Get-ProfileFunctionMutationUserModuleRemovalBackup -Name $missingName
            if ($moduleBackup) {
                $alreadyRemovedBackups.Add($moduleBackup) | Out-Null
                continue
            }
            $liveCommand = Get-Command -Name $missingName -CommandType Function -ErrorAction SilentlyContinue |
                Select-Object -First 1
            if ($liveCommand) {
                $liveOnlyNames.Add($missingName) | Out-Null
            }
            else {
                $unknownNames.Add($missingName) | Out-Null
            }
        }
    }
    if ($unknownNames.Count -gt 0) {
        throw "rmfunc could not find '$($unknownNames -join "', '")' in any saved profile source, module source, or the current session."
    }
    if (($moduleRemovals.Count -gt 0 -or $alreadyRemovedBackups.Count -gt 0) -and ($changes.Count -gt 0 -or $liveOnlyNames.Count -gt 0)) {
        throw "rmfunc cannot mix saved profile-function removal with user-module source removal in one invocation."
    }
    if ($liveOnlyNames.Count -gt 0) {
        foreach ($removal in @(Get-ProfileFunctionMutationSourceFileRemovals -Names $liveOnlyNames.ToArray())) {
            $changes.Add([pscustomobject]@{
                Path = $removal.Path
                OriginalSource = $removal.Document.Source
                UpdatedSource = $removal.UpdatedSource
                Encoding = $removal.Document.Encoding
                Verification = [pscustomobject]@{
                    PresentName = $null
                    ExpectedBody = $null
                    AbsentNames = $removal.RemovedNames
                }
            }) | Out-Null
        }
    }
    if ($changes.Count -eq 0 -and $moduleRemovals.Count -eq 0) {
        foreach ($target in $names) {
            Remove-Item -LiteralPath "Function:\$target" -Force -ErrorAction SilentlyContinue
        }
        $hadLive = @($names | Where-Object {
            Get-Command -Name $_ -CommandType Function -ErrorAction SilentlyContinue
        }).Count -gt 0
        [pscustomobject]@{
            Status = if ($hadLive) { 'RMFUNC_OK' } else { 'RMFUNC_ALREADY_REMOVED' }
            Name = $names
            Profiles = @()
            ModuleSources = @()
            Backups = @($alreadyRemovedBackups | ForEach-Object { $_.Path })
        }
        return
    }
    if ($moduleRemovals.Count -gt 0 -and $changes.Count -eq 0) {
        $backups = @(Remove-ProfileFunctionMutationUserModuleSources -Removal $moduleRemovals.ToArray())
        foreach ($target in $names) {
            Remove-Item -LiteralPath "Function:\$target" -Force -ErrorAction SilentlyContinue
        }
        Clear-ProfileFunctionMutationRuntimeCache
        [pscustomobject]@{
            Status = 'RMFUNC_OK'
            Name = $names
            Profiles = @()
            ModuleSources = @($moduleRemovals | ForEach-Object { $_.Path })
            Backups = @($backups + @($alreadyRemovedBackups | ForEach-Object { $_.Path }))
        }
        return
    }

    Add-ProfileFunctionMutationGeneratedWrapperRemoval -Changes $changes -Name $names
    $generatedModulePath = Get-ProfileFunctionMutationGeneratedModulePath
    $hasGeneratedModuleChange = @($changes | Where-Object { $_.Path -ieq $generatedModulePath }).Count -gt 0
    $liveCommands = @(
        foreach ($target in $names) {
            Get-Command -Name $target -CommandType Function -ErrorAction SilentlyContinue
        }
    )
    $backups = @()
    if ($changes.Count -gt 0) {
        Write-ProfileFunctionMutationProgress -Stage 'saving-removal' -Detail ($names -join ',')
        $backups = @(Set-ProfileFunctionMutationDocuments -Changes $changes.ToArray())
    }
    Clear-ProfileFunctionMutationRuntimeCache
    if ($hasGeneratedModuleChange -or ($changes.Count -eq 0 -and $liveCommands.Count -gt 0 -and (Get-Module -Name CodexProfileFunctions))) {
        Refresh-ProfileFunctionMutationGeneratedModule
    }
    foreach ($target in $names) {
        Remove-Item -LiteralPath "Function:\$target" -Force -ErrorAction SilentlyContinue
    }
    $profilePaths = @($changes | ForEach-Object { $_.Path })
    [pscustomobject]@{ Status = 'RMFUNC_OK'; Name = $names; Profiles = $profilePaths; Backups = $backups }
}

function Invoke-ProfileFunctionUpdate {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, Position = 0)][string]$Name,
        [Parameter(Mandatory, Position = 1)][scriptblock]$Body
    )
    $Name = Assert-ProfileFunctionMutationName -Name $Name
    $found = $false
    foreach ($path in Get-ProfileFunctionMutationPaths) {
        $document = Get-ProfileFunctionMutationDocument -Path $path
        if (Get-ProfileFunctionMutationMatch -Document $document -Name $Name) {
            $found = $true
        }
    }
    $liveCommand = Get-Command -Name $Name -CommandType Function -ErrorAction SilentlyContinue |
        Select-Object -First 1
    if (-not $found -and -not $liveCommand) {
        throw "Function '$Name' does not exist in any saved profile source or the current session. Use addfunc to create it."
    }
    $result = Invoke-ProfileFunctionAdd -Name $Name -Body $Body -Force
    [pscustomobject]@{
        Status = 'MVFUNC_OK'
        Action = 'updated'
        Name = $Name
        Profiles = $result.Profiles
        Backups = $result.Backups
    }
}

