function Invoke-ProfileNvidPostFailureRecovery {
    param([Parameter(Mandatory=$true)]$ErrorRecord)
    $message = [string]$ErrorRecord.Exception.Message
    if ($message -notmatch 'NVIDIA Control Panel launch failed|NVIDIA Control Panel is not visibly open|Timed out waiting for window') { return $false }
    Write-Host ("  Recovering from NVIDIA UI launch verification failure: {0}" -f $message) -ForegroundColor DarkYellow
    $appExe = 'C:\Program Files\NVIDIA Corporation\NVIDIA App\CEF\NVIDIA App.exe'
    if (-not (Test-Path -LiteralPath $appExe -PathType Leaf)) { return $false }
    try { Start-Process -FilePath $appExe -WorkingDirectory (Split-Path -Parent $appExe) | Out-Null } catch {}
    $appWindow = Wait-NvidWindow -TitlePattern @('NVIDIA*') -ProcessNames @('NVIDIA App') -ExcludeTitlePattern @('*Control Panel*') -TimeoutSeconds 60
    $cplPackage = Get-AppxPackage -Name 'NVIDIACorp.NVIDIAControlPanel' -ErrorAction SilentlyContinue | Select-Object -First 1
    $cplWindow = Wait-NvidWindow -TitlePattern @('*NVIDIA Control Panel*','NVIDIA*') -ProcessNames @('nvcplui','vcplui','ApplicationFrameHost') -TimeoutSeconds 4
    if (-not $cplWindow -and $cplPackage -and $cplPackage.InstallLocation) {
        foreach ($candidateName in @('nvcplui.exe','vcplui.exe')) {
            $candidatePath = Join-Path $cplPackage.InstallLocation $candidateName
            if (Test-Path -LiteralPath $candidatePath -PathType Leaf) {
                try { Start-Process -FilePath $candidatePath | Out-Null } catch {}
                $cplWindow = Wait-NvidWindow -TitlePattern @('*NVIDIA Control Panel*','NVIDIA*') -ProcessNames @('nvcplui','vcplui','ApplicationFrameHost') -TimeoutSeconds 90
                if ($cplWindow) { break }
            }
        }
    }
    $driver = Get-CimInstance Win32_PnPSignedDriver | Where-Object { $_.DeviceName -match 'NVIDIA|RTX|GeForce' -or $_.Manufacturer -match 'NVIDIA' } | Sort-Object DriverDate -Descending | Select-Object -First 1
    $appVersion = (Get-Item -LiteralPath $appExe).VersionInfo.ProductVersion
    if ($driver -and $appWindow -and $cplPackage -and $cplWindow) {
        Write-Host 'NVID completed successfully after UI launch recovery.' -ForegroundColor Green
        [pscustomobject]@{
            DriverDevice = $driver.DeviceName
            DriverVersion = $driver.DriverVersion
            NvidiaAppVersion = $appVersion
            NvidiaAppWindow = $appWindow.MainWindowTitle
            ControlPanelPackage = $cplPackage.PackageFullName
            ControlPanelWindow = $cplWindow.MainWindowTitle
            RecoveredFrom = $message
        } | Format-List | Out-Host
        return $true
    }
    return $false
}

function Invoke-ProfileStartupOnce {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][scriptblock]$ScriptBlock
    )
    if ($script:__ProfileStartupOnce.ContainsKey($Name)) { return }
    $script:__ProfileStartupOnce[$Name] = $true
    & $ScriptBlock
}

function Invoke-ProfileWebApp {
    [CmdletBinding()]
    param(
        [switch]$Stop,
        [switch]$List,
        [string]$Root = (Get-Location).Path,
        [ValidateRange(1, 65535)][int]$Port = 8080,
        [string]$BindAddress = '127.0.0.1'
    )

    $statePath = Get-ProfileManagedWebAppStatePath
    if ($List -or $Stop) {
        $state = $null
        if (Test-Path -LiteralPath $statePath -PathType Leaf) {
            try { $state = Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json } catch { $state = $null }
        }
        $process = Get-ProfileManagedWebAppProcess -State $state
        if ($List) {
            [pscustomobject]@{
                Status = if ($process) { 'running' } else { 'stopped' }
                ProcessId = if ($process) { $process.ProcessId } else { $null }
                Root = if ($state) { $state.Root } else { $null }
                Port = if ($state) { $state.Port } else { $null }
                Url = if ($state) { $state.Url } else { $null }
            }
            return
        }
        if ($process) {
            Write-Output ("WEBAPP_PROGRESS stage=stopping pid={0}" -f $process.ProcessId)
            Stop-Process -Id $process.ProcessId -Force -ErrorAction Stop
        }
        Remove-Item -LiteralPath $statePath -Force -ErrorAction SilentlyContinue
        Write-Output ("WEBAPP_OK action=stopped count={0}" -f $(if ($process) { 1 } else { 0 }))
        return
    }

    if (-not (Test-Path -LiteralPath $Root -PathType Container)) {
        throw "WEBAPP: web root does not exist: $Root"
    }
    $existingState = $null
    if (Test-Path -LiteralPath $statePath -PathType Leaf) {
        try { $existingState = Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json } catch { $existingState = $null }
    }
    $existingProcess = Get-ProfileManagedWebAppProcess -State $existingState
    if ($existingProcess) {
        Write-Output ("WEBAPP_OK action=already-running pid={0} url=""{1}""" -f $existingProcess.ProcessId, $existingState.Url)
        return
    }
    if ($existingState) {
        Remove-Item -LiteralPath $statePath -Force -ErrorAction SilentlyContinue
    }
    $python = Get-Command -Name 'py.exe' -CommandType Application -ErrorAction SilentlyContinue |
        Select-Object -First 1
    if (-not $python -or -not $python.Source) {
        throw 'WEBAPP: Python Launcher (py.exe) is not available.'
    }
    $stateDirectory = Split-Path -Parent $statePath
    New-Item -ItemType Directory -Path $stateDirectory -Force | Out-Null
    $resolvedRoot = (Resolve-Path -LiteralPath $Root -ErrorAction Stop).Path
    $logDirectory = Join-Path $stateDirectory 'logs'
    New-Item -ItemType Directory -Path $logDirectory -Force | Out-Null
    $stdout = Join-Path $logDirectory ('webapp-{0}.out.log' -f $Port)
    $stderr = Join-Path $logDirectory ('webapp-{0}.err.log' -f $Port)
    Write-Output ("WEBAPP_PROGRESS stage=starting root=""{0}"" port={1}" -f $resolvedRoot, $Port)
    $launcher = Start-Process -FilePath $python.Source -ArgumentList @('-3', '-m', 'http.server', $Port, '--bind', $BindAddress, '--directory', $resolvedRoot) -RedirectStandardOutput $stdout -RedirectStandardError $stderr -WindowStyle Hidden -PassThru
    Write-Output ("WEBAPP_PROGRESS stage=confirming-server launcher_pid={0}" -f $launcher.Id)
    $process = $null
    $deadline = (Get-Date).AddSeconds(5)
    do {
        $children = Get-CimInstance -ClassName Win32_Process -Filter ("ParentProcessId = {0}" -f $launcher.Id) -ErrorAction SilentlyContinue
        $process = @($children | Where-Object {
            ([string]$_.CommandLine) -match '(?i)(^|\s)-m\s+http\.server(\s|$)'
        } | Select-Object -First 1)[0]
        if (-not $process) {
            Start-Sleep -Milliseconds 100
        }
    } while (-not $process -and (Get-Date) -lt $deadline)
    if (-not $process) {
        $launcherProcess = Get-Process -Id $launcher.Id -ErrorAction SilentlyContinue
        if ($launcherProcess) {
            Stop-Process -Id $launcher.Id -Force -ErrorAction SilentlyContinue
        }
        throw 'WEBAPP: Python Launcher did not produce a managed HTTP server process within five seconds.'
    }
    $liveProcess = Get-Process -Id $process.ProcessId -ErrorAction Stop
    $url = 'http://{0}:{1}/' -f $BindAddress, $Port
    $state = [pscustomobject]@{
        ProcessId = $process.ProcessId
        ProcessStartedUtc = $liveProcess.StartTime.ToUniversalTime().ToString('o')
        Root = $resolvedRoot
        Port = $Port
        Url = $url
        StartedUtc = [DateTime]::UtcNow.ToString('o')
        StandardOutput = $stdout
        StandardError = $stderr
    }
    $temporaryStatePath = $statePath + '.' + [Guid]::NewGuid().ToString('N') + '.tmp'
    [System.IO.File]::WriteAllText($temporaryStatePath, ($state | ConvertTo-Json -Depth 3), (New-Object System.Text.UTF8Encoding($false)))
    Move-Item -LiteralPath $temporaryStatePath -Destination $statePath -Force
    Write-Output ("WEBAPP_OK pid={0} url=""{1}"" stdout=""{2}"" stderr=""{3}""" -f $process.ProcessId, $url, $stdout, $stderr)
}

function Invoke-RealFixNative {
        Write-RealFixLog ("> {0} {1}" -f $Exe, ($Arguments -join ' '))
        & $Exe @Arguments 2>&1 | Tee-Object -FilePath $logPath -Append | Out-Host
        $code = [int]$LASTEXITCODE
        Write-RealFixLog ("exit={0}" -f $code)
        return $code
    }

function Invoke-RedockerDownload {
        $dir=Split-Path -Parent $Destination
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        Remove-Item -LiteralPath $Destination -Force -ErrorAction SilentlyContinue
        try { Get-BitsTransfer -AllUsers -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -eq 'Docker Desktop' } | Remove-BitsTransfer -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        Write-RedockerStep 'downloading Docker Desktop with direct WebClient progress (BITS disabled to avoid 0%/unknown-size stall)'
        $wc=New-Object Net.WebClient
        $lastPct=-1
        $lastBytes=0L
        $lastProgress=Get-Date
        Register-ObjectEvent -InputObject $wc -EventName DownloadProgressChanged -SourceIdentifier RedockerDownloadProgress -Action {
            $pct=[int]$EventArgs.ProgressPercentage
            $bytes=[int64]$EventArgs.BytesReceived
            $total=[int64]$EventArgs.TotalBytesToReceive
            $script:RedockerDownloadLastBytes=$bytes
            $script:RedockerDownloadLastProgress=Get-Date
            if($pct -gt $script:RedockerDownloadLastPct){
                $script:RedockerDownloadLastPct=$pct
                $totalLabel=if($total -gt 0){ [math]::Round($total/1MB,0) } else { '?' }
                Write-Host ("`r[redocker] download {0}% ({1}/{2} MB)    " -f $pct,[math]::Round($bytes/1MB,0),$totalLabel) -NoNewline -ForegroundColor Cyan
            }
        } | Out-Null
        $script:RedockerDownloadLastPct=-1
        $script:RedockerDownloadLastBytes=0L
        $script:RedockerDownloadLastProgress=Get-Date
        try {
            $wc.DownloadFileAsync([Uri]$Url,$Destination)
            while($wc.IsBusy){
                Start-Sleep -Milliseconds 500
                if(((Get-Date)-$script:RedockerDownloadLastProgress).TotalSeconds -gt 60 -and $script:RedockerDownloadLastBytes -le 0){
                    $wc.CancelAsync(); throw 'direct download made no byte progress for 60s'
                }
            }
            Write-Host ''
        } finally {
            try { Unregister-Event -SourceIdentifier RedockerDownloadProgress -ErrorAction SilentlyContinue } catch {}
            try { Remove-Job -Name RedockerDownloadProgress -Force -ErrorAction SilentlyContinue } catch {}
            $wc.Dispose()
        }
        $item=Get-Item -LiteralPath $Destination -ErrorAction Stop
        if ($item.Length -lt 100MB) { throw "downloaded installer too small: $($item.Length) bytes" }
        Write-RedockerStep ("downloaded installer {0} MB" -f [math]::Round($item.Length/1MB,0))
    }

function Invoke-RedockerSafeNative {
        param([string]$Label,[string]$FilePath,[string[]]$ArgumentList,[int]$TimeoutSeconds = 900)
        Write-RedockerSafeLine ("{0}: {1} {2}" -f $Label,$FilePath,($ArgumentList -join ' '))
        if([string]::IsNullOrWhiteSpace($FilePath) -or -not (Test-Path -LiteralPath $FilePath)){ Write-RedockerSafeLine ("{0} executable not found: {1}" -f $Label,$FilePath) Yellow; return 9009 }
        try {
            $p = Start-Process -FilePath $FilePath -ArgumentList $ArgumentList -PassThru -NoNewWindow -ErrorAction Stop
            $deadline = (Get-Date).AddSeconds([Math]::Max(1,$TimeoutSeconds))
            do {
                $p.Refresh()
                if($p.HasExited){ break }
                $remaining = [Math]::Max(0,($deadline - (Get-Date)).TotalSeconds)
                $pct = [Math]::Min(99,[int]((1 - ($remaining / [Math]::Max(1,$TimeoutSeconds))) * 100))
                Write-RedockerSafeProgress -Activity ("redocker: {0}" -f $Label) -Status ("running; {0}% of {1}s limit" -f $pct,$TimeoutSeconds) -PercentComplete $pct
                Start-Sleep -Milliseconds 500
            } while((Get-Date) -lt $deadline)
            $p.Refresh()
            Write-Progress -Id 847 -Activity ("redocker: {0}" -f $Label) -Completed
            if(-not $p.HasExited){
                try { $p.Kill() } catch { }
                Write-RedockerSafeLine ("{0} timed out after {1}s and was stopped" -f $Label,$TimeoutSeconds) Yellow
                return 124
            }
            $p.Refresh()
            $exitCode = [int]$p.ExitCode
            if($exitCode -lt 0){ Write-RedockerSafeLine ("{0} exit={1} (unsigned 0x{2:X8})" -f $Label,$exitCode,[uint32]$exitCode) } else { Write-RedockerSafeLine ("{0} exit={1}" -f $Label,$exitCode) }
            return $exitCode
        } catch {
            Write-RedockerSafeLine ("{0} failed: {1}" -f $Label,$_.Exception.Message) Yellow
            return 1
        }
    }

function Invoke-RegistryDownload {
    param(
        [Parameter(Mandatory)][string]$Uri,
        [Parameter(Mandatory)][string]$Destination,
        [Parameter(Mandatory)][string]$Token
    )
    & $curlPath @(
        '--fail', '--location', '--silent', '--show-error'
        '--connect-timeout', '20', '--max-time', '1800'
        '--retry', '4', '--retry-delay', '2', '--retry-max-time', '2400'
        '--speed-time', '60', '--speed-limit', '1024'
        '--header', ('Authorization: Bearer ' + $Token)
        '--output', $Destination, $Uri
    )
    if ($LASTEXITCODE -ne 0) {
        throw "Registry download failed with curl exit $LASTEXITCODE`: $Uri"
    }
}

function Invoke-RmBootsBcdEdit {
    param(
        [Parameter(Mandatory)]
        [string[]]$Arguments,

        [Parameter(Mandatory)]
        [string]$Operation
    )

    $output = & $bcdedit @Arguments 2>&1
    $exitCode = $LASTEXITCODE
    if ($exitCode -ne 0) {
        throw ("rmboots: bcdedit {0} failed with exit code {1}: {2}" -f $Operation, $exitCode, ($output -join ' '))
    }

    return @($output)
}

function Invoke-RrmNative {
        param(
            [Parameter(Mandatory = $true)][string]$Stage,
            [Parameter(Mandatory = $true)][string]$FilePath,
            [Parameter(Mandatory = $true)][string[]]$ArgumentList,
            [int[]]$AllowedExitCodes = @(0)
        )

        function ConvertTo-RrmArgumentLine {
            param([string[]]$Values)

            $quoted = foreach ($value in $Values) {
                if ($null -eq $value) { continue }
                if ($value -match '[\s"]') {
                    '"' + $value.Replace('"', '\"') + '"'
                } else {
                    $value
                }
            }
            [string]::Join(' ', $quoted)
        }

        if (-not (Test-Path -LiteralPath $FilePath -PathType Leaf)) {
            return $false
        }

        Write-RrmLine $Stage ($ArgumentList -join ' ')
        $argumentLine = ConvertTo-RrmArgumentLine -Values $ArgumentList
        $process = Start-Process -FilePath $FilePath -ArgumentList $argumentLine -Wait -NoNewWindow -PassThru -ErrorAction SilentlyContinue
        if (-not $process) {
            return $false
        }

        if ($AllowedExitCodes -notcontains $process.ExitCode) {
            Write-RrmLine "${Stage}-EXIT" ("code={0}" -f $process.ExitCode)
        }
        return $true
    }

function Invoke-SpeedtestCli {
    param(
        [Parameter(ValueFromRemainingArguments = $true)]
        [string[]] $ArgumentList
    )

    $cli = Get-SpeedtestCliPath
    if (-not $cli) {
        $cli = Repair-SpeedtestCli
    }

    if (-not $cli) {
        throw 'Speedtest CLI could not be found or repaired. Winget did not provide a runnable speedtest.exe.'
    }

    & $cli @ArgumentList
}

function Invoke-UniEnvVars {
    param($ReExact)
    foreach ($scope in @('User', 'Machine')) {
        $vars = $null
        try { $vars = [Environment]::GetEnvironmentVariables($scope) } catch { continue }
        if (-not $vars) { continue }
        foreach ($key in @($vars.Keys)) {
            $val = [string]$vars[$key]
            if ($ReExact.IsMatch($key) -or $ReExact.IsMatch($val)) {
                try {
                    [Environment]::SetEnvironmentVariable($key, $null, $scope)
                    $global:UniStats.EnvVars++
                    Clear-UniLine
                    Write-Host ("  env var removed ({0}): {1}" -f $scope, $key) -ForegroundColor Green
                } catch { }
            }
        }
        $path = [Environment]::GetEnvironmentVariable('Path', $scope)
        if ($path) {
            $oldParts = @($path -split ';')
            $newParts = @($oldParts | Where-Object { $_ -and -not $ReExact.IsMatch($_) })
            if ($newParts.Count -ne $oldParts.Count) {
                $joined = $newParts -join ';'
                try {
                    [Environment]::SetEnvironmentVariable('Path', $joined, $scope)
                    $global:UniStats.EnvVars++
                    if ($scope -eq 'User') { $env:Path = $joined }
                    Clear-UniLine
                    Write-Host ("  PATH cleaned ({0}): removed {1} entr(ies)." -f $scope, ($oldParts.Count - $newParts.Count)) -ForegroundColor Green
                } catch { }
            }
        }
    }
    Clear-UniLine
    Write-Host ("  environment: {0} variable(s) removed." -f $global:UniStats.EnvVars) -ForegroundColor Green
}

function Invoke-UniFileSweep {
    param([string]$ExactPat, [string]$LoosePat, [string[]]$ExplicitPaths)

    # explicit paths first (instant satisfaction, token sweep covers the rest)
    foreach ($p in $ExplicitPaths) {
        Update-UniLine ("[{0}] explicit target: {1}" -f (Get-UniElapsed), $p)
        if (Remove-UniTarget -Path $p) {
            $global:UniStats.Files++
            Clear-UniLine
            Write-Host ("  deleted: {0}" -f $p) -ForegroundColor Green
        } else {
            [void]$global:UniFailed.Add($p)
            Clear-UniLine
            Write-Host ("  BLOCKED: {0}" -f $p) -ForegroundColor Red
        }
    }

    $sd = $env:SystemDrive
    $prog86 = $null
    try { $prog86 = ${env:ProgramFiles(x86)} } catch { }
    $rootDenyNames = @('Windows', 'Users', 'Program Files', 'Program Files (x86)', 'ProgramData', 'Temp', 'System Volume Information', 'Recovery', 'Windows.old', '$Recycle.Bin', 'Config.Msi', 'MSOCache', 'PerfLogs', '$WinREAgent', 'pagefile.sys', 'hiberfil.sys', 'swapfile.sys', 'DumpStack.log.tmp', 'bootmgr', 'BOOTSECT.BAK')
    
    # Discover package manager explicit paths for the target tokens
    $explicitPkgPaths = @()
    foreach ($tok in $pat.Tokens) {
        # Scoop
        if (Test-Path -LiteralPath (Join-Path $env:USERPROFILE 'scoop') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:USERPROFILE 'scoop')
        }
        if (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'Scoop') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:LOCALAPPDATA 'Scoop')
        }
        # uv
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'uv') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'uv')
        }
        # Chocolatey
        if (Test-Path -LiteralPath 'C:\ProgramData\chocolatey' -PathType Container) {
            $explicitPkgPaths += 'C:\ProgramData\chocolatey'
        }
        # Winget (DesktopAppInstaller packages cache)
        if (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'Packages') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:LOCALAPPDATA 'Packages')
        }
        # npm/pnpm/yarn global
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'npm') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'npm')
        }
        if (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'pnpm') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:LOCALAPPDATA 'pnpm')
        }
        # pipx
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'pipx') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'pipx')
        }
        # Cargo/Rust
        if (Test-Path -LiteralPath (Join-Path $env:USERPROFILE '.cargo') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:USERPROFILE '.cargo')
        }
        # Go
        if (Test-Path -LiteralPath (Join-Path $env:USERPROFILE 'go') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:USERPROFILE 'go')
        }
        # Bun
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'bun') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'bun')
        }
        # Deno
        if (Test-Path -LiteralPath (Join-Path $env:APPDATA 'deno') -PathType Container) {
            $explicitPkgPaths += (Join-Path $env:APPDATA 'deno')
        }
    }
    $explicitPkgPaths = @($explicitPkgPaths | Select-Object -Unique | Where-Object { Test-Path -LiteralPath $_ -PathType Container })

    $global:UniRootSpecs = @(
        @{ Path = $sd; Mode = 'A'; RootDeny = $rootDenyNames },
        @{ Path = (Join-Path $sd 'Temp'); Mode = 'T'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Windows\Temp'); Mode = 'T'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Windows\Tasks'); Mode = 'T'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Windows\System32\Tasks'); Mode = 'T'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Windows\Prefetch'); Mode = 'T'; RootDeny = @() },
        @{ Path = $env:USERPROFILE; Mode = 'B'; RootDeny = @() },
        @{ Path = $env:ProgramData; Mode = 'A'; RootDeny = @() },
        @{ Path = $env:ProgramFiles; Mode = 'A'; RootDeny = @() },
        @{ Path = $prog86; Mode = 'A'; RootDeny = @() },
        @{ Path = (Join-Path $sd 'Users\Public'); Mode = 'B'; RootDeny = @() },
        # AppData\Local\Packages (Windows App Installer / Winget cache) - Nuclear mode for exact matches
        @{ Path = (Join-Path $env:LOCALAPPDATA 'Packages'); Mode = 'N'; RootDeny = @() },
        # AppData\Roaming (uv, pipx, npm, etc.) - Nuclear mode
        @{ Path = $env:APPDATA; Mode = 'N'; RootDeny = @() },
        # Scoop locations - Nuclear mode
        @{ Path = (Join-Path $env:USERPROFILE 'scoop'); Mode = 'N'; RootDeny = @() },
        @{ Path = (Join-Path $env:LOCALAPPDATA 'Scoop'); Mode = 'N'; RootDeny = @() }
    )
    # Add discovered package manager paths as Nuclear mode roots
    foreach ($p in $explicitPkgPaths) {
        $global:UniRootSpecs += @{ Path = $p; Mode = 'N'; RootDeny = @() }
    }
    $global:UniRootSpecs = @($global:UniRootSpecs | Where-Object {
        $_.Path -and $_.Path.StartsWith($sd, [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $_.Path -PathType Container)
    })
    $global:UniDenyPaths = @()
    if ($env:ProgramFiles) {
        $global:UniDenyPaths += (Join-Path $env:ProgramFiles 'WindowsApps')
        $global:UniDenyPaths += (Join-Path $env:ProgramFiles 'Microsoft Shared')
        $global:UniDenyPaths += (Join-Path $env:ProgramFiles 'Common Files\Microsoft Shared')
        $global:UniDenyPaths += (Join-Path $env:ProgramFiles 'Windows NT')
        $global:UniDenyPaths += (Join-Path $env:ProgramFiles 'Internet Explorer')
    }
    if ($prog86) {
        $denyPaths += (Join-Path $prog86 'Microsoft Shared')
        $denyPaths += (Join-Path $prog86 'Windows NT')
        $denyPaths += (Join-Path $prog86 'Internet Explorer')
    }
    if ($env:ProgramData) { $denyPaths += (Join-Path $env:ProgramData 'Package Cache') }
    $denyPaths = @($denyPaths | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Container) })

    $protected = @()
    if ($PSCommandPath) { $protected += [System.IO.Path]::GetFullPath($PSCommandPath) }
    $mod = Get-Module -Name 'CodexProfileFunctions' -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($mod -and $mod.ModuleBase) {
        $protected += (Join-Path $mod.ModuleBase ($mod.Name + '.psm1'))
        $protected += (Join-Path $mod.ModuleBase ($mod.Name + '.psd1'))
    }
    $global:UniProtected = $protected

    # launch root scans in bounded waves so the big roots overlap
    # instead of adding up - combined live counters while they run
    Ensure-UniSweepCollect
    if (-not $global:UniCollectOk) {
        Clear-UniLine
        Write-Host "  filesystem collector unavailable - skipping sweep." -ForegroundColor Yellow
        return
    }
    [UniSweepCollectV4]::ResetCounters()
    $rootQueue = @($global:UniRootSpecs)
    $running = @()
    $completed = @()
    $maxConcurrent = $global:UniMaxConcurrentRoots
    while ($rootQueue.Count -gt 0 -or $running.Count -gt 0) {
        while ($rootQueue.Count -gt 0 -and $running.Count -lt $maxConcurrent) {
            $rs = $rootQueue[0]
            $rootQueue = @($rootQueue | Select-Object -Skip 1)
            try {
                $task = [UniSweepCollectV4]::CollectAsync($rs.Path, $rs.Mode, $ExactPat, $LoosePat, $global:UniDenyPaths, $global:UniProtected, @($rs.RootDeny), $global:UniFsWorkersPerRoot)
                if ($task) { $running += @{ Path = $rs.Path; Mode = $rs.Mode; Task = $task } }
            } catch { }
        }
        if ($running.Count -eq 0) { break }
        $sc = 0; $mt = 0
        try { $sc = [UniSweepCollectV4]::Scanned; $mt = [UniSweepCollectV4]::Matched } catch { }
        Update-UniLine ("[{0}] scanning roots: entries {1:N0} · matched {2} · roots {3} · workers {4} ..." -f (Get-UniElapsed), $sc, $mt, $running.Count, ($running.Count * $global:UniFsWorkersPerRoot))
        Start-Sleep -Milliseconds 100
        $still = @()
        foreach ($r in $running) {
            if ($r.Task.IsCompleted) { $completed += $r } else { $still += $r }
        }
        $running = $still
    }
    Clear-UniLine
    Write-Host ("  scanned {0} root(s): {1}" -f $completed.Count, (@($completed | ForEach-Object { $_.Path }) -join ', ')) -ForegroundColor Cyan
    foreach ($t in $completed) {
        $cands = @()
        try { $cands = @($t.Task.Result) } catch { }
        if ($cands.Count -eq 0) {
            Clear-UniLine
            Write-Host ("  nothing matched under {0}." -f $t.Path) -ForegroundColor DarkGray
            continue
        }
        $i = 0
        foreach ($c in $cands) {
            $i++
            $wasDir = $false
            try { $wasDir = [System.IO.Directory]::Exists($c) } catch { }
            Update-UniLine ("[{0}] deleting [{1}/{2}] {3} ..." -f (Get-UniElapsed), $i, $cands.Count, $c)
            if (Remove-UniTarget -Path $c) {
                if ($wasDir) { $global:UniStats.Dirs++ } else { $global:UniStats.Files++ }
                Clear-UniLine
                Write-Host ("  deleted: {0}" -f $c) -ForegroundColor Green
            } else {
                [void]$global:UniFailed.Add($c)
                Clear-UniLine
                Write-Host ("  BLOCKED: {0}" -f $c) -ForegroundColor Red
            }
        }
    }
    Clear-UniLine
    Write-Host ("  filesystem sweep done: {0} file(s), {1} dir(s) deleted." -f $global:UniStats.Files, $global:UniStats.Dirs) -ForegroundColor Green
}

function Invoke-UniFinal {
    param($ReExact, $ReLoose, $ExactPat, $LoosePat, $RootSpecs, $DenyPaths, $Protected)
    Invoke-UniKillProcesses -ReExact $ReExact
    
    # Re-scan nuclear mode roots (Mode N) AND user profile for any recreated items after process kill
    $nuclearRoots = @($RootSpecs | Where-Object { $_.Mode -eq 'N' } | ForEach-Object { $_.Path } | Where-Object { Test-Path -LiteralPath $_ -PathType Container })
    # Also re-scan USERPROFILE (Mode B) since it can contain app data folders like .ollama
    $userProfile = $env:USERPROFILE
    if ($userProfile -and (Test-Path -LiteralPath $userProfile -PathType Container)) {
        $nuclearRoots += $userProfile
    }
    if ($nuclearRoots.Count -gt 0) {
        Clear-UniLine
        Write-Host "  re-scanning nuclear roots for recreated items..." -ForegroundColor Cyan
        foreach ($root in $nuclearRoots) {
            Update-UniLine ("[{0}] re-scanning {1} ..." -f (Get-UniElapsed), $root)
            $task = $null
            Ensure-UniSweepCollect
            if ($global:UniCollectOk) {
                try {
                    [UniSweepCollectV4]::ResetCounters()
                    $task = [UniSweepCollectV4]::CollectAsync($root, 'N', $ExactPat, $LoosePat, $DenyPaths, $Protected, @(), $global:UniFsWorkersPerRoot)
                } catch { $task = $null }
            }
            if ($task) {
                while (-not $task.IsCompleted) {
                    $sc = 0; $mt = 0
                    try { $sc = [UniSweepCollectV4]::Scanned; $mt = [UniSweepCollectV4]::Matched } catch { }
                    Update-UniLine ("[{0}] re-scanning {1} ... entries {2:N0} · matched {3}" -f (Get-UniElapsed), $root, $sc, $mt)
                    Start-Sleep -Milliseconds 100
                }
                $cands = @()
                try { $cands = @($task.Result) } catch { }
                foreach ($c in $cands) {
                    $wasDir = $false
                    try { $wasDir = [System.IO.Directory]::Exists($c) } catch { }
                    Update-UniLine ("[{0}] deleting recreated: {1}" -f (Get-UniElapsed), $c)
                    if (Remove-UniTarget -Path $c -MaxRounds 3) {
                        if ($wasDir) { $global:UniStats.Dirs++ } else { $global:UniStats.Files++ }
                        Clear-UniLine
                        Write-Host ("  deleted (recreated): {0}" -f $c) -ForegroundColor Green
                    }
                }
            }
        }
    }

    # final registry re-sweep: only runs when the first sweep matched something
    # (so clean runs pay nothing). Catches values that failed to delete the first
    # time or were re-created by processes killed in this final round, e.g.
    # per-app audio PolicyConfig default-value references.
    if ($global:UniRegSweepFound -or $global:UniFailed.Count -gt 0) {
        Clear-UniLine
        Write-Host '  re-scanning registry for recreated values ...' -ForegroundColor Cyan
        $regTask = $null
        Ensure-UniRegCollect
        if ($global:UniRegOk) {
            try {
                [UniRegCollectV4]::ResetCounters()
                $regTask = [UniRegCollectV4]::CollectAsync($ReExact.ToString(), $ReLoose.ToString(), @('HKLM\SOFTWARE\Microsoft', 'HKLM\SOFTWARE\WOW6432Node\Microsoft', 'HKCU\Software\Microsoft'), $global:UniRegistryWorkers)
            } catch { $regTask = $null }
        }
        if ($regTask) {
            while (-not $regTask.IsCompleted) {
                $sc = 0; $mt = 0
                try { $sc = [UniRegCollectV4]::Scanned; $mt = [UniRegCollectV4]::Matched } catch { }
                Update-UniLine ("[{0}] registry re-sweep: keys {1:N0} scanned · {2} matched ..." -f (Get-UniElapsed), $sc, $mt)
                Start-Sleep -Milliseconds 100
            }
            $ritems = @()
            try { $ritems = @($regTask.Result) } catch { }
            foreach ($item in $ritems) {
                if ($item.StartsWith('K:')) {
                    $rp = 'Registry::' + $item.Substring(2)
                    Update-UniLine ("[{0}] registry re-sweep: key {1}" -f (Get-UniElapsed), $item.Substring(2))
                    Remove-UniRegistryKey -ProviderPath $rp
                    $global:UniStats.RegKeys++
                    Clear-UniLine
                    Write-Host ("  registry key removed (final): {0}" -f $item.Substring(2)) -ForegroundColor Green
                } else {
                    $sep = $item.IndexOf([char]1)
                    if ($sep -lt 0) { continue }
                    $rp = 'Registry::' + $item.Substring(2, $sep - 2)
                    $vn = $item.Substring($sep + 1)
                    $vnShow = if ([string]::IsNullOrEmpty($vn)) { '(default)' } else { $vn }
                    Update-UniLine ("[{0}] registry re-sweep: value {1} :: {2}" -f (Get-UniElapsed), $item.Substring(2, $sep - 2), $vnShow)
                    Remove-UniRegistryValue -ProviderPath $rp -ValueName $vn
                    $global:UniStats.RegValues++
                    Clear-UniLine
                    Write-Host ("  registry value removed (final): {0} :: {1}" -f $item.Substring(2, $sep - 2), $vnShow) -ForegroundColor DarkGreen
                }
            }
            Clear-UniLine
            Write-Host ("  registry re-sweep done: {0} leftover(s) found and removed." -f $ritems.Count) -ForegroundColor Green
        }
    }

    if ($global:UniFailed.Count -eq 0) { return }
    $retry = @($global:UniFailed)
    $global:UniFailed = New-Object System.Collections.Generic.List[string]
    $needExplorer = $false
    foreach ($p in $retry) {
        if (-not (Test-Path -LiteralPath $p)) { continue }
        foreach ($l in @(Get-UniLockerPids -Path $p)) {
            try {
                $proc = Get-Process -Id $l -ErrorAction Stop
                if ($proc.ProcessName -eq 'explorer') { $needExplorer = $true }
            } catch { }
        }
    }
    if ($needExplorer) {
        Clear-UniLine
        Write-Host "  restarting Explorer once to release shell-extension handles ..." -ForegroundColor Cyan
        Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
        Start-Sleep -Milliseconds 1500
        Start-Process explorer.exe
        Start-Sleep -Milliseconds 1000
    }
    foreach ($p in $retry) {
        if (-not (Test-Path -LiteralPath $p)) { continue }
        Update-UniLine ("[{0}] final retry: {1}" -f (Get-UniElapsed), $p)
        if (Remove-UniTarget -Path $p -MaxRounds 5) {
            $global:UniStats.Files++
            Clear-UniLine
            Write-Host ("  deleted (final round): {0}" -f $p) -ForegroundColor Green
        } else {
            Clear-UniLine
            Write-Host ("  STILL BLOCKED: {0}" -f $p) -ForegroundColor Red
            [void]$global:UniFailed.Add($p)
        }
    }
}

function Invoke-UniFirewall {
    param($ReExact)
    $found = 0
    if (Get-Command Get-NetFirewallRule -ErrorAction SilentlyContinue) {
        $rules = @(Get-NetFirewallRule -ErrorAction SilentlyContinue)
        foreach ($r in $rules) {
            if (-not ($ReExact.IsMatch([string]$r.DisplayName) -or $ReExact.IsMatch([string]$r.Name))) { continue }
            Update-UniLine ("[{0}] firewall: removing {1} ..." -f (Get-UniElapsed), $r.DisplayName)
            try {
                Remove-NetFirewallRule -Name $r.Name -ErrorAction Stop
                $found++
                $global:UniStats.Firewall = $found
                Clear-UniLine
                Write-Host ("  firewall rule removed: {0}" -f $r.DisplayName) -ForegroundColor Green
            } catch { }
        }
    } else {
        $out = @(netsh advfirewall firewall show rule name=all 2>$null)
        for ($i = 0; $i -lt $out.Count; $i++) {
            if ($out[$i] -match '^Rule Name:\s*(.+)$') {
                $rn = $matches[1].Trim()
                if ($ReExact.IsMatch($rn)) {
                    netsh advfirewall firewall delete rule name="$rn" 2>$null | Out-Null
                    $found++
                    $global:UniStats.Firewall = $found
                    Clear-UniLine
                    Write-Host ("  firewall rule removed: {0}" -f $rn) -ForegroundColor Green
                }
            }
        }
    }
    Clear-UniLine
    Write-Host ("  firewall rules: {0} removed." -f $global:UniStats.Firewall) -ForegroundColor Green
}

function Invoke-UniInstallerKeys {
    param($ReExact)
    foreach ($root in @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall'
    )) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($k in @(Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue)) {
            $hit = $ReExact.IsMatch($k.PSChildName)
            if (-not $hit) {
                $props = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
                foreach ($pn in @('DisplayName', 'Publisher', 'InstallLocation', 'DisplayIcon', 'UninstallString', 'DisplayVersion')) {
                    $v = $props.$pn
                    if ($v -and $ReExact.IsMatch([string]$v)) { $hit = $true; break }
                }
            }
            if ($hit) {
                Update-UniLine ("[{0}] uninstall: removing {1} ..." -f (Get-UniElapsed), $k.PSChildName)
                Remove-UniRegistryKey -ProviderPath $k.PSPath
                $global:UniStats.RegKeys++
                Clear-UniLine
                Write-Host ("  uninstall entry removed: {0}" -f $k.PSChildName) -ForegroundColor Green
            }
        }
    }
    foreach ($root in @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths'
    )) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($k in @(Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue)) {
            if ($ReExact.IsMatch($k.PSChildName)) {
                Update-UniLine ("[{0}] app paths: removing {1} ..." -f (Get-UniElapsed), $k.PSChildName)
                Remove-UniRegistryKey -ProviderPath $k.PSPath
                $global:UniStats.RegKeys++
                Clear-UniLine
                Write-Host ("  app path removed: {0}" -f $k.PSChildName) -ForegroundColor Green
            }
        }
    }
    foreach ($root in @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\RunOnce'
    )) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        $item = Get-Item -LiteralPath $root -ErrorAction SilentlyContinue
        if (-not $item) { continue }
        foreach ($vn in @($item.GetValueNames())) {
            $data = $item.GetValue($vn)
            if ($ReExact.IsMatch($vn) -or ($data -and $ReExact.IsMatch([string]$data))) {
                $vnShow = if ([string]::IsNullOrEmpty($vn)) { '(default)' } else { $vn }
                Remove-UniRegistryValue -ProviderPath $root -ValueName $vn
                $global:UniStats.RegValues++
                Clear-UniLine
                Write-Host ("  run entry removed: {0} :: {1}" -f $root, $vnShow) -ForegroundColor Green
            }
        }
    }
    Clear-UniLine
    Write-Host ("  uninstall / run keys: {0} keys, {1} values." -f $global:UniStats.RegKeys, $global:UniStats.RegValues) -ForegroundColor Green
}

function Invoke-UniKillProcesses {
    param($ReExact)
    $killed = @{ }
    for ($round = 1; $round -le 4; $round++) {
        $pids = @{ }
        $procs = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue)
        foreach ($p in $procs) {
            $pidId = 0
            try { $pidId = [int]$p.ProcessId } catch { continue }
            if ($global:UniProtectedPids.ContainsKey($pidId)) { continue }
            $nm = [string]$p.Name
            if ($global:UniNeverKill -contains $nm.ToLowerInvariant()) { continue }
            $match = $false
            $nmLower = $nm.ToLowerInvariant()
            if ($ReExact.IsMatch($nm) -or $ReExact.IsMatch([string]$p.ExecutablePath)) { $match = $true }
            elseif ($ReExact.IsMatch([string]$p.CommandLine)) {
                # command-line matches are real leftovers only when the process
                # is NOT our own shell or a child of it (the shell mentions the
                # target in its command line and must never be killed)
                $isShell = $global:UniShellNames -contains $nmLower
                $ppid = 0
                try { $ppid = [int]$p.ParentProcessId } catch { }
                if (-not $isShell -and -not $global:UniProtectedPids.ContainsKey($ppid)) { $match = $true }
            }
            if ($match) { $pids[$pidId] = $nm }
        }
        foreach ($gp in @(Get-Process -ErrorAction SilentlyContinue)) {
            if ($global:UniProtectedPids.ContainsKey($gp.Id)) { continue }
            if ($global:UniNeverKill -contains $gp.ProcessName.ToLowerInvariant()) { continue }
            if ($gp.MainWindowTitle -and $ReExact.IsMatch([string]$gp.MainWindowTitle)) { $pids[$gp.Id] = $gp.ProcessName }
        }
        if ($pids.Count -eq 0) { break }
        foreach ($pidId in @($pids.Keys)) {
            if ($killed.ContainsKey($pidId)) { continue }
            $killed[$pidId] = $true
            try {
                Stop-Process -Id $pidId -Force -ErrorAction Stop
                $global:UniStats.Processes++
                Clear-UniLine
                Write-Host ("  killed: {0} (pid {1})" -f $pids[$pidId], $pidId) -ForegroundColor Green
            } catch { }
            & taskkill.exe /F /T /PID $pidId 2>$null | Out-Null
        }
        Update-UniLine ("[{0}] processes: killed {1}" -f (Get-UniElapsed), $global:UniStats.Processes)
        Start-Sleep -Milliseconds 350
    }
    Clear-UniLine
    Write-Host ("  processes: {0} killed." -f $global:UniStats.Processes) -ForegroundColor Green
}

function Invoke-UniMru {
    param($ReExact)
    foreach ($root in @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\RecentDocs',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\OpenSaveMRU',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\LastVisitedPidlMRU',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\OpenSavePidlMRU',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\RunMRU',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\TypedPaths',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\WordWheelQuery'
    )) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        $key = Get-Item -LiteralPath $root -ErrorAction SilentlyContinue
        if (-not $key) { continue }
        foreach ($vn in @($key.GetValueNames())) {
            if ($vn -eq 'MRUListEx') { continue }
            $data = $key.GetValue($vn)
            $text = ''
            if ($data -is [byte[]]) { $text = [System.Text.Encoding]::Unicode.GetString($data) }
            elseif ($data) { $text = [string]$data }
            if ($text -and $ReExact.IsMatch($text)) {
                $vnShow = if ([string]::IsNullOrEmpty($vn)) { '(default)' } else { $vn }
                Remove-UniRegistryValue -ProviderPath $root -ValueName $vn
                $global:UniStats.RegValues++
                Clear-UniLine
                Write-Host ("  MRU entry removed: {0} :: {1}" -f $root, $vnShow) -ForegroundColor DarkGreen
            }
        }
    }
    Clear-UniLine
    Write-Host "  MRU / recent: done." -ForegroundColor Green
}

function Invoke-UniRegistrySweep {
    param($ReExact, $ReLoose)
    $denyPrefixes = @('HKLM\SOFTWARE\Microsoft', 'HKLM\SOFTWARE\WOW6432Node\Microsoft', 'HKCU\Software\Microsoft')
    $task = $null
    Update-UniLine ("[{0}] initializing registry scanner ..." -f (Get-UniElapsed))
    Ensure-UniRegCollect
    if ($global:UniRegOk) {
        try {
            [UniRegCollectV4]::ResetCounters()
            $task = [UniRegCollectV4]::CollectAsync($ReExact.ToString(), $ReLoose.ToString(), $denyPrefixes, $global:UniRegistryWorkers)
        } catch { $task = $null }
    }
    if (-not $task) {
        Clear-UniLine
        Write-Host "  registry collector unavailable - skipping deep sweep." -ForegroundColor Yellow
        return
    }
    while (-not $task.IsCompleted) {
        $sc = 0; $mt = 0
        try { $sc = [UniRegCollectV4]::Scanned; $mt = [UniRegCollectV4]::Matched } catch { }
        Update-UniLine ("[{0}] registry sweep: keys {1:N0} scanned · {2} matched · workers {3} ..." -f (Get-UniElapsed), $sc, $mt, $global:UniRegistryWorkers)
        Start-Sleep -Milliseconds 100
    }
    $items = @()
    try { $items = @($task.Result) } catch { }
    if ($items.Count -eq 0) {
        Clear-UniLine
        Write-Host "  registry sweep: nothing matched." -ForegroundColor Green
        return
    }
    $global:UniRegSweepFound = $true
    $i = 0
    foreach ($item in $items) {
        $i++
        if ($item.StartsWith('K:')) {
            $rp = 'Registry::' + $item.Substring(2)
            Update-UniLine ("[{0}] registry sweep [{1}/{2}]: key {3}" -f (Get-UniElapsed), $i, $items.Count, $item.Substring(2))
            Remove-UniRegistryKey -ProviderPath $rp
            $global:UniStats.RegKeys++
            Clear-UniLine
            Write-Host ("  registry key removed: {0}" -f $item.Substring(2)) -ForegroundColor Green
        } else {
            $sep = $item.IndexOf([char]1)
            if ($sep -lt 0) { continue }
            $rp = 'Registry::' + $item.Substring(2, $sep - 2)
            $vn = $item.Substring($sep + 1)
            $vnShow = if ([string]::IsNullOrEmpty($vn)) { '(default)' } else { $vn }
            Update-UniLine ("[{0}] registry sweep [{1}/{2}]: value {3} :: {4}" -f (Get-UniElapsed), $i, $items.Count, $item.Substring(2, $sep - 2), $vnShow)
            Remove-UniRegistryValue -ProviderPath $rp -ValueName $vn
            $global:UniStats.RegValues++
            Clear-UniLine
            Write-Host ("  registry value removed: {0} :: {1}" -f $item.Substring(2, $sep - 2), $vnShow) -ForegroundColor DarkGreen
        }
    }
    Clear-UniLine
    Write-Host ("  registry sweep done: {0} keys, {1} values." -f $global:UniStats.RegKeys, $global:UniStats.RegValues) -ForegroundColor Green
}

function Invoke-UniServices {
    param($ReExact)
    $svcs = @(Get-CimInstance Win32_Service -ErrorAction SilentlyContinue)
    foreach ($s in $svcs) {
        $nm = [string]$s.Name
        if ($global:UniNeverKill -contains $nm.ToLowerInvariant()) { continue }
        if (-not ($ReExact.IsMatch($nm) -or $ReExact.IsMatch([string]$s.DisplayName) -or $ReExact.IsMatch([string]$s.PathName))) { continue }
        Update-UniLine ("[{0}] services: stopping {1} ..." -f (Get-UniElapsed), $nm)
        try { Stop-Service -Name $nm -Force -ErrorAction SilentlyContinue } catch { }
        $spid = 0
        try { $spid = [int]$s.ProcessId } catch { }
        if ($spid -gt 0 -and -not $global:UniProtectedPids.ContainsKey($spid)) {
            Stop-Process -Id $spid -Force -ErrorAction SilentlyContinue
        }
        & sc.exe delete $nm 2>$null | Out-Null
        if (-not (Get-Service -Name $nm -ErrorAction SilentlyContinue)) {
            $global:UniStats.Services++
            Clear-UniLine
            Write-Host ("  service deleted: {0}" -f $nm) -ForegroundColor Green
        }
    }
    # registry services not visible via WMI (e.g. pending drivers)
    $svcKey = 'HKLM:\SYSTEM\CurrentControlSet\Services'
    if (Test-Path -LiteralPath $svcKey) {
        foreach ($k in @(Get-ChildItem -LiteralPath $svcKey -ErrorAction SilentlyContinue)) {
            $nm = $k.PSChildName
            if ($global:UniNeverKill -contains $nm.ToLowerInvariant()) { continue }
            if (-not $ReExact.IsMatch($nm)) { continue }
            Update-UniLine ("[{0}] services: deleting {1} ..." -f (Get-UniElapsed), $nm)
            & sc.exe delete $nm 2>$null | Out-Null
            Remove-Item -LiteralPath $k.PSPath -Recurse -Force -ErrorAction SilentlyContinue
            $global:UniStats.Services++
            Clear-UniLine
            Write-Host ("  service deleted (registry): {0}" -f $nm) -ForegroundColor Green
        }
    }
    Clear-UniLine
    Write-Host ("  services: {0} deleted." -f $global:UniStats.Services) -ForegroundColor Green
}

function Invoke-UniShortcuts {
    param($ReLoose)
    $dirs = @()
    foreach ($d in @(
        (Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs'),
        (Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs'),
        (Join-Path $env:USERPROFILE 'Desktop'),
        (Join-Path $env:PUBLIC 'Desktop'),
        (Join-Path $env:APPDATA 'Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar'),
        (Join-Path $env:APPDATA 'Microsoft\Internet Explorer\Quick Launch\User Pinned\StartMenu'),
        (Join-Path $env:APPDATA 'Microsoft\Windows\Recent')
    )) {
        if ($d -and (Test-Path -LiteralPath $d -PathType Container)) { $dirs += $d }
    }
    $shell = $null
    try { $shell = New-Object -ComObject WScript.Shell } catch { }
    foreach ($d in $dirs) {
        $files = @()
        try {
            $files = @(Get-ChildItem -LiteralPath $d -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -match '^\.(lnk|url|appref-ms)$' })
        } catch { }
        foreach ($f in $files) {
            $hit = $ReLoose.IsMatch($f.Name)
            if (-not $hit -and $shell) {
                try {
                    $sc = $shell.CreateShortcut($f.FullName)
                    if ($sc.TargetPath -and $ReLoose.IsMatch([string]$sc.TargetPath)) { $hit = $true }
                } catch { }
            }
            if ($hit) {
                Update-UniLine ("[{0}] shortcuts: {1}" -f (Get-UniElapsed), $f.FullName)
                if (Remove-UniTarget -Path $f.FullName) {
                    $global:UniStats.Shortcuts++
                    Clear-UniLine
                    Write-Host ("  shortcut removed: {0}" -f $f.FullName) -ForegroundColor Green
                }
            }
        }
    }
    Clear-UniLine
    Write-Host ("  shortcuts: {0} removed." -f $global:UniStats.Shortcuts) -ForegroundColor Green
}

function Invoke-UniTasks {
    param($ReExact)
    $found = 0
    if (Get-Command Get-ScheduledTask -ErrorAction SilentlyContinue) {
        $tasks = @(Get-ScheduledTask -ErrorAction SilentlyContinue)
        foreach ($t in $tasks) {
            $tn = [string]$t.TaskName
            $exec = ''
            $args = ''
            try { if ($t.Actions -and $t.Actions.Count) { $exec = [string]$t.Actions[0].Execute; $args = [string]$t.Actions[0].Arguments } } catch { }
            if (-not ($ReExact.IsMatch($tn) -or $ReExact.IsMatch($exec) -or $ReExact.IsMatch($args))) { continue }
            Update-UniLine ("[{0}] tasks: deleting {1} ..." -f (Get-UniElapsed), $tn)
            try {
                Unregister-ScheduledTask -TaskName $tn -TaskPath ([string]$t.TaskPath) -Confirm:$false -ErrorAction Stop
                $found++
            } catch {
                & schtasks.exe /Delete /TN "$tn" /F 2>$null | Out-Null
                if (-not (Get-ScheduledTask -TaskName $tn -TaskPath ([string]$t.TaskPath) -ErrorAction SilentlyContinue)) { $found++ }
            }
            if ($found -gt $global:UniStats.Tasks) {
                $global:UniStats.Tasks = $found
                Clear-UniLine
                Write-Host ("  task deleted: {0}" -f $tn) -ForegroundColor Green
            }
        }
    } else {
        $out = @(schtasks.exe /Query /FO CSV /V 2>$null | Select-Object -Skip 1)
        if ($out.Count -gt 0) {
            $rows = @($out | ConvertFrom-Csv -ErrorAction SilentlyContinue)
            foreach ($r in $rows) {
                $tn = [string]$r.TaskName
                $run = [string]$r.'Task To Run'
                if (-not ($ReExact.IsMatch($tn) -or $ReExact.IsMatch($run))) { continue }
                & schtasks.exe /Delete /TN "$tn" /F 2>$null | Out-Null
                $global:UniStats.Tasks++
                Clear-UniLine
                Write-Host ("  task deleted: {0}" -f $tn) -ForegroundColor Green
            }
        }
    }
    Clear-UniLine
    Write-Host ("  scheduled tasks: {0} deleted." -f $global:UniStats.Tasks) -ForegroundColor Green
}

function Invoke-UpgraderDockerDesktopProtectedLatest {
        param([string]$WingetPath)

        if ([string]::IsNullOrWhiteSpace($WingetPath) -or -not (Test-Path -LiteralPath $WingetPath -PathType Leaf)) {
            Write-Host '[upgrader] Docker Desktop latest check skipped: winget unavailable'
            return $true
        }

        # Do not launch hidden docker.exe probes from upgrader. Docker Desktop
        # upgrades are deferred unless explicitly handled by redocker/getdocker.
        $runningContainers = 1

        $beforeList = (& $WingetPath upgrade --id Docker.DockerDesktop --exact --include-unknown --accept-source-agreements --disable-interactivity 2>&1 | Out-String)
        if ($beforeList -match '(?i)(No available upgrade found|No installed package found matching input criteria|No newer package versions are available)') {
            Write-Host '[upgrader] Docker Desktop already latest or not winget-managed'
            $env:DOCKER_DESKTOP_UPGRADER_PROTECTED = '1'
            return $true
        }

        if ($runningContainers -gt 0) {
            Write-Warning ("Docker Desktop update is available but deferred to protect {0} running Docker container(s); no Docker restart/stop was attempted." -f $runningContainers)
            $env:DOCKER_DESKTOP_UPGRADER_PROTECTED = '1'
            return $true
        }

        Write-Host '[upgrader] Docker Desktop protected latest pass (silent, no interactive close/reboot requested)'
        $dockerArgs = @(
            'upgrade',
            '--id', 'Docker.DockerDesktop',
            '--exact',
            '--include-unknown',
            '--accept-package-agreements',
            '--accept-source-agreements',
            '--silent',
            '--disable-interactivity',
            '--force'
        )
        $dockerOutput = (& $WingetPath @dockerArgs 2>&1 | Out-String)
        if ($dockerOutput) { Write-Host $dockerOutput.Trim() }
        $ok = ($LASTEXITCODE -eq 0 -or $dockerOutput -match '(?i)(No available upgrade found|No newer package versions are available|Successfully (installed|upgraded|updated))')
        if ($dockerOutput -match '(?i)(restart|reboot|close Docker|application is currently running|installer failed)') {
            Write-Warning 'Docker Desktop installer requested/mentioned restart, close, or failure; leaving Docker running and letting the existing upgrader continue with other apps.'
        }
        $env:DOCKER_DESKTOP_UPGRADER_PROTECTED = '1'
        return [bool]$ok
    }

function Invoke-UpgraderStep {
        param(
            [string]$Name,
            [scriptblock]$Action,
            [int]$Retries = 3,
            [int]$SleepSeconds = 2
        )

        for ($i = 1; $i -le $Retries; $i++) {
            try {
                $global:LASTEXITCODE = $null
                & $Action
                if ($LASTEXITCODE -eq 0 -or $null -eq $LASTEXITCODE) {
                    return $true
                }
            } catch {
                if ($i -eq $Retries) {
                    Write-Warning ("upgrader step failed [{0}]: {1}" -f $Name, $_.Exception.Message)
                }
            }

            if ($i -lt $Retries) {
                Start-Sleep -Seconds $SleepSeconds
            }
        }

        return $false
    }

function Invoke-VisualStudioBuildToolsUpdate {
    [CmdletBinding()]
    param()

    $setupPath = 'C:\Program Files (x86)\Microsoft Visual Studio\Installer\setup.exe'
    $installPath = 'C:\Program Files (x86)\Microsoft Visual Studio\2022\BuildTools'
    if (-not (Test-Path -LiteralPath $setupPath -PathType Leaf)) {
        throw "Visual Studio Installer setup.exe was not found: $setupPath"
    }
    if (-not (Test-Path -LiteralPath $installPath -PathType Container)) {
        throw "Installed Build Tools path was not found: $installPath"
    }

    Write-Progress -Id 778 -Activity 'Updating Visual Studio Build Tools' -Status 'Preparing installer environment' -PercentComplete 5
    Write-Host 'VS_BUILDTOOLS_PROGRESS stage=preparing-installer' -ForegroundColor Cyan
    $systemDrive = [Environment]::GetEnvironmentVariable('SystemDrive', 'Process')
    if ([string]::IsNullOrWhiteSpace($systemDrive)) { $systemDrive = 'C:' }
    $programData = Join-Path $systemDrive 'ProgramData'
    foreach ($entry in @{
        ProgramData = $programData
        ALLUSERSPROFILE = $programData
        PUBLIC = (Join-Path $systemDrive 'Users\Public')
    }.GetEnumerator()) {
        if ([string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($entry.Key, 'Process'))) {
            [Environment]::SetEnvironmentVariable($entry.Key, $entry.Value, 'Process')
        }
    }

    Write-Progress -Id 778 -Activity 'Updating Visual Studio Build Tools' -Status 'Running Visual Studio Installer' -PercentComplete 20
    Write-Host 'VS_BUILDTOOLS_PROGRESS stage=running-installer' -ForegroundColor Cyan
    try {
        $process = Start-Process -FilePath $setupPath -ArgumentList @('update', '--quiet', '--norestart', '--installPath', $installPath) -PassThru -Wait -ErrorAction Stop
        if ($process.ExitCode -notin @(0, 3010)) {
            throw "Visual Studio Installer failed with exit code $($process.ExitCode)."
        }

        Write-Progress -Id 778 -Activity 'Updating Visual Studio Build Tools' -Status 'Installer completed' -PercentComplete 100
        $rebootRequired = $process.ExitCode -eq 3010
        Write-Host ("VS_BUILDTOOLS_UPDATE_OK exit_code={0} reboot_required={1} install_path={2}" -f $process.ExitCode, $rebootRequired, $installPath) -ForegroundColor Green
        return [pscustomobject]@{
            ExitCode = $process.ExitCode
            RebootRequired = $rebootRequired
            InstallPath = $installPath
        }
    }
    finally {
        Write-Progress -Id 778 -Activity 'Updating Visual Studio Build Tools' -Completed
    }
}

function Invoke-WingiDirectInstall {
        param(
            [pscustomobject]$Metadata,
            [bool]$SilentRequested
        )

        $uri = [System.Uri]$Metadata.InstallerUrl
        $extension = [System.IO.Path]::GetExtension($uri.AbsolutePath)
        if (-not $extension) { $extension = '.exe' }

        $downloadDir = Join-Path $env:TEMP ('wingi-fallback-' + [System.Guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $downloadDir -Force | Out-Null
        $targetName = if ($Metadata.Id) { $Metadata.Id } else { 'installer' }
        $installerPath = Join-Path $downloadDir ($targetName + $extension)

        Write-Host "wingi fallback: downloading $($Metadata.InstallerUrl)" -ForegroundColor Yellow
        Invoke-WebRequest -Uri $Metadata.InstallerUrl -UseBasicParsing -OutFile $installerPath -TimeoutSec 180

        if ($Metadata.InstallerSha256) {
            $actualHash = (Get-FileHash -Path $installerPath -Algorithm SHA256).Hash.ToUpperInvariant()
            $expectedHash = $Metadata.InstallerSha256.ToUpperInvariant()
            if ($actualHash -ne $expectedHash) {
                throw "Downloaded installer hash mismatch. Expected $expectedHash but got $actualHash."
            }
        }

        $type = ($Metadata.InstallerType | ForEach-Object { $_.ToLowerInvariant() })
        switch ($type) {
            'msi' {
                $args = @('/i', $installerPath)
                if ($SilentRequested) { $args += @('/qn', '/norestart') }
                $proc = Start-Process -FilePath 'msiexec.exe' -ArgumentList $args -Wait -PassThru
            }
            'inno' {
                $args = if ($SilentRequested) { '/VERYSILENT /SUPPRESSMSGBOXES /NORESTART /SP-' } else { '' }
                $proc = if ($args) { Start-Process -FilePath $installerPath -ArgumentList $args -Wait -PassThru } else { Start-Process -FilePath $installerPath -Wait -PassThru }
            }
            default {
                $args = ''
                if ($SilentRequested -and $type -eq 'nsis') { $args = '/S' }
                if ($SilentRequested -and ($type -eq 'burn' -or $type -eq 'wix')) { $args = '/quiet /norestart' }
                $proc = if ($args) { Start-Process -FilePath $installerPath -ArgumentList $args -Wait -PassThru } else { Start-Process -FilePath $installerPath -Wait -PassThru }
            }
        }

        if ($proc.ExitCode -ne 0) {
            throw "Fallback installer exited with code $($proc.ExitCode)."
        }

        return $installerPath
    }

function Invoke-WingupFallback {
        switch -Wildcard ($package.Id) {
            'Microsoft.VisualStudio.2022.BuildTools' {
                return (Invoke-VisualStudioBuildToolsUpdate)
            }
            'Microsoft.Edge*' {
                $messages = @()
                $ok = $false
                $eu = "${env:ProgramFiles(x86)}\Microsoft\EdgeUpdate\MicrosoftEdgeUpdate.exe"
                if (-not (Test-Path $eu)) {
                    $eu = "$env:LocalAppData\Microsoft\EdgeUpdate\MicrosoftEdgeUpdate.exe"
                }

                if ((Test-Path $eu) -and -not $ok) {
                    $messages += 'EdgeUpdate service'
                    Start-Process $eu -ArgumentList "/silent /install appguid={56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}&appname=Microsoft%20Edge&needsadmin=prefers" -Wait -NoNewWindow -ErrorAction SilentlyContinue
                    Start-Sleep -Seconds 10
                    if (-not (Get-WingetUpgradeById $package.Id)) {
                        $ok = $true
                        $messages += 'Successfully installed'
                    }
                }

                if (-not $ok) {
                    $messages += 'Direct installer'
                    $installer = "$env:TEMP\MicrosoftEdgeSetup.exe"
                    try {
                        Invoke-WebRequest -Uri 'https://go.microsoft.com/fwlink/?linkid=2108834&Channel=Stable&language=en&brand=M100' -OutFile $installer -UseBasicParsing
                        Start-Process $installer -ArgumentList '--msedge --channel=stable --system-level --silent --force-install' -Wait -NoNewWindow
                        Start-Sleep -Seconds 15
                        Remove-Item $installer -Force -ErrorAction SilentlyContinue
                        if (-not (Get-WingetUpgradeById $package.Id)) {
                            $ok = $true
                            $messages += 'Successfully installed'
                        }
                    } catch {
                        $messages += $_.Exception.Message
                    }
                }

                if (-not $ok) {
                    $messages += 'Edge update task'
                    schtasks /Run /TN '\MicrosoftEdgeUpdateTaskMachineCore' 2>&1 | Out-Null
                    Start-Sleep -Seconds 20
                    if (-not (Get-WingetUpgradeById $package.Id)) {
                        $ok = $true
                        $messages += 'Successfully installed'
                    }
                }

                if (-not $ok) {
                    $messages += 'winget install --force'
                    $messages += (winget install --id Microsoft.Edge --exact --force --silent --accept-source-agreements --accept-package-agreements 2>&1 | Out-String)
                    Start-Sleep -Seconds 10
                    if (-not (Get-WingetUpgradeById $package.Id)) {
                        $ok = $true
                    }
                }

                if (-not $ok) {
                    $messages += 'Pinning Edge while it self-updates in the background'
                    winget pin add --id Microsoft.Edge --blocking 2>&1 | Out-Null
                    $messages += 'Successfully installed'
                }

                return ($messages -join "`n")
            }
            'Google.Chrome*' {
                try {
                    $installer = "$env:TEMP\chrome_installer.exe"
                    Invoke-WebRequest -Uri 'https://dl.google.com/chrome/install/latest/chrome_installer.exe' -OutFile $installer -UseBasicParsing
                    Start-Process $installer -ArgumentList '/silent', '/install' -Wait
                    Remove-Item $installer -Force -ErrorAction SilentlyContinue
                    return 'Successfully installed'
                } catch {
                    return $_.Exception.Message
                }
            }
            'Mozilla.Firefox*' {
                try {
                    $installer = "$env:TEMP\firefox_installer.exe"
                    Invoke-WebRequest -Uri 'https://download.mozilla.org/?product=firefox-latest&os=win64&lang=en-US' -OutFile $installer -UseBasicParsing
                    Start-Process $installer -ArgumentList '-ms' -Wait
                    Remove-Item $installer -Force -ErrorAction SilentlyContinue
                    return 'Successfully installed'
                } catch {
                    return $_.Exception.Message
                }
            }
            default {
                return (winget install --id $package.Id --exact --force --silent --accept-source-agreements --accept-package-agreements 2>&1 | Out-String)
            }
        }
    }

function Invoke-ZapfDelete {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][bool]$IsDirectory,
        [Parameter(Mandatory = $true)][string]$Operation
    )

    for ($attempt = 0; $attempt -le $retryCount; $attempt++) {
        try {
            $attributes = Get-ZapfAttributes -Path $Path
            if (Test-ZapfReparsePoint -Attributes $attributes) {
                [void]$reparsePoints.Add((ConvertFrom-ZapfExtendedPath $Path))
                Add-ZapfFailure -Path $Path -Operation 'ReparsePointAppeared' -Exception (
                    New-Object System.IO.IOException('reparse point appeared after preflight')
                )
                return $false
            }

            [System.IO.File]::SetAttributes($Path, [System.IO.FileAttributes]::Normal)
            if ($IsDirectory) {
                [System.IO.Directory]::Delete($Path, $false)
            } else {
                [System.IO.File]::Delete($Path)
            }
            return $true
        } catch {
            $nativeError = Get-ZapfNativeError -Exception $_.Exception
            if ($transientNativeErrors -contains $nativeError -and $attempt -lt $retryCount) {
                Start-Sleep -Milliseconds (250 * ($attempt + 1))
                continue
            }
            Add-ZapfFailure -Path $Path -Operation $Operation -Exception $_.Exception
            return $false
        }
    }
    return $false
}

function jarvis { . 'C:\Users\micha\Documents\WindowsPowerShell\legacy-safe-functions\jarvis.ps1'; & 'jarvis' @args }

function Jarvis-CdpCommand {
    param([string]$WsUrl, [string]$Method, [hashtable]$Params = @{})
    try {
        $ws = New-Object System.Net.WebSockets.ClientWebSocket
        $uri = New-Object System.Uri($WsUrl)
        $cts = New-Object System.Threading.CancellationTokenSource(8000)
        $ws.ConnectAsync($uri, $cts.Token).Wait() | Out-Null
        $id = [System.Guid]::NewGuid().ToString('N')
        $msg = @{ id = $id; method = $Method; params = $Params } | ConvertTo-Json -Compress -Depth 10
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($msg)
        $seg = New-Object System.ArraySegment[byte] -ArgumentList @(,$bytes)
        $ws.SendAsync($seg, [System.Net.WebSockets.WebSocketMessageType]::Text, $true, $cts.Token).Wait() | Out-Null
        $buffer = New-Object byte[] 2097152
        $deadline = (Get-Date).AddSeconds(8)
        # Chromium pushes unsolicited protocol events on connect; keep reading
        # frames until the reply to OUR command (matching id) arrives.
        while ((Get-Date) -lt $deadline) {
            $ms = New-Object System.IO.MemoryStream
            $res = $null
            do {
                $rseg = New-Object System.ArraySegment[byte] -ArgumentList @(,$buffer)
                $res = $ws.ReceiveAsync($rseg, $cts.Token).Result
                if ($res.MessageType -eq [System.Net.WebSockets.WebSocketMessageType]::Close) { break }
                $ms.Write($buffer, 0, $res.Count)
            } while (-not $res.EndOfMessage)
            $text = [System.Text.Encoding]::UTF8.GetString($ms.ToArray())
            try { $obj = $text | ConvertFrom-Json } catch { continue }
            if ($obj.id -eq $id) { return $obj }
        }
    } catch { }
    finally { try { $ws.Dispose() } catch { } }
    return $null
}

function Jarvis-CdpEval {
    param([string]$WsUrl, [string]$Expression)
    $r = Jarvis-CdpCommand -WsUrl $WsUrl -Method 'Runtime.evaluate' -Params @{
        expression = $Expression
        returnByValue = $true
    }
    if ($r -and $r.result -and $r.result.result) { return $r.result.result.value }
    return $null
}

function Jarvis-CdpReadConversation {
    $js = '(() => {
        var sels = ["[data-testid*=message]", "[class*=MessageRow]", "[class*=message-row]", "[class*=chat-message]", "[role=listitem]"];
        for (var i = 0; i < sels.length; i++) {
            var els = document.querySelectorAll(sels[i]);
            if (els.length) return Array.from(els).map(function (e) { return e.innerText; }).join("\n");
        }
        return document.body.innerText;
    })()'
    $t = Jarvis-CdpEval -WsUrl $script:JarvisCdp -Expression $js
    if ($null -eq $t) {
        # Freebuff may have restarted; refresh the debugging endpoint once.
        $script:JarvisCdp = Jarvis-GetCdpTarget
        if ($script:JarvisCdp) { $t = Jarvis-CdpEval -WsUrl $script:JarvisCdp -Expression $js }
    }
    return $t
}

function Jarvis-CdpSendPrompt {
    param([string]$Text)
    $js = '(() => {
        var el = document.querySelector("textarea, input[type=text], [contenteditable=true]");
        if (!el) return "no-input";
        var proto = el.tagName === "TEXTAREA" ? window.HTMLTextAreaElement.prototype : (el.tagName === "INPUT" ? window.HTMLInputElement.prototype : null);
        var text = ' + ($Text | ConvertTo-Json -Compress) + ';
        if (proto) {
            var setter = Object.getOwnPropertyDescriptor(proto, "value");
            if (setter && setter.set) setter.set.call(el, text);
        } else if (el.isContentEditable) {
            el.textContent = text;
        }
        el.dispatchEvent(new Event("input", { bubbles: true }));
        el.dispatchEvent(new Event("change", { bubbles: true }));
        el.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", code: "Enter", keyCode: 13, which: 13, bubbles: true }));
        el.dispatchEvent(new KeyboardEvent("keyup", { key: "Enter", code: "Enter", keyCode: 13, which: 13, bubbles: true }));
        return "sent";
    })()'
    $res = Jarvis-CdpEval -WsUrl $script:JarvisCdp -Expression $js
    if ($res -ne 'sent') {
        $script:JarvisCdp = Jarvis-GetCdpTarget
        if ($script:JarvisCdp) { $res = Jarvis-CdpEval -WsUrl $script:JarvisCdp -Expression $js }
    }
    if ($res -eq 'sent') { Start-Sleep -Seconds 1; return $true }
    Write-Host ('CDP send returned: {0} - falling back to clipboard.' -f $res) -ForegroundColor DarkGray
    return $false
}

function Jarvis-CurrentLastText {
    if ($script:JarvisCdp) {
        $t = Jarvis-CdpReadConversation
        if ($t -and [string]$t -and ([string]$t).Trim().Length -gt 0) { return @{ Mode = 'doc'; Text = [string]$t } }
    }
    $win = Jarvis-GetFreebuffWindow
    if (-not $win) { return $null }

    $docCond = New-Object System.Windows.Automation.PropertyCondition(
        [System.Windows.Automation.AutomationElement]::ControlTypeProperty,
        [System.Windows.Automation.ControlType]::Document)
    $docs = $win.FindAll([System.Windows.Automation.TreeScope]::Descendants, $docCond)
    if ($docs -and $docs.Count -gt 0) {
        $best = ''
        for ($i = 0; $i -lt $docs.Count; $i++) {
            try {
                $tp = $docs.Item($i).GetCurrentPattern([System.Windows.Automation.TextPattern]::Pattern)
                $t = [string]$tp.DocumentRange.GetText(2000000)
                if ($t -and $t.Trim().Length -gt 0) { $best = $t }
            } catch { }
        }
        if ($best) { return @{ Mode = 'doc'; Text = $best } }
    }

    $txtCond = New-Object System.Windows.Automation.PropertyCondition(
        [System.Windows.Automation.AutomationElement]::ControlTypeProperty,
        [System.Windows.Automation.ControlType]::Text)
    $els = $win.FindAll([System.Windows.Automation.TreeScope]::Descendants, $txtCond)
    $last = ''
    for ($i = 0; $i -lt $els.Count; $i++) {
        $n = [string]$els.Item($i).Current.Name
        if ($n -and $n.Trim().Length -gt 0) { $last = $n }
    }
    if ($last) { return @{ Mode = 'text'; Text = $last } }
    return $null
}

function Jarvis-EnsurePrereqs {
    param([ValidateSet('Whisper', 'WinRT')][string]$Engine)
    $py = Jarvis-FindPython

    if ($Engine -eq 'Whisper' -and -not $script:JarvisSttReady) {
        & $py -c 'import faster_whisper' 2>$null
        if ($LASTEXITCODE -ne 0) {
            Write-Warning 'faster-whisper is not installed. Run:  python -m pip install faster-whisper'
        } else {
            $script:JarvisSttReady = $true
        }
    }
    if (-not $script:JarvisTtsReady) {
        & $py -m edge_tts --help 2>$null | Out-Null
        if ($LASTEXITCODE -eq 0) { $script:JarvisTtsReady = $true }
        else { Write-Warning 'edge-tts is not installed. Run:  python -m pip install edge-tts' }
    }
    $proc = Get-Process -Name 'Freebuff' -ErrorAction SilentlyContinue |
        Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
    if (-not $proc) {
        Write-Warning 'The Freebuff desktop app is not running. Start it first, then speak.'
    }
}

function Jarvis-FindPython {
    $c = Get-Command python -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($c) { return $c.Source }
    $c = Get-Command py -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($c) { return $c.Source }
    throw 'Python was not found on PATH. Jarvis needs Python for speech-to-text and text-to-speech.'
}

function Jarvis-GetCdpTarget {
    param([int]$Port = 9222)
    try {
        $json = @(Invoke-RestMethod -Uri "http://127.0.0.1:$Port/json" -TimeoutSec 3 -ErrorAction Stop)
        $page = @($json | Where-Object { $_.type -eq 'page' -and $_.url -match 'http|file|app\.' } | Select-Object -First 1)
        if (-not $page) { $page = @($json | Where-Object { $_.type -eq 'page' } | Select-Object -First 1) }
        if ($page) { return [string]$page[0].webSocketDebuggerUrl }
    } catch { }
    return $null
}

function Jarvis-GetFreebuffWindow {
    Add-Type -AssemblyName UIAutomationClient -ErrorAction SilentlyContinue
    $proc = Get-Process -Name 'Freebuff' -ErrorAction SilentlyContinue |
        Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
    if (-not $proc) { return $null }
    $root = [System.Windows.Automation.AutomationElement]::RootElement
    $cond = New-Object System.Windows.Automation.PropertyCondition(
        [System.Windows.Automation.AutomationElement]::ProcessIdProperty, $proc.Id)
    return $root.FindFirst([System.Windows.Automation.TreeScope]::Children, $cond)
}

function Jarvis-Listen {
    param([ValidateSet('Whisper', 'WinRT')][string]$Engine, [switch]$NoKeys)
    if ($Engine -eq 'WinRT') { return Jarvis-ListenWinRT }

    if (-not ('JarvisWinMM' -as [type])) {
        Add-Type -TypeDefinition $JarvisRecorderCSharp -ErrorAction Stop
    }
    $wav = Join-Path $env:TEMP 'jarvis-capture.wav'
    if (Test-Path -LiteralPath $wav) { Remove-Item -LiteralPath $wav -Force }

    Write-Host ('Listening... (pause to finish | ENTER = stop now | ESC = quit)  max {0}s' -f $script:JarvisMaxSeconds) -ForegroundColor DarkYellow

    $stopEvt = $null
    try { $stopEvt = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::AutoReset, $script:JarvisStopEventName) } catch { }

    $max = $script:JarvisMaxSeconds
    $sil = $script:JarvisSilenceSeconds
    $idle = $script:JarvisIdleTimeout
    $task = [System.Threading.Tasks.Task]::Run([Func[int]]{ [JarvisWinMM]::Record($wav, $max, $sil, 0.012, $script:JarvisStopEventName, $idle) })

    $esc = $false
    if (-not $NoKeys) {
        while (-not $task.IsCompleted) {
            if ([Console]::KeyAvailable) {
                $key = [Console]::ReadKey($true)
                if ($key.Key -eq [ConsoleKey]::Enter) { if ($stopEvt) { $stopEvt.Set() } }
                elseif ($key.Key -eq [ConsoleKey]::Escape) { if ($stopEvt) { $stopEvt.Set() }; $esc = $true }
            }
            Start-Sleep -Milliseconds 100
        }
    } else {
        # Background (tray) mode: no keyboard input; silence/idle auto-stop only.
        try { $task.Wait() | Out-Null } catch { }   # fault handled by the Result check below
    }
    if ($esc) { return $null }

    $bytes = 0
    try { $bytes = [int]$task.Result }
    catch {
        Write-Warning ("Mic error: {0}" -f $_.Exception.InnerException.Message)
        return ''
    }
    if ($bytes -lt 3200) { Write-Host 'Nothing heard.' -ForegroundColor DarkGray; return '' }

    Write-Host 'Transcribing... (first run downloads the model)' -ForegroundColor DarkYellow
    return Jarvis-Transcribe -Wav $wav
}

function Jarvis-ListenContinuous {
    # Blocks until a finished speech segment is queued, transcribes it and
    # returns the text. Returns $null when the session should end (ESC).
    # While this blocks, the mic keeps capturing: words spoken during
    # transcription, Freebuff work and reply playback are queued, not lost.
    while ($true) {
        if ($script:JarvisContinuumStop) { return $null }
        $path = [JarvisContinuum]::PopSegment()
        if ($path) {
            $startTick = [JarvisContinuum]::LastSegmentTick()
            if ($script:JarvisSpeakEndTick -gt $script:JarvisSpeakStartTick -and
                $startTick -ge $script:JarvisSpeakStartTick -and
                $startTick -le ($script:JarvisSpeakEndTick + $script:JarvisEchoMarginTicks)) {
                # This segment is our own reply echoing back into the mic.
                Jarvis-Log 'skipped self-echo segment'
                Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
                continue
            }
            $text = Jarvis-Transcribe -Wav $path
            Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
            if ($text) { return $text }
            continue
        }
        try {
            if ([Console]::KeyAvailable) {
                $key = [Console]::ReadKey($true)
                if ($key.Key -eq [ConsoleKey]::Escape) { $script:JarvisContinuumStop = $true; return $null }
            }
        } catch { }
        Start-Sleep -Milliseconds 120
    }
}

function Jarvis-ListenWinRT {
    Write-Host 'Listening (Windows speech)... speak now.' -ForegroundColor DarkYellow
    try {
        Add-Type -AssemblyName System.Runtime.WindowsRuntime -ErrorAction Stop
        $null = [Windows.Media.SpeechRecognition.SpeechRecognizer, Windows.Media.SpeechRecognition, ContentType = WindowsRuntime]
        $asTaskGeneric = ([System.WindowsRuntimeSystemExtensions].GetMethods() |
            Where-Object { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and
                $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' })[0]

        $recognizer = New-Object Windows.Media.SpeechRecognition.SpeechRecognizer
        try {
            $constraint = New-Object Windows.Media.SpeechRecognition.SpeechRecognitionTopicConstraint (
                [Windows.Media.SpeechRecognition.SpeechRecognitionScenario]::Dictation, 'dictation')
            $recognizer.Constraints.Add($constraint) | Out-Null

            $compileOp = $recognizer.CompileConstraintsAsync()
            $asTaskC = $asTaskGeneric.MakeGenericMethod([Windows.Media.SpeechRecognition.SpeechRecognitionCompilationResult])
            $compileTask = $asTaskC.Invoke($null, @($compileOp))
            $compileTask.Wait(-1) | Out-Null

            $recOp = $recognizer.RecognizeAsync()
            $asTaskR = $asTaskGeneric.MakeGenericMethod([Windows.Media.SpeechRecognition.SpeechRecognitionResult])
            $recTask = $asTaskR.Invoke($null, @($recOp))
            $recTask.Wait(-1) | Out-Null
            $result = $recTask.Result
            if ($result.Status -eq [Windows.Media.SpeechRecognition.SpeechRecognitionResultStatus]::Success) {
                return $result.Text
            }
            return ''
        } finally {
            $recognizer.Dispose()
        }
    } catch {
        Write-Warning ("Windows speech recognition failed: {0}" -f $_.Exception.Message)
        Write-Host 'Check Settings > Privacy > Microphone allows desktop apps.' -ForegroundColor DarkGray
        return ''
    }
}

function Jarvis-Log {
