    } catch { }
}

function Jarvis-ReadResponse {
    param(
        [string]$SentPrompt,
        [hashtable]$Before,
        [int]$TimeoutSeconds = 1200,
        [int]$StableSeconds = 5
    )
    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    $beforeText = if ($Before -and $Before.Text) { [string]$Before.Text } else { '' }
    $promptTrim = $SentPrompt.Trim()
    $prevDoc = $null
    $stableSince = $null
    $started = $false
    $startedAt = Get-Date
    $lastStatus = Get-Date

    while ((Get-Date) -lt $deadline) {
        if (((Get-Date) - $lastStatus).TotalSeconds -ge 15) {
            Write-Host ('  Freebuff is working... {0}s elapsed' -f [int]((Get-Date) - $startedAt).TotalSeconds) -ForegroundColor DarkGray
            $lastStatus = Get-Date
        }
        $cur = Jarvis-CurrentLastText
        if ($null -eq $cur -and ((Get-Date) - $startedAt).TotalSeconds -ge 30) {
            # Freebuff is not readable (no CDP endpoint and no UI Automation
            # content) - don't sit here for the full timeout.
            return $null
        }
        if ($cur -and $cur.Text) {
            $textTrim = ([string]$cur.Text).Trim()
            $isPromptEcho = $textTrim -eq $promptTrim -or
                ([string]$cur.Text).TrimEnd().EndsWith($promptTrim)

            if (-not $started) {
                if ($cur.Mode -eq 'doc') {
                    $docGrew = $cur.Text.Length -gt $beforeText.Length + 2 -and -not $isPromptEcho
                    if ($docGrew) { $started = $true; $prevDoc = $cur.Text; $stableSince = Get-Date }
                } else {
                    $changed = $textTrim -ne $promptTrim -and $textTrim -ne $beforeText.Trim() -and $textTrim.Length -gt 0
                    if ($changed) { $started = $true; $prevDoc = $cur.Text; $stableSince = Get-Date }
                }
            } else {
                if ($cur.Text -ne $prevDoc) { $prevDoc = $cur.Text; $stableSince = Get-Date }
                elseif (((Get-Date) - $stableSince).TotalSeconds -ge $StableSeconds) {
                    if ($cur.Mode -eq 'doc') {
                        $newPart = $cur.Text.Substring([Math]::Min($beforeText.Length, $cur.Text.Length))
                        $newPart = $newPart.TrimStart()
                        if ($newPart.Length -ge $promptTrim.Length -and
                            $newPart.Substring(0, $promptTrim.Length) -eq $promptTrim) {
                            $newPart = $newPart.Substring($promptTrim.Length).TrimStart()
                        }
                        return $newPart.Trim()
                    }
                    return $textTrim
                }
            }
        }
        Start-Sleep -Milliseconds 700
    }
    return $null
}

function Jarvis-SendPrompt {
    param([string]$Text)
    if ($script:JarvisCdp) {
        if (Jarvis-CdpSendPrompt -Text $Text) { return }
    }
    $shell = New-Object -ComObject WScript.Shell
    $proc = Get-Process -Name 'Freebuff' -ErrorAction SilentlyContinue |
        Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
    if (-not $proc) { throw 'Freebuff desktop app is not running.' }
    $null = $shell.AppActivate($proc.Id)
    Start-Sleep -Milliseconds 700

    $edit = $null
    $win = Jarvis-GetFreebuffWindow
    if ($win) {
        $editCond = New-Object System.Windows.Automation.PropertyCondition(
            [System.Windows.Automation.AutomationElement]::ControlTypeProperty,
            [System.Windows.Automation.ControlType]::Edit)
        $edit = $win.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $editCond)
    }

    $set = $false
    if ($edit) {
        try {
            $edit.SetFocus() | Out-Null
            Start-Sleep -Milliseconds 150
            $vp = $edit.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern)
            $vp.SetValue($Text)
            $set = $true
        } catch { $set = $false }
    }
    if (-not $set) {
        # MTA-safe clipboard set via clip.exe, then paste.
        $clip = Join-Path $env:SystemRoot 'System32\clip.exe'
        $p = New-Object System.Diagnostics.Process
        $p.StartInfo.FileName = $clip
        $p.StartInfo.UseShellExecute = $false
        $p.StartInfo.RedirectStandardInput = $true
        $null = $p.Start()
        $p.StandardInput.Write($Text)
        $p.StandardInput.Close()
        $p.WaitForExit()
        Start-Sleep -Milliseconds 200
        $shell.SendKeys('^v')
        Start-Sleep -Milliseconds 300
    }
    $shell.SendKeys('{ENTER}')
    Start-Sleep -Milliseconds 600
}

function Jarvis-Speak {
    param([string]$Text, [switch]$Force)
    if ($script:JarvisMuted -and -not $Force) { Write-Host '[muted]' -ForegroundColor DarkGray; return }
    if ([string]::IsNullOrWhiteSpace($Text)) { return }
    if ($Text.Length -gt 4000) { $Text = $Text.Substring(0, 4000) + ' (response truncated; full text in the transcript)' }

    try {
        $py = Jarvis-FindPython
        $mp3 = Join-Path $env:TEMP 'jarvis-speech.mp3'
        $txt = Join-Path $env:TEMP 'jarvis-speech.txt'
        [System.IO.File]::WriteAllText($txt, $Text, (New-Object System.Text.UTF8Encoding($false)))
        & $py -m edge_tts --voice $script:JarvisVoice --file $txt --write-media $mp3 2>$null | Out-Null
        if (-not (Test-Path -LiteralPath $mp3) -or (Get-Item -LiteralPath $mp3).Length -lt 2048) {
            Write-Warning 'edge-tts returned no audio; falling back to the Windows system voice.'
            Add-Type -AssemblyName System.Speech -ErrorAction SilentlyContinue
            $synth = New-Object System.Speech.Synthesis.SpeechSynthesizer
            $synth.Rate = 0
            $script:JarvisSpeakStartTick = [System.Diagnostics.Stopwatch]::GetTimestamp()
            $synth.Speak($Text)
            $script:JarvisSpeakEndTick = [System.Diagnostics.Stopwatch]::GetTimestamp()
            return
        }

        # Playback, never blocking forever: MediaPlayer (bounded sleep) -> WMP (capped) -> OS default.
        # The speak-window ticks let the continuous listener discard our own echo.
        $script:JarvisSpeakStartTick = [System.Diagnostics.Stopwatch]::GetTimestamp()
        $script:JarvisSpeakEndTick = $script:JarvisSpeakStartTick
        try {
            Add-Type -AssemblyName PresentationCore -ErrorAction Stop
            $player = New-Object System.Windows.Media.MediaPlayer
            $player.Open([Uri](New-Object System.Uri($mp3)))
            $player.Play()
            $secs = [Math]::Min(180, [Math]::Max(2, [Math]::Ceiling($Text.Length / 14)))
            Start-Sleep -Seconds $secs
            try { $player.Stop(); $player.Close() } catch { }
            $script:JarvisSpeakEndTick = [System.Diagnostics.Stopwatch]::GetTimestamp()
        } catch {
            try {
                $wmp = New-Object -ComObject WMPlayer.OCX
                $wmp.settings.volume = 100
                $wmp.URL = $mp3
                $deadline = (Get-Date).AddSeconds(25)
                while ($wmp.playState -ne 1 -and (Get-Date) -lt $deadline) { Start-Sleep -Milliseconds 150 }
                $script:JarvisSpeakEndTick = [System.Diagnostics.Stopwatch]::GetTimestamp()
            } catch {
                try { Start-Process $mp3 } catch { }
                $script:JarvisSpeakEndTick = [System.Diagnostics.Stopwatch]::GetTimestamp()
                Write-Warning ("Speech playback failed: {0}" -f $_.Exception.Message)
            }
        }
    } catch {
        Write-Warning ("TTS failed: {0}" -f $_.Exception.Message)
    }
}

function Jarvis-StartContinuum {
    # Threshold = minimum RMS (0..1) treated as speech; lower = more sensitive.
    # 0.012 is right for a normal voice; raise it if fan/keyboard noise triggers
    # segments, lower it if quiet speech is missed.
    param([double]$Threshold = 0.012)
    if (-not ('JarvisContinuum' -as [type])) {
        Add-Type -TypeDefinition $JarvisContinuumCSharp -ErrorAction Stop
    }
    $dir = Join-Path $env:TEMP 'jarvis-segments'
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    Get-ChildItem -LiteralPath $dir -Filter 'seg-*.wav' -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
    [JarvisContinuum]::Start($dir, $Threshold, $script:JarvisSilenceSeconds, 30)
    $script:JarvisSegmentDir = $dir
    $script:JarvisContinuumStop = $false
}

function Jarvis-Transcribe {
    param([string]$Wav)
    if (-not (Test-Path -LiteralPath $Wav)) { return '' }
    $py = Jarvis-FindPython
    $stt = Join-Path $PSScriptRoot 'jarvis-stt.py'
    $out = & $py $stt $Wav $script:JarvisSTTModel 2>$null
    return ([string]($out | Select-Object -Last 1)).Trim()
}

