function latest {
[CmdletBinding()]
    param()

    $currentDirectory = (Get-Location).Path
    $latestFile = Get-ChildItem -LiteralPath $currentDirectory -Force -File -ErrorAction Stop |
        Sort-Object -Property @{ Expression = { [System.Math]::Max($_.LastWriteTimeUtc.Ticks, $_.CreationTimeUtc.Ticks) }; Descending = $true }, @{ Expression = { $_.FullName }; Descending = $false } |
        Select-Object -First 1

    if ($null -eq $latestFile) {
        throw "No files were found in the current directory: $currentDirectory"
    }

    $fullPath = $latestFile.FullName
    Set-Clipboard -Value $fullPath -ErrorAction Stop
    $fullPath
}

