function lines {
    param([string]$Path)
    try {
        $resolved = (Resolve-Path $Path -ErrorAction Stop).Path
        $file = [System.IO.File]::OpenRead($resolved)
        $reader = [System.IO.StreamReader]::new($file)
        $count = 0
        while ($null -ne ($line = $reader.ReadLine())) { $count++ }
        $reader.Dispose()
        $file.Dispose()
        $count
    } catch {
        Write-Error "lines: $_"
    }
}

function listcc {
    [CmdletBinding()]
    param()
    $points = @(Get-ComputerRestorePoint | Sort-Object SequenceNumber -Descending)
    if ($points.Count -eq 0) {
        Write-Host 'No restore points found.'
        return
    }
    $points | ForEach-Object {
        [pscustomobject]@{
            SequenceNumber = $_.SequenceNumber
            Date           = global:Convert-CcRestorePointTime $_.CreationTime
            Description    = $_.Description
            RestoreType    = $_.RestorePointType
            EventType      = $_.EventType
            AffectedItems  = 'Windows does not expose the per-restore-point affected-programs scan through PowerShell; use System Restore UI > Scan for affected programs for this exact point.'
        }
    } | Format-List
}

function listcod {
    $p = 'F:\backup\codex'
    if (-not (Test-Path $p)) { Write-Warning "listcod: backup root not found: $p"; return }
    Write-Host "=== F:\backup\codex (newest first) ===" -ForegroundColor Cyan
    Write-Host ""
    $dirs = Get-ChildItem $p -Directory -Force | Sort-Object LastWriteTime -Descending
    foreach ($d in $dirs) {
        $metaPath = Join-Path $d.FullName 'BACKUP-METADATA.json'
        $sizeBytes = 0L
        $note = ''
        if (Test-Path $metaPath) {
            try {
                $meta = Get-Content $metaPath -Raw | ConvertFrom-Json
                if ($meta.PayloadBytes) { $sizeBytes = [int64]$meta.PayloadBytes }
            } catch {}
        }
        if (-not $sizeBytes) {
            try {
                $sizeBytes = (Get-ChildItem $d.FullName -Recurse -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum
            } catch { $sizeBytes = 0L }
        }
        if (Test-Path (Join-Path $d.FullName 'BACKUP-POINTER.json')) { $note = '  [pointer -> latest payload]' }
        $sizeMB = [math]::Round($sizeBytes / 1MB, 2)
        $sizeGB = [math]::Round($sizeBytes / 1GB, 3)
        Write-Host ("[DIR]  {0,-45} {1,10} MB  ({2,8} GB)  Created: {3}{4}" -f $d.Name, $sizeMB, $sizeGB, $d.CreationTime.ToString('yyyy-MM-dd HH:mm:ss'), $note) -ForegroundColor Yellow
    }
}

