function mmsr {
    $f = "$env:TEMP\MSERT.exe"
    $removalLog = "F:\study\security\msert-automation\removal-log.txt"
    Write-Host "Downloading MSERT..." -ForegroundColor Cyan
    iwr 'https://go.microsoft.com/fwlink/?LinkId=212732' -OutFile $f
    Write-Host "Running scan (auto-removal enabled)..." -ForegroundColor Yellow
    $proc = Start-Process $f -ArgumentList "/Q" -PassThru -Wait
    $logPath = "C:\Windows\debug\msert.log"
    if (Test-Path $logPath) {
        $content = Get-Content $logPath -Raw
        $found = [regex]::Matches($content, '([A-Za-z]:\\[^\r\n"]+\.(exe|dll|bat|vbs|ps1|sys|tmp))')
        $removed = 0
        foreach ($m in $found) {
            $fp = $m.Groups[1].Value.Trim()
            if (Test-Path $fp -ErrorAction SilentlyContinue) {
                try {
                    takeown /f "$fp" /a 2>$null | Out-Null
                    icacls "$fp" /grant "Administrators:F" /c /q 2>$null | Out-Null
                    Remove-Item $fp -Force -ErrorAction Stop
                    Write-Host "[REMOVED] $fp" -ForegroundColor Green
                    Add-Content $removalLog "[mmsr][$(Get-Date -f 'yyyy-MM-dd HH:mm:ss')][REMOVED] $fp"
                    $removed++
                } catch { Write-Host "[FAILED] $fp" -ForegroundColor Red }
            }
        }
        try { Remove-MpThreat -ErrorAction SilentlyContinue } catch {}
        Write-Host "mmsr complete. $removed file(s) force-removed." -ForegroundColor Cyan
    }
    Remove-Item $f -Force -ErrorAction SilentlyContinue
}

function mmv {
    [CmdletBinding()]
    param(
        [Parameter(ValueFromRemainingArguments = $true)]
        [string[]]$Items
    )

    if (-not $Items -or $Items.Count -lt 2) {
        throw 'Usage: mmv <source1> <source2> ... <destination-folder>'
    }

    $destination = $Items[-1]
    $sources = @($Items[0..($Items.Count - 2)])
    Invoke-FastLiteralTransfer -SourcePaths $sources -DestinationPath $destination -Mode Move
}

