function New-BackupDockerTag {
    [CmdletBinding(DefaultParameterSetName = 'RepoSlug')]
    param(
        [Parameter(Mandatory, ParameterSetName = 'Path')]
        [string]$Path,

        [Parameter(Mandatory, ParameterSetName = 'Name')]
        [string]$Name,

        [Parameter(Mandatory, ParameterSetName = 'RepoSlug')]
        [string]$RepoSlug
    )

    $resolvedRepoSlug = if ($PSCmdlet.ParameterSetName -eq 'Path') {
        Get-BackupDockerRepoSlug -Path $Path
    } elseif ($PSCmdlet.ParameterSetName -eq 'Name') {
        Get-BackupDockerRepoSlug -Name $Name
    } else {
        $RepoSlug
    }

    $remoteTagNames = @(Get-BackupDockerHubTagNames -RepoSlug $resolvedRepoSlug)
    return ([string]($remoteTagNames.Count + 1))
}

function New-JarvisIcon {
    try {
        $bmp = New-Object System.Drawing.Bitmap 32, 32
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.Clear([System.Drawing.Color]::FromArgb(255, 0, 112, 243))
        $font = New-Object System.Drawing.Font('Segoe UI', 17, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)
        $g.DrawString('J', $font, [System.Drawing.Brushes]::White, 5, 0)
        $g.Flush()
        $hIcon = $bmp.GetHicon()
        $ic = [System.Drawing.Icon]::FromHandle($hIcon)
        $fs = [System.IO.File]::Open($script:IconPath, [System.IO.FileMode]::Create)
        $ic.Save($fs)
        $fs.Close()
        $ic.Dispose()
        $g.Dispose()
        $bmp.Dispose()
    } catch { Write-TrayLog ('icon creation failed: ' + $_.Exception.Message) }
}

function New-ProfileFunctionMutationDefinition {
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][scriptblock]$Body,
        [switch]$Global
    )
    $bodyText = $Body.ToString().Trim()
    if ([string]::IsNullOrWhiteSpace($bodyText)) {
        throw "Function '$Name' needs a non-empty script block body."
    }
    $declaredName = if ($Global) { "global:$Name" } else { $Name }
    $definition = "function $declaredName {`r`n$bodyText`r`n}"
    Test-ProfileFunctionMutationSource -Source $definition -Label "Function '$Name'"
    $definition
}

function New-RobocopyArgumentLine {
        param([string[]]$Values)

        $quotedValues = foreach ($value in $Values) {
            if ($null -eq $value) { continue }
            if ($value -match '[\s"]') {
                '"' + $value.Replace('"', '\"') + '"'
            } else {
                $value
            }
        }
        return [string]::Join(' ', $quotedValues)
    }

