function nvioc {
    [CmdletBinding()]
    param(
        # Run the (slow) health check first: verify the model list, probe
        # inference, and auto-fall-back to the best working model.
        # Default OFF so the TUI opens INSTANTLY with the default model.
        [switch]$Check,
        [Parameter(ValueFromRemainingArguments = $true)][string[]]$Args
    )

    # ═══════════════════════════════════════════════════════════════════
    # NVIDIA API KEY LOADING
    # Priority: env var -> key file -> opencode auth.json
    # ═══════════════════════════════════════════════════════════════════
    $nvidiaApiKey = $env:NVIDIA_API_KEY
    $keySource = 'env'

    if (-not $nvidiaApiKey -or [string]::IsNullOrWhiteSpace($nvidiaApiKey)) {
        $keyFile = 'F:\backup\windowsapps\credentials\nvidia\api.txt'
        if (Test-Path -LiteralPath $keyFile -PathType Leaf) {
            $nvidiaApiKey = (Get-Content -LiteralPath $keyFile -Raw).Trim()
            $keySource = 'file'
            Write-Host "OC_PROGRESS stage=api-key-loaded source=file"
        }
    }

    if (-not $nvidiaApiKey -or [string]::IsNullOrWhiteSpace($nvidiaApiKey)) {
        $authFile = Join-Path $env:USERPROFILE '.local\share\opencode\auth.json'
        if (Test-Path -LiteralPath $authFile -PathType Leaf) {
            try {
                $authJson = Get-Content -LiteralPath $authFile -Raw | ConvertFrom-Json
                if ($authJson.nvidia -and $authJson.nvidia.key) {
                    $nvidiaApiKey = $authJson.nvidia.key
                    $keySource = 'auth.json'
                    Write-Host "OC_PROGRESS stage=api-key-loaded source=auth.json"
                }
            } catch {
                Write-Host "OC_PROGRESS stage=auth-json-parse-error msg=$($_.Exception.Message)"
            }
        }
    }

    if (-not $nvidiaApiKey -or [string]::IsNullOrWhiteSpace($nvidiaApiKey)) {
        $ocCfgCandidates = @(
            (Join-Path $env:USERPROFILE '.config\opencode\opencode.json'),
            (Join-Path $env:APPDATA 'opencode\opencode.json')
        )
        foreach ($ocCfg in $ocCfgCandidates) {
            if (-not (Test-Path -LiteralPath $ocCfg -PathType Leaf)) { continue }
            try {
                $ocCfgJson = Get-Content -LiteralPath $ocCfg -Raw | ConvertFrom-Json
                $nested = $null
                if ($ocCfgJson.provider -and $ocCfgJson.provider.'nvidia-nim') {
                    $nested = $ocCfgJson.provider.'nvidia-nim'
                } elseif ($ocCfgJson.provider -and $ocCfgJson.provider.nvidia) {
                    $nested = $ocCfgJson.provider.nvidia
                }
                if ($nested) {
                    if ($nested.options -and $nested.options.apiKey) {
                        $nvidiaApiKey = [string]$nested.options.apiKey
                        $keySource = 'opencode.json'
                        Write-Host "OC_PROGRESS stage=api-key-loaded source=opencode.json"
                        break
                    }
                }
            } catch {
                Write-Host "OC_PROGRESS stage=opencode-config-parse-error msg=$($_.Exception.Message)"
            }
        }
    }

    if (-not $nvidiaApiKey -or [string]::IsNullOrWhiteSpace($nvidiaApiKey)) {
        throw "NVIDIA_API_KEY not found. Set env var, ensure key file at F:\backup\windowsapps\credentials\nvidia\api-keys.txt, or run 'opencode auth login' with nvidia provider."
    }

    # Set NVIDIA API key in environment for opencode's built-in nvidia provider
    $env:NVIDIA_API_KEY = $nvidiaApiKey

    # Also set OPENAI_API_KEY — the @ai-sdk/openai-compatible SDK reads this
    # for auth when apiKey is not in provider options.
    $env:OPENAI_API_KEY = $nvidiaApiKey

    # ═══════════════════════════════════════════════════════════════════
    # PERMISSION MODE (auto-allow all tools)
    # ═══════════════════════════════════════════════════════════════════
    $env:OPENCODE_PERMISSION_BASH = 'allow'
    $env:OPENCODE_PERMISSION_READ = 'allow'
    $env:OPENCODE_PERMISSION_WRITE = 'allow'
    $env:OPENCODE_PERMISSION_EDIT = 'allow'
    $env:OPENCODE_PERMISSION_GLOB = 'allow'
    $env:OPENCODE_PERMISSION_GREP = 'allow'
    $env:OPENCODE_PERMISSION_TASK = 'allow'
    $env:OPENCODE_PERMISSION_WEBFETCH = 'allow'
    $env:OPENCODE_PERMISSION_PATCH = 'allow'
    $env:OPENCODE_PERMISSION_LIST = 'allow'
    $env:OPENCODE_PERMISSION_TODO = 'allow'
    $env:OPENCODE_PERMISSION_QUESTION = 'allow'

    # Pin OpenCode's shell discovery to native Windows PowerShell 5.1. This
    # prevents Git Bash/WSL from pre-expanding PowerShell syntax such as $_.
    $env:SHELL = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"

    # ═══════════════════════════════════════════════════════════════════
    # MODEL DEFINITIONS (verified Aug 18 2026 via NVIDIA NIM API)
    # Ranked by CAPABILITY first (best model is the DEFAULT), with the
    # fast anti-429 pre-flight falling back to the best AVAILABLE model
    # when the top one is rate-limited at launch time.
    #
    # Custom provider "nvidia-nim" (NOT "nvidia") avoids merging with
    # the built-in nvidia provider from models.dev catalog, which has
    # 3-segment model IDs that crash with "U.split is not a function".
    #
    # Measured Aug 18 2026: glm-5.2 and inkling were 429 rate-limited;
    # nemotron-3-ultra-550b (0.7s), nemotron-3-super (0.8s) answered OK;
    # deepseek-v4-flash answered OK but slow (9.3s first token).
    # NVIDIA free tier throttles PER MODEL, so the pre-flight probe picks
    # the highest-capability model that is answering RIGHT NOW.
    #
    # 1. Nemotron 3 Ultra   550B flagship, strong general (DEFAULT best)
    # 2. GLM-5.2            753B MoE, 1M ctx, best coding
    # 3. Nemotron 3 Super   120B (120B params), strong general
    # 4. DeepSeek V4 Flash  284B MoE, 1M ctx, fast coding
    # 5. Inkling             256-expert MoE, 1M ctx, multimodal
    # ═══════════════════════════════════════════════════════════════════
    # Capability order used by nvi through nvi15 and by -Check fallback.
    $modelOrder = @(
        'nvidia-nim/thinkingmachines/inkling',
        'nvidia-nim/nvidia/nemotron-3-ultra-550b-a55b',
        'nvidia-nim/deepseek-ai/deepseek-v4-flash-0731',
        'nvidia-nim/minimaxai/minimax-m3',
        'nvidia-nim/google/gemma-4-31b-it',
        'nvidia-nim/stepfun-ai/step-3.7-flash',
        'nvidia-nim/nvidia/nemotron-3-super-120b-a12b',
        'nvidia-nim/nvidia/llama-3.3-nemotron-super-49b-v1.5',
        'nvidia-nim/poolside/laguna-xs-2.1',
        'nvidia-nim/openai/gpt-oss-120b',
        'nvidia-nim/meta/llama-3.3-70b-instruct',
        'nvidia-nim/meta/llama-3.1-70b-instruct',
        'nvidia-nim/nvidia/nemotron-3-nano-omni-30b-a3b-reasoning',
        'nvidia-nim/nvidia/nemotron-3.5-lightning-30b-a3b',
        'nvidia-nim/nvidia/nemotron-3-nano-30b-a3b'
    )

    # Human-readable labels for progress output
    $modelLabels = @{
        'nvidia-nim/nvidia/nemotron-3-ultra-550b-a55b'   = 'Nemotron 3 Ultra (550B flagship, best general)'
        'nvidia-nim/z-ai/glm-5.2'                       = 'GLM-5.2 (753B MoE, best coding)'
        'nvidia-nim/nvidia/nemotron-3-super-120b-a12b'   = 'Nemotron 3 Super (120B, strong general)'
        'nvidia-nim/deepseek-ai/deepseek-v4-flash-0731' = 'DeepSeek V4 Flash (284B MoE, fast coding)'
        'nvidia-nim/thinkingmachines/inkling'            = 'Inkling (multimodal, text+image+audio)'
        'nvidia-nim/minimaxai/minimax-m3'                = 'MiniMax M3 (428B MoE, multimodal, 1M context)'
        'nvidia-nim/google/gemma-4-31b-it'                = 'Gemma 4 31B IT (reasoning, coding, multimodal)'
        'nvidia-nim/stepfun-ai/step-3.7-flash'            = 'Step 3.7 Flash (198B MoE, coding, multimodal)'
        'nvidia-nim/nvidia/llama-3.3-nemotron-super-49b-v1.5' = 'Llama 3.3 Nemotron Super 49B v1.5'
        'nvidia-nim/poolside/laguna-xs-2.1'               = 'Poolside Laguna XS 2.1 (agentic coding)'
        'nvidia-nim/openai/gpt-oss-120b'                  = 'GPT-OSS 120B (OpenAI open)'
        'nvidia-nim/meta/llama-3.3-70b-instruct'           = 'Llama 3.3 70B Instruct'
        'nvidia-nim/meta/llama-3.1-70b-instruct'           = 'Llama 3.1 70B Instruct'
        'nvidia-nim/nvidia/nemotron-3-nano-omni-30b-a3b-reasoning' = 'Nemotron Nano Omni 30B Reasoning'
        'nvidia-nim/nvidia/nemotron-3.5-lightning-30b-a3b' = 'Nemotron 3.5 Lightning 30B'
        'nvidia-nim/nvidia/nemotron-3-nano-30b-a3b'       = 'Nemotron 3 Nano 30B'
    }

    # DEFAULT: Nemotron 3 Super (120B) — 50x faster than Ultra (550B).
    # Ultra: ~36s response. Super: ~0.6s response. Both strong general.
    # The TUI opens almost instantly unless -Check is passed; the
    # fast pre-flight probe below re-verifies and falls back if throttled.
    $defaultModel = 'nvidia-nim/nvidia/nemotron-3-super-120b-a12b'

    # ═══════════════════════════════════════════════════════════════════
    # PARSE COMMAND-LINE ARGUMENTS
    # Extract -m/--model flag and value, pass everything else through.
    # NOTE: the model is passed exactly ONCE via '-m $finalModelArg' at
    # launch below. Never inject another '-m' into $Args here: yargs 18
    # turns a repeated -m/--model into an ARRAY, and opencode's TUI
    # crashes with "U.split is not a function" on a non-string model.
    # ═══════════════════════════════════════════════════════════════════
    $modelArg = $defaultModel
    $hasModelFlag = $false
    $filteredArgs = @()
    for ($i = 0; $i -lt $Args.Count; $i++) {
        $arg = $Args[$i]
        if ($arg -eq '-m' -or $arg -eq '--model') {
            $hasModelFlag = $true
            if ($i + 1 -lt $Args.Count) {
                $modelArg = $Args[$i + 1]
                $i++
            }
        } elseif ($arg -match '^-m=(.+)$') {
            $hasModelFlag = $true
            $modelArg = $matches[1]
        } elseif ($arg -match '^--model=(.+)$') {
            $hasModelFlag = $true
            $modelArg = $matches[1]
        } else {
            $filteredArgs += $arg
        }
    }
    $Args = $filteredArgs

    # ═══════════════════════════════════════════════════════════════════
    # OPTIONAL HEALTH CHECK (only with -Check)
    # Phase 1: Check model exists in /v1/models list (no credits)
    # Phase 2: Quick inference probe with max_tokens=1 (detects 429)
    # ═══════════════════════════════════════════════════════════════════
    function Get-NvidiaModelList {
        param(
            [string]$ApiKey,
            [int]$TimeoutSec = 30
        )
        try {
            $headers = @{ 'Authorization' = "Bearer $ApiKey" }
            $response = Invoke-RestMethod -Uri 'https://integrate.api.nvidia.com/v1/models' -Headers $headers -Method Get -TimeoutSec $TimeoutSec -ErrorAction Stop
            if ($response -and $response.data) {
                return $response.data
            }
        } catch {
            Write-Host "OC_PROGRESS stage=model-list-error msg=$($_.Exception.Message)"
        }
        return $null
    }

    function Test-ModelListed {
        param(
            [string]$ModelId,
            [object[]]$ModelList
        )
        # Strip the opencode provider prefix to get the raw NIM model ID
        # nvidia-nim/z-ai/glm-5.2 -> z-ai/glm-5.2
        # nvidia-nim/nvidia/nemotron-3-ultra-550b-a55b -> nvidia/nemotron-3-ultra-550b-a55b
        $apiModelId = $ModelId -replace '^[^/]+/', ''

        if ($null -eq $ModelList) { return $false }

        foreach ($m in $ModelList) {
            if ($m.id -eq $apiModelId) {
                return $true
            }
        }
        return $false
    }

    function Test-ModelInference {
        param(
            [string]$ModelId,
            [string]$ApiKey,
            [int]$TimeoutSec = 30,
            [int]$MaxRetries = 3
        )
        # Quick inference probe with retries.
        # Retries handle transient 500s, timeouts (status=0), and brief 429s.
        $apiModelId = $ModelId -replace '^[^/]+/', ''
        $lastStatus = 0

        for ($attempt = 1; $attempt -le $MaxRetries; $attempt++) {
            try {
                $headers = @{
                    'Authorization' = "Bearer $ApiKey"
                    'Content-Type'  = 'application/json'
                }
                $body = @{
                    model       = $apiModelId
                    messages    = @(@{ role = 'user'; content = 'Hi' })
                    max_tokens  = 1
                    temperature = 0
                } | ConvertTo-Json -Depth 5
                $response = Invoke-RestMethod -Uri 'https://integrate.api.nvidia.com/v1/chat/completions' -Headers $headers -Method Post -Body $body -TimeoutSec $TimeoutSec -ErrorAction Stop
                return $true
            } catch {
                $lastStatus = 0
                if ($_.Exception.Response) {
                    $lastStatus = $_.Exception.Response.StatusCode.value__
                }
                # 429 = rate limit, 500/502/503 = transient server error, 0 = timeout/connection
                # All are retryable. 404 = model doesn't exist, not retryable.
                if ($lastStatus -eq 404) {
                    Write-Host "OC_PROGRESS stage=inference-probe-fail model=$ModelId status=$lastStatus (not found, no retry)"
                    return $false
                }
                if ($attempt -lt $MaxRetries) {
                    $backoff = $attempt * 2
                    Write-Host "OC_PROGRESS stage=inference-probe-retry model=$ModelId status=$lastStatus attempt=$attempt/$MaxRetries wait=${backoff}s"
                    Start-Sleep -Seconds $backoff
                } else {
                    Write-Host "OC_PROGRESS stage=inference-probe-fail model=$ModelId status=$lastStatus attempts=$MaxRetries exhausted"
                    return $false
                }
            }
        }
        return $false
    }

    function Test-ModelFast {
        param(
            [string]$ModelId,
            [string]$ApiKey,
            [int]$TimeoutSec = 5
        )
        # Single-shot availability probe: catches 429 rate limits fast.
        # No retries - a 429 answers in ~0.2s; we simply move to the next
        # model. Timeout capped so a hung model can't stall launch.
        $apiModelId = $ModelId -replace '^[^/]+/', ''
        try {
            $headers = @{
                'Authorization' = "Bearer $ApiKey"
                'Content-Type'  = 'application/json'
            }
            $body = @{
                model       = $apiModelId
                messages    = @(@{ role = 'user'; content = 'Hi' })
                max_tokens  = 1
                temperature = 0
            } | ConvertTo-Json -Depth 5
            $null = Invoke-RestMethod -Uri 'https://integrate.api.nvidia.com/v1/chat/completions' -Headers $headers -Method Post -Body $body -TimeoutSec $TimeoutSec -ErrorAction Stop
            return $true
        } catch {
            return $false
        }
    }

    # ───────────────────────────────────────────────────────────────────
    # MODEL HEALTH CACHE
    # Every launch used to re-probe models - and those probes themselves
    # burn the shared NVIDIA rate limit, CAUSING the very 429s we avoid.
    # A small JSON cache with a TTL means a model verified OK within the
    # last minute is trusted instantly (zero probe traffic), and a model
    # that was throttled isn't re-probed until its window likely cleared.
    # This keeps launches instant AND reduces self-inflicted throttling.
    # ───────────────────────────────────────────────────────────────────
    $healthCachePath = Join-Path $env:USERPROFILE '.config\opencode\model-health.json'

    function Read-ModelHealthCache {
        if (Test-Path -LiteralPath $healthCachePath -PathType Leaf) {
            try {
                return (Get-Content -LiteralPath $healthCachePath -Raw | ConvertFrom-Json)
            } catch { }
        }
        return $null
    }

    function Write-ModelHealthCache {
        param([object]$Cache)
        $cacheMutex = New-Object Threading.Mutex($false, 'Local\NviocModelHealthCacheV1')
        $cacheLockTaken = $false
        $temporaryPath = $null
        try {
            try {
                $cacheLockTaken = $cacheMutex.WaitOne(1000)
            } catch [Threading.AbandonedMutexException] {
                $cacheLockTaken = $true
            }
            if (-not $cacheLockTaken) { return }
            $dir = Split-Path -Parent $healthCachePath
            if (-not (Test-Path -LiteralPath $dir -PathType Container)) {
                New-Item -ItemType Directory -Force -Path $dir | Out-Null
            }
            $temporaryPath = "$healthCachePath.tmp.$PID.$([guid]::NewGuid().ToString('N'))"
            $json = $Cache | ConvertTo-Json -Depth 4
            [IO.File]::WriteAllText(
                $temporaryPath,
                ($json + "`r`n"),
                (New-Object Text.UTF8Encoding($false))
            )
            if ([IO.File]::Exists($healthCachePath)) {
                [IO.File]::Replace($temporaryPath, $healthCachePath, $null, $true)
            } else {
                [IO.File]::Move($temporaryPath, $healthCachePath)
            }
            $temporaryPath = $null
        } catch { }
        finally {
            if ($temporaryPath -and [IO.File]::Exists($temporaryPath)) {
                [IO.File]::Delete($temporaryPath)
            }
            if ($cacheLockTaken) {
                [void]$cacheMutex.ReleaseMutex()
            }
            $cacheMutex.Dispose()
        }
    }

    function Test-ModelCached {
        param(
            [string]$ModelId,
            [string]$ApiKey,
            [int]$OkTtlSec = 60,
            [int]$ThrottledRetrySec = 45
        )
        # Decision helper: honor a fresh cache entry instead of probing.
        # Returns @{ ok; status; source = 'cache' | 'probe' }
        $now = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
        $cache = Read-ModelHealthCache
        if ($cache -and $cache.models -and $cache.models.$ModelId) {
            $entry = $cache.models.$ModelId
            $ageSec = ($now - [int64]$entry.ts) / 1000.0
            if ($entry.ok -and $ageSec -le $OkTtlSec) {
                return @{ ok = $true; status = 200; source = 'cache' }
            }
            if (-not $entry.ok -and $entry.status -eq 429 -and $ageSec -le $ThrottledRetrySec) {
                return @{ ok = $false; status = 429; source = 'cache' }
            }
        }
        # Probe (real request) and persist the result.
        $result = Test-ModelFastWithStatus -ModelId $ModelId -ApiKey $ApiKey
        if ($null -eq $cache) { $cache = @{} }
        if (-not $cache.models) { $cache.models = @{} }
        $cache.models.$ModelId = @{
            ok     = [bool]$result.ok
            status = [int]$result.status
            ts     = $now
        }
        Write-ModelHealthCache -Cache $cache
        return @{ ok = [bool]$result.ok; status = [int]$result.status; source = 'probe' }
    }

    function Test-ModelFastWithStatus {
        param(
            [string]$ModelId,
            [string]$ApiKey,
            [int]$TimeoutSec = 5
        )
        # Like Test-ModelFast but returns the HTTP status code so callers
        # can distinguish 429 (rate limit, may clear) from 404/500/etc.
        $apiModelId = $ModelId -replace '^[^/]+/', ''
        try {
            $headers = @{
                'Authorization' = "Bearer $ApiKey"
                'Content-Type'  = 'application/json'
            }
            $body = @{
                model       = $apiModelId
                messages    = @(@{ role = 'user'; content = 'Hi' })
                max_tokens  = 1
                temperature = 0
            } | ConvertTo-Json -Depth 5
            $null = Invoke-RestMethod -Uri 'https://integrate.api.nvidia.com/v1/chat/completions' -Headers $headers -Method Post -Body $body -TimeoutSec $TimeoutSec -ErrorAction Stop
            return @{ ok = $true; status = 200 }
        } catch {
            $status = 0
            if ($_.Exception.Response) { $status = [int]$_.Exception.Response.StatusCode }
            return @{ ok = $false; status = $status }
        }
    }

    function Backup-OpenCodeSessions {
        # The database can be several gigabytes. Start one low-priority,
        # SQLite-consistent backup worker and never block the TUI launch.
        $dbPath = Join-Path $env:USERPROFILE '.local\share\opencode\opencode.db'
        if (-not (Test-Path -LiteralPath $dbPath -PathType Leaf)) { return }
        $backupDir = 'F:\backup\opencode-sessions'
        $helper = 'F:\study\Platforms\windows\functions\backup-opencode-sessions.py'
        $marker = Join-Path $backupDir '.opencode-backup.active'
        $receipt = Join-Path $backupDir 'opencode-backup-receipt.json'
        try {
            if (-not (Test-Path -LiteralPath $backupDir -PathType Container)) {
                New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
            }
            if (-not (Test-Path -LiteralPath $helper -PathType Leaf)) {
                Write-Host "OC_PROGRESS stage=sessions-backup-helper-missing path=$helper"
                return
            }
            if (Test-Path -LiteralPath $receipt -PathType Leaf) {
                try {
                    $receiptState = Get-Content -LiteralPath $receipt -Raw | ConvertFrom-Json
                    $receiptAge = ([DateTime]::UtcNow - (Get-Item -LiteralPath $receipt).LastWriteTimeUtc).TotalSeconds
                    if ($receiptAge -lt 900 -and $receiptState.status -in @('completed', 'recent_backup')) {
                        return
                    }
                } catch { }
            }
            if (Test-Path -LiteralPath $marker -PathType Leaf) {
                $markerAge = ([DateTime]::UtcNow - (Get-Item -LiteralPath $marker).LastWriteTimeUtc).TotalSeconds
                $markerPid = 0
                try { $markerPid = [int](Get-Content -LiteralPath $marker -Raw).Trim() } catch { }
                if (($markerPid -gt 0 -and (Get-Process -Id $markerPid -ErrorAction SilentlyContinue)) -or $markerAge -lt 60) {
                    return
                }
                Remove-Item -LiteralPath $marker -Force -ErrorAction SilentlyContinue
            }
            $markerStream = $null
            try {
                $markerStream = [IO.File]::Open(
                    $marker,
                    [IO.FileMode]::CreateNew,
                    [IO.FileAccess]::Write,
                    [IO.FileShare]::Read
                )
            } catch [IO.IOException] {
                return
            } finally {
                if ($markerStream) { $markerStream.Dispose() }
            }
            $pyExe = $null
            foreach ($pythonCandidate in @(
                'C:\Users\micha\AppData\Local\Programs\Python\Python312\python.exe',
                'C:\Users\micha\AppData\Local\Programs\Python\Python311\python.exe'
            )) {
                if (Test-Path -LiteralPath $pythonCandidate -PathType Leaf) {
                    $pyExe = $pythonCandidate
                    break
                }
            }
            if (-not $pyExe) {
                foreach ($pyCmd in (Get-Command python.exe -CommandType Application -ErrorAction SilentlyContinue)) {
                    if ($pyCmd.Source -notmatch 'WindowsApps') {
                        $pyExe = $pyCmd.Source
                        break
                    }
                }
            }
            if (-not $pyExe) {
                Remove-Item -LiteralPath $marker -Force -ErrorAction SilentlyContinue
                Write-Host 'OC_PROGRESS stage=sessions-backup-skip msg=no-real-python.exe'
                return
            }
            $backupProcess = Start-Process -FilePath $pyExe -ArgumentList @(
                $helper,
                '--source', $dbPath,
                '--destination', $backupDir,
                '--marker', $marker,
                '--minimum-interval-seconds', '900',
                '--retain', '20'
            ) -WindowStyle Hidden -PassThru -ErrorAction Stop
            Write-Host "OC_PROGRESS stage=sessions-backup-started pid=$($backupProcess.Id)"
            $backupProcess.Dispose()
        } catch {
            Remove-Item -LiteralPath $marker -Force -ErrorAction SilentlyContinue
            Write-Host "OC_PROGRESS stage=sessions-backup-skip msg=$($_.Exception.Message)"
        }
    }

    function Clear-StaleOpenCode {
        # Parent lifetimes are not reliable ownership evidence: Windows
        # Terminal handoffs and concurrent short-lived shells can leave a
        # healthy OpenCode process parentless. Preserve every session and
        # let explicit user cancellation plus proxy disconnect handling
        # release upstream work.
        $sessionCount = @(Get-Process -Name 'opencode' -ErrorAction SilentlyContinue).Count
        Write-Host "OC_PROGRESS stage=session-preservation active=$sessionCount"
    }

    # =====================================================================
    # NVIDIA RATE-LIMIT PROXY (with API key rotation)
    # A zero-dependency Node.js proxy on localhost:3460 that:
    #   1. Intercepts 429/503/529 and retries BEFORE OpenCode sees them
    #   2. ROTATES between multiple API keys to maximize rate limit headroom
    #   3. Per-key cooldown: a 429'd key is skipped for 60s
    #   4. Auto-reloads keys file every 60s (add keys without restart)
    #
    # Keys live in nvidia-api-keys.txt (one nvapi- key per line).
    # Add more free keys from https://org.ngc.nvidia.com/setup/api-keys
    # =====================================================================
    $proxyScript = Join-Path $env:USERPROFILE '.config\opencode\nvidia-proxy.cjs'
    $proxyKeysFile = 'F:\backup\windowsapps\credentials\nvidia\api-keys.txt'
    $proxyPort = 3460
    $proxyBaseUrl = "http://127.0.0.1:$proxyPort/v1"

    function Sync-NvidiaApiKeys {
        # Collect all known NVIDIA API keys from various sources and
        # write them to the proxy keys file. Called before proxy start.
        $knownKeys = @{}
        # Source 1: existing keys file
        if (Test-Path -LiteralPath $proxyKeysFile -PathType Leaf) {
            foreach ($line in (Get-Content -LiteralPath $proxyKeysFile)) {
                $t = $line.Trim()
                if ($t -and -not $t.StartsWith('#') -and $t -match 'nvapi-') {
                    $knownKeys[$t] = 'keys-file'
                }
            }
        }
        # Source 2: env var
        if ($env:NVIDIA_API_KEY -and $env:NVIDIA_API_KEY -match 'nvapi-') {
            $knownKeys[$env:NVIDIA_API_KEY.Trim()] = 'env'
        }
        # Source 3: legacy key files (individual api.txt, api2.txt, api3.txt)
        $legacyKeyDir = 'F:\backup\windowsapps\credentials\nvidia'
        if (Test-Path -LiteralPath $legacyKeyDir -PathType Container) {
            foreach ($lkf in @('api.txt', 'api2.txt', 'api3.txt')) {
                $lkfPath = Join-Path $legacyKeyDir $lkf
                if (Test-Path -LiteralPath $lkfPath -PathType Leaf) {
                    $fk = (Get-Content -LiteralPath $lkfPath -Raw).Trim()
                    if ($fk -match 'nvapi-') { $knownKeys[$fk] = "legacy-$lkf" }
                }
            }
        }
        # Source 4: opencode auth.json
        $authFile = Join-Path $env:USERPROFILE '.local\share\opencode\auth.json'
        if (Test-Path -LiteralPath $authFile -PathType Leaf) {
            try {
                $aj = Get-Content -LiteralPath $authFile -Raw | ConvertFrom-Json
                if ($aj.nvidia -and $aj.nvidia.key -and $aj.nvidia.key -match 'nvapi-') {
                    $knownKeys[$aj.nvidia.key.Trim()] = 'auth.json'
                }
            } catch { }
        }
        # Source 5: opencode.json provider configs
        $ocCfgs = @(
            (Join-Path $env:USERPROFILE '.config\opencode\opencode.json'),
            (Join-Path $env:APPDATA 'opencode\opencode.json')
        )
        foreach ($ocCfg in $ocCfgs) {
            if (-not (Test-Path -LiteralPath $ocCfg -PathType Leaf)) { continue }
            try {
                $j = Get-Content -LiteralPath $ocCfg -Raw | ConvertFrom-Json
                $providers = @()
                if ($j.provider.'nvidia-nim') { $providers += $j.provider.'nvidia-nim' }
                if ($j.provider.nvidia) { $providers += $j.provider.nvidia }
                foreach ($p in $providers) {
                    if ($p.options -and $p.options.apiKey -and $p.options.apiKey -match 'nvapi-') {
                        $knownKeys[$p.options.apiKey.Trim()] = 'opencode.json'
                    }
                }
            } catch { }
        }
        # Write unique keys to file
        if ($knownKeys.Count -eq 0) {
            Write-Host "OC_PROGRESS stage=keys-sync-warning no-keys-found"
            return
        }
        $dir = Split-Path -Parent $proxyKeysFile
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) {
            New-Item -ItemType Directory -Force -Path $dir | Out-Null
        }
        $kl = @("# NVIDIA NIM API Keys (auto-synced by nvioc)")
        $kl += "# Add more at https://org.ngc.nvidia.com/setup/api-keys"
        $kl += "# One nvapi- key per line. Proxy rotates between all."
        $kl += "#"
        foreach ($k in $knownKeys.Keys) { $kl += $k }
        $kl -join "`n" | Set-Content -LiteralPath $proxyKeysFile -Encoding UTF8
        Write-Host "OC_PROGRESS stage=keys-synced count=$($knownKeys.Count) path=$proxyKeysFile"
    }

    function Get-NvidiaProxyHealth {
        try {
            $resp = Invoke-WebRequest -Uri "http://127.0.0.1:$proxyPort/health" `
                -Method Get -TimeoutSec 2 -UseBasicParsing -ErrorAction Stop
            if ($resp.StatusCode -eq 200) { return ($resp.Content | ConvertFrom-Json) }
        } catch { }
        return $null
    }

    function Ensure-NvidiaProxy {
        # Returns $true if the proxy is reachable, $false if it could not be started.
        $health = Get-NvidiaProxyHealth
        if ($health) {
            Write-Host "OC_PROGRESS stage=proxy-already-running port=$proxyPort keys=$($health.keys)"
            # Hot-reload the keys file
            try { $null = Invoke-WebRequest -Uri "http://127.0.0.1:$proxyPort/_reload" -Method Get -TimeoutSec 2 -UseBasicParsing -ErrorAction SilentlyContinue } catch { }
            return $true
        }
        if (-not (Test-Path -LiteralPath $proxyScript -PathType Leaf)) {
            Write-Host "OC_PROGRESS stage=proxy-missing path=$proxyScript"
            return $false
        }
        $startupMutex = New-Object Threading.Mutex($false, 'Local\NviocNvidiaProxyStartupV1')
        $startupLockTaken = $false
        try {
            try {
                $startupLockTaken = $startupMutex.WaitOne(0)
            } catch [Threading.AbandonedMutexException] {
                $startupLockTaken = $true
            }
            if (-not $startupLockTaken) {
                $followerDeadline = (Get-Date).AddSeconds(8)
                while ((Get-Date) -lt $followerDeadline) {
                    Start-Sleep -Milliseconds 100
                    if (Get-NvidiaProxyHealth) { return $true }
                }
                Write-Host "OC_PROGRESS stage=proxy-start-wait-timeout port=$proxyPort"
                return $false
            }
            $health = Get-NvidiaProxyHealth
            if ($health) { return $true }
            Sync-NvidiaApiKeys
            $nodeExe = $null
            # Resolve node.exe even when it is not on PATH (the default
            # Node.js install directory is frequently missing from PATH).
            $nodeCandidates = @(
                (Join-Path ${env:ProgramFiles} 'nodejs\node.exe'),
                (Join-Path ${env:ProgramFiles(x86)} 'nodejs\node.exe'),
                (Join-Path ${env:ProgramFiles} 'nodejs\nodejs.exe'),
                (Join-Path ${env:ProgramFiles(x86)} 'nodejs\nodejs.exe')
            )
            foreach ($nodePath in $nodeCandidates) {
                if ($nodePath -and (Test-Path -LiteralPath $nodePath -PathType Leaf)) {
                    $nodeExe = $nodePath
                    break
                }
            }
            if (-not $nodeExe) {
                foreach ($c in (Get-Command node.exe -CommandType Application -ErrorAction SilentlyContinue)) {
                    if ($c.Source -notmatch 'WindowsApps') { $nodeExe = $c.Source; break }
                }
            }
            if (-not $nodeExe) { $nodeExe = 'node' }
            $proxyProcess = Start-Process -FilePath $nodeExe -ArgumentList "`"$proxyScript`" --port $proxyPort --keys `"$proxyKeysFile`"" -WindowStyle Hidden -PassThru -ErrorAction Stop
            $proxyProcess.Dispose()
            $deadline = (Get-Date).AddSeconds(8)
            while ((Get-Date) -lt $deadline) {
                Start-Sleep -Milliseconds 100
                $h = Get-NvidiaProxyHealth
                if ($h) {
                    Write-Host "OC_PROGRESS stage=proxy-started port=$proxyPort keys=$($h.keys)"
                    return $true
                }
            }
            Write-Host "OC_PROGRESS stage=proxy-timeout port=$proxyPort"
            return $false
        } catch {
            Write-Host "OC_PROGRESS stage=proxy-start-error msg=$($_.Exception.Message)"
            return $false
        } finally {
            if ($startupLockTaken) {
                [void]$startupMutex.ReleaseMutex()
            }
            $startupMutex.Dispose()
        }
    }

    $finalModelArg = $modelArg
    $finalLabel = $modelLabels[$finalModelArg]
    if (-not $finalLabel) { $finalLabel = $finalModelArg }

    if ($Check) {
        Write-Host "OC_PROGRESS stage=fetching-model-list"
        $nimModelList = $null
        $maxRetries = 3
        for ($retry = 1; $retry -le $maxRetries; $retry++) {
            $nimModelList = Get-NvidiaModelList -ApiKey $nvidiaApiKey -TimeoutSec 30
            if ($null -ne $nimModelList) {
                $modelCount = @($nimModelList).Count
                Write-Host "OC_PROGRESS stage=model-list-ok count=$modelCount"
                break
            }
            Write-Host "OC_PROGRESS stage=model-list-retry attempt=$retry/$maxRetries"
            if ($retry -lt $maxRetries) {
                Start-Sleep -Seconds ($retry * 2)
            }
        }

        # Build fallback list: user-requested model first, then all others in priority order
        $modelsToTest = @()
        if ($hasModelFlag) {
            $modelsToTest += $modelArg
            foreach ($m in $modelOrder) {
                if ($m -ne $modelArg) {
                    $modelsToTest += $m
                }
            }
        } else {
            $modelsToTest = $modelOrder
        }

        $workingModelId = $null
        if ($null -ne $nimModelList) {
            foreach ($testId in $modelsToTest) {
                $label = $modelLabels[$testId]
                if (-not $label) { $label = $testId }

                # Phase 1: Check model exists in catalog
                if (-not (Test-ModelListed -ModelId $testId -ModelList $nimModelList)) {
                    Write-Host "OC_PROGRESS stage=model-not-listed model=$testId label=$label"
                    continue
                }

                # Phase 2: Quick inference probe (detects 429 rate limits)
                Write-Host "OC_PROGRESS stage=probe-testing model=$testId label=$label"
                if (Test-ModelInference -ModelId $testId -ApiKey $nvidiaApiKey -TimeoutSec 30) {
                    Write-Host "OC_PROGRESS stage=model-verified model=$testId label=$label"
                    $workingModelId = $testId
                    break
                } else {
                    Write-Host "OC_PROGRESS stage=model-probe-failed model=$testId label=$label"
                }
            }
        } else {
            # Could not fetch model list - use the requested model and let opencode handle errors
            Write-Host "OC_PROGRESS stage=model-list-failed using-model=$modelArg"
            $workingModelId = $modelArg
        }

        if (-not $workingModelId) {
            # All probes failed. Don't throw — opencode may still work via the
            # custom provider (some models respond to the SDK but not to raw
            # probe requests). Fall back to the first model.
            Write-Host "OC_PROGRESS stage=all-probes-failed using-fallback=$defaultModel"
            $workingModelId = $defaultModel
        }

        $finalModelArg = $workingModelId
        $finalLabel = $modelLabels[$finalModelArg]
        if (-not $finalLabel) { $finalLabel = $finalModelArg }

        if ($finalModelArg -ne $modelArg) {
            Write-Host "OC_PROGRESS stage=auto-fallback from=$modelArg to=$finalModelArg label=$finalLabel"
        } else {
            Write-Host "OC_PROGRESS stage=model-selected model=$finalModelArg label=$finalLabel"
        }
    } else {
        # INSTANT PATH: skip preflight when proxy handles 429s.
        # The proxy rotates keys, retries with backoff, and NEVER passes 429s
        # to OpenCode. Probing wastes rate-limit quota and causes the very 429s
        # we want to avoid. When the proxy is running, just launch immediately.
        Clear-StaleOpenCode
        Backup-OpenCodeSessions

        # Ensure proxy is running
        $proxyRunning = Ensure-NvidiaProxy
        if ($proxyRunning) {
            Write-Host "OC_PROGRESS stage=proxy-active model=$finalModelArg (proxy handles 429s, skipping preflight)"
            $finalModelArg = $finalModelArg
            $finalLabel = $modelLabels[$finalModelArg]
            if (-not $finalLabel) { $finalLabel = $finalModelArg }
            Write-Host "OC_PROGRESS stage=instant-launch model=$finalModelArg label=$finalLabel"
        } else {
            # Proxy not running — fall back to preflight probes
            Write-Host "OC_PROGRESS stage=proxy-not-running (falling back to preflight probes)"
            # Step 1: the chosen model, cache-aware (instant if fresh).
            $launchModel = $null
            $probe = Test-ModelCached -ModelId $finalModelArg -ApiKey $nvidiaApiKey
            if ($probe.ok) {
                $launchModel = $finalModelArg
                Write-Host "OC_PROGRESS stage=preflight-ok model=$finalModelArg label=$finalLabel source=$($probe.source)"
            } else {
                Write-Host "OC_PROGRESS stage=preflight-skip model=$finalModelArg status=$($probe.status) source=$($probe.source) (rate-limited or unavailable)"
            }

            if (-not $launchModel -and $hasModelFlag) {
                Write-Host "OC_PROGRESS stage=preflight-wait model=$finalModelArg (waiting for rate limit to clear, up to 90s)"
                $deadline = (Get-Date).AddSeconds(90)
                $attempt = 0
                while ((Get-Date) -lt $deadline) {
                    Start-Sleep -Seconds 10
                    $attempt++
                    $probe = Test-ModelCached -ModelId $finalModelArg -ApiKey $nvidiaApiKey -OkTtlSec 5 -ThrottledRetrySec 5
                    if ($probe.ok) {
                        Write-Host "OC_PROGRESS stage=preflight-ok model=$finalModelArg label=$finalLabel (after wait)"
                        $launchModel = $finalModelArg
                        break
                    } else {
                        Write-Host "OC_PROGRESS stage=preflight-wait-retry model=$finalModelArg status=$($probe.status) attempt=$attempt"
                    }
                }
                if (-not $launchModel) {
                    Write-Host "OC_PROGRESS stage=preflight-wait-expired model=$finalModelArg (still rate-limited after 90s)"
                }
            }

            if (-not $launchModel) {
                foreach ($testId in $modelOrder) {
                    if ($testId -eq $finalModelArg) { continue }
                    Write-Host "OC_PROGRESS stage=preflight-probe model=$testId"
                    $probe = Test-ModelCached -ModelId $testId -ApiKey $nvidiaApiKey
                    if ($probe.ok) {
                        $launchModel = $testId
                        $okLabel = $modelLabels[$testId]
                        if (-not $okLabel) { $okLabel = $testId }
                        Write-Host "OC_PROGRESS stage=preflight-ok model=$testId label=$okLabel source=$($probe.source)"
                        break
                    } else {
                        Write-Host "OC_PROGRESS stage=preflight-skip model=$testId status=$($probe.status) source=$($probe.source) (rate-limited or unavailable)"
                    }
                }
            }

            if (-not $launchModel) {
                Write-Host "OC_PROGRESS stage=all-rate-limited using=$finalModelArg"
                $launchModel = $finalModelArg
            }
            if ($launchModel -ne $finalModelArg) {
                Write-Host "OC_PROGRESS stage=auto-fallback from=$finalModelArg to=$launchModel"
            }
            $finalModelArg = $launchModel
            $finalLabel = $modelLabels[$finalModelArg]
            if (-not $finalLabel) { $finalLabel = $finalModelArg }
            Write-Host "OC_PROGRESS stage=instant-launch model=$finalModelArg label=$finalLabel"
        }
    }

    # ═══════════════════════════════════════════════════════════════════
    # OPENCODE CONFIG MANAGEMENT
    # Two config locations opencode reads:
    #   1. %APPDATA%\opencode\opencode.json (Windows standard)
    #   2. ~/.config/opencode/opencode.json (XDG-style, can override)
    # ═══════════════════════════════════════════════════════════════════
    $configPaths = @(
        (Join-Path $env:APPDATA 'opencode\opencode.json'),
        (Join-Path $env:USERPROFILE '.config\opencode\opencode.json')
    )

    # Permission config
    $permissionConfig = @{
        '*'         = 'allow'
        'doom_loop' = 'ask'
    }

    # Instructions file path
    $instructionsPath = Join-Path $env:USERPROFILE '.config\opencode\instructions.md'
    $instructionsRel = '~/.config/opencode/instructions.md'

    # Build prompt file path
    $buildPromptPath = Join-Path $env:USERPROFILE '.config\opencode\build-prompt.txt'
    $buildPromptRel = '{file:~/.config/opencode/build-prompt.txt}'

    # Agent config
    # steps: maximum agentic iterations before opencode force-stops the
    # agent and demands text-only. Pinned near-infinite so the agent can
    # NEVER be forced to stop mid-task (the never-stop mandate lives in
    # build-prompt.txt + instructions.md; this removes the hard cap that
    # could otherwise interrupt a long autonomous run).
    $agentConfig = @{
        build = @{
            mode       = 'primary'
            prompt     = $buildPromptRel
            steps      = 100000
            permission = @{
                '*' = 'allow'
            }
        }
    }

    # ═══════════════════════════════════════════════════════════════════
    # CUSTOM NVIDIA PROVIDER CONFIG
    # CRITICAL: The built-in nvidia provider crashes with "U.split is
    # not a function" because it can't parse 3-segment model IDs like
    # nvidia/thinkingmachines/inkling. We define a custom provider
    # using @ai-sdk/openai-compatible with key "nvidia-nim" (not "nvidia")
    # to create a SEPARATE provider that doesn't merge with the built-in
    # nvidia provider from models.dev catalog.
    #
    # baseURL routes through the local rate-limit proxy (localhost:3460)
    # so NVIDIA 429/503/529 responses are retried with exponential
    # backoff BEFORE OpenCode ever sees them.  If the proxy is not
    # running, this falls back transparently to the direct NVIDIA URL.
    #
    # Each model declares:
    #   modalities  — tells OC what input/output types are supported
    #   attachment  — false = OC will NEVER try to send images to this model
    #   tool_call   — true  = model supports function/tool calling
    #   temperature — boolean capability flag (true = model supports temperature)
    #   limit       — context + output token limits
    # ═══════════════════════════════════════════════════════════════════

    # Start the proxy if it is not already running. If it fails to start,
    # fall back to the direct NVIDIA URL so OC still works (just without
    # the 429-retry shield).
    if ($null -eq $proxyRunning) {
        $proxyRunning = Ensure-NvidiaProxy
    }
    if ($proxyRunning) {
        $effectiveBase = $proxyBaseUrl
        Write-Host "OC_PROGRESS stage=proxy-active url=$effectiveBase"
    } else {
        $effectiveBase = 'https://integrate.api.nvidia.com/v1'
        Write-Host "OC_PROGRESS stage=proxy-unavailable url=$effectiveBase (429s will reach OpenCode)"
    }

    $nvidiaProviderConfig = @{
        npm     = '@ai-sdk/openai-compatible'
        name    = 'NVIDIA NGC'
        env     = @('NVIDIA_API_KEY')
        options = @{
            baseURL = $effectiveBase
            apiKey  = $nvidiaApiKey
        }
        models  = @{
            'nvidia/nemotron-3-ultra-550b-a55b' = @{
                name         = 'Nemotron 3 Ultra (550B flagship, best general)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 1048576; output = 16384 }
            }
            'z-ai/glm-5.2' = @{
                name         = 'GLM-5.2 (753B MoE, best coding)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 1048576; output = 32768 }
            }
            'nvidia/nemotron-3-super-120b-a12b' = @{
                name         = 'Nemotron 3 Super (120B, strong general)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 131072; output = 16384 }
            }
            'deepseek-ai/deepseek-v4-flash-0731' = @{
                name         = 'DeepSeek V4 Flash (284B MoE, fast coding)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 1048576; output = 32768 }
            }
            'thinkingmachines/inkling' = @{
                name         = 'Inkling (256-expert MoE, 1M ctx, multimodal)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 1048576; output = 32768 }
            }
            'minimaxai/minimax-m3' = @{
                name         = 'MiniMax M3 (428B MoE, multimodal, 1M context)'
                modalities   = @{ input = @('text', 'image'); output = @('text') }
                attachment   = $true
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 1048576; output = 8192 }
            }
            'google/gemma-4-31b-it' = @{
                name         = 'Gemma 4 31B IT (reasoning, coding, multimodal)'
                modalities   = @{ input = @('text', 'image'); output = @('text') }
                attachment   = $true
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 262144; output = 16384 }
            }
            'stepfun-ai/step-3.7-flash' = @{
                name         = 'Step 3.7 Flash (198B MoE, coding, multimodal)'
                modalities   = @{ input = @('text', 'image'); output = @('text') }
                attachment   = $true
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 262144; output = 16384 }
            }
            'nvidia/llama-3.3-nemotron-super-49b-v1.5' = @{
                name         = 'Llama 3.3 Nemotron Super 49B v1.5'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 131072; output = 65536 }
            }
            'poolside/laguna-xs-2.1' = @{
                name         = 'Poolside Laguna XS 2.1 (agentic coding)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 262144; output = 8192 }
            }
            'meta/llama-3.1-70b-instruct' = @{
                name         = 'Llama 3.1 70B (Best open general)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 131072; output = 16384 }
            }
            'meta/llama-3.3-70b-instruct' = @{
                name         = 'Llama 3.3 70B Instruct'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 131072; output = 16384 }
            }
            'openai/gpt-oss-120b' = @{
                name         = 'GPT-OSS 120B (OpenAI open)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 131072; output = 16384 }
            }
            'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning' = @{
                name         = 'Nemotron Omni 30B (Multimodal + Reasoning)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 131072; output = 16384 }
            }
            'nvidia/nemotron-3.5-lightning-30b-a3b' = @{
                name         = 'Nemotron Lightning 30B (Fastest)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 131072; output = 16384 }
            }
            'nvidia/nemotron-3-nano-30b-a3b' = @{
                name         = 'Nemotron Nano 30B (Efficient)'
                modalities   = @{ input = @('text'); output = @('text') }
                attachment   = $false
                tool_call    = $true
                temperature  = $true
                limit        = @{ context = 131072; output = 16384 }
            }
        }
    }

    function Test-NviocProviderConfigCurrent {
        param(
            [object]$Config,
            [string]$BaseUrl,
            [string[]]$ModelIds
        )
        if (-not $Config -or -not $Config.provider) { return $false }
        foreach ($providerName in @('nvidia-nim', 'nvidia')) {
            $providerProperty = $Config.provider.PSObject.Properties[$providerName]
            if (-not $providerProperty) { return $false }
            $provider = $providerProperty.Value
            if (-not $provider.options -or [string]$provider.options.baseURL -ne $BaseUrl -or -not $provider.models) {
                return $false
            }
            foreach ($modelId in $ModelIds) {
                if (-not $provider.models.PSObject.Properties[$modelId]) {
                    return $false
                }
            }
        }
        return $true
    }

    function Write-NviocJsonFileAtomic {
        param(
            [string]$Path,
            [object]$Value
        )
        $operationId = "$PID.$([guid]::NewGuid().ToString('N'))"
        $temporaryPath = "$Path.tmp.$operationId"
        $replacementBackupPath = "$Path.replace-backup.$operationId"
        try {
            $json = $Value | ConvertTo-Json -Depth 10
            [IO.File]::WriteAllText(
                $temporaryPath,
                ($json + "`r`n"),
                (New-Object Text.UTF8Encoding($false))
            )
            if ([IO.File]::Exists($Path)) {
                [IO.File]::Replace($temporaryPath, $Path, $replacementBackupPath, $true)
                [IO.File]::Delete($replacementBackupPath)
            } else {
                [IO.File]::Move($temporaryPath, $Path)
            }
            $temporaryPath = $null
        } finally {
            if ($temporaryPath -and [IO.File]::Exists($temporaryPath)) {
                [IO.File]::Delete($temporaryPath)
            }
            if ($replacementBackupPath -and [IO.File]::Exists($replacementBackupPath)) {
                [IO.File]::Delete($replacementBackupPath)
            }
        }
    }

    $expectedModelIds = [string[]]@($nvidiaProviderConfig.models.Keys)
    $configNeedsUpdate = $false
    foreach ($configProbePath in $configPaths) {
        if (-not (Test-Path -LiteralPath $configProbePath -PathType Leaf)) {
            $configNeedsUpdate = $true
            break
        }
        try {
            $configProbe = Get-Content -LiteralPath $configProbePath -Raw | ConvertFrom-Json
            if (-not (Test-NviocProviderConfigCurrent -Config $configProbe -BaseUrl $effectiveBase -ModelIds $expectedModelIds)) {
                $configNeedsUpdate = $true
                break
            }
        } catch {
            $configNeedsUpdate = $true
            break
        }
    }

    $configMutex = New-Object Threading.Mutex($false, 'Local\NviocOpenCodeConfigV1')
    $configLockTaken = $false
    if ($configNeedsUpdate) {
        try {
            $configLockTaken = $configMutex.WaitOne(5000)
        } catch [Threading.AbandonedMutexException] {
            $configLockTaken = $true
        }
        if (-not $configLockTaken) {
            Write-Host 'OC_PROGRESS stage=config-lock-timeout'
            $configNeedsUpdate = $false
        }
    }

    try {
        if (-not $configNeedsUpdate) {
            Write-Host "OC_PROGRESS stage=config-current model=$finalModelArg"
        } else {
            foreach ($configPath in $configPaths) {
        $configDir = Split-Path -Parent $configPath
        if (-not (Test-Path -LiteralPath $configDir -PathType Container)) {
            New-Item -ItemType Directory -Force -Path $configDir | Out-Null
        }

        # nvioc only owns the nvidia-nim provider block. Everything else
        # (model, agent, permission, instructions, other providers, plugins)
        # belongs to the user and to `oc`, so it is preserved verbatim and
        # never overwritten. The chosen model is passed explicitly via '-m'
        # at launch, so no top-level "model" key is written here — that is
        # what previously made nvioc and oc fight over the shared config.
        $existing = $null
        if (Test-Path -LiteralPath $configPath -PathType Leaf) {
            try {
                $existing = Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json
            } catch {
                Write-Host "OC_PROGRESS stage=config-parse-error path=$configPath msg=$($_.Exception.Message)"
                continue
            }
        }

        if (Test-NviocProviderConfigCurrent -Config $existing -BaseUrl $effectiveBase -ModelIds $expectedModelIds) {
            continue
        }

        try {
            $merged = @{}
            if ($existing) {
                foreach ($prop in $existing.PSObject.Properties) {
                    $merged[$prop.Name] = $prop.Value
                }
            }

            $merged['$schema'] = 'https://opencode.ai/config.json'

            # Merge the nvidia-nim provider AND override the built-in nvidia
            # provider to route through the proxy. Without this, switching
            # models in the TUI resolves to the built-in nvidia provider
            # which goes DIRECT to NVIDIA, bypassing the proxy entirely.
            $providers = @{}
            if ($existing -and $existing.provider) {
                foreach ($p in $existing.provider.PSObject.Properties) {
                    $providers[$p.Name] = $p.Value
                }
            }
            $providers['nvidia-nim'] = $nvidiaProviderConfig
            # Override built-in 'nvidia' provider to use same proxy + models
            $providers['nvidia'] = @{
                npm     = '@ai-sdk/openai-compatible'
                name    = 'NVIDIA NIM (via proxy)'
                env     = @('NVIDIA_API_KEY')
                options = @{
                    baseURL = $effectiveBase
                    apiKey  = $nvidiaApiKey
                }
                models  = $nvidiaProviderConfig.models
            }
            $merged['provider'] = $providers
            # Keep agent tool calls in the native Windows shell. Wrapping
            # PowerShell in Bash corrupts variables such as $_ before execution.
            $merged['shell'] = 'powershell'

            # Seed the nvioc defaults only on a brand-new config.
            if (-not $existing) {
                $merged['permission'] = $permissionConfig
                $merged['instructions'] = @($instructionsRel)
                $merged['agent'] = $agentConfig
            }

            Write-NviocJsonFileAtomic -Path $configPath -Value $merged
            Write-Host "OC_PROGRESS stage=config-updated path=$configPath model=$finalModelArg"
        } catch {
            Write-Host "OC_PROGRESS stage=config-write-error path=$configPath msg=$($_.Exception.Message)"
        }
    }
        }
    } finally {
        if ($configLockTaken) {
            [void]$configMutex.ReleaseMutex()
        }
        $configMutex.Dispose()
    }

    # ═══════════════════════════════════════════════════════════════════
    # ENSURE INSTRUCTIONS FILE EXISTS
    # ═══════════════════════════════════════════════════════════════════
    if (-not (Test-Path -LiteralPath $instructionsPath -PathType Leaf)) {
        $instructionsDir = Split-Path -Parent $instructionsPath
        if (-not (Test-Path -LiteralPath $instructionsDir -PathType Container)) {
            New-Item -ItemType Directory -Force -Path $instructionsDir | Out-Null
        }
        $defaultInstructions = @"
# Global Rules for OpenCode

These rules apply to ALL opencode sessions.

## CRITICAL RULES - ALWAYS FOLLOW

### Rule 1: ALWAYS test what you create
- After creating or modifying ANY file, you MUST run/test it to verify it works

### Rule 2: ALWAYS output the full path when done
- Format: FULL PATH: C:/path/to/file

### Rule 3: NEVER create generic garbage
- Always create REAL, WORKING code with proper error handling

### Rule 4: ALWAYS show real-time progress
- Show what you're doing at each step

### Rule 5: PowerShell 5 compatibility
- All scripts MUST work in PowerShell 5.1
- Avoid PS6+ features like pipe-pipe, question-question, AsHashtable
- Use try/catch blocks instead of single-pipe error handling
- This host is Windows. Run PowerShell commands directly in the shell tool.
- NEVER wrap PowerShell with bash, /usr/bin/bash, sh, wsl, or powershell -Command.
- Use semicolons instead of &&. Preserve PowerShell variables such as `$_` literally.

### Rule 6: NEVER STOP until the task is achieved
- Never stop working before the user's request is fully and verifiably achieved, no matter how complex or how long it takes.
- Do not stop after partial work. Do not stop to ask "should I continue?" - just continue.
- Keep looping: plan -> execute -> test -> fix -> verify -> continue until done.
- If something fails, diagnose it, fix it, and retry with a different approach. Never report failure as the outcome while a path forward exists.
- Only stop when the request is fully implemented AND verified working, or when the user manually stops you.
"@
        $defaultInstructions | Set-Content -LiteralPath $instructionsPath -Encoding UTF8
        Write-Host "OC_PROGRESS stage=instructions-created path=$instructionsPath"
    }

    if (-not (Test-Path -LiteralPath $buildPromptPath -PathType Leaf)) {
        $buildPromptDir = Split-Path -Parent $buildPromptPath
        if (-not (Test-Path -LiteralPath $buildPromptDir -PathType Container)) {
            New-Item -ItemType Directory -Force -Path $buildPromptDir | Out-Null
        }
        $defaultBuildPrompt = @'
# Build Agent Rules

You are the build agent. You turn requests into real, working, verified code. You FINISH what you start.

## THE #1 RULE - NEVER STOP UNTIL THE GOAL IS ACHIEVED

You must NEVER stop working before the user's request is fully and verifiably achieved - no matter how
complex, how long it takes, or how many obstacles appear. This is non-negotiable and overrides everything
else except an explicit manual stop by the user (Ctrl+C / Esc / "stop").

- Do not stop after a partial implementation. Do not stop after "a good start". Do not stop to ask
  "should I continue?" - JUST CONTINUE.
- Keep working in a loop: plan -> execute -> test -> fix -> verify -> continue, until the task is done.
- If a step fails or an error appears, do NOT stop and report the failure as the outcome. Diagnose it,
  fix it, and retry. Try alternative approaches until one works.
- If you are uncertain, investigate (read files, search, web fetch, run commands) until you are certain.
- Only stop when BOTH are true: (1) the user's request is fully implemented, and (2) you have verified
  it actually works by running/testing it. If either is false, keep going.
- Break large tasks into steps and track them with the todo tool. Work through the list to completion
  without being asked.
- If a truly external blocker exists (e.g., a service is down, credentials missing), do everything you
  can to work around it first. Only if there is literally no path forward do you report the blocker -
  and say exactly what is blocking and what unblocks it.

## Non-negotiable rules

1. ALWAYS test what you create: after creating or modifying ANY file, run or test it to prove it works.
   If it doesn't work, fix it - never leave broken code behind.
2. ALWAYS report the full path of every file you create or modify. Format: FULL PATH: C:/path/to/file
3. NEVER create generic garbage: produce real, complete, working code with proper error handling.
4. ALWAYS show real-time progress: state what you are doing at each step before doing it.
5. PowerShell 5 compatibility: on Windows, scripts MUST work in Windows PowerShell 5.1 - no ??, no &&,
   no AsHashtable; use try/catch blocks. Run PowerShell directly; never nest it inside bash, sh, WSL,
   or powershell -Command because nested shells corrupt `$_` and quoting. Use semicolons instead of &&.
6. Never leave broken or half-finished work. If something cannot be completed, say exactly what is
   blocking it - after exhausting every workaround.

Use any tool you need to verify your work. When the task is done, summarize exactly what changed and
how it was verified.
'@
        $defaultBuildPrompt | Set-Content -LiteralPath $buildPromptPath -Encoding UTF8
        Write-Host "OC_PROGRESS stage=build-prompt-created path=$buildPromptPath"
    }

    # ═══════════════════════════════════════════════════════════════════
    # LAUNCH OPENCODE - IMMEDIATELY (auto-heals if missing)
    # ═══════════════════════════════════════════════════════════════════
    function Resolve-NviocOpenCode {
        # The platform binary lives directly in opencode-ai\bin AND (as a
        # hard link) in the optional opencode-windows-x64 package. Check both
        # so a half-installed package never defeats the launcher. Prefer the
        # real exe over the .cmd shim (a shim can be stale and point at a
        # missing binary).
        $candidates = @(
            (Join-Path $env:LOCALAPPDATA 'npm-global\node_modules\opencode-ai\bin\opencode.exe'),
            (Join-Path $env:LOCALAPPDATA 'npm-global\node_modules\opencode-ai\node_modules\opencode-windows-x64\bin\opencode.exe'),
            (Join-Path $env:LOCALAPPDATA 'npm-global\node_modules\opencode-ai\node_modules\opencode-windows-x64-baseline\bin\opencode.exe'),
            (Join-Path $env:APPDATA 'npm\node_modules\opencode-ai\bin\opencode.exe')
        )
        foreach ($candidate in $candidates) {
            if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
        }
        foreach ($shim in @('opencode.cmd', 'opencode')) {
            $cmd = Get-Command $shim -CommandType Application -ErrorAction SilentlyContinue
            if ($cmd -and $cmd.Source) { return $cmd.Source }
        }
        return $null
    }

    function Test-NviocOpenCodeWorks {
        param([string]$Path)
        $receiptPath = "$Path.verified.json"
        try {
            if (Test-Path -LiteralPath $receiptPath -PathType Leaf) {
                $receipt = Get-Content -LiteralPath $receiptPath -Raw | ConvertFrom-Json
                $file = Get-Item -LiteralPath $Path
                if ([long]$receipt.length -eq $file.Length -and
                    [long]$receipt.lastWriteTimeUtcTicks -eq $file.LastWriteTimeUtc.Ticks -and
                    [string]$receipt.identity -eq 'opencode models') {
                    return $true
                }
            }
        } catch { }

        # Bun itself also returns a semantic version, so verify an OpenCode-only
        # command signature before trusting a native executable or shim.
        try {
            $version = (& $Path '--version' 2>$null) -join " "
            if ($LASTEXITCODE -ne 0 -or $version -notmatch '^\s*\d+\.\d+\.\d+\s*$') { return $false }
            $help = ((& $Path 'models' '--help' 2>&1) -join "`n") -replace "`e\[[0-9;]*m", ''
            if ($help -match '(?m)^\s*opencode\s+models\b') {
                try {
                    $file = Get-Item -LiteralPath $Path
                    [pscustomobject]@{
                        length = $file.Length
                        lastWriteTimeUtcTicks = $file.LastWriteTimeUtc.Ticks
                        version = $version.Trim()
                        identity = 'opencode models'
                    } | ConvertTo-Json | Set-Content -LiteralPath $receiptPath -Encoding UTF8
                } catch { }
                return $true
            }
        } catch { }
        return $false
    }

    $openCodePath = Resolve-NviocOpenCode
    if ($openCodePath -and -not (Test-NviocOpenCodeWorks -Path $openCodePath)) {
        Write-Host "OC_PROGRESS stage=invalid-binary path=$openCodePath"
        $openCodePath = $null
    }
    if (-not $openCodePath) {
        # Never fail with 'not installed': run the permanent installer on the
        # spot and re-resolve (same auto-bootstrap as the oc launcher).
        Write-Host 'OC_PROGRESS stage=not-installed-auto-bootstrap'
        $installer = 'F:\study\Platforms\windows\functions\getoc2.ps1'
        if (Test-Path -LiteralPath $installer -PathType Leaf) {
            & $installer
            if (-not $?) {
                throw "nvioc: opencode auto-install failed: $installer"
            }
        } else {
            throw "nvioc: opencode auto-install script is missing: $installer"
        }
        $openCodePath = Resolve-NviocOpenCode
        Write-Host "OC_PROGRESS stage=auto-installed path=$openCodePath"
    }
    if (-not $openCodePath) {
        throw 'nvioc: opencode could not be installed. Check your network / npm, then run getoc2 manually.'
    }

    Write-Host "OC_PROGRESS stage=launching model=$finalModelArg label=$finalLabel"
    & $openCodePath '-m' $finalModelArg @Args
}

