function Open-NvidDesktopApp {
    param(
        [string]$ExecutablePath,
        [string]$ProtocolArgument = 'nvidiaapp:',
        [string[]]$TitlePattern = @('NVIDIA*'),
        [string[]]$ProcessNames = @('NVIDIA App'),
        [string[]]$ExcludeTitlePattern = @('*Control Panel*'),
        [int]$TimeoutSeconds = 120
    )

    if ([string]::IsNullOrWhiteSpace($ExecutablePath) -or -not (Test-Path $ExecutablePath)) {
        throw ("NVIDIA App executable is missing: {0}" -f $ExecutablePath)
    }

    $window = Wait-NvidWindow -TitlePattern $TitlePattern -ProcessNames $ProcessNames -ExcludeTitlePattern $ExcludeTitlePattern -TimeoutSeconds 4
    if ($window) {
        return $window
    }

    Start-Process -FilePath $ExecutablePath -WorkingDirectory (Split-Path $ExecutablePath) -ArgumentList $ProtocolArgument | Out-Null
    $window = Wait-NvidWindow -TitlePattern $TitlePattern -ProcessNames $ProcessNames -ExcludeTitlePattern $ExcludeTitlePattern -TimeoutSeconds $TimeoutSeconds
    if (-not $window) {
        throw ("Timed out waiting for NVIDIA App after launching '{0}'." -f $ExecutablePath)
    }

    return $window
}

function global:Open-NvidStartApp {
        param(
            [string]$AppId,
            [string[]]$TitlePattern,
            [string[]]$ProcessNames = @(),
            [string[]]$ExcludeTitlePattern = @(),
            [int]$TimeoutSeconds = 90
        )
        if ([string]::IsNullOrWhiteSpace($AppId)) { throw 'AppId is required to launch the NVIDIA surface.' }
        $titleText = ($TitlePattern -join ', ')
        $window = Wait-NvidWindow -TitlePattern $TitlePattern -ProcessNames $ProcessNames -ExcludeTitlePattern $ExcludeTitlePattern -TimeoutSeconds 4
        if ($window) { return $window }
        Start-Process -FilePath 'explorer.exe' -ArgumentList ("shell:AppsFolder\" + $AppId) | Out-Null
        $window = Wait-NvidWindow -TitlePattern $TitlePattern -ProcessNames $ProcessNames -ExcludeTitlePattern $ExcludeTitlePattern -TimeoutSeconds $TimeoutSeconds
        if ($window) { return $window }
        throw ("Timed out waiting for window '{0}' after launching '{1}'." -f $titleText, $AppId)
    }

function Optimize-CurrentTerminalResponsiveness {
    try {
        $current = [System.Diagnostics.Process]::GetCurrentProcess()
        if ($current.PriorityClass -in @('Idle', 'BelowNormal', 'Normal')) {
            $current.PriorityClass = 'AboveNormal'
        }

        $processId = $PID
        for ($depth = 0; $depth -lt 6; $depth++) {
            $procInfo = Get-CimInstance Win32_Process -Filter "ProcessId=$processId" -ErrorAction SilentlyContinue
            if (-not $procInfo -or -not $procInfo.ParentProcessId) { break }
            $processId = [int]$procInfo.ParentProcessId
            $parent = Get-Process -Id $processId -ErrorAction SilentlyContinue
            if (-not $parent) { continue }
            if ($parent.ProcessName -eq 'WindowsTerminal') {
                if ($parent.PriorityClass -ne 'High') { $parent.PriorityClass = 'High' }
            } elseif ($parent.ProcessName -in @('OpenConsole', 'conhost', 'cmd', 'powershell', 'pwsh')) {
                if ($parent.PriorityClass -in @('Idle', 'BelowNormal', 'Normal')) { $parent.PriorityClass = 'AboveNormal' }
            }
        }
    } catch { }
}

