        }
    }

function Prune-WingupState {
        $changed = $false
        for ($i = $state.Entries.Count - 1; $i -ge 0; $i--) {
            $entry = $state.Entries[$i]
            $package = $null
            foreach ($candidate in @($packages)) {
                if ($candidate.Id -eq $entry.Id) {
                    $package = $candidate
                    break
                }
            }

            if (-not $package) {
                $state.Entries.RemoveAt($i)
                $changed = $true
                continue
            }

            if ($package.Available -ne $entry.Available) {
                $state.Entries.RemoveAt($i)
                $changed = $true
                continue
            }

            if ($entry.Reason -eq 'metadata-stuck' -and $package.Current -ne 'Unknown') {
                $state.Entries.RemoveAt($i)
                $changed = $true
            }
        }
        return $changed
    }

function ps5000 {
$runtimePath = 'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable\Microsoft.PowerShell_profile.runtime.ps1'
$roots = @('C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable','C:\Users\micha\Documents\WindowsPowerShell\legacy-safe-functions')
$filesToScan = @(foreach ($root in $roots) {
    if (-not (Test-Path -LiteralPath $root)) { continue }
    Get-ChildItem -LiteralPath $root -Filter *.ps1 -Recurse -File -ErrorAction SilentlyContinue | Where-Object {
        $_.FullName -notmatch '\\backups(?:\\|$)' -and $_.FullName -notmatch '\.bak-(?:funcmutation|rmfunc|saved)-'
    }
})
$runtimeFuncs = @()
if (Test-Path -LiteralPath $runtimePath) {
    $runtimeFuncs = @(. {
        $tokens = $null; $errors = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile($runtimePath, [ref]$tokens, [ref]$errors)
        if (@($errors).Count -gt 0) { return }
        $ast.FindAll({
            param($node)
            if ($node -isnot [System.Management.Automation.Language.FunctionDefinitionAst]) { return $false }
            $parent = $node.Parent
            while ($parent) {
                if ($parent -is [System.Management.Automation.Language.FunctionDefinitionAst]) { return $false }
                $parent = $parent.Parent
            }
            $true
        }, $true) | ForEach-Object {
            [pscustomobject]@{
                Name = $_.Name -replace '^(?i:global:)', ''
                Lines = $_.Extent.EndLineNumber - $_.Extent.StartLineNumber + 1
                File = $runtimePath
            }
        }
    })
}
$runtimeNames = @{}
foreach ($f in $runtimeFuncs) { $runtimeNames[$f.Name] = $true }
$otherFuncs = @(foreach ($f in $filesToScan) {
    if ($f.FullName -eq $runtimePath) { continue }
    $tokens = $null; $errors = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseFile($f.FullName, [ref]$tokens, [ref]$errors)
    if (@($errors).Count -gt 0) { continue }
    $ast.FindAll({
        param($node)
        if ($node -isnot [System.Management.Automation.Language.FunctionDefinitionAst]) { return $false }
        $parent = $node.Parent
        while ($parent) {
            if ($parent -is [System.Management.Automation.Language.FunctionDefinitionAst]) { return $false }
            $parent = $parent.Parent
        }
        $true
    }, $true) | ForEach-Object {
        [pscustomobject]@{
            Name = $_.Name -replace '^(?i:global:)', ''
            Lines = $_.Extent.EndLineNumber - $_.Extent.StartLineNumber + 1
            File = $f.FullName
        }
    }
})
$allFuncs = @($runtimeFuncs) + @($otherFuncs | Where-Object { -not $runtimeNames.ContainsKey($_.Name) })
$allFuncs | Group-Object { $_.Name -replace '(.)\1+', '$1' } | ForEach-Object { $_.Group | Sort-Object Lines -Descending | Select-Object -First 1 } | Sort-Object Lines -Descending | Select-Object -First 500 | Format-Table -AutoSize
}

function ps527 {
    $src = "$HOME\Documents\WindowsPowerShell"
    if (-not (Test-Path $src)) { Write-Host "SKIP ps527: $src not found" -ForegroundColor DarkYellow; return }
    Microsoft.PowerShell.Management\Get-ChildItem "$src\*profile*.ps1" -File -ErrorAction SilentlyContinue | ForEach-Object {
        $d = $_.FullName -replace 'WindowsPowerShell','PowerShell'
        $destinationDirectory = [IO.Path]::GetDirectoryName($d)
        if (-not [IO.Directory]::Exists($destinationDirectory)) {
            [void][IO.Directory]::CreateDirectory($destinationDirectory)
        }
        $copyRequired = $true
        $destinationInfo = [IO.FileInfo]::new($d)
        if ($destinationInfo.Exists -and $destinationInfo.Length -eq $_.Length -and
            $destinationInfo.LastWriteTimeUtc.Ticks -eq $_.LastWriteTimeUtc.Ticks) {
            $copyRequired = $false
        }
        elseif ($destinationInfo.Exists -and $destinationInfo.Length -eq $_.Length) {
            $sourceHash = (Microsoft.PowerShell.Utility\Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash
            $destinationHash = (Microsoft.PowerShell.Utility\Get-FileHash -LiteralPath $d -Algorithm SHA256).Hash
            $copyRequired = $sourceHash -cne $destinationHash
        }
        if ($copyRequired) {
            [IO.File]::Copy($_.FullName, $d, $true)
        }
    }
}

function PushBlob([string]$Path,[string]$Digest,[string]$Token){
 try{$h=Request HEAD "https://registry-1.docker.io/v2/$repository/blobs/$Digest" $Token $null $null 0 0 $null; if($h.Status -eq 200){Write-Host "[blob] exists $Digest"; return}}catch{}
 $x=Request POST "https://registry-1.docker.io/v2/$repository/blobs/uploads/" $Token 'application/octet-stream' $null 0 0 $null; $location=Absolute $x.Location; $size=(Get-Item -LiteralPath $Path).Length; $offset=0L; $chunk=[long]$ChunkMiB*1MB
 while($offset -lt $size){$count=[Math]::Min($chunk,$size-$offset); $x=Request PATCH $location $Token 'application/octet-stream' $Path $offset $count $null; if($x.Status -ne 202){throw "Unexpected PATCH status $($x.Status)"}; $location=Absolute $x.Location; $offset+=$count; Write-Host ("[blob] {0:N1}%" -f (100*$offset/$size))}
 $join=if($location.Contains('?')){'&'}else{'?'}; $x=Request PUT ($location+$join+'digest='+[Uri]::EscapeDataString($Digest)) $Token 'application/octet-stream' $null 0 0 $null; if($x.Status -ne 201){throw "Unexpected commit status $($x.Status)"}
}

