function Read-BeforeReNewLogText {
        param([string]$Path, [ref]$Offset, [switch]$IsError)
        if (-not (Test-Path -LiteralPath $Path)) { return $false }
        $fs = $null
        try {
            $fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            if ($fs.Length -le $Offset.Value) { return $false }
            [void]$fs.Seek([int64]$Offset.Value, [System.IO.SeekOrigin]::Begin)
            $count = [int]($fs.Length - $Offset.Value)
            $bytes = New-Object byte[] $count
            [void]$fs.Read($bytes, 0, $count)
            $Offset.Value = $fs.Length
            $text = [System.Text.Encoding]::UTF8.GetString($bytes)
            if ($text) {
                if ($IsError) { Write-Host $text -NoNewline -ForegroundColor Yellow } else { Write-Host $text -NoNewline }
                return $true
            }
        } catch { } finally { if ($fs) { $fs.Dispose() } }
        return $false
    }

function Read-CleancAllowlistLocal {
        param([string]$Path,[string]$ResolvedRootPath)
        if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "cleanc allowlist not found: $Path" }
        $set = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        $entries = New-Object 'System.Collections.Generic.List[string]'
        $rootPrefix = $ResolvedRootPath.TrimEnd('\') + '\'
        $lineNumber = 0
        foreach ($raw in [System.IO.File]::ReadAllLines($Path)) {
            $lineNumber++
            $line = $raw.Trim()
            if ([string]::IsNullOrWhiteSpace($line) -or $line.StartsWith('#') -or $line.StartsWith(';')) { continue }
            if ([System.IO.Path]::IsPathRooted($line)) {
                $resolved = [System.IO.Path]::GetFullPath($line)
                if (-not $resolved.StartsWith($rootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) { throw "cleanc allowlist line $lineNumber is outside root ${ResolvedRootPath}: $line" }
                $name = $resolved.Substring($rootPrefix.Length).TrimStart('\')
                if ([string]::IsNullOrWhiteSpace($name) -or $name.Contains('\')) { throw "cleanc allowlist line $lineNumber must target a direct child of ${ResolvedRootPath}: $line" }
            } else {
                if ($line.Contains('\') -or $line.Contains('/')) { throw "cleanc allowlist line $lineNumber must be a root item name or rooted path: $line" }
                $name = $line
            }
            if ($set.Add($name)) { $entries.Add($name) | Out-Null }
        }
        if ($entries.Count -eq 0) { throw "cleanc allowlist is empty: $Path" }
        [pscustomobject]@{ Path=$Path; Entries=@($entries); EntrySet=$set }
    }

function Read-FixDocker2NewText {
                param([string]$Path, [ref]$Position)
                if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return '' }
                $stream = $null
                $reader = $null
                try {
                    $stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
                    if ($Position.Value -gt $stream.Length) { $Position.Value = 0 }
                    [void]$stream.Seek([int64]$Position.Value, [System.IO.SeekOrigin]::Begin)
                    $reader = New-Object System.IO.StreamReader($stream)
                    $text = $reader.ReadToEnd()
                    $Position.Value = $stream.Position
                    return $text
                } catch {
                    return ''
                } finally {
                    if ($reader) { $reader.Dispose() } elseif ($stream) { $stream.Dispose() }
                }
            }

