function Receive-HttpFile {
    param([string]$Url, [string]$Path, [int]$TimeoutSec)

    $request = [Net.HttpWebRequest]::Create($Url)
    $request.Timeout = $TimeoutSec * 1000
    $request.ReadWriteTimeout = 30000
    $request.AllowAutoRedirect = $true
    $request.Referer = $amdSupportPage
    $request.UserAgent = $amdUserAgent
    $response = $request.GetResponse()
    try {
        $expected = [int64]$response.ContentLength
        $input = $response.GetResponseStream()
        try {
            $output = New-Object IO.FileStream($Path, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
            try {
                $buffer = New-Object byte[] 131072
                $written = [int64]0
                while (($read = $input.Read($buffer, 0, $buffer.Length)) -gt 0) {
                    $output.Write($buffer, 0, $read)
                    $written += $read
                }
                $output.Flush($true)
            } finally {
                $output.Dispose()
            }
        } finally {
            $input.Dispose()
        }
        if ($expected -ge 0 -and $written -ne $expected) {
            throw "PowerShell HTTP downloaded $written bytes; expected $expected."
        }
        return [pscustomobject]@{ Bytes = $written; ExpectedBytes = $expected }
    } finally {
        $response.Close()
    }
}

