function Remove-CcSpaceFastEntry {
    param([Parameter(Mandatory = $true)][string]$Path)

    $script:ccSpaceFastProcessed++
    try {
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
            $script:ccSpaceFastSkipped++
            return
        }

        if ($item.PSIsContainer) {
            Get-ChildItem -LiteralPath $item.FullName -Force -ErrorAction SilentlyContinue | ForEach-Object {
                Remove-CcSpaceFastEntry -Path $_.FullName
            }
        }

        Remove-Item -LiteralPath $item.FullName -Force -ErrorAction Stop
        $script:ccSpaceFastDeleted++
    } catch {
        $script:ccSpaceFastFailed++
    } finally {
        if ((((Get-Date) - $script:ccSpaceFastLastReport).TotalSeconds -ge 1) -or (($script:ccSpaceFastProcessed % 25) -eq 0)) {
            Write-CcSpaceFastProgress -Stage 'cleaning' -Target $script:ccSpaceFastCurrentTarget
        }
    }
}

