}

function Remove-NvidObsoleteDriverStoreEntries {
    param([string[]]$KeepPublishedNames)

    $entries = Get-NvidDriverStoreEntries |
        Where-Object {
            $_.ProviderName -match '^NVIDIA' -and
            $KeepPublishedNames -notcontains $_.PublishedName -and
            ($_.ClassName -eq 'Display' -or $_.OriginalName -eq 'nvhda.inf')
        }

    $results = @()
    foreach ($entry in @($entries)) {
        $output = (pnputil /delete-driver $entry.PublishedName /uninstall /force 2>&1 | Out-String).Trim()
        $results += [pscustomobject]@{
            PublishedName = $entry.PublishedName
            OriginalName  = $entry.OriginalName
            ClassName     = $entry.ClassName
            DriverVersion = $entry.DriverVersion
            Output        = $output
        }
    }
    return $results
}

function Remove-ProfileFunctionMutationUserModuleSources {
    param([Parameter(Mandatory)][object[]]$Removal)

    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss-fff'
    $moved = New-Object System.Collections.Generic.List[object]
    try {
        foreach ($item in $Removal) {
            if (-not [System.IO.File]::Exists($item.Path)) {
                throw "User module source '$($item.Path)' no longer exists."
            }

            $backupPath = "$($item.Path).bak-rmfunc-module-$stamp"
            if ([System.IO.File]::Exists($backupPath)) {
                throw "User module backup path already exists: $backupPath"
            }

            Write-ProfileFunctionMutationProgress -Stage 'saving-module-source' -Detail $item.Path
            [System.IO.File]::Move($item.Path, $backupPath)
            $moved.Add([pscustomobject]@{
                Path = $item.Path
                Backup = $backupPath
            }) | Out-Null
        }
    }
    catch {
        foreach ($item in @($moved | Sort-Object { $_.Path } -Descending)) {
            if ([System.IO.File]::Exists($item.Backup) -and -not [System.IO.File]::Exists($item.Path)) {
                [System.IO.File]::Move($item.Backup, $item.Path)
            }
        }
        throw
    }

    @($moved | ForEach-Object { $_.Backup })
}

function Remove-RedockerPath {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path)

    if([string]::IsNullOrWhiteSpace($Path) -or -not [IO.Path]::IsPathRooted($Path)) {
        Write-RedockerStep 'purge rejected: path must be rooted'
        return $false
    }
    if(-not (Test-Path -LiteralPath $Path)) {
        Write-RedockerStep ("purge already absent: {0}" -f $Path)
        return $true
    }
    try {
        $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).ProviderPath
    } catch {
        Write-RedockerStep ("purge resolve failed for {0}: {1}" -f $Path,$_.Exception.Message)
        return $false
    }
    if($resolved.TrimEnd('\') -eq [IO.Path]::GetPathRoot($resolved).TrimEnd('\')) {
        Write-RedockerStep ("purge rejected: drive root {0}" -f $resolved)
        return $false
    }

    Write-RedockerStep ("purging {0}" -f $resolved)
    try {
        $item = Get-Item -LiteralPath $resolved -Force -ErrorAction Stop
        $takeown = Join-Path $env:SystemRoot 'System32\takeown.exe'
        $icacls = Join-Path $env:SystemRoot 'System32\icacls.exe'
        if(Test-Path -LiteralPath $takeown) {
            if($item.PSIsContainer) { & $takeown /F $resolved /R /D Y /A 2>&1 | Out-Null } else { & $takeown /F $resolved /A 2>&1 | Out-Null }
            if($LASTEXITCODE -gt 1) { throw "takeown exit=$LASTEXITCODE" }
        }
        if(Test-Path -LiteralPath $icacls) {
            if($item.PSIsContainer) { & $icacls $resolved /grant 'Administrators:(OI)(CI)F' /T /C 2>&1 | Out-Null } else { & $icacls $resolved /grant 'Administrators:F' /C 2>&1 | Out-Null }
            if($LASTEXITCODE -ne 0) { throw "icacls exit=$LASTEXITCODE" }
        }
    } catch {
        Write-RedockerStep ("purge ownership warning for {0}: {1}" -f $resolved,$_.Exception.Message)
    }
    try {
        Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction Stop
    } catch {
        Write-RedockerStep ("purge primary delete failed for {0}: {1}" -f $resolved,$_.Exception.Message)
        try {
            $item = Get-Item -LiteralPath $resolved -Force -ErrorAction Stop
            if($item.PSIsContainer) { [IO.Directory]::Delete($resolved,$true) } else { [IO.File]::Delete($resolved) }
        } catch {
            Write-RedockerStep ("purge fallback delete failed for {0}: {1}" -f $resolved,$_.Exception.Message)
            return $false
        }
    }
    $verified = -not (Test-Path -LiteralPath $resolved)
    Write-RedockerStep ("purge {0}: {1}" -f $(if($verified){'verified'}else{'not verified'}),$resolved)
    return $verified
}

function Remove-RedockerSafePath {
        param([string]$Path,[switch]$PreserveWslData,[switch]$PreserveVmData)
        if([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)){ return }
        $resolved = $null
        try { $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).ProviderPath } catch { $resolved = $Path }
        if($resolved -notmatch '^(?i)C:\\'){ return }
        if($resolved -notmatch '(?i)(\\Docker\\?|\\DockerDesktop\\?|\\Docker Desktop\\?|\\containerd\\?|\\\.docker\\?|docker-desktop|ext4\.vhdx|docker.*\.vhdx)'){ return }
        if($resolved -match '(?i)\.vhdx$'){ Write-RedockerSafeLine ("refusing to delete Docker virtual disk: {0}" -f $resolved) Yellow; return }
        Write-RedockerSafeLine ("purge {0}" -f $resolved) DarkCyan
        $preservedNames = New-Object System.Collections.Generic.List[string]
        if($PreserveWslData -and (Test-Path -LiteralPath (Join-Path $resolved 'wsl') -PathType Container)){ [void]$preservedNames.Add('wsl') }
        if($PreserveVmData -and (Test-Path -LiteralPath (Join-Path $resolved 'vm-data') -PathType Container)){ [void]$preservedNames.Add('vm-data') }
        if($preservedNames.Count -gt 0){
            Write-RedockerSafeLine ("preserving Docker virtual disk directories: {0}" -f (($preservedNames.ToArray()) -join ', ')) DarkCyan
            foreach($child in @(Get-ChildItem -LiteralPath $resolved -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin $preservedNames.ToArray() })){
                try { Remove-Item -LiteralPath $child.FullName -Recurse -Force -ErrorAction Stop } catch { try { Remove-Item -LiteralPath $child.FullName -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
            }
            return
        }
        try { Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction Stop } catch { try { Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
    }

function Remove-RrmFile {
        param(
            [Parameter(Mandatory = $true)][string]$Target,
            [Parameter(Mandatory = $true)][int]$Passes
        )

        $takeown = Join-Path $env:windir 'System32\takeown.exe'
        $icacls = Join-Path $env:windir 'System32\icacls.exe'
        $cmd = Join-Path $env:windir 'System32\cmd.exe'
        $fileTarget = [IO.Path]::GetFullPath($Target)

        for ($pass = 1; $pass -le $Passes; $pass++) {
            Write-RrmLine 'PASS' ("file {0}/{1} target={2}" -f $pass, $Passes, $fileTarget)
            Stop-RrmTargetProcesses -Target $fileTarget
            [void](Invoke-RrmNative -Stage 'FILE-TAKEOWN' -FilePath $takeown -ArgumentList @('/f', $fileTarget))
            [void](Invoke-RrmNative -Stage 'FILE-ICACLS' -FilePath $icacls -ArgumentList @($fileTarget, '/grant', "$($env:USERNAME):F", '*S-1-5-32-544:F', '*S-1-5-18:F', '/c', '/q'))
            [void](Invoke-RrmNative -Stage 'FILE-ATTRIB' -FilePath $cmd -ArgumentList @('/d', '/c', ('attrib -r -s -h "{0}" >nul 2>nul & exit /b 0' -f $fileTarget)))
            [void](Invoke-RrmNative -Stage 'FILE-DEL' -FilePath $cmd -ArgumentList @('/d', '/c', ('del /f /q "{0}" >nul 2>nul & exit /b 0' -f $fileTarget)))
            try { [IO.File]::Delete($fileTarget) } catch { Write-RrmLine 'WARN' ("FILE-DOTNET-DELETE failed: {0}" -f $_.Exception.Message) }
            try { Remove-Item -LiteralPath $fileTarget -Force -ErrorAction Stop } catch { Write-RrmLine 'WARN' ("FILE-PS-REMOVE failed: {0}" -f $_.Exception.Message) }
            if (-not (Test-Path -LiteralPath $fileTarget)) {
                Write-RrmLine 'DONE' ("file={0}" -f $fileTarget)
                return
            }
            Start-Sleep -Milliseconds ([Math]::Min(1500, 150 * $pass))
        }

        throw ("rrm could not delete file: {0}" -f $fileTarget)
    }

function Remove-RrmFolder {
        param(
            [Parameter(Mandatory = $true)][string]$Target,
            [Parameter(Mandatory = $true)][int]$Passes
        )

        $targetNorm = [IO.Path]::GetFullPath($Target).TrimEnd('\')
        $empty = Join-Path $env:TEMP ('rrm_empty_' + [guid]::NewGuid().ToString('N'))
        $cmd = Join-Path $env:windir 'System32\cmd.exe'
        $takeown = Join-Path $env:windir 'System32\takeown.exe'
        $icacls = Join-Path $env:windir 'System32\icacls.exe'
        $robocopy = Join-Path $env:windir 'System32\robocopy.exe'

        try {
            New-Item -ItemType Directory -Force -Path $empty | Out-Null
            for ($pass = 1; $pass -le $Passes; $pass++) {
                $before = Get-RrmRootSummary -LiteralPath $targetNorm
                Write-RrmLine 'PASS' ("dir {0}/{1} target={2} exists={3} children={4} sample={5}" -f $pass, $Passes, $targetNorm, $before.Exists, $before.ChildCount, $before.Sample)
                Stop-RrmTargetProcesses -Target $targetNorm
                [void](Invoke-RrmNative -Stage 'DIR-TAKEOWN' -FilePath $takeown -ArgumentList @('/f', $targetNorm, '/r', '/d', 'y'))
                [void](Invoke-RrmNative -Stage 'DIR-ICACLS' -FilePath $icacls -ArgumentList @($targetNorm, '/grant', "$($env:USERNAME):(OI)(CI)F", '*S-1-5-32-544:(OI)(CI)F', '*S-1-5-18:(OI)(CI)F', '/inheritance:e', '/t', '/c', '/q'))
                [void](Invoke-RrmNative -Stage 'DIR-ATTRIB' -FilePath $cmd -ArgumentList @('/d', '/c', ('attrib -r -s -h "{0}\*" /s /d >nul 2>nul & exit /b 0' -f $targetNorm)))
                [void](Invoke-RrmNative -Stage 'DIR-ROBOCOPY' -FilePath $robocopy -ArgumentList @($empty, $targetNorm, '/MIR', '/MT:64', '/R:0', '/W:0', '/XJ') -AllowedExitCodes @(0,1,2,3,4,5,6,7))
                [void](Invoke-RrmNative -Stage 'DIR-CMDSWEEP' -FilePath $cmd -ArgumentList @('/d', '/c', ('for /d %I in ("{0}\*") do rd /s /q "%~fI" 2>nul & del /f /q "{0}\*" 2>nul & rd /s /q "{0}" 2>nul & exit /b 0' -f $targetNorm)))
                try { Get-ChildItem -LiteralPath $targetNorm -Force -ErrorAction Stop | Remove-Item -Recurse -Force -ErrorAction Stop } catch { Write-RrmLine 'WARN' ("DIR-PS-SWEEP failed: {0}" -f $_.Exception.Message) }
                try { Remove-Item -LiteralPath $targetNorm -Recurse -Force -ErrorAction Stop } catch { Write-RrmLine 'WARN' ("DIR-PS-REMOVE failed: {0}" -f $_.Exception.Message) }
                [void](Invoke-RrmNative -Stage 'DIR-RD' -FilePath $cmd -ArgumentList @('/d', '/c', ('rd /s /q "{0}" 2>nul & exit /b 0' -f $targetNorm)))
                if (-not (Test-Path -LiteralPath $targetNorm)) {
                    Write-RrmLine 'DONE' ("dir={0}" -f $targetNorm)
                    return
                }
                $after = Get-RrmRootSummary -LiteralPath $targetNorm
                Write-RrmLine 'VERIFY' ("pass={0} exists={1} children={2} sample={3}" -f $pass, $after.Exists, $after.ChildCount, $after.Sample)
                Start-Sleep -Milliseconds ([Math]::Min(1500, 150 * $pass))
            }
        } finally {
            try { Remove-Item -LiteralPath $empty -Recurse -Force -ErrorAction Stop } catch { Write-RrmLine 'WARN' ("DIR-TEMP-CLEANUP failed: {0}" -f $_.Exception.Message) }
        }

        throw ("rrm could not delete folder: {0}" -f $targetNorm)
    }

function Remove-TemporaryFileWithRetry {
    param([Parameter(Mandatory)][string]$LiteralPath)
    for ($attempt = 1; $attempt -le 30; $attempt++) {
        try {
            Remove-Item -LiteralPath $LiteralPath -Force -ErrorAction Stop
            return
        } catch [IO.IOException] {
            if ($attempt -eq 30) { throw }
            Start-Sleep -Milliseconds 500
        }
    }
}

function Remove-UniRegistryKey {
    param([string]$ProviderPath)
    Remove-Item -LiteralPath $ProviderPath -Recurse -Force -ErrorAction SilentlyContinue
    $cur = Split-Path -Parent $ProviderPath
    for ($i = 0; $i -lt 6 -and $cur -and $cur -match '\\Software($|\\)'; $i++) {
        if (Test-Path -LiteralPath $cur) {
            $k = Get-Item -LiteralPath $cur -ErrorAction SilentlyContinue
            if ($k -and $k.SubKeyCount -eq 0 -and @($k.GetValueNames()).Count -eq 0) {
                Remove-Item -LiteralPath $cur -Force -ErrorAction SilentlyContinue
                $cur = Split-Path -Parent $cur
            } else { break }
        } else { break }
    }
}

function Remove-UniRegistryValue {
    param([string]$ProviderPath, [string]$ValueName)
    if (-not [string]::IsNullOrEmpty($ValueName)) {
        Remove-ItemProperty -LiteralPath $ProviderPath -Name $ValueName -ErrorAction SilentlyContinue
        return
    }
    try {
        $p = $ProviderPath
        if ($p.StartsWith('Registry::', [System.StringComparison]::OrdinalIgnoreCase)) { $p = $p.Substring(10) }
        $hiveName = ''
        $sub = ''
        if ($p -match '^([A-Za-z]+):\\(.*)$') { $hiveName = $matches[1]; $sub = $matches[2] }
        elseif ($p -match '^([A-Za-z]+)\\(.*)$') { $hiveName = $matches[1]; $sub = $matches[2] }
        $hive = $null
        if ($hiveName -eq 'HKCU') { $hive = [Microsoft.Win32.Registry]::CurrentUser }
        elseif ($hiveName -eq 'HKLM') { $hive = [Microsoft.Win32.Registry]::LocalMachine }
        elseif ($hiveName -eq 'HKCR') { $hive = [Microsoft.Win32.Registry]::ClassesRoot }
        elseif ($hiveName -eq 'HKU') { $hive = [Microsoft.Win32.Registry]::Users }
        if ($hive -and $sub) {
            $key = $hive.OpenSubKey($sub, $true)
            if ($key) {
                try { $key.DeleteValue('', $false) } catch { }
                $key.Close()
            }
        }
    } catch { }
}

function Remove-UniTarget {
    param([string]$Path, [int]$MaxRounds = 3)
    for ($round = 0; $round -lt $MaxRounds; $round++) {
        if (-not (Test-Path -LiteralPath $Path)) { return $true }
        $isDir = $false
        try { $isDir = [System.IO.Directory]::Exists($Path) } catch { }
        $lp = $Path
        if ($lp.Length -ge 248) { $lp = '\\?\' + $lp.TrimEnd('\') }

        if ($isDir) { & cmd.exe /c rd /s /q "$lp" 2>$null }
        else { & cmd.exe /c del /f /q /a "$lp" 2>$null }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        if ($isDir) { & attrib.exe -R -S -H "$Path" /D /S 2>$null | Out-Null }
        else { & attrib.exe -R -S -H "$Path" 2>$null | Out-Null }
        try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        $lockers = @(Get-UniLockerPids -Path $Path)
        foreach ($pidId in $lockers) {
            if ($global:UniProtectedPids.ContainsKey($pidId)) { continue }
            try {
                $lkp = Get-Process -Id $pidId -ErrorAction Stop
                if ($global:UniNeverKill -contains $lkp.ProcessName.ToLowerInvariant()) { continue }
                Stop-Process -Id $pidId -Force -ErrorAction SilentlyContinue
            } catch { }
        }
        Start-Sleep -Milliseconds 250
        if ($isDir) { & cmd.exe /c rd /s /q "$lp" 2>$null }
        else { & cmd.exe /c del /f /q /a "$lp" 2>$null }
        try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        if ($global:UniIsElevated) {
            if ($isDir) { & takeown.exe /F "$Path" /A /R /D Y 2>$null | Out-Null; & icacls.exe "$Path" /grant "*S-1-5-32-544:(OI)(CI)F" /T /C /Q 2>$null | Out-Null }
            else { & takeown.exe /F "$Path" /A 2>$null | Out-Null; & icacls.exe "$Path" /grant "*S-1-5-32-544:F" /C /Q 2>$null | Out-Null }
            try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { }
            if (-not (Test-Path -LiteralPath $Path)) { return $true }
        }
        Start-Sleep -Milliseconds 200
    }
    return -not (Test-Path -LiteralPath $Path)
}

function Remove-WingupStateEntry {
        $removed = $false
        for ($i = $state.Entries.Count - 1; $i -ge 0; $i--) {
            if ($state.Entries[$i].Id -eq $id) {
                $state.Entries.RemoveAt($i)
                $removed = $true
            }
        }
        return $removed
    }

function Repair-OpenCodePackageBinary {
    $packageRoot = Get-OpenCodeNpmPackageRoot
    if (-not $packageRoot) {
        return $false
    }

    $postinstall = Join-Path $packageRoot 'postinstall.mjs'
    if (-not (Test-Path -LiteralPath $postinstall -PathType Leaf)) {
        return $false
    }

    $nodePath = Resolve-OpenCodeApplicationPath -Name 'node.exe'
    if (-not $nodePath) {
        $nodePath = Resolve-OpenCodeApplicationPath -Name 'node'
    }
    if (-not $nodePath) {
        return $false
    }

    Write-Host "OC_PROGRESS stage=repairing-package postinstall=$postinstall"
    & $nodePath $postinstall
    if ($LASTEXITCODE -ne 0) {
        throw "OpenCode postinstall repair exited with code $LASTEXITCODE."
    }

    $true
}

function Repair-RedockerSafeSettings {
        $dockerRoaming = Join-Path $env:APPDATA 'Docker'
        $dotDocker = Join-Path $env:USERPROFILE '.docker'
        $settingsStore = Join-Path $dockerRoaming 'settings-store.json'
        $settingsJson = Join-Path $dockerRoaming 'settings.json'
        $daemonJson = Join-Path $dotDocker 'daemon.json'
        $windowsDaemonJson = Join-Path $dotDocker 'windows-daemon.json'
        $fullSettings = "{`n  `"AutoStart`": false,`n  `"DisplayedOnboarding`": true,`n  `"EnableCLIHints`": true,`n  `"EnableDockerAI`": true,`n  `"EnableIntegrationWithDefaultWslDistro`": false,`n  `"FilesharingDirectories`": [`"C:\\\\`", `"E:\\\\`", `"F:\\\\`"],`n  `"InferenceCanUseGPUVariant`": true,`n  `"LicenseTermsVersion`": 2,`n  `"MemoryMiB`": 33792,`n  `"OpenUIOnStartupDisabled`": true,`n  `"SettingsVersion`": 44,`n  `"SwapMiB`": 3072,`n  `"ThemeSource`": `"dark`",`n  `"UseBackgroundIndexing`": false,`n  `"UseContainerdSnapshotter`": true,`n  `"UseVirtualizationFramework`": false,`n  `"WslEngineEnabled`": false`n}"
        $desktopSettings = "{`n  `"WslEngineEnabled`": false,`n  `"UseVirtualizationFramework`": false,`n  `"EnableIntegrationWithDefaultWslDistro`": false,`n  `"AutoStart`": false`n}"
        $daemonSettings = "{`n  `"builder`": {`"gc`": {`"defaultKeepStorage`": `"20GB`", `"enabled`": true}},`n  `"experimental`": false,`n  `"max-concurrent-downloads`": 10,`n  `"max-concurrent-uploads`": 10,`n  `"max-download-attempts`": 5,`n  `"features`": {`"buildkit`": true}`n}"
        $needsFullSettings = $true
        if(Test-Path -LiteralPath $settingsStore){
            try {
                $current = [IO.File]::ReadAllText($settingsStore)
                $needsFullSettings = ($current -notmatch 'FilesharingDirectories' -or $current -notmatch 'MemoryMiB' -or $current -notmatch 'UseContainerdSnapshotter')
            } catch { $needsFullSettings = $true }
        }
        if($needsFullSettings){ Save-RedockerSafeText -Path $settingsStore -Text $fullSettings; Write-RedockerSafeLine 'restored full Docker Desktop settings-store including C/E/F file sharing and resource settings' Green }
        if(-not (Test-Path -LiteralPath $settingsJson)){ Save-RedockerSafeText -Path $settingsJson -Text $desktopSettings }
        $needsDaemon = $true
        if(Test-Path -LiteralPath $daemonJson){
            try { $needsDaemon = ([IO.File]::ReadAllText($daemonJson) -notmatch 'max-concurrent-downloads') } catch { $needsDaemon = $true }
        }
        if($needsDaemon){ Save-RedockerSafeText -Path $daemonJson -Text $daemonSettings; Write-RedockerSafeLine 'restored daemon performance settings' Green }
        if(-not (Test-Path -LiteralPath $windowsDaemonJson)){ Save-RedockerSafeText -Path $windowsDaemonJson -Text "{`n}`n" }
        foreach($var in @('DOCKER_BUILDKIT','COMPOSE_DOCKER_CLI_BUILD')){
            try { [Environment]::SetEnvironmentVariable($var,'1','Machine') } catch { }
            Set-Item -Path ("Env:{0}" -f $var) -Value '1' -ErrorAction SilentlyContinue
        }
        try { [Environment]::SetEnvironmentVariable('BUILDKIT_PROGRESS','plain','Machine'); $env:BUILDKIT_PROGRESS='plain' } catch { }
    }

