function Repair-StandardWindowsEnvironment {
    $userProfile = if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
        $env:USERPROFILE
    } else {
        'C:\Users\micha'
    }
    $systemDrive = if (-not [string]::IsNullOrWhiteSpace($env:SystemDrive)) {
        $env:SystemDrive
    } elseif (-not [string]::IsNullOrWhiteSpace($env:SystemRoot) -and $env:SystemRoot -match '^[A-Za-z]:') {
        $env:SystemRoot.Substring(0, 2)
    } else {
        'C:'
    }
    $programData = Join-Path $systemDrive 'ProgramData'
    $publicProfile = Join-Path $systemDrive 'Users\Public'
    $homeDrive = Split-Path $userProfile -Qualifier
    $homePath = if ($homeDrive -and $userProfile.StartsWith($homeDrive, [System.StringComparison]::OrdinalIgnoreCase)) {
        $userProfile.Substring($homeDrive.Length)
    } else {
        '\Users\micha'
    }
    $defaults = [ordered]@{
        SystemDrive = $systemDrive
        ProgramData = $programData
        ALLUSERSPROFILE = $programData
        PUBLIC = $publicProfile
        HOMEDRIVE = if ($homeDrive) { $homeDrive } else { 'C:' }
        HOMEPATH = $homePath
    }

    foreach ($name in $defaults.Keys) {
        if ([string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($name, 'Process'))) {
            Set-Item -Path "Env:$name" -Value $defaults[$name]
        }
    }
}

function Repair-StandardWindowsProcessEnvironment {
$systemRoot = [Environment]::GetEnvironmentVariable('SystemRoot', 'Process')
if ([string]::IsNullOrWhiteSpace($systemRoot)) {
    $systemRoot = [Environment]::GetEnvironmentVariable('SystemRoot', 'Machine')
}
if ([string]::IsNullOrWhiteSpace($systemRoot)) { $systemRoot = 'C:\Windows' }

$systemDrive = [Environment]::GetEnvironmentVariable('SystemDrive', 'Process')
if ([string]::IsNullOrWhiteSpace($systemDrive) -and $systemRoot -match '^[A-Za-z]:') {
    $systemDrive = $systemRoot.Substring(0, 2)
}
if ([string]::IsNullOrWhiteSpace($systemDrive)) { $systemDrive = 'C:' }

$defaults = @{
    SystemDrive = $systemDrive
    SystemRoot = $systemRoot
    windir = $systemRoot
    ProgramData = (Join-Path $systemDrive 'ProgramData')
    ALLUSERSPROFILE = (Join-Path $systemDrive 'ProgramData')
    PUBLIC = (Join-Path $systemDrive 'Users\Public')
}

foreach ($name in $defaults.Keys) {
    if ([string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($name, 'Process'))) {
        Set-Item -Path "Env:$name" -Value $defaults[$name]
    }
}

$pathCandidates = New-Object System.Collections.ArrayList
foreach ($scope in @('Process', 'User', 'Machine')) {
    $value = [Environment]::GetEnvironmentVariable('Path', $scope)
    if ([string]::IsNullOrWhiteSpace($value)) { continue }

    foreach ($entry in $value -split ';') {
        if ([string]::IsNullOrWhiteSpace($entry)) { continue }
        [void]$pathCandidates.Add([Environment]::ExpandEnvironmentVariables($entry.Trim()))
    }
}
foreach ($entry in @(
    (Join-Path $systemRoot 'System32'),
    $systemRoot,
    (Join-Path $systemRoot 'System32\Wbem'),
    (Join-Path $systemRoot 'System32\WindowsPowerShell\v1.0')
)) {
    if (Test-Path -LiteralPath $entry -PathType Container) {
        [void]$pathCandidates.Add($entry)
    }
}

$pathEntries = New-Object System.Collections.ArrayList
foreach ($entry in @($pathCandidates)) {
    if ([string]::IsNullOrWhiteSpace($entry)) { continue }
    if (-not (@($pathEntries) | Where-Object { $_ -ieq $entry })) {
        [void]$pathEntries.Add($entry)
    }
}
$env:Path = @($pathEntries) -join ';'

$modulePathCandidates = New-Object System.Collections.ArrayList
foreach ($scope in @('Process', 'User', 'Machine')) {
    $value = [Environment]::GetEnvironmentVariable('PSModulePath', $scope)
    if ([string]::IsNullOrWhiteSpace($value)) { continue }

    foreach ($entry in $value -split ';') {
        if ([string]::IsNullOrWhiteSpace($entry)) { continue }
        [void]$modulePathCandidates.Add([Environment]::ExpandEnvironmentVariables($entry.Trim()))
    }
}

if (-not [string]::IsNullOrWhiteSpace($HOME)) {
    [void]$modulePathCandidates.Add((Join-Path $HOME 'Documents\WindowsPowerShell\Modules'))
}
if (-not [string]::IsNullOrWhiteSpace($env:ProgramFiles)) {
    [void]$modulePathCandidates.Add((Join-Path $env:ProgramFiles 'WindowsPowerShell\Modules'))
}
[void]$modulePathCandidates.Add((Join-Path $PSHOME 'Modules'))

$modulePathEntries = New-Object System.Collections.ArrayList
foreach ($entry in @($modulePathCandidates)) {
    if ([string]::IsNullOrWhiteSpace($entry)) { continue }
    if (-not (@($modulePathEntries) | Where-Object { $_ -ieq $entry })) {
        [void]$modulePathEntries.Add($entry)
    }
}
$env:PSModulePath = @($modulePathEntries) -join ';'
}

function Replace-ProfileFunctionMutationDefinitions {
    param(
        [Parameter(Mandatory)][string]$Source,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Matches,
        [Parameter(Mandatory)][string]$Definition
    )

    if ($Matches.Count -eq 0) {
        return $Source.TrimEnd() + "`r`n`r`n" + $Definition + "`r`n"
    }

    $insertOffset = $Matches[-1].Extent.StartOffset
    $updated = $Source
    foreach ($match in @($Matches | Sort-Object { $_.Extent.StartOffset } -Descending)) {
        if ($match.Extent.StartOffset -lt $insertOffset) {
            $insertOffset -= ($match.Extent.EndOffset - $match.Extent.StartOffset)
        }
        $updated = $updated.Remove($match.Extent.StartOffset, $match.Extent.EndOffset - $match.Extent.StartOffset)
    }
    $updated.Insert($insertOffset, $Definition)
}

