function Resolve-CleancRootPathLocal {
        param([Parameter(Mandatory=$true)][string]$Path)
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        if (-not $item.PSIsContainer) { throw "cleanc root path must be a directory: $Path" }
        $resolved = [System.IO.Path]::GetFullPath($item.FullName).TrimEnd('\')
        if ($resolved.Length -eq 2 -and $resolved[1] -eq ':') { return ($resolved + '\') }
        return $resolved
    }

function Resolve-CodexExecutableCandidate {
        if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
        if (-not (Test-Path -LiteralPath $Path)) { return $null }

        try {
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        } catch {
            return $null
        }

        if ($item.PSIsContainer) { return $null }

        $targets = @()
        if ($item.LinkType -and $item.Target) {
            $targets = @($item.Target)
        }

        foreach ($target in $targets) {
            $resolvedTarget = $target
            if (-not [System.IO.Path]::IsPathRooted($resolvedTarget)) {
                $resolvedTarget = Join-Path $item.DirectoryName $resolvedTarget
            }

            if (-not (Test-Path -LiteralPath $resolvedTarget)) { continue }

            try {
                $targetItem = Get-Item -LiteralPath $resolvedTarget -Force -ErrorAction Stop
            } catch {
                continue
            }

            if ($targetItem.PSIsContainer) { continue }
            if ([System.IO.Path]::GetExtension($targetItem.Name) -ne '.exe') { continue }
            if ($targetItem.Length -le 0) { continue }

            return $targetItem.FullName
        }

        if ([System.IO.Path]::GetExtension($item.Name) -ne '.exe') { return $null }
        if ($item.Length -le 0) { return $null }

        return $item.FullName
    }

function Resolve-FastTransferLiteralPath {
