    }

    $resolved = Resolve-Path -LiteralPath $InputPath -ErrorAction SilentlyContinue
    if ($resolved) {
        return $resolved.ProviderPath
    }

    $candidate = Join-Path (Get-Location).Path $InputPath
    $resolvedCandidate = Resolve-Path -LiteralPath $candidate -ErrorAction SilentlyContinue
    if ($resolvedCandidate) {
        return $resolvedCandidate.ProviderPath
    }

    throw "Path not found: $InputPath"
}

function Resolve-NvidLatestDriverDownload {
        param([Parameter(Mandatory=$true)]$Target)
        $osId = 135
        $uri = ('https://www.nvidia.com/Download/processFind.aspx?psid={0}&pfid={1}&osID={2}&languageCode=1033&beta=0&isWHQL=1&dltype=-1&sort1=0&numberOfResults=10&dtcid=1' -f $Target.SeriesId,$Target.ProductId,$osId)
        Write-NvidStep ("querying latest NVIDIA display driver for {0} via NVIDIA processFind" -f $Target.ProductName)
        $page = Invoke-WebRequest -Uri $uri -UseBasicParsing -TimeoutSec 60
        $html = [string]$page.Content
        $rows = [regex]::Matches($html, '<tr id="driverList">(?<row>[\s\S]*?)</tr>')
        foreach($m in $rows) {
            $row = $m.Groups['row'].Value
            $idMatch = [regex]::Match($row, 'driverResults\.aspx/(?<id>\d+)/en-us')
            $verMatch = [regex]::Match($row, '<td class="gridItem">(?<ver>\d+\.\d+)</td>')
            if ($idMatch.Success -and $verMatch.Success -and $row -match 'GeForce Game Ready Driver') {
                $ver = $verMatch.Groups['ver'].Value
                $driverId = $idMatch.Groups['id'].Value
                $candidates = @(
                    ('https://us.download.nvidia.com/Windows/{0}/{0}-desktop-win10-win11-64bit-international-dch-whql.exe' -f $ver),
                    ('https://international.download.nvidia.com/Windows/{0}/{0}-desktop-win10-win11-64bit-international-dch-whql.exe' -f $ver)
                )
                foreach($candidate in $candidates) {
                    try {
                        $req = [System.Net.HttpWebRequest]::Create($candidate)
                        $req.Method = 'HEAD'
                        $req.Timeout = 30000
                        $resp = $req.GetResponse()
                        try { if ([int]$resp.StatusCode -eq 200) { return [pscustomobject]@{ Version = $ver; DriverId = $driverId; Url = $candidate } } } finally { $resp.Close() }
                    } catch {}
                }
                throw ("Latest NVIDIA driver {0} was found but download URL pattern did not resolve." -f $ver)
            }
        }
        throw 'NVIDIA processFind returned no English GeForce Game Ready Driver rows.'
    }

function Resolve-NviocOpenCode {
        # The platform binary lives directly in opencode-ai\bin AND (as a
        # hard link) in the optional opencode-windows-x64 package. Check both
        # so a half-installed package never defeats the launcher. Prefer the
        # real exe over the .cmd shim (a shim can be stale and point at a
        # missing binary).
        $candidates = @(
            (Join-Path $env:LOCALAPPDATA 'npm-global\node_modules\opencode-ai\bin\opencode.exe'),
            (Join-Path $env:LOCALAPPDATA 'npm-global\node_modules\opencode-ai\node_modules\opencode-windows-x64\bin\opencode.exe'),
            (Join-Path $env:LOCALAPPDATA 'npm-global\node_modules\opencode-ai\node_modules\opencode-windows-x64-baseline\bin\opencode.exe'),
            (Join-Path $env:APPDATA 'npm\node_modules\opencode-ai\bin\opencode.exe')
        )
        foreach ($candidate in $candidates) {
            if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
        }
        foreach ($shim in @('opencode.cmd', 'opencode')) {
            $cmd = Get-Command $shim -CommandType Application -ErrorAction SilentlyContinue
            if ($cmd -and $cmd.Source) { return $cmd.Source }
        }
        return $null
    }

function Resolve-OcToolPath {
        param(
            [string[]]$Candidates,
            [string[]]$CommandNames
        )

        foreach ($candidate in $Candidates) {
            if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
                return $candidate
            }
        }
        foreach ($commandName in $CommandNames) {
            foreach ($command in (Get-Command $commandName -All -ErrorAction SilentlyContinue)) {
                if ($command.Source -and
                    $command.Source -notmatch 'WindowsApps' -and
                    (Test-Path -LiteralPath $command.Source -PathType Leaf)) {
                    return $command.Source
                }
            }
        }
        return $null
    }

