function Resolve-OpenCodeApplicationPath {
    param([Parameter(Mandatory = $true)][string]$Name)

    $applications = @(Get-Command -Name $Name -CommandType Application -All -ErrorAction Ignore)
    foreach ($application in $applications) {
        $candidate = [string]$application.Path
        if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
