function Resolve-OpenCodeCliPath {
    foreach ($name in @('opencode.cmd', 'opencode')) {
        $candidate = Resolve-OpenCodeApplicationPath -Name $name
        if ($candidate) {
            return $candidate
        }
    }

    foreach ($candidate in @(
        (Join-Path $env:APPDATA 'npm\opencode.cmd'),
        (Join-Path $env:LOCALAPPDATA 'npm\opencode.cmd'),
        (Join-Path $env:LOCALAPPDATA 'npm-global\opencode.cmd')
    )) {
        if (Test-Path -LiteralPath $candidate -PathType Leaf) {
            return $candidate
        }
    }

    $npmPath = Resolve-OpenCodeApplicationPath -Name 'npm.cmd'
    if ($npmPath) {
        $npmGlobalRoot = @(& $npmPath root -g)
        $npmExitCode = $LASTEXITCODE
        $npmRoot = $npmGlobalRoot | Select-Object -First 1
        if ($npmExitCode -eq 0 -and $npmRoot) {
            $npmBin = ($npmRoot | Split-Path).Trim()
            $candidate = Join-Path $npmBin 'opencode.cmd'
            if (Test-Path -LiteralPath $candidate -PathType Leaf) {
                return $candidate
            }
        }
    }

    $null
}

function Resolve-OpenCodePlatformBinary {
    $packageRoot = Get-OpenCodeNpmPackageRoot
    if (-not $packageRoot) {
        return $null
    }

    $packageNames = if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64') {
        @('opencode-windows-arm64')
    } else {
        @('opencode-windows-x64', 'opencode-windows-x64-baseline')
    }

    foreach ($packageName in $packageNames) {
        $candidate = Join-Path $packageRoot "node_modules\$packageName\bin\opencode.exe"
        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) {
            continue
        }

        $probe = Test-OpenCodeCommand -Path $candidate
        if ($probe.IsValid) {
            return [pscustomobject]@{
                Path = $candidate
                Version = $probe.Version
            }
        }
    }

    $null
}

function Resolve-PostAction {
        if (-not $afterPackage) {
            [void](Remove-WingupStateEntry $state $package.Id)
            return [pscustomobject]@{
                Status = 'success'
                Message = "$($package.Name) is no longer listed by winget."
            }
        }

        if ($result.RestartRequired) {
            $note = 'Upgrade succeeded, but winget still lists the old version until the app is restarted.'
            Set-WingupStateEntry $state $package 'restart-required' $note
            return [pscustomobject]@{
                Status = 'suppressed'
                Message = "$($package.Name) was updated and is now suppressed until restart state clears."
            }
        }

        if ($result.Succeeded -and $afterPackage.Current -eq 'Unknown' -and $afterPackage.Available -eq $package.Available) {
            $note = 'Upgrade succeeded, but winget still reports the package because the installed version stays Unknown.'
            Set-WingupStateEntry $state $package 'metadata-stuck' $note
            return [pscustomobject]@{
                Status = 'suppressed'
                Message = "$($package.Name) was upgraded; winget metadata is stuck, so it is suppressed until the available version changes."
            }
        }

        if ($package.Id -eq 'OpenAI.Codex' -and $result.AccessDenied -and (Test-CodexCliRunning)) {
            return [pscustomobject]@{
                Status = 'deferred'
                Message = 'Codex CLI is running from the winget-managed path. Close Codex CLI sessions and rerun wingup to finish that upgrade.'
            }
        }

        return [pscustomobject]@{
            Status = 'pending'
            Message = "$($package.Name) is still listed after the attempt."
        }
    }

function Resolve-ProfilePythonExecutable {
    if ($script:CachedProfilePythonExecutable -and (Test-Path -LiteralPath $script:CachedProfilePythonExecutable -PathType Leaf)) {
        return $script:CachedProfilePythonExecutable
    }

    $candidatePaths = @(
        $env:CODEX_PROFILE_PYTHON,
        (Join-Path $env:LOCALAPPDATA 'Programs\Python\Python312\python.exe'),
        (Join-Path $env:LOCALAPPDATA 'Programs\Python\Python311\python.exe'),
        'C:\Python312\python.exe',
        'C:\Python311\python.exe'
    )

    foreach ($candidate in $candidatePaths) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        if (Test-Path -LiteralPath $candidate -PathType Leaf) {
            $script:CachedProfilePythonExecutable = (Resolve-Path -LiteralPath $candidate).ProviderPath
            return $script:CachedProfilePythonExecutable
        }
    }

    $command = Get-Command python -All -CommandType Application -ErrorAction SilentlyContinue |
        Where-Object { $_.Path -and $_.Path -notlike '*\Microsoft\WindowsApps\python*.exe' } |
        Select-Object -First 1
    if ($command) {
        $script:CachedProfilePythonExecutable = $command.Path
        return $script:CachedProfilePythonExecutable
    }

    $launcher = Get-Command py.exe -CommandType Application -ErrorAction SilentlyContinue
    if ($launcher) { return $launcher.Path }

    throw 'No usable Python interpreter found. Install Python or set CODEX_PROFILE_PYTHON to a real python.exe path.'
}

function Resolve-RedockerDockerCli {
        $candidates=@('C:\Program Files\Docker\Docker\resources\bin\docker.exe','C:\Program Files\Docker\Docker\docker.exe')
        $cmd=Get-Command docker.exe -ErrorAction SilentlyContinue
        if($cmd){ $candidates=@($cmd.Source)+$candidates }
        foreach($candidate in ($candidates | Where-Object { $_ } | Select-Object -Unique)){
            if(Test-Path -LiteralPath $candidate -PathType Leaf){ return $candidate }
        }
        return $null
    }

function Resolve-RedockerSafeWingetPath {
        $candidates = New-Object System.Collections.Generic.List[string]
        foreach($cmdName in @('winget.exe','winget')){
            try {
                foreach($cmd in @(Get-Command $cmdName -CommandType Application -ErrorAction SilentlyContinue)){
                    if($cmd.Source){ [void]$candidates.Add($cmd.Source) }
                    if($cmd.Path){ [void]$candidates.Add($cmd.Path) }
                }
            } catch { }
        }
        $windowsAppsWinget = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
        if($windowsAppsWinget){ [void]$candidates.Add($windowsAppsWinget) }
        try {
            $packageRoot = Join-Path ${env:ProgramFiles} 'WindowsApps'
            if(Test-Path -LiteralPath $packageRoot){
                foreach($wingetExe in @(Get-ChildItem -LiteralPath $packageRoot -Filter 'winget.exe' -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)){
                    [void]$candidates.Add($wingetExe.FullName)
                }
            }
        } catch { }
        foreach($candidate in ($candidates | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)){
            try {
                if((Test-Path -LiteralPath $candidate -PathType Leaf) -and ((Get-Item -LiteralPath $candidate -Force).Length -gt 0 -or $candidate -match '\\WindowsApps\\winget\.exe$')){
                    return $candidate
                }
            } catch { }
        }
        return $null
    }

function Resolve-WingetExecutable {
    $cached = $script:CachedWingetExecutable
    if ($cached -and (Test-Path -LiteralPath $cached -PathType Leaf) -and ($cached -notlike '*\Microsoft\WindowsApps\winget.exe')) {
        return $cached
    }
    $script:CachedWingetExecutable = $null

    $candidates = New-Object System.Collections.Generic.List[string]
    $appx = Get-AppxPackage -Name Microsoft.DesktopAppInstaller -ErrorAction SilentlyContinue |
        Sort-Object Version -Descending |
        Select-Object -First 1
    if ($appx -and $appx.InstallLocation) {
        $candidates.Add((Join-Path $appx.InstallLocation 'winget.exe'))
    }

    $programFilesWindowsApps = Join-Path $env:ProgramFiles 'WindowsApps'
    if (Test-Path -LiteralPath $programFilesWindowsApps -PathType Container) {
        Get-ChildItem -Path (Join-Path $programFilesWindowsApps 'Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe\winget.exe') -ErrorAction SilentlyContinue |
            Sort-Object LastWriteTime -Descending |
            ForEach-Object { $candidates.Add($_.FullName) }
    }

    Get-Command winget.exe -CommandType Application -ErrorAction SilentlyContinue |
        ForEach-Object { if ($_.Source) { $candidates.Add([string]$_.Source) } }

    foreach ($candidate in ($candidates | Where-Object { $_ } | Select-Object -Unique)) {
        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) { continue }
        if ($candidate -like '*\Microsoft\WindowsApps\winget.exe') { continue }
        $script:CachedWingetExecutable = $candidate
        return $script:CachedWingetExecutable
    }

    throw 'real packaged winget.exe not found. Update/install App Installer from Microsoft Store, or enable the App Installer package.'
}

