                $regOut = Join-Path $regTempRoot ('nvid_reg_import_{0}.txt' -f ([guid]::NewGuid().ToString('N')))
                & cmd.exe /d /c "reg import `"$regPath`" > `"$regOut`" 2>&1"
                $regImportOutput = if (Test-Path -LiteralPath $regOut) { Get-Content -LiteralPath $regOut -ErrorAction SilentlyContinue } else { @() }
                if ($LASTEXITCODE -ne 0) { throw ("reg import failed for {0}: {1}" -f $regFile,($regImportOutput -join ' ')) }
                Write-NvidStep ("imported NVIDIA settings registry baseline {0}" -f $regFile)
