        }
        foreach($svcName in @('NvContainerLocalSystem','NVDisplay.ContainerLocalSystem')) {
            try { Set-Service -Name $svcName -StartupType Automatic -ErrorAction SilentlyContinue } catch {}
            try { Start-Service -Name $svcName -ErrorAction SilentlyContinue } catch {}
        }
        $smi = @('C:\Windows\System32\nvidia-smi.exe','C:\Program Files\NVIDIA Corporation\NVSMI\nvidia-smi.exe') | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
        if ($smi) {
            try { & $smi -pm 1 2>&1 | Out-Null } catch {}
            try { & $smi -pl 400 2>&1 | Out-Null; Write-NvidStep 'restored NVIDIA power limit target to 400W from captured current state' } catch { Write-Host ("[nvid] warning: could not restore NVIDIA power limit: {0}" -f $_.Exception.Message) -ForegroundColor Yellow }
        }
        try {
            $cpl = Get-AppxPackage -Name 'NVIDIACorp.NVIDIAControlPanel' -ErrorAction SilentlyContinue | Select-Object -First 1
            if (-not $cpl) {
                $winget = $null
                try { $winget = Resolve-WingetExecutable } catch { $winget = $null }
                if ($winget) { & $winget install --id 9NF8H0H7WMLT --source msstore --accept-package-agreements --accept-source-agreements --silent 2>&1 | Out-Host }
                $cpl = Get-AppxPackage -Name 'NVIDIACorp.NVIDIAControlPanel' -ErrorAction SilentlyContinue | Select-Object -First 1
            }
            if (-not $cpl) { throw 'NVIDIA Control Panel AppX package is not installed.' }
            $manifest = Join-Path $cpl.InstallLocation 'AppxManifest.xml'
            if (Test-Path -LiteralPath $manifest) { Add-AppxPackage -DisableDevelopmentMode -Register $manifest -ErrorAction SilentlyContinue }
            Write-NvidStep ("NVIDIA Control Panel package ready: {0}" -f $cpl.PackageFullName)
        } catch { throw ("NVIDIA Control Panel package restore failed: {0}" -f $_.Exception.Message) }
        try {
            $nvCplDll = 'C:\Windows\System32\nvcpl.dll'
            if (Test-Path -LiteralPath $nvCplDll) { & regsvr32.exe /s $nvCplDll 2>$null | Out-Null }
            $nvProfile = 'C:\Program Files\NVIDIA Corporation\Control Panel Client\nvcplui.exe'
            if (Test-Path -LiteralPath $nvProfile) { Start-Process -FilePath $nvProfile -ArgumentList '-forcepsem' -WindowStyle Minimized -ErrorAction SilentlyContinue | Out-Null }
        } catch { Write-Host ("[nvid] warning: Control Panel shell refresh failed: {0}" -f $_.Exception.Message) -ForegroundColor Yellow }
        return $baseline
    }

function Restore-RedockerSafeDir {
        param([string]$Snapshot,[string]$Dest)
        if([string]::IsNullOrWhiteSpace($Snapshot) -or -not (Test-Path -LiteralPath $Snapshot)){ return }
        try {
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Dest) | Out-Null
            Copy-Item -LiteralPath $Snapshot -Destination $Dest -Recurse -Force -ErrorAction Stop
        } catch { Write-RedockerSafeLine ("restore failed {0}: {1}" -f $Dest,$_.Exception.Message) Yellow }
    }

function Restore-RedockerSettingsSnapshot {
        param([Parameter(Mandatory)][string]$SnapshotRoot)
        if(-not (Test-Path -LiteralPath $SnapshotRoot -PathType Container)){ throw "Docker settings snapshot not found: $SnapshotRoot" }
        $manifestPath = Join-Path $SnapshotRoot 'manifest.json'
        if(-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)){ throw "Docker settings snapshot manifest missing: $manifestPath" }
        $manifest = @(Get-RedockerManifestEntries -ManifestPath $manifestPath)
        $restored = 0
        foreach($entry in $manifest){
            $entryName = [string]$entry.Name
            $entrySource = [string]$entry.Source
            $entryRegistry = [string]$entry.Registry
            if(-not [string]::IsNullOrWhiteSpace($entrySource) -and $entryName -notmatch '\\'){
                $snapshot = Join-Path $SnapshotRoot ('files\' + $entryName)
                $restored += Restore-RedockerSnapshotTree -Snapshot $snapshot -Destination $entrySource
            } elseif(-not [string]::IsNullOrWhiteSpace($entryRegistry) -and (Test-Path -LiteralPath $entryRegistry -PathType Leaf)){
                $regExe = Join-Path $env:SystemRoot 'System32\reg.exe'
                & $regExe import $entryRegistry | Out-Null
                if($LASTEXITCODE -ne 0){ throw "Docker registry settings restore failed: $entryName" }
            }
        }
        $environmentPath = Join-Path $SnapshotRoot 'environment.json'
        if(Test-Path -LiteralPath $environmentPath -PathType Leaf){
            $environment = Get-Content -LiteralPath $environmentPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            foreach($property in $environment.PSObject.Properties){
                Set-Item -Path ('Env:{0}' -f $property.Name) -Value ([string]$property.Value)
                try { [Environment]::SetEnvironmentVariable($property.Name,[string]$property.Value,'User') } catch { }
            }
        }
        Write-RedockerSafeLine ("settings snapshot restored: {0} files" -f $restored) Green
        return $restored
    }

function Restore-RedockerSnapshotTree {
        param([Parameter(Mandatory)][string]$Snapshot,[Parameter(Mandatory)][string]$Destination)
        if(-not (Test-Path -LiteralPath $Snapshot -PathType Container)){ return 0 }
        $restored = 0
        foreach($item in @(Get-ChildItem -LiteralPath $Snapshot -Force -Recurse -File -ErrorAction Stop)){
            $relative = $item.FullName.Substring($Snapshot.Length).TrimStart('\')
            $target = Join-Path $Destination $relative
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
            Copy-Item -LiteralPath $item.FullName -Destination $target -Force -ErrorAction Stop
            $restored++
        }
        return $restored
    }

