function rmboots {
    [CmdletBinding(SupportsShouldProcess, ConfirmImpact = 'High')]
    param()

    $helperPath = 'C:\Users\micha\Documents\WindowsPowerShell\legacy-safe-functions\Invoke-RmBoots.ps1'
    if (-not (Test-Path -LiteralPath $helperPath -PathType Leaf)) {
        throw "rmboots: helper script not found: $helperPath"
    }

    if (-not $PSCmdlet.ShouldProcess('all non-current Windows boot-loader entries', 'Delete and suppress the boot menu')) {
        Write-Host 'RMBOOTS_CANCELLED stage=confirmation' -ForegroundColor Yellow
        return
    }

    Write-Progress -Id 775 -Activity 'Removing obsolete Windows boot entries' -Status 'Checking elevation' -PercentComplete 2
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    $isAdministrator = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

    try {
        if ($isAdministrator) {
            Write-Host 'RMBOOTS_PROGRESS stage=running-elevated-helper' -ForegroundColor Cyan
            & $helperPath -Apply -Confirm:$false
            return
        }

        Write-Host 'RMBOOTS_PROGRESS stage=requesting-elevation' -ForegroundColor Cyan
        $argumentList = "-NoProfile -ExecutionPolicy Bypass -File `"$helperPath`" -Apply -Confirm:`$false"
        $process = Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -Verb RunAs -ArgumentList $argumentList -PassThru -Wait -ErrorAction Stop
        if ($process.ExitCode -ne 0) {
            throw "rmboots: elevated helper failed with exit code $($process.ExitCode)."
        }

        Write-Host 'RMBOOTS_OK stage=elevated-helper-completed' -ForegroundColor Green
    }
    finally {
        Write-Progress -Id 775 -Activity 'Removing obsolete Windows boot entries' -Completed
    }
}

