function Run-WithTimeout {
    param([string]$Name, [string]$Cmd, [int]$TimeoutSec = 120)
    Write-Host ('[ccc1] Running: {0}...' -f $Name) -ForegroundColor Cyan
    $command = '. ''' + $PROFILE + ''' -ErrorAction SilentlyContinue; ' + $Cmd
    $argsList = @('-NoLogo', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-Command', $command)
    $proc = Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList $argsList -PassThru -WindowStyle Hidden
    if ($proc.WaitForExit($TimeoutSec * 1000)) {
        Write-Host ('[ccc1] Done: {0}' -f $Name) -ForegroundColor Green
    } else {
        $proc.Kill()
        Write-Host ('[ccc1] TIMEOUT: {0} (>{1}s) - skipped' -f $Name, $TimeoutSec) -ForegroundColor Yellow
    }
}

function runall {
    $exeFiles = Get-ChildItem -Path "F:\games" -Recurse -Filter *.exe -File | Where-Object {
        $_.Name -notmatch '(?i)^unins\d*\.exe$' -and
        $_.Name -notmatch '(?i)^uninstall.*\.exe$' -and
        $_.Name -notmatch '(?i)vc_redist|vcredist|quicksfv|dxwebsetup|crashreportclient|crash'
    }
    foreach ($exe in $exeFiles) {
        try {
            Write-Output "`n[RUNNING] $($exe.FullName)"
            $process = Start-Process -FilePath $exe.FullName -PassThru
            Start-Sleep -Seconds 10
            if (!$process.HasExited) {
                Write-Output "[CLOSING] $($exe.Name)"
                Stop-Process -Id $process.Id -Force
            } else {
                Write-Output "[EXITED EARLY] $($exe.Name)"
            }
        } catch {
            Write-Warning "[ERROR] Failed to handle $($exe.FullName): $_"
        }
    }
    Write-Output "`n[DONE] All filtered executables processed."
}

