function Set-DockerVmmSettings {
    $settingsPath = Join-Path $env:APPDATA 'Docker\settings-store.json'
    $parent = Split-Path -Parent $settingsPath
    New-Item -ItemType Directory -Path $parent -Force -ErrorAction Stop | Out-Null
    $settings = $null
    if (Test-Path -LiteralPath $settingsPath -PathType Leaf) {
        try { $settings = Get-Content -LiteralPath $settingsPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop } catch { }
    }
    if (-not $settings) {
        $settings = [pscustomobject][ordered]@{
            AutoStart = $false
            DisplayedOnboarding = $true
            EnableIntegrationWithDefaultWslDistro = $false
            FilesharingDirectories = @($env:USERPROFILE)
            MemoryMiB = 33792
            OpenUIOnStartupDisabled = $true
            SettingsVersion = 45
        }
    }
    function Set-DockerVmmProperty {
        param([Parameter(Mandatory)]$Object, [Parameter(Mandatory)][string]$Name, $Value)
        $property = $Object.PSObject.Properties[$Name]
        if ($property) { $property.Value = $Value } else { $Object | Add-Member -NotePropertyName $Name -NotePropertyValue $Value }
    }
    Set-DockerVmmProperty -Object $settings -Name 'AllowBetaFeatures' -Value $true
    Set-DockerVmmProperty -Object $settings -Name 'LicenseTermsVersion' -Value 2
    Set-DockerVmmProperty -Object $settings -Name 'DisplayedOnboarding' -Value $true
    Set-DockerVmmProperty -Object $settings -Name 'MemoryMiB' -Value 33792
    Set-DockerVmmProperty -Object $settings -Name 'UseLibkrun' -Value $true
    Set-DockerVmmProperty -Object $settings -Name 'UseResourceSaver' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'UseVirtualizationFramework' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'WslEngineEnabled' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'UseContainerdSnapshotter' -Value $true
    Set-DockerVmmProperty -Object $settings -Name 'EnableIntegrationWithDefaultWslDistro' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'AutoStart' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'OpenUIOnStartupDisabled' -Value $true
    Set-DockerVmmProperty -Object $settings -Name 'ShowInstallScreen' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'DisplayRestartDialog' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'ShowAnnouncementNotifications' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'ShowGeneralNotifications' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'ShowPromotionalNotifications' -Value $false
    Set-DockerVmmProperty -Object $settings -Name 'ShowSurveyNotifications' -Value $false
    $shares = @(@($settings.FilesharingDirectories) + @($env:USERPROFILE, 'C:\Temp', 'F:\study') | Where-Object {
        -not [string]::IsNullOrWhiteSpace([string]$_) -and
        [string]$_ -notmatch '^[A-Za-z]:\\$' -and
        (Test-Path -LiteralPath ([string]$_) -PathType Container)
    } | Select-Object -Unique)
    Set-DockerVmmProperty -Object $settings -Name 'FilesharingDirectories' -Value $shares
    $temporary = Join-Path $parent ('.settings-store.' + [guid]::NewGuid().ToString('N') + '.tmp')
    try {
        [IO.File]::WriteAllText($temporary, ($settings | ConvertTo-Json -Depth 12), [Text.UTF8Encoding]::new($false))
        Move-Item -LiteralPath $temporary -Destination $settingsPath -Force -ErrorAction Stop
    } finally {
        if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue }
    }
    Write-DLine ("Docker VMM settings enforced; explicit shares={0}" -f $shares.Count) 'Green'
}

function Set-ProfileFunctionMutationCurrentDefinition {
    param([Parameter(Mandatory)][string]$Name, [Parameter(Mandatory)][string]$Definition)

    $tokens = $null
    $errors = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseInput(
        $Definition,
        [ref]$tokens,
        [ref]$errors
    )
    if (@($errors).Count -gt 0) {
        throw "Cannot install '$Name' into the current session: $($errors[0].Message)"
    }

    $definitions = @(Get-ProfileFunctionMutationOuterFunctions -Ast $ast)
    if ($definitions.Count -ne 1) {
        throw "Cannot install '$Name' into the current session because its saved definition is ambiguous."
    }

    $bodyText = $definitions[0].Body.Extent.Text.Trim()
    if ($bodyText.Length -lt 2 -or $bodyText[0] -ne '{' -or $bodyText[$bodyText.Length - 1] -ne '}') {
        throw "Cannot install '$Name' into the current session because its body is invalid."
    }

    $liveBody = [scriptblock]::Create($bodyText.Substring(1, $bodyText.Length - 2))
    Set-Item -LiteralPath "Function:global:$Name" -Value $liveBody -Force

    $installed = Get-Command -Name $Name -CommandType Function -ErrorAction SilentlyContinue |
        Select-Object -First 1
    if (-not $installed) {
        throw "Function '$Name' was saved but could not be installed into the current session."
    }
}

function Set-ProfileFunctionMutationDocuments {
    param([Parameter(Mandatory)][object[]]$Changes)
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss-fff'
    $prepared = New-Object System.Collections.Generic.List[object]
    $committed = New-Object System.Collections.Generic.List[object]
    try {
        foreach ($change in $Changes) {
            Test-ProfileFunctionMutationSource -Source $change.UpdatedSource -Label $change.Path
            $temporary = "$($change.Path).funcmutation-$stamp.tmp"
            [System.IO.File]::WriteAllText($temporary, $change.UpdatedSource, $change.Encoding)
            $prepared.Add([pscustomobject]@{
                Path = $change.Path
                OriginalSource = $change.OriginalSource
                Encoding = $change.Encoding
                Temporary = $temporary
                Backup = "$($change.Path).bak-funcmutation-$stamp"
                Verification = $change.Verification
            }) | Out-Null
        }
        foreach ($item in $prepared) {
            Write-ProfileFunctionMutationProgress -Stage 'saving-profile' -Detail $item.Path
            [System.IO.File]::Replace($item.Temporary, $item.Path, $item.Backup, $true)
            $committed.Add($item) | Out-Null
        }
        Assert-ProfileFunctionMutationCommittedChanges -Changes $prepared.ToArray()
    } catch {
        foreach ($item in $committed) {
            Write-ProfileFunctionMutationProgress -Stage 'rolling-back-profile' -Detail $item.Path
            [System.IO.File]::WriteAllText($item.Path, $item.OriginalSource, $item.Encoding)
        }
        throw
    } finally {
        foreach ($item in $prepared) {
            if (Test-Path -LiteralPath $item.Temporary -PathType Leaf) {
                Remove-Item -LiteralPath $item.Temporary -Force -ErrorAction SilentlyContinue
            }
        }
    }
    @($prepared | ForEach-Object { $_.Backup })
}

function Set-RedockerKnownSettings {
        $dockerRoaming = Join-Path $env:APPDATA 'Docker'
        $dotDocker = Join-Path $env:USERPROFILE '.docker'
        New-Item -ItemType Directory -Force -Path $dockerRoaming | Out-Null
        New-Item -ItemType Directory -Force -Path $dotDocker | Out-Null
        $settingsStore = Join-Path $dockerRoaming 'settings-store.json'
        $settingsJson = Join-Path $dockerRoaming 'settings.json'
        $daemonJson = Join-Path $dotDocker 'daemon.json'
        $windowsDaemonJson = Join-Path $dotDocker 'windows-daemon.json'
        $settingsVersion = 45
        $full = $null
        if(Test-Path -LiteralPath $settingsStore){
            try {
                $full = Get-Content -LiteralPath $settingsStore -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                $currentVersion = 0
                try { $currentVersion = [int]$full.SettingsVersion } catch { }
                if($currentVersion -gt $settingsVersion){ $settingsVersion = $currentVersion }
            } catch { }
        }
        if(-not $full){
            $full = [pscustomobject][ordered]@{
                AutoStart = $false
                DisplayedOnboarding = $true
                EnableCLIHints = $true
                EnableDockerAI = $true
                EnableIntegrationWithDefaultWslDistro = $false
                FilesharingDirectories = @($env:USERPROFILE)
                InferenceCanUseGPUVariant = $true
                LicenseTermsVersion = 2
                MemoryMiB = 33792
                OpenUIOnStartupDisabled = $true
                SettingsVersion = $settingsVersion
                SwapMiB = 3072
                ThemeSource = 'dark'
                UseBackgroundIndexing = $false
                UseContainerdSnapshotter = $true
                UseLibkrun = $true
                UseResourceSaver = $false
                UseVirtualizationFramework = $false
                WslEngineEnabled = $false
            }
        }

        function Set-RedockerSetting {
            param([Parameter(Mandatory)]$Settings,[Parameter(Mandatory)][string]$Name,$Value)
            $property = $Settings.PSObject.Properties[$Name]
            if($property){ $property.Value = $Value } else { $Settings | Add-Member -NotePropertyName $Name -NotePropertyValue $Value }
        }
        Set-RedockerSetting -Settings $full -Name 'AutoStart' -Value $false
        Set-RedockerSetting -Settings $full -Name 'EnableIntegrationWithDefaultWslDistro' -Value $false
        Set-RedockerSetting -Settings $full -Name 'MemoryMiB' -Value 33792
        Set-RedockerSetting -Settings $full -Name 'OpenUIOnStartupDisabled' -Value $true
        Set-RedockerSetting -Settings $full -Name 'SettingsVersion' -Value $settingsVersion
        Set-RedockerSetting -Settings $full -Name 'SwapMiB' -Value 3072
        Set-RedockerSetting -Settings $full -Name 'UseBackgroundIndexing' -Value $false
        Set-RedockerSetting -Settings $full -Name 'UseContainerdSnapshotter' -Value $true
        Set-RedockerSetting -Settings $full -Name 'AllowBetaFeatures' -Value $true
        Set-RedockerSetting -Settings $full -Name 'UseLibkrun' -Value $true
        Set-RedockerSetting -Settings $full -Name 'UseResourceSaver' -Value $false
        Set-RedockerSetting -Settings $full -Name 'UseVirtualizationFramework' -Value $false
        Set-RedockerSetting -Settings $full -Name 'WslEngineEnabled' -Value $false
        $safeShares = @($full.FilesharingDirectories | Where-Object {
            -not [string]::IsNullOrWhiteSpace([string]$_) -and
            [string]$_ -notmatch '^[A-Za-z]:\\$' -and
            (Test-Path -LiteralPath ([string]$_) -PathType Container)
        } | Select-Object -Unique)
        if($safeShares.Count -eq 0){
            $safeShares = @(@($env:USERPROFILE,'C:\Temp','F:\study') | Where-Object {
                -not [string]::IsNullOrWhiteSpace([string]$_) -and
                (Test-Path -LiteralPath ([string]$_) -PathType Container)
            } | Select-Object -Unique)
        }
        Set-RedockerSetting -Settings $full -Name 'FilesharingDirectories' -Value $safeShares
        Save-RedockerSafeText -Path $settingsStore -Text ($full | ConvertTo-Json -Depth 5)
        Write-RedockerSafeLine ("applied Docker Desktop settings: Docker VMM, 33792 MiB memory, Resource Saver off, {0} explicit file shares, no startup" -f $safeShares.Count) Green
        if(Test-Path -LiteralPath $settingsJson -PathType Leaf){
            try {
                $desktop = Get-Content -LiteralPath $settingsJson -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                Set-RedockerSetting -Settings $desktop -Name 'UseLibkrun' -Value $true
                Set-RedockerSetting -Settings $desktop -Name 'WslEngineEnabled' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'UseVirtualizationFramework' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'EnableIntegrationWithDefaultWslDistro' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'UseResourceSaver' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'AutoStart' -Value $false
                Save-RedockerSafeText -Path $settingsJson -Text ($desktop | ConvertTo-Json -Depth 5)
            } catch { Write-RedockerSafeLine ("legacy settings.json update skipped: {0}" -f $_.Exception.Message) DarkYellow }
        }
        $daemon = [ordered]@{
            builder = [ordered]@{ gc = [ordered]@{ defaultKeepStorage = '20GB'; enabled = $true } }
            experimental = $false
            'max-concurrent-downloads' = 10
            'max-concurrent-uploads' = 10
            'max-download-attempts' = 5
            features = [ordered]@{ buildkit = $true }
        }
        Save-RedockerSafeText -Path $daemonJson -Text ($daemon | ConvertTo-Json -Depth 5)
        Write-RedockerSafeLine 'applied daemon performance settings' Green
        if(-not (Test-Path -LiteralPath $windowsDaemonJson -PathType Leaf)){
            Save-RedockerSafeText -Path $windowsDaemonJson -Text "{`r`n}"
        }
        foreach($var in @('DOCKER_BUILDKIT','COMPOSE_DOCKER_CLI_BUILD')){
            try { [Environment]::SetEnvironmentVariable($var,'1','Machine') } catch { }
            Set-Item -Path ("Env:{0}" -f $var) -Value '1' -ErrorAction SilentlyContinue
        }
        try { [Environment]::SetEnvironmentVariable('BUILDKIT_PROGRESS','plain','Machine'); $env:BUILDKIT_PROGRESS='plain' } catch { }
    }

