'logFile := A_AppData "\com.fitlauncher.carrotrub\logs\fitgirl-installer-dialog-ahk-watchdog.log"',
'DirCreate DirName(logFile)',
'Log(msg) {',
'    global logFile',
'    FileAppend FormatTime(, "yyyy-MM-ddTHH:mm:ss") " " msg "`n", logFile, "UTF-8"',
'}',
'DirName(path) {',
'    SplitPath path, , &dir',
'    return dir',
'}',
'CleanGameInstallName(name) {',
'    if (name = "")',
'        name := "Game"',
'    name := RegExReplace(name, "\[[^\]]*\]", " ")',
'    name := RegExReplace(name, "\([^)]*\)", " ")',
'    name := RegExReplace(name, "i)\b(fitgirl|repack|deluxe|edition|multiplayer|crack|codex|rune|elamigos|gog)\b", " ")',
'    name := RegExReplace(name, "i)\s+-\s+v[\d\.\-_].*$", "")',
'    name := RegExReplace(name, "i)\s+v[\d\.\-_].*$", "")',
'    name := RegExReplace(name, "[<>:/\\|?*]", " ")',
'    name := StrReplace(name, Chr(34), " ")',
'    name := Trim(RegExReplace(name, "\s+", " "), " .-_")',
'    if (name = "")',
'        name := "Game"',
'    return name',
'}',
'GetSetupInstallDir(hwnd) {',
'    try exe := WinGetProcessPath("ahk_id " hwnd)',
'    catch',
'        exe := ""',
'    game := "Game"',
'    if (exe != "") {',
'        SplitPath exe, , &dir',
'        for path in [dir "\.pathbridge-install-target.txt", dir "\.pathbridge-install-started.txt"] {',
'            if FileExist(path) {',
'                try {',
'                    txt := FileRead(path, "UTF-8")',
'                    if RegExMatch(txt, "i)install_dir=([A-Z]:\\[^``r``n]+?)(?:\s+job=|$)", &m)',
'                        return Trim(m[1], " ``t``r``n")',
'                    if RegExMatch(txt, "i)^([A-Z]:\\[^``r``n]+)$", &m2)',
'                        return Trim(m2[1], " ``t``r``n")',
'                } catch as e {',
'                    Log "READ_INSTALL_TARGET_FAIL path=" path " err=" e.Message',
'                }',
'            }',
'        }',
'        SplitPath dir, &game',
'    }',
'    return "F:\Downloads\" CleanGameInstallName(game)',
'}',
'MoveInstallerToMonitor2(hwnd) {',
'    try {',
'        count := MonitorGetCount()',
'        if (count < 2)',
'            return false',
'        target := 1, bestLeft := -999999',
'        Loop count {',
'            MonitorGet A_Index, &l, &t, &r, &b',
'            if (l > bestLeft) {',
'                bestLeft := l, target := A_Index',
'            }',
'        }',
'        MonitorGet target, &ml, &mt, &mr, &mb',
'        WinGetPos &x, &y, &w, &h, "ahk_id " hwnd',
'        if (w = "" || w < 300)',
'            w := 760',
'        if (h = "" || h < 220)',
'            h := 560',
'        if (x < ml || y < mt || (x + w) > mr || (y + h) > mb) {',
'            nx := ml + 80, ny := mt + 80',
'            WinMove nx, ny, w, h, "ahk_id " hwnd',
'            Log "MOVE_TO_MONITOR2 hwnd=" hwnd " from=" x "," y " size=" w "x" h " to=" nx "," ny " monitor=" target',
'            Sleep 150',
'            return true',
'        }',
'    } catch as e {',
'        Log "MOVE_TO_MONITOR2_FAIL hwnd=" hwnd " err=" e.Message',
'    }',
'    return false',
'}',
'LooksLikeInstallPath(value) {',
'    return RegExMatch(value, "i)^[A-Z]:\\") && !RegExMatch(value, "i)\\(setup|redist|directx|vcredist|_commonredist)(\\|$)")',
'}',
'EnsureInstallDestination(hwnd) {',
'    target := GetSetupInstallDir(hwnd)',
'    changed := false',
'    controls := []',
'    try controls := WinGetControls("ahk_id " hwnd)',
'    catch',
'        return false',
'    for ctrl in controls {',
'        txt := ""',
'        try txt := ControlGetText(ctrl, "ahk_id " hwnd)',
'        catch',
'            txt := ""',
'        if RegExMatch(ctrl, "i)^Edit") && LooksLikeInstallPath(txt) && (txt != target) {',
'            try {',
'                DirCreate target',
'                ControlSetText target, ctrl, "ahk_id " hwnd',
'                Log "SET_INSTALL_DIR hwnd=" hwnd " ctrl=" ctrl " from=" txt " to=" target',
'                changed := true',
'            } catch as e {',
'                Log "SET_INSTALL_DIR_FAIL hwnd=" hwnd " ctrl=" ctrl " target=" target " err=" e.Message',
'            }',
'        }',
'    }',
'    return changed',
'}',
'ButtonText(ctrl, hwnd) {',
'    try return Trim(ControlGetText(ctrl, "ahk_id " hwnd))',
'    catch',
'        return ""',
'}',
'ClickControl(hwnd, ctrl, label, why) {',
'    try {',
'        MoveInstallerToMonitor2(hwnd)',
'        if !WinActive("ahk_id " hwnd)',
'            WinActivate "ahk_id " hwnd',
'        Sleep 80',
'        ControlClick ctrl, "ahk_id " hwnd,,,, "NA"',
'        Log "CLICK hwnd=" hwnd " ctrl=" ctrl " text=" label " why=" why',
'        return true',
'    } catch as e {',
'        Log "CLICK_FAIL hwnd=" hwnd " ctrl=" ctrl " text=" label " err=" e.Message',
'    }',
'    return false',
'}',
'SendEnter(hwnd, why) {',
'    try {',
'        MoveInstallerToMonitor2(hwnd)',
'        WinActivate "ahk_id " hwnd',
'        Sleep 100',
'        Send "{Enter}"',
'        Log "SEND_ENTER hwnd=" hwnd " why=" why',
'        return true',
'    } catch as e {',
'        Log "SEND_ENTER_FAIL hwnd=" hwnd " err=" e.Message',
'    }',
'    return false',
'}',
'GetAllText(hwnd, controls) {',
'    text := ""',
'    try text .= WinGetTitle("ahk_id " hwnd) " | "',
'    for ctrl in controls {',
'        try {',
'            t := ControlGetText(ctrl, "ahk_id " hwnd)',
'            if (t != "")',
'                text .= " | " t',
'        }',
'    }',
'    return text',
'}',
'IsExitSetupDialog(allText) {',
'    return RegExMatch(allText, "i)(Exit Setup\?|Setup is not complete|If you exit now|terminate setup)")',
'}',
'IsNormalInstallerPage(allText) {',
'    return RegExMatch(allText, "i)(Welcome to the|License Agreement|Information|Select Destination Location|Select Start Menu Folder|Select Additional Tasks|Ready to Install|Setup will install)")',
'}',
'IsSafeYesDialog(allText) {',
'    return RegExMatch(allText, "i)(Folder Exists|already exists\. Would you like to install to that folder anyway)")',
'}',
'IsSafeIgnoreDialog(allText) {',
'    return RegExMatch(allText, "i)(vc_redist|vcredist|directx|dxsetup|oalinst|dotnet|redistributable)") && !RegExMatch(allText, "i)(fg-\d+\.bin|\.bin|\.arc|\.pak|\.ucas|\.utoc)")',
'}',
'IsPassiveProgressPage(allText) {',
'    return RegExMatch(allText, "i)(Installing|Extracting files|Downloading additional files|Elapsed time|Remaining time|Current file)")',
'}',
'HandleSafeOptionals(hwnd, controls, allText) {',
'    if IsExitSetupDialog(allText) {',
'        Log "BLOCK_EXIT_SETUP_OPTIONALS hwnd=" hwnd',
'        return false',
'    }',
'    optionalFail := RegExMatch(allText, "i)(Download failed|Cannot connect|certificate is invalid|SSL|TLS|revocation|connection failed|unable to download|timed out|Downloading additional files)")',
'    if optionalFail && IsNormalInstallerPage(allText) {',
'        Log "IGNORE_OPTIONAL_FALSE_POSITIVE hwnd=" hwnd',
'        optionalFail := false',
'    }',
'    for ctrl in controls {',
'        txt := ButtonText(ctrl, hwnd)',
'        if (txt = "")',
'            continue',
'        if RegExMatch(ctrl, "i)Check|List") && (StrLen(txt) < 200) && RegExMatch(txt, "i)(DirectX|Visual C\+\+|Redistributable|additional files|download|bonus|soundtrack|video)") && !RegExMatch(txt, "i)^(Next|Install|Finish|OK|Yes|Retry|Details)") {',
'            try {',
'                ControlSetChecked 0, ctrl, "ahk_id " hwnd',
'                Log "UNCHECK_OPTIONAL hwnd=" hwnd " ctrl=" ctrl " text=" txt',
'            }',
'        }',
'    }',
'    if optionalFail {',
'        for pat in ["i)^Skip$", "i)^No$", "i)^OK$", "i)^Continue$", "i)^Ignore$"] {',
'            for ctrl in controls {',
'                txt := ButtonText(ctrl, hwnd)',
'                if RegExMatch(txt, pat) && !RegExMatch(txt, "i)Abort|Retry|Details|Back") {',
'                    if ClickControl(hwnd, ctrl, txt, "optional-download-failure")',
'                        return true',
'                }',
'            }',
'        }',
'    }',
'    return false',
'}',
'ClickFirstSafeButton(hwnd, why := "") {',
'    MoveInstallerToMonitor2(hwnd)',
'    controls := []',
'    try controls := WinGetControls("ahk_id " hwnd)',
'    catch as e {',
'        Log "CONTROLS_FAIL hwnd=" hwnd " err=" e.Message',
'        return false',
'    }',
'    EnsureInstallDestination(hwnd)',
'    allText := GetAllText(hwnd, controls)',
'    if IsSafeIgnoreDialog(allText) {',
'        for ctrl in controls {',
'            txt := ButtonText(ctrl, hwnd)',
'            if RegExMatch(txt, "i)^&?Ignore$") {',
'                if ClickControl(hwnd, ctrl, txt, "safe-ignore-optional-runtime")',
'                    return true',
'            }',
'        }',
'    }',
'    if IsSafeYesDialog(allText) {',
'        for ctrl in controls {',
'            txt := ButtonText(ctrl, hwnd)',
'            if RegExMatch(txt, "i)^&?Yes$") {',
'                if ClickControl(hwnd, ctrl, txt, "safe-folder-exists-yes")',
'                    return true',
'            }',
'        }',
'    }',
'    if IsPassiveProgressPage(allText)',
'        return false',
'    if IsExitSetupDialog(allText) {',
'        for ctrl in controls {',
'            txt := ButtonText(ctrl, hwnd)',
'            if RegExMatch(txt, "i)^&?No$") {',
'                if ClickControl(hwnd, ctrl, txt, "block-exit-setup")',
'                    return true',
'            }',
'        }',
'        Log "BLOCK_EXIT_SETUP hwnd=" hwnd',
'        return true',
'    }',
'    if HandleSafeOptionals(hwnd, controls, allText)',
'        return true',
'    for ctrl in controls {',
'        txt := ButtonText(ctrl, hwnd)',
'        if RegExMatch(txt, "i)limit.*2\s*GB|2\s*GB.*RAM") {',
'            try {',
'                ControlSetChecked 0, ctrl, "ahk_id " hwnd',
'                Log "UNCHECK_2GB hwnd=" hwnd " ctrl=" ctrl " text=" txt',
'            }',
'        }',
'        if RegExMatch(txt, "i)I accept|accept the agreement") {',
'            try {',
'                ControlSetChecked 1, ctrl, "ahk_id " hwnd',
'                Log "ACCEPT_LICENSE hwnd=" hwnd " ctrl=" ctrl " text=" txt',
'            }',
'        }',
'        if RegExMatch(ctrl, "i)Check|List") && (StrLen(txt) < 200) && RegExMatch(txt, "i)(DirectX|Visual C\+\+|Redistributable|additional files|download|bonus|soundtrack|video)") && !RegExMatch(txt, "i)^(Next|Install|Finish|OK|Yes)") {',
'            try {',
'                ControlSetChecked 0, ctrl, "ahk_id " hwnd',
'                Log "UNCHECK_OPTIONAL hwnd=" hwnd " ctrl=" ctrl " text=" txt',
'            }',
'        }',
'    }',
'    for pat in ["i)^&?OK$", "i)^I accept.*$", "i)^&?Next\s*>?$", "i)^&?Install$", "i)^&?Finish$", "i)^&?Close$"] {',
'        for ctrl in controls {',
'            txt := ButtonText(ctrl, hwnd)',
'            if RegExMatch(txt, pat) && !RegExMatch(txt, "i)Cancel|Abort|Decline|Back|Browse|Retry|Details") {',
'                if ClickControl(hwnd, ctrl, txt, why)',
'                    return true',
'            }',
'        }',
'    }',
'    title := ""',
'    try title := WinGetTitle("ahk_id " hwnd)',
'    if RegExMatch(title, "i)Select Setup Language")',
'        return SendEnter(hwnd, "language-default")',
'    return false',
'}',
'Sweep() {',
'    clicked := 0',
'    for titlePat in ["Select Setup Language", "Setup", "Folder Exists", "Error", "ISDone", "Unarc", "FitGirl", "Download failed", "Cannot connect"] {',
'        hwnds := []',
'        try hwnds := WinGetList(titlePat)',
'        catch',
'            hwnds := []',
'        for hwnd in hwnds {',
'            title := "", proc := ""',
'            try title := WinGetTitle("ahk_id " hwnd)',
'            try proc := WinGetProcessName("ahk_id " hwnd)',
'            if (title = "")',
'                continue',
'            if !(RegExMatch(title, "i)Select Setup Language|Setup|Folder Exists|Error|FitGirl|Installer|Unarc|ISDone|Download failed|Cannot connect") || RegExMatch(proc, "i)^setup|isdone|unarc"))',
'                continue',
'            if ClickFirstSafeButton(hwnd, "title=" title " proc=" proc)',
'                clicked += 1',
'        }',
'    }',
'    return clicked',
'}',
'Log "START robust-ahk pid=" DllCall("GetCurrentProcessId")',
'Loop {',
'    try Sweep()',
'    catch as e',
'        Log "SWEEP_ERROR " e.Message',
'    Sleep 250',
'}'
    )
    Set-Content -LiteralPath $ahkScript -Encoding UTF8 -Force -Value ($ahkLines -join "`r`n")
    if (Test-Path -LiteralPath $ahkExe -PathType Leaf) {
        & $ahkExe /ErrorStdOut $ahkScript --selftest | Out-Null
        if ($LASTEXITCODE -ne 0) { throw "AHK watchdog selftest failed exit=$LASTEXITCODE" }
        Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
            Where-Object { $_.ProcessId -ne $PID -and (''+$_.CommandLine) -match 'FitGirlInstallerDialogAhkWatchdog\.ahk' } |
            ForEach-Object { try { Stop-Process -Id ([int]$_.ProcessId) -Force -ErrorAction SilentlyContinue } catch {} }
        try {
            if (Get-Command New-ScheduledTaskAction -ErrorAction SilentlyContinue) {
                $action = New-ScheduledTaskAction -Execute $ahkExe -Argument ('"' + $ahkScript + '"')
                $trigger = New-ScheduledTaskTrigger -AtLogOn
                $principal = New-ScheduledTaskPrincipal -UserId ([System.Security.Principal.WindowsIdentity]::GetCurrent().Name) -LogonType Interactive -RunLevel Limited
                $settings = New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1)
                Register-ScheduledTask -TaskName 'FitGirl Installer Dialog Watchdog' -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Force | Out-Null
                Enable-ScheduledTask -TaskName 'FitGirl Installer Dialog Watchdog' | Out-Null
                Start-ScheduledTask -TaskName 'FitGirl Installer Dialog Watchdog'
            } else {
                $cmd = '"' + $ahkExe + '" "' + $ahkScript + '"'
                & (Join-Path $env:SystemRoot 'System32\schtasks.exe') /Create /TN 'FitGirl Installer Dialog Watchdog' /SC ONLOGON /TR $cmd /F | Out-Null
                & (Join-Path $env:SystemRoot 'System32\schtasks.exe') /Change /TN 'FitGirl Installer Dialog Watchdog' /ENABLE | Out-Null
                & (Join-Path $env:SystemRoot 'System32\schtasks.exe') /Run /TN 'FitGirl Installer Dialog Watchdog' | Out-Null
            }
        } catch { Write-Host ("[afitgirl] AHK scheduled task warning: {0}" -f $_.Exception.Message) }
        Start-Sleep -Seconds 2
        $running = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { (''+$_.CommandLine) -match 'FitGirlInstallerDialogAhkWatchdog\.ahk' })
        if ($running.Count -lt 1) {
            Start-Process -FilePath $ahkExe -ArgumentList ('"' + $ahkScript + '"') -WindowStyle Hidden | Out-Null
            Start-Sleep -Seconds 1
            $running = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { (''+$_.CommandLine) -match 'FitGirlInstallerDialogAhkWatchdog\.ahk' })
        }
        if ($running.Count -lt 1) { throw 'interactive AHK installer watchdog did not start' }
    } else {
        Write-Host "[afitgirl] AutoHotkey v2 missing at $ahkExe; hidden PS fallback will still run"
    }
    Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue |
        Where-Object { $_.ProcessId -ne $PID -and (('' + $_.CommandLine) -match 'AfitgirlInstallerAutoClickerV[0-9]|afitgirl-installer-autoclicker') } |
        ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch {} }
    $code = @'
$ErrorActionPreference = 'Continue'
$logDir = 'F:\Downloads\.fitgirl_tmp'
if (-not (Test-Path -LiteralPath $logDir -PathType Container)) { New-Item -ItemType Directory -Force -Path $logDir | Out-Null }
$log = Join-Path $logDir 'afitgirl-installer-autoclicker.log'
function Log($m){ try { Add-Content -LiteralPath $log -Encoding UTF8 -Value ((Get-Date -Format 'yyyy-MM-ddTHH:mm:ss.fffK') + ' ' + $m) } catch {} }
$mutex = New-Object System.Threading.Mutex($false, 'Global\AfitgirlInstallerAutoClickerV5')
if (-not $mutex.WaitOne(0)) { return }
try {
Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction SilentlyContinue
Add-Type -AssemblyName UIAutomationClient -ErrorAction SilentlyContinue
Add-Type -AssemblyName UIAutomationTypes -ErrorAction SilentlyContinue
function Get-Text($root){$names=@();try{$nodes=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);foreach($n in @($nodes)){try{$nm=(''+$n.Current.Name).Trim();if($nm){$names+=$nm}}catch{}}}catch{};($names -join ' | ')}
function Click($b,$why){try{$p=$b.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern);$p.Invoke();Log ('click '+$why);$true}catch{Log ('click failed '+$why+' '+$_.Exception.Message);$false}}
function ToggleOff($e,$why){try{$p=$e.GetCurrentPattern([System.Windows.Automation.TogglePattern]::Pattern);if($p.Current.ToggleState -eq [System.Windows.Automation.ToggleState]::On){$p.Toggle();Log ('toggle-off '+$why);$true}}catch{};$false}
function HandleInstaller($p){try{if($p.MainWindowHandle -eq 0){return};$title=''+$p.MainWindowTitle;if($title -notmatch '(?i)setup|select setup language|install|download failed|cannot connect|exit setup'){return};$root=[System.Windows.Automation.AutomationElement]::FromHandle([IntPtr]$p.MainWindowHandle);if(!$root){return};$all=$title+' | '+(Get-Text $root);$nodes=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);if($all -match '(?i)(Exit Setup\?|Setup is not complete|If you exit now|terminate setup)'){foreach($n in @($nodes)){$nm='';try{$nm=(''+$n.Current.Name).Trim()}catch{};if($nm -match '(?i)^&?No$'){try{[Microsoft.VisualBasic.Interaction]::AppActivate($p.Id)|Out-Null;Start-Sleep -Milliseconds 80}catch{};Click $n ('block-exit-setup '+$nm+' title='+$title)|Out-Null;return}};Log ('blocked exit setup title='+$title);return};$normal=($all -match '(?i)(Welcome to the|License Agreement|Information|Select Destination Location|Select Start Menu Folder|Select Additional Tasks|Ready to Install|Setup will install)');if(!$normal -and $all -match '(?i)(Downloading additional files|Download failed|Cannot connect|certificate is invalid|SSL|TLS|revocation|connection failed|unable to download|timed out)'){foreach($want in @('^Skip$','^No$','^OK$','^Continue$','^Ignore$')){foreach($n in @($nodes)){$nm='';try{$nm=(''+$n.Current.Name).Trim()}catch{};if($nm -match ('(?i)'+$want) -and $nm -notmatch '(?i)Abort|Retry|Details|Back|Cancel'){try{[Microsoft.VisualBasic.Interaction]::AppActivate($p.Id)|Out-Null;Start-Sleep -Milliseconds 80}catch{};if(Click $n ('optional-failure '+$nm+' title='+$title)){return}}}}};foreach($n in @($nodes)){$nm='';try{$nm=(''+$n.Current.Name).Trim()}catch{};if($nm.Length -lt 200 -and $nm -match '(?i)(DirectX|Visual C\+\+|Redistributable|additional files|download|bonus|soundtrack|video)' -and $nm -notmatch '(?i)^Next|Install|Finish|OK|Yes|Retry|Details$'){ToggleOff $n ($nm+' title='+$title)|Out-Null}};foreach($want in @('^OK$','^Next\s*>?$','^Install$','^Finish$','^Close$')){foreach($n in @($nodes)){$nm='';try{$nm=(''+$n.Current.Name).Trim()}catch{};if($nm -match ('(?i)'+$want) -and $nm -notmatch '(?i)Cancel|Abort|Decline|Back|Browse|Retry|Details'){try{[Microsoft.VisualBasic.Interaction]::AppActivate($p.Id)|Out-Null;Start-Sleep -Milliseconds 80}catch{};if(Click $n ($nm+' title='+$title)){return}}}};if($title -match '(?i)select setup language'){try{[Microsoft.VisualBasic.Interaction]::AppActivate($p.Id)|Out-Null;Start-Sleep -Milliseconds 120;[System.Windows.Forms.SendKeys]::SendWait('{ENTER}');Log ('sendkeys language-enter title='+$title+' pid='+$p.Id)}catch{}}}catch{Log ('installer handler failed '+$_.Exception.Message)}}
function GuardQuickSfv{try{$now=Get-Date;foreach($p in @(Get-CimInstance Win32_Process -Filter "Name='QuickSFV.EXE'" -ErrorAction SilentlyContinue)){$age=0;try{$age=($now-([Management.ManagementDateTimeConverter]::ToDateTime($p.CreationDate))).TotalSeconds}catch{};if($age -ge 45){try{Stop-Process -Id ([int]$p.ProcessId) -Force -ErrorAction SilentlyContinue;Log ('killed optional QuickSFV checker pid='+$p.ProcessId+' age='+[int]$age)}catch{}}}}catch{Log ('QuickSFV guard failed '+$_.Exception.Message)}}
Log 'V5 started: robust dialog clicker, optional-online-failure skip, destination guard, QuickSFV skip'
 $endsAt = (Get-Date).AddMinutes($LifetimeMinutes)
while((Get-Date) -lt $endsAt){try{GuardQuickSfv;foreach($p in @(Get-Process -ErrorAction SilentlyContinue|Where-Object{$_.ProcessName -match '^(setup|setup\.tmp)$' -and $_.MainWindowHandle -ne 0})){HandleInstaller $p}}catch{Log ('loop warning '+$_.Exception.Message)};Start-Sleep -Milliseconds 500}
} finally { try { $mutex.ReleaseMutex() } catch {}; try { $mutex.Dispose() } catch {} }
'@
    $code = $code.Replace('$LifetimeMinutes', [string]$LifetimeMinutes)
    $childPath = Join-Path $scriptDir 'AfitgirlInstallerAutoClickerV5.ps1'
    [IO.File]::WriteAllText($childPath, $code, [Text.Encoding]::UTF8)
    $process = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',$childPath) -WindowStyle Hidden -PassThru -ErrorAction Stop
    Write-Host ("AFITGIRL_AUTOCLICKER_OK pid={0} script={1} lifetime_minutes={2}; AHK task/script refreshed" -f $process.Id, $childPath, $LifetimeMinutes) -ForegroundColor Green
    return [pscustomobject]@{ ProcessId = $process.Id; ScriptPath = $childPath; LifetimeMinutes = $LifetimeMinutes }
}

function Start-AfitgirlMinuteMonitor {
    [CmdletBinding()]
    param(
        [ValidateRange(0, 100000)][int] $MinimumActive = 16,
        [ValidateRange(0, 100000)][int] $MinimumTotalSpeedMBps = 40
    )

    $ps5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $profilePath = 'C:\Users\micha\Documents\WindowsPowerShell\Microsoft.PowerShell_profile.ps1'
    $logDir = 'F:\Downloads\.fitgirl_tmp'
    if (-not (Test-Path -LiteralPath $logDir -PathType Container)) { New-Item -ItemType Directory -Force -Path $logDir | Out-Null }
    $logPath = Join-Path $logDir 'afitgirl-minute-speed-monitor.log'
    if (-not (Test-Path -LiteralPath $ps5 -PathType Leaf)) { throw "Windows PowerShell 5 missing: $ps5" }
    Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
        Where-Object {
            $_.Name -match 'powershell' -and $_.ProcessId -ne $PID -and
            ('' + $_.CommandLine) -match 'AfitgirlMinuteSpeedMonitorV4|afitgirl-minute-speed-monitor'
        } |
        ForEach-Object {
            try {
                Write-Host ("AFIT_MINUTE_MONITOR_PROGRESS stage=stopping-prior-monitor pid={0}" -f $_.ProcessId) -ForegroundColor Cyan
                Stop-Process -Id $_.ProcessId -Force -ErrorAction Stop
            } catch {
                Write-Warning ("AFIT_MINUTE_MONITOR_WARN prior_pid={0} error={1}" -f $_.ProcessId, $_.Exception.Message)
            }
        }

    $code = @"
`$ErrorActionPreference = 'Continue'
`$marker = 'afitgirl-minute-speed-monitor'
`$mutex = New-Object System.Threading.Mutex(`$false, 'Global\AfitgirlMinuteSpeedMonitorV4')
if (-not `$mutex.WaitOne(0)) { return }
try {
    . '$profilePath'
    Add-Content -LiteralPath '$logPath' -Value ((Get-Date -Format s) + ' monitor v4 started; target-active=$MinimumActive target-speed-mbps=$MinimumTotalSpeedMBps') -Encoding UTF8
    `$lastBridge = [datetime]::MinValue
    `$lastLog = [datetime]::MinValue
    while (`$true) {
        try {
            `$now = Get-Date
            `$s = Invoke-AfitgirlDownloadPolicy -MinimumActive $MinimumActive -MinimumTotalSpeedMBps $MinimumTotalSpeedMBps -Quiet
            `$perTitle = @()
            try {
                foreach(`$item in @((Invoke-AfitgirlAria2Rpc -Method 'aria2.tellActive' -Params @() -TimeoutSec 8).result)){
                    `$name = ''
                    try { if(`$item.bittorrent -and `$item.bittorrent.info -and `$item.bittorrent.info.name){ `$name = '' + `$item.bittorrent.info.name } } catch {}
                    if([string]::IsNullOrWhiteSpace(`$name)){
                        try { foreach(`$f in @(`$item.files)){ if(`$f.path){ `$name = Split-Path -Leaf (Split-Path -Parent ('' + `$f.path)); break } } } catch {}
                    }
                    if([string]::IsNullOrWhiteSpace(`$name)){ `$name = '' + `$item.gid }
                    `$spd = 0L; try { `$spd = [int64]`$item.downloadSpeed } catch {}
                    `$done = 0L; `$total = 0L; try { `$done = [int64]`$item.completedLength; `$total = [int64]`$item.totalLength } catch {}
                    `$pct = if(`$total -gt 0){ [math]::Round((100.0 * `$done / `$total), 2) } else { 0 }
                    `$perTitle += (('{0}={1}MB/s {2}%' -f `$name,[math]::Round((`$spd/1MB),2),`$pct))
                }
            } catch { `$perTitle += ('per-title-speed-warning=' + `$_.Exception.Message) }
            try { Invoke-AfitgirlVisibleDownloadsRepair -Reason 'live monitor refresh' | Out-Null } catch { Add-Content -LiteralPath '$logPath' -Value ((Get-Date -Format s) + ' visible refresh warning: ' + `$_.Exception.Message) -Encoding UTF8 }
            if (((`$now - `$lastLog).TotalSeconds -ge 10)) {
                Add-Content -LiteralPath '$logPath' -Value ((Get-Date -Format s) + (' active={0} waiting={1} stopped={2} total_speed={3}MB/s target={4}MB/s status={5}; titles: {6}' -f `$s.Active,`$s.Waiting,`$s.Stopped,`$s.SpeedMBps,`$s.TargetMBps,`$s.Status,(`$perTitle -join ' | '))) -Encoding UTF8
                `$lastLog = `$now
            }
        } catch {
            Add-Content -LiteralPath '$logPath' -Value ((Get-Date -Format s) + ' monitor warning: ' + `$_.Exception.Message) -Encoding UTF8
        }
        Start-Sleep -Seconds 10
    }
} finally {
    try { `$mutex.ReleaseMutex() } catch {}
    try { `$mutex.Dispose() } catch {}
}
"@
    $childPath = Join-Path $logDir 'AfitgirlMinuteSpeedMonitorV4.ps1'
    [IO.File]::WriteAllText($childPath, $code, [Text.Encoding]::UTF8)
    $process = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',$childPath) -WindowStyle Hidden -PassThru -ErrorAction Stop
    Write-Host ("AFIT_MINUTE_MONITOR_OK pid={0} log={1} script={2}" -f $process.Id, $logPath, $childPath) -ForegroundColor Green
    return [pscustomobject]@{ ProcessId = $process.Id; LogPath = $logPath; ScriptPath = $childPath }
}

function Start-AndVerifyApp {
    param([string[]]$PreviouslyRunningServices)
    foreach ($serviceName in $PreviouslyRunningServices) {
        Start-Service -Name $serviceName -ErrorAction SilentlyContinue
    }

    switch ([string]$app.Kind) {
        'Exe' {
            $exe = Join-Path $targetPath ([string]$app.Path)
            if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) { throw "Launcher not found: $exe" }
            Start-Process -FilePath $exe -WorkingDirectory (Split-Path -Parent $exe) | Out-Null
            $process = Wait-ExactProcess -ExecutablePath $exe -Name ([string]$app.Process) -Seconds 45
            return "process=$($process.ProcessId)"
        }
        'PowerShell' {
            $script = Join-Path $targetPath ([string]$app.Path)
            $arguments = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $script) + @($app.Arguments)
            & "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" @arguments
            if ($LASTEXITCODE -ne 0) { throw "Launcher script failed: $script" }
            return 'script=ready'
        }
        'PowerShellDetached' {
            $script = Join-Path $targetPath ([string]$app.Path)
            if (-not (Test-Path -LiteralPath $script -PathType Leaf)) { throw "Launcher script not found: $script" }
            $before = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Path -and $_.Path.StartsWith($targetPath + '\', [StringComparison]::OrdinalIgnoreCase) } | Select-Object -ExpandProperty Id)
            $launcher = Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $script) -WorkingDirectory (Split-Path -Parent $script) -PassThru
            Start-Sleep -Seconds 4
            $owned = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Path -and $_.Path.StartsWith($targetPath + '\', [StringComparison]::OrdinalIgnoreCase) -and $before -notcontains $_.Id })
            if ($owned.Count) { return "process=$($owned[0].Id)" }
            $launcher.Refresh()
            if (-not $launcher.HasExited) { return "launcher=$($launcher.Id)" }
            if ($launcher.ExitCode -ne 0) { throw "Launcher script failed with exit $($launcher.ExitCode): $script" }
            return 'script=completed'
        }
        'HttpScript' {
            $script = Join-Path $targetPath ([string]$app.Path)
            & "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -NoProfile -ExecutionPolicy Bypass -File $script
            if ($LASTEXITCODE -ne 0) { throw "Launcher script failed: $script" }
            Wait-HttpReady -Uri ([string]$app.Uri)
            return "http=$($app.Uri)"
        }
        'Command' {
            $command = Join-Path $targetPath ([string]$app.Path)
            $output = @(& $command @($app.Arguments) 2>&1)
            if ($LASTEXITCODE -ne 0) { throw "Command validation failed: $command $($output -join ' ')" }
            return 'command=ready'
        }
        'Content' {
            $content = Join-Path $targetPath ([string]$app.Path)
            if (-not (Test-Path -LiteralPath $content -PathType Leaf)) { throw "Content validation failed: $content" }
            return 'content=ready'
        }
        'PluginSync' {
            $enginePath = Join-Path $env:LOCALAPPDATA 'qBittorrent\nova3\engines'
            New-Item -ItemType Directory -Path $enginePath -Force | Out-Null
            Get-ChildItem -LiteralPath $targetPath -File -Filter '*.py' -Force | ForEach-Object {
                Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $enginePath $_.Name) -Force
                if ((Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash -ne
                    (Get-FileHash -LiteralPath (Join-Path $enginePath $_.Name) -Algorithm SHA256).Hash) {
                    throw "qBittorrent plugin copy verification failed: $($_.Name)"
                }
            }
            return 'plugins=synchronized'
        }
        'Everything' {
            $exe = Join-Path $targetPath 'Everything.exe'
            $service = Get-Service -Name 'Everything' -ErrorAction SilentlyContinue
            if (-not $service) {
                & $exe -install-service | Out-Null
            }
            Start-Service -Name 'Everything' -ErrorAction Stop
            Start-Process -FilePath $exe | Out-Null
            $process = Wait-ExactProcess -ExecutablePath $exe -Name 'everything.exe'
            return "service=Running process=$($process.ProcessId)"
        }
        'ProcessLasso' {
            $gui = Join-Path $targetPath 'ProcessLasso.exe'
            $governor = Join-Path $targetPath 'ProcessGovernor.exe'
            $stub = Join-Path $targetPath 'srvstub.exe'
            if (-not (Get-Service -Name 'ProcessGovernor' -ErrorAction SilentlyContinue)) {
                New-Service -Name 'ProcessGovernor' -DisplayName 'Process Lasso Core (Process Governor)' `
                    -BinaryPathName ('"{0}" "{1}" "ProcessGovernor" /exitevent:Global\ProcessGovernorExitEvent' -f $stub, $governor) `
                    -StartupType Automatic | Out-Null
            }
            Start-Service -Name 'ProcessGovernor' -ErrorAction Stop
            Start-Process -FilePath $gui | Out-Null
            $process = Wait-ExactProcess -ExecutablePath $gui -Name 'ProcessLasso.exe'
            return "service=Running process=$($process.ProcessId)"
        }
        'Tailscale' {
            $daemon = Join-Path $targetPath 'tailscaled.exe'
            $cli = Join-Path $targetPath 'tailscale.exe'
            $gui = Join-Path $targetPath 'tailscale-ipn.exe'
            $service = Get-Service -Name 'Tailscale' -ErrorAction SilentlyContinue
            if (-not $service) {
                New-Service -Name 'Tailscale' -DisplayName 'Tailscale' -BinaryPathName ('"{0}"' -f $daemon) -StartupType Automatic | Out-Null
            } else {
                & "$env:SystemRoot\System32\sc.exe" config Tailscale 'binPath=' ('"{0}"' -f $daemon) 'start=' auto | Out-Null
                if ($LASTEXITCODE -ne 0) { throw 'Could not repair the Tailscale service.' }
            }
            Start-Service -Name 'Tailscale' -ErrorAction Stop
            Start-Process -FilePath $gui | Out-Null
            Start-Sleep -Seconds 3
            $status = @(& $cli status 2>&1)
            if ($LASTEXITCODE -ne 0 -and ($status -join ' ') -notmatch 'Logged out|NeedsLogin') {
                throw "Tailscale CLI readiness failed: $($status -join ' ')"
            }
            $process = Wait-ExactProcess -ExecutablePath $gui -Name 'tailscale-ipn.exe'
            return "service=Running process=$($process.ProcessId)"
        }
        'Cloudflare' {
            $serviceExe = Join-Path $targetPath 'warp-svc.exe'
            $cli = Join-Path $targetPath 'warp-cli.exe'
            $gui = Join-Path $targetPath 'Cloudflare WARP.exe'
            & "$env:SystemRoot\System32\sc.exe" config CloudflareWARP 'binPath=' ('"{0}"' -f $serviceExe) | Out-Null
            if ($LASTEXITCODE -ne 0) { throw 'Could not repair CloudflareWARP service path.' }
            Start-Service -Name 'CloudflareWARP' -ErrorAction Stop
            $status = @(& $cli --no-ansi --json status 2>&1)
            if ($LASTEXITCODE -ne 0) { throw "Cloudflare CLI readiness failed: $($status -join ' ')" }
            Start-Process -FilePath $gui | Out-Null
            $process = Wait-ExactProcess -ExecutablePath $gui -Name 'Cloudflare WARP.exe'
            return "service=Running process=$($process.ProcessId)"
        }
        'CodexMonitor' {
            $launcher = Join-Path $targetPath 'Open-CodexMonitor.cmd'
            Start-Process -FilePath $launcher | Out-Null
            $daemon = Join-Path $targetPath 'app-live-codex-wall\codex_monitor_daemon.exe'
            $gui = Join-Path $targetPath 'app-live-codex-wall\codex-monitor.exe'
            $daemonProcess = Wait-ExactProcess -ExecutablePath $daemon -Name 'codex_monitor_daemon.exe' -Seconds 60
            $guiProcess = Wait-ExactProcess -ExecutablePath $gui -Name 'codex-monitor.exe' -Seconds 60
            return "daemon=$($daemonProcess.ProcessId) process=$($guiProcess.ProcessId)"
        }
        default {
            throw "Unsupported launch kind for $Folder`: $($app.Kind)"
        }
    }
}

