function Start-DKillFastHiddenProcess {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$FilePath,[string[]]$ArgumentList)
    if([string]::IsNullOrWhiteSpace($FilePath) -or -not (Test-Path -LiteralPath $FilePath)) { Write-DKillFastLine ("DKILL_LAUNCH_FAIL executable not found: {0}" -f $FilePath) Red; return $false }
    try {
        $psi=New-Object Diagnostics.ProcessStartInfo; $psi.FileName=$FilePath; $psi.UseShellExecute=$false; $psi.CreateNoWindow=$true; $psi.WindowStyle=[Diagnostics.ProcessWindowStyle]::Hidden; $psi.Arguments=((@($ArgumentList)|ForEach-Object{'"'+([string]$_).Replace('"','\"')+'"'})-join ' ')
        $process=[Diagnostics.Process]::Start($psi); if(-not $process){throw 'process start returned null'}; Write-DKillFastLine ("DKILL_LAUNCH_OK pid={0} executable={1}" -f $process.Id,$FilePath) DarkCyan; $process.Dispose(); return $true
    } catch {
        Write-DKillFastLine ("DKILL_LAUNCH_FAIL executable={0}: {1}" -f $FilePath,$_.Exception.Message) Red
        return $false
    }
}

function Start-DockerVmmWithTray {
    $backendExe = Join-Path ${env:ProgramFiles} 'Docker\Docker\resources\com.docker.backend.exe'
    $desktopExe = Join-Path ${env:ProgramFiles} 'Docker\Docker\Docker Desktop.exe'
    if (-not (Test-Path -LiteralPath $backendExe -PathType Leaf) -or -not (Test-Path -LiteralPath $desktopExe -PathType Leaf)) {
        Write-DLine 'ERROR Docker VMM backend or Docker Desktop tray executable was not found' 'Red'
        return $false
    }
    try {
        # Docker Desktop must own startup. A backend created with
        # -with-frontend=false rejects a later tray attachment and makes the
        # Desktop process exit even though the daemon remains healthy.
        Start-Process -FilePath $desktopExe | Out-Null
        Write-DLine 'Docker VMM and system-tray frontend launched unattended' 'Cyan'
        return $true
    } catch {
        Write-DLine ("ERROR Docker VMM/tray launch failed: {0}" -f $_.Exception.Message) 'Red'
        return $false
    }
}

