function Start-PrivateService {
    param([string]$ServiceName = 'com.docker.service')
    $sc = Join-Path $env:SystemRoot 'System32\sc.exe'
    if (-not (Test-Path -LiteralPath $sc)) { return $false }
    $query = Invoke-Bounded -FilePath $sc -ArgumentList @('query', $ServiceName) -Milliseconds 5000
    if ($query.ExitCode -eq 0 -and $query.Stdout -match '(?im)^\s*STATE\s*:\s*4\s+RUNNING') { return $true }
    $null = Invoke-Bounded -FilePath $sc -ArgumentList @('start', $ServiceName) -Milliseconds 10000
    for ($attempt = 1; $attempt -le 8; $attempt++) {
        Start-Sleep -Milliseconds 750
        $query2 = Invoke-Bounded -FilePath $sc -ArgumentList @('query', $ServiceName) -Milliseconds 5000
        if ($query2.ExitCode -eq 0 -and $query2.Stdout -match '(?im)^\s*STATE\s*:\s*4\s+RUNNING') {
            Write-DLine ("privileged helper service running: {0}" -f $ServiceName) 'Green'
            return $true
        }
    }
    Write-DLine ("WARN privileged helper service did not start: {0}" -f $ServiceName) 'Yellow'
    return $false
}

function Start-Proxy {
    if (-not (Test-Path -LiteralPath $proxyScript -PathType Leaf)) {
        Write-Host "OC_PROGRESS stage=watchdog-proxy-missing path=$proxyScript"
        return $false
    }

    # Find node.exe
    $nodeExe = $null
    $nodeCandidates = @(
        (Join-Path ${env:ProgramFiles} 'nodejs\node.exe'),
        (Join-Path ${env:ProgramFiles(x86)} 'nodejs\node.exe')
    )
    foreach ($nodePath in $nodeCandidates) {
        if ($nodePath -and (Test-Path -LiteralPath $nodePath -PathType Leaf)) {
            $nodeExe = $nodePath
            break
        }
    }
    if (-not $nodeExe) {
        foreach ($c in (Get-Command node.exe -CommandType Application -ErrorAction SilentlyContinue)) {
            if ($c.Source -notmatch 'WindowsApps') { $nodeExe = $c.Source; break }
        }
    }
    if (-not $nodeExe) { $nodeExe = 'node' }

    Write-Host "OC_PROGRESS stage=watchdog-starting-proxy"
    Start-Process -FilePath $nodeExe -ArgumentList "`"$proxyScript`" --port $proxyPort --keys `"$proxyKeysFile`"" `
        -WindowStyle Hidden -ErrorAction Stop | Out-Null

    # Wait for it to come up (max 8s)
    $deadline = (Get-Date).AddSeconds(8)
    while ((Get-Date) -lt $deadline) {
        Start-Sleep -Milliseconds 500
        $h = Get-ProxyHealth
        if ($h) {
            Write-Host "OC_PROGRESS stage=watchdog-proxy-started keys=$($h.keys) running=$($h.running)"
            return $true
        }
    }
    Write-Host "OC_PROGRESS stage=watchdog-proxy-timeout"
    return $false
}

function Start-WSLDistro {
    param([string]$DistroName)
    Write-Host "Starting WSL distribution '$DistroName'..." -ForegroundColor Yellow
    try {
        $null = & "$env:SystemRoot\System32\wsl.exe" -d $DistroName -u root bash -c "echo 'WSL started' > /dev/null" 2>$null
        Start-Sleep -Milliseconds 500
        if (Test-WSLDistroRunning -DistroName $DistroName) {
            Write-Host "WSL distribution '$DistroName' is now running." -ForegroundColor Green
        } else {
            Write-Warning "WSL distribution '$DistroName' may not have started properly."
        }
    } catch {
        Write-Error "Failed to start WSL distribution '$DistroName': $_"
    }
}

