function Stop-GititProcess {
    param($State)

    if ($null -eq $State -or $null -eq $State.Process) { return }
    Write-GititLogDelta -State $State -FlushAll
    try {
        if (-not $State.Process.HasExited) {
            cmd /c "taskkill /F /T /PID $($State.Process.Id) >nul 2>&1" | Out-Null
            Start-Sleep -Milliseconds 300
        }
    } catch {}
    foreach ($path in @($State.StdoutPath, $State.StderrPath)) {
        try { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue } catch {}
    }
    try { Remove-Item -LiteralPath $State.LogRoot -Force -Recurse -ErrorAction SilentlyContinue } catch {}
}

