        $procs=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -ieq 'docker-agent.exe' -or ($_.Name -ieq 'Docker Desktop.exe' -and $_.CommandLine -match 'error-dialog') })
        if($OnlyIfErrorDialog -and -not @($procs | Where-Object { $_.Name -ieq 'Docker Desktop.exe' -and $_.CommandLine -match 'error-dialog' }).Count){ return }
        foreach($proc in $procs){
            try { Write-RedockerStep ("stopping lingering startup blocker pid={0} name={1}" -f $proc.ProcessId,$proc.Name); Stop-Process -Id $proc.ProcessId -Force -ErrorAction SilentlyContinue } catch {}
