    }

function Stop-RedockerSafeDocker {
        $processNames = @('Docker Desktop','Docker Desktop Installer','com.docker.backend','com.docker.build','com.docker.dev-envs','com.docker.extensions','com.docker.proxy','com.docker.sailor','com.docker.vpnkit','docker-agent','docker-sandbox','dockerd','docker','vpnkit','com.docker.service')
        foreach($name in $processNames){
            try { Get-Process -Name $name -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch { }
        }
        try { Stop-Service -Name 'com.docker.service' -Force -ErrorAction SilentlyContinue } catch { }
        $wslExe = Join-Path $env:SystemRoot 'System32\wsl.exe'
        if(Test-Path -LiteralPath $wslExe){
            foreach($distro in @('docker-desktop','docker-desktop-data')){
                try { & $wslExe --terminate $distro *> $null } catch { }
            }
        }
        try {
            if(Get-Command Get-VM -ErrorAction SilentlyContinue){
                $vm = Get-VM -Name 'DockerDesktopVM' -ErrorAction SilentlyContinue
                if($vm -and $vm.State -ne 'Off'){ Stop-VM -Name 'DockerDesktopVM' -TurnOff -Force -ErrorAction SilentlyContinue }
            }
        } catch { }
        $deadline = (Get-Date).AddSeconds(20)
        do {
            $alive = @($processNames | ForEach-Object { Get-Process -Name $_ -ErrorAction SilentlyContinue } | Select-Object -First 1)
            if(-not $alive){ break }
            Start-Sleep -Milliseconds 400
        } while((Get-Date) -lt $deadline)
    }

function Stop-RminsTargetProcesses {
    param(
        [Parameter(Mandatory)]
        [string]$TargetPath
    )

    $prefix = (Test-RminsTarget -Path $TargetPath).TrimEnd('\') + '\'
    $protected = Get-RminsCurrentProcessIds
    $matched = @(
        Get-CimInstance Win32_Process -ErrorAction Stop |
            Where-Object {
                $executable = '' + $_.ExecutablePath
                $commandLine = '' + $_.CommandLine
                -not $protected.Contains([int]$_.ProcessId) -and
                ($executable.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase) -or
                    $commandLine.IndexOf($prefix, [StringComparison]::OrdinalIgnoreCase) -ge 0)
            }
    )

    foreach ($process in $matched) {
        $label = '{0}[{1}]' -f $process.Name, $process.ProcessId
        Write-Host ("RMINS_PROGRESS stage=stopping-process target={0} process={1}" -f $TargetPath, $label) -ForegroundColor Cyan
        if ($PSCmdlet.ShouldProcess($label, "Stop process using $TargetPath")) {
            try {
                Stop-Process -Id $process.ProcessId -Force -ErrorAction Stop
                Write-Host ("RMINS_PROCESS_STOPPED process={0}" -f $label) -ForegroundColor Green
            }
            catch {
                throw ("rmins: could not stop {0}: {1}" -f $label, $_.Exception.Message)
            }
        }
    }

    return $matched.Count
}

