function Stop-RrmTargetProcesses {
        param([Parameter(Mandatory = $true)][string]$Target)

        $targetNorm = [IO.Path]::GetFullPath($Target).TrimEnd('\')
        $excludeIds = @{}
        $walkId = [int]$PID
        for ($depth = 0; $depth -lt 12 -and $walkId -gt 0; $depth++) {
            $excludeIds[$walkId] = $true
            $procInfo = Get-CimInstance Win32_Process -Filter ("ProcessId={0}" -f $walkId) -ErrorAction SilentlyContinue
            if (-not $procInfo -or -not $procInfo.ParentProcessId -or [int]$procInfo.ParentProcessId -eq $walkId) { break }
            $walkId = [int]$procInfo.ParentProcessId
        }

        $matches = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
            if ($excludeIds.ContainsKey([int]$_.ProcessId)) { return $false }
            $cmd = '' + $_.CommandLine
            $exe = '' + $_.ExecutablePath
            $decoded = ''
            if ($cmd -match '-EncodedCommand\s+(\S+)') {
                try { $decoded = [Text.Encoding]::Unicode.GetString([Convert]::FromBase64String($Matches[1])) } catch { $decoded = '' }
            }
            ($exe -and ($exe.StartsWith($targetNorm, [StringComparison]::OrdinalIgnoreCase) -or [string]::Equals($exe, $targetNorm, [StringComparison]::OrdinalIgnoreCase))) -or
            ($cmd -and $cmd.IndexOf($targetNorm, [StringComparison]::OrdinalIgnoreCase) -ge 0) -or
            ($decoded -and $decoded.IndexOf($targetNorm, [StringComparison]::OrdinalIgnoreCase) -ge 0)
        })

        foreach ($proc in $matches) {
            try {
                Write-RrmLine 'STOP' ("pid={0} name={1}" -f $proc.ProcessId, $proc.Name)
                $live = Get-Process -Id ([int]$proc.ProcessId) -ErrorAction SilentlyContinue
                if ($live) {
                    try { $null = $live.CloseMainWindow() } catch { Write-RrmLine 'WARN' ('close pid={0}: {1}' -f $live.Id,$_.Exception.Message) }
                    Start-Sleep -Milliseconds 200
                    Stop-Process -Id $live.Id -Force -ErrorAction Stop
                }
            } catch { Write-RrmLine 'FAIL' ('pid={0}: {1}' -f $proc.ProcessId,$_.Exception.Message); throw }
        }
    }

function Stop-UnfreezePid {
        if ($TargetPid -le 0 -or $TargetPid -eq $PID) { return }
        try {
            $p = Get-Process -Id $TargetPid -ErrorAction Stop
            $label = ("{0}[{1}] {2}" -f $p.Name,$TargetPid,$Reason)
            if ($DryRun -or -not $PSCmdlet.ShouldProcess($label,'Stop-Process -Force')) { Add-UnfreezeReport 'would-kill' $label 'dry-run'; return }
            Stop-Process -Id $TargetPid -Force -ErrorAction Stop
            Add-UnfreezeReport 'killed' $label 'ok'
        } catch { Add-UnfreezeReport 'kill-failed' ("pid={0} {1}" -f $TargetPid,$Reason) $_.Exception.Message }
    }

