function Test-GitCurl {
    param([string]$Url, [int]$TimeoutSec, [string]$ProbePath)

    $path = 'C:\Program Files\Git\mingw64\bin\curl.exe'
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        return [pscustomobject]@{ Usable = $false; Path = $path; Version = $null; Detail = 'Git curl is unavailable.' }
    }
    $version = (& $path --version 2>&1 | Select-Object -First 1)
    if ($LASTEXITCODE -ne 0 -or $version -notmatch '^curl\s+\d+\.\d+\.\d+') {
        return [pscustomobject]@{ Usable = $false; Path = $path; Version = $version; Detail = 'Git curl version validation failed.' }
    }
    Remove-Item -LiteralPath $ProbePath -Force -ErrorAction SilentlyContinue
    $stderr = $ProbePath + '.stderr'
    $stdout = $ProbePath + '.stdout'
    $process = Start-Process -FilePath $path -ArgumentList @(
        '--silent', '--show-error', '--fail', '--location',
        '--connect-timeout', $TimeoutSec, '--max-time', $TimeoutSec,
        '--referer', $amdSupportPage, '--user-agent', $amdUserAgent,
        '--head', $Url
    ) -Wait -PassThru -NoNewWindow -RedirectStandardOutput $stdout -RedirectStandardError $stderr
    $code = [int]$process.ExitCode
    Remove-Item -LiteralPath $stdout, $stderr -Force -ErrorAction SilentlyContinue
    $usable = $code -eq 0
    [pscustomobject]@{ Usable = $usable; Path = $path; Version = $version; Detail = "probeExit=$code" }
}

function Test-GitlogToken {
