    if ($loginProbe.ExitCode -eq 0 -and $loginProbe.Output) {
        return [pscustomobject]@{ Ok = $true; Login = $loginProbe.Output; Message = 'token accepted by GitHub API' }
    }

    $apiProbe = Invoke-GitlogGh -ArgumentList @('api','user') -TokenForProcess $CandidateToken
    return [pscustomobject]@{ Ok = $false; Login = ''; Message = $apiProbe.Output }
}

