function Test-PortableExecutable {
    param([string]$Path)

    $stream = New-Object IO.FileStream($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
    try {
        if ($stream.Length -lt 64) {
            return $false
        }
        $header = New-Object byte[] 64
        if ($stream.Read($header, 0, $header.Length) -ne $header.Length) {
            return $false
        }
        if ($header[0] -ne 0x4d -or $header[1] -ne 0x5a) {
            return $false
        }
        $peOffset = [BitConverter]::ToInt32($header, 0x3c)
        if ($peOffset -lt 64 -or $peOffset -gt ($stream.Length - 4)) {
            return $false
        }
        $stream.Position = $peOffset
        $signature = New-Object byte[] 4
        return $stream.Read($signature, 0, $signature.Length) -eq 4 -and
            $signature[0] -eq 0x50 -and $signature[1] -eq 0x45 -and
            $signature[2] -eq 0 -and $signature[3] -eq 0
    } finally {
        $stream.Dispose()
    }
}

