function Test-ReassTreeEqual {
    param(
        [Parameter(Mandatory)]
        [string]$Expected,

        [Parameter(Mandatory)]
        [string]$Actual,

        [Parameter(Mandatory)]
        [string]$Stage,

        [Parameter(Mandatory)]
        [int]$ProgressStart,

        [Parameter(Mandatory)]
        [int]$ProgressEnd
    )

    $expectedRoot = [IO.Path]::GetFullPath($Expected).TrimEnd('\')
    $actualRoot = [IO.Path]::GetFullPath($Actual).TrimEnd('\')
    $expectedFiles = Get-ReassFiles -Path $expectedRoot
    $actualFiles = Get-ReassFiles -Path $actualRoot
    if ($expectedFiles.Count -ne $actualFiles.Count) {
        throw ("reass: verification failed at {0}; file count expected={1} actual={2}" -f $Stage, $expectedFiles.Count, $actualFiles.Count)
    }

    $actualMap = @{}
    foreach ($file in $actualFiles) {
        $actualMap[$file.FullName.Substring($actualRoot.Length).TrimStart('\')] = $file
    }

    for ($index = 0; $index -lt $expectedFiles.Count; $index++) {
        $expectedFile = $expectedFiles[$index]
        $relative = $expectedFile.FullName.Substring($expectedRoot.Length).TrimStart('\')
        if (-not $actualMap.ContainsKey($relative)) {
            throw ("reass: verification failed at {0}; missing file {1}" -f $Stage, $relative)
        }

        $actualFile = $actualMap[$relative]
        if ($expectedFile.Length -ne $actualFile.Length) {
            throw ("reass: verification failed at {0}; byte mismatch for {1}" -f $Stage, $relative)
        }

        $expectedHash = (Get-FileHash -LiteralPath $expectedFile.FullName -Algorithm SHA256 -ErrorAction Stop).Hash
        $actualHash = (Get-FileHash -LiteralPath $actualFile.FullName -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($expectedHash -ne $actualHash) {
            throw ("reass: verification failed at {0}; hash mismatch for {1}" -f $Stage, $relative)
        }

        $percent = $ProgressStart + [Math]::Floor(($ProgressEnd - $ProgressStart) * (($index + 1) / [double][Math]::Max(1, $expectedFiles.Count)))
        Write-Progress -Id 776 -Activity 'Restoring High On Life 2 save data' -Status ("{0}: {1}" -f $Stage, $relative) -PercentComplete $percent
    }
}

