function Test-UpgraderProcessUsingPath {
        param([string]$Path)

        if ([string]::IsNullOrWhiteSpace($Path)) {
            return $false
        }

        try {
            return @(
                Get-Process -ErrorAction SilentlyContinue |
                    Where-Object { $_.Path -eq $Path }
            ).Count -gt 0
