function Toggle-JarvisDaemon {
    # Debounce: key-repeat / double-fire protection.
    if ($script:LastToggleTime -and ((Get-Date) - $script:LastToggleTime).TotalMilliseconds -lt 2000) {
        Write-TrayLog 'toggle ignored (debounce)'
        return
    }
    $script:LastToggleTime = Get-Date
    $existing = Get-JarvisDaemonPid
    if ($existing) {
        Stop-Process -Id $existing -Force -ErrorAction SilentlyContinue
        try { Remove-Item -LiteralPath $script:PidFile -Force -ErrorAction SilentlyContinue } catch { }
        Write-TrayLog ('daemon stopped (was pid ' + $existing + ')')
        try {
            $script:Icon.Text = 'Jarvis - OFF (Alt+O)'
            $script:Icon.ShowBalloonTip(1500, 'Jarvis', 'Voice assistant is off. Alt+O to turn on.', [System.Windows.Forms.ToolTipIcon]::Info)
        } catch { }
    } else {
        $p = Start-Process -FilePath 'powershell.exe' -ArgumentList @('-NoProfile', '-WindowStyle', 'Hidden', '-ExecutionPolicy', 'Bypass', '-File', $script:DaemonScript) -WindowStyle Hidden -PassThru
        $p.Id | Set-Content -LiteralPath $script:PidFile
        Write-TrayLog ('daemon started pid=' + $p.Id)
        try {
            $script:Icon.Text = 'Jarvis - LISTENING (Alt+O stops)'
            $script:Icon.ShowBalloonTip(1500, 'Jarvis', 'Listening... Alt+O to stop.', [System.Windows.Forms.ToolTipIcon]::Info)
        } catch { }
    }
}

function top {
    param(
        [string]$Path = "."
    )
    Get-ChildItem -Path $Path |
    ForEach-Object {
        $size = 0
        if ($_.PSIsContainer) {
            $size = (Get-ChildItem -Path $_.FullName -Recurse -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        }
        else {
            $size = $_.Length
        }
        [PSCustomObject]@{
            Name = $_.Name
            SizeMB = [Math]::Round($size / 1MB, 2)
            SizeGB = [Math]::Round($size / 1GB, 2)
            Type = if ($_.PSIsContainer) {"Folder"} else {"File"}
        }
    } | Sort-Object -Property SizeMB -Descending | Format-Table -AutoSize
}

function ts {
    $start = Get-Variable -Name bleachStart -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    if (-not ($start -is [datetime])) {
        $start = Get-Date
        Set-Variable -Name bleachStart -Scope Script -Value $start
    }

    $elapsedSeconds = [Math]::Max(0, [int]((Get-Date) - $start).TotalSeconds)
    $minutes = [int]($elapsedSeconds / 60)
    $seconds = [int]($elapsedSeconds % 60)
    return ('[{0:D2}:{1:D2}]' -f $minutes, $seconds)
}

function tweek {
    $tweekDir = "F:\backup\windowsapps\installed\Fit Launcher\fixers\Tweaking.com"
