function Wait-DockerCommanderVisibleSeconds {
    param(
        [int]$Seconds = 1,
        [string]$Activity = 'waiting'
    )
    if ($Seconds -lt 0) { $Seconds = 0 }
    for ($remaining = $Seconds; $remaining -gt 0; $remaining--) {
        Write-Host ("[{0}] {1}s remaining" -f $Activity, $remaining)
        Start-Sleep -Seconds 1
    }
}

function Wait-ExactProcess {
    param([string]$ExecutablePath, [string]$Name, [int]$Seconds = 30)
    $deadline = (Get-Date).AddSeconds($Seconds)
    do {
        $process = Get-Process -ErrorAction SilentlyContinue |
            Where-Object {
                $_.ProcessName -eq [IO.Path]::GetFileNameWithoutExtension($Name) -and
                $_.Path -and $_.Path.Equals($ExecutablePath, [StringComparison]::OrdinalIgnoreCase)
            } |
            Select-Object -First 1
        if ($process) {
            Start-Sleep -Seconds 2
            $native = Get-Process -Id $process.Id -ErrorAction SilentlyContinue
            if ($native -and -not $native.HasExited -and $native.Responding) {
                return [pscustomobject]@{ ProcessId = $native.Id }
            }
        }
        Start-Sleep -Milliseconds 500
    } while ((Get-Date) -lt $deadline)
    throw "$Name did not remain ready from $ExecutablePath."
}

function Wait-ForDaemon {
    param([string]$DockerExe, [int]$Seconds = 120)
    $deadline = (Get-Date).AddSeconds([Math]::Max(5, $Seconds))
    $lastPct = -1
    while ((Get-Date) -lt $deadline) {
        if (Test-DaemonReady -DockerExe $DockerExe -Milliseconds 500) { return $true }
        $remaining = [int][Math]::Max(0, ($deadline - (Get-Date)).TotalSeconds)
        $pct = [Math]::Min(99, [int]((1 - ($remaining / [Math]::Max(1, $Seconds))) * 100))
        if ($pct -ne $lastPct) {
            Write-DLine ("waiting for Docker daemon... {0}% ({1}s remaining)" -f $pct, $remaining) 'DarkCyan'
            $lastPct = $pct
        }
        Start-Sleep -Milliseconds 100
    }
    return (Test-DaemonReady -DockerExe $DockerExe -Milliseconds 1000)
}

function Wait-HttpReady {
    param([string]$Uri, [int]$Seconds = 60)
    $deadline = (Get-Date).AddSeconds($Seconds)
    do {
        try {
            $response = Invoke-WebRequest -UseBasicParsing -Uri $Uri -TimeoutSec 4
            if ($response.StatusCode -ge 200 -and $response.StatusCode -lt 500) {
                return
            }
        } catch {
        }
        Start-Sleep -Milliseconds 750
    } while ((Get-Date) -lt $deadline)
    throw "HTTP readiness check failed: $Uri"
}

