function Wait-RedockerSafeDockerFiles {
        param([int]$TimeoutSeconds = 180)
        $deadline = (Get-Date).AddSeconds([Math]::Max(5,$TimeoutSeconds))
        $last = -1
        do {
            $desktop = Find-RedockerSafeDockerPath -Kind Desktop
            $cli = Find-RedockerSafeDockerPath -Kind Cli
            if($desktop -and $cli){ return [pscustomobject]@{ DesktopExe = $desktop; DockerExe = $cli } }
            $elapsed = [int]([Math]::Max(0,((Get-Date).AddSeconds($TimeoutSeconds) - $deadline).TotalSeconds))
            $pct = [Math]::Min(99,[int](($elapsed / [Math]::Max(1,$TimeoutSeconds)) * 100))
            if($pct -ne $last){
                Write-RedockerSafeLine ("waiting for installed executables {0}% desktop={1} cli={2}" -f $pct,[bool]$desktop,[bool]$cli) DarkCyan
                Write-RedockerSafeProgress -Activity 'redocker: locating installed Docker executables' -Status ("desktop={0}; cli={1}" -f [bool]$desktop,[bool]$cli) -PercentComplete $pct
                $last = $pct
            }
            Start-Sleep -Milliseconds 500
        } while((Get-Date) -lt $deadline)
        Write-Progress -Id 847 -Activity 'redocker: locating installed Docker executables' -Completed
        return [pscustomobject]@{ DesktopExe = (Find-RedockerSafeDockerPath -Kind Desktop); DockerExe = (Find-RedockerSafeDockerPath -Kind Cli) }
    }

function Wait-RedockerSafeDockerReady {
        param([string]$DockerExe,[int]$TimeoutSeconds = 180)
        $deadline = (Get-Date).AddSeconds([Math]::Max(5,$TimeoutSeconds))
        $last = -1
        do {
            if(Test-RedockerSafeDockerReady -DockerExe $DockerExe){ return $true }
            $elapsed = [int]([Math]::Max(0,((Get-Date).AddSeconds($TimeoutSeconds) - $deadline).TotalSeconds))
            $pct = [Math]::Min(99,[int](($elapsed / [Math]::Max(1,$TimeoutSeconds)) * 100))
            if($pct -ne $last){
                Write-RedockerSafeLine ("waiting for Docker daemon readiness {0}%" -f $pct) DarkCyan
                Write-RedockerSafeProgress -Activity 'redocker: waiting for Docker daemon' -Status 'checking docker version' -PercentComplete $pct
                $last = $pct
            }
            Start-Sleep -Milliseconds 750
        } while((Get-Date) -lt $deadline)
        Write-Progress -Id 847 -Activity 'redocker: waiting for Docker daemon' -Completed
        return (Test-RedockerSafeDockerReady -DockerExe $DockerExe -Milliseconds 2500)
    }

