function webterm {
    [CmdletBinding()]
    param([string]$WorkingDirectory = (Get-Location).Path)

    if (-not (Test-Path -LiteralPath $WorkingDirectory -PathType Container)) {
        throw "WEBTERM: working directory does not exist: $WorkingDirectory"
    }
    $systemRoot = [Environment]::GetEnvironmentVariable('SystemRoot', 'Process')
    if ([string]::IsNullOrWhiteSpace($systemRoot)) { $systemRoot = 'C:\Windows' }
    $powershell = Join-Path $systemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    if (-not (Test-Path -LiteralPath $powershell -PathType Leaf)) {
        throw "WEBTERM: Windows PowerShell 5 executable is missing: $powershell"
    }
    $statePath = Get-ProfileManagedWebTermStatePath
    $existingState = $null
    if (Test-Path -LiteralPath $statePath -PathType Leaf) {
        try { $existingState = Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json } catch { $existingState = $null }
    }
    $existingProcess = Get-ProfileManagedWebTermProcess -State $existingState
    if ($existingProcess) {
        Write-Output ("WEBTERM_OK action=already-running pid={0}" -f $existingProcess.Id)
        return
    }
    if ($existingState) {
        Remove-Item -LiteralPath $statePath -Force -ErrorAction SilentlyContinue
    }
    Write-Output ("WEBTERM_PROGRESS stage=starting working_directory=""{0}""" -f $WorkingDirectory)
    $process = Start-Process -FilePath $powershell -ArgumentList @('-NoExit', '-Command', 'Set-Location -LiteralPath $args[0]', '--', $WorkingDirectory) -WorkingDirectory $WorkingDirectory -PassThru
    $stateDirectory = Split-Path -Parent $statePath
    New-Item -ItemType Directory -Path $stateDirectory -Force | Out-Null
    [System.IO.File]::WriteAllText($statePath, (([pscustomobject]@{
        ProcessId = $process.Id
        ProcessStartedUtc = $process.StartTime.ToUniversalTime().ToString('o')
        WorkingDirectory = $WorkingDirectory
        StartedUtc = [DateTime]::UtcNow.ToString('o')
    }) | ConvertTo-Json -Depth 2), (New-Object System.Text.UTF8Encoding($false)))
    Write-Output ("WEBTERM_OK pid={0}" -f $process.Id)
}

