function Write-MmenuNewLogBytes {
        param([Parameter(Mandatory=$true)][string]$File,[Parameter(Mandatory=$true)][ref]$Offset)
        if (-not (Test-Path -LiteralPath $File -PathType Leaf)) { return }
        $fs = [IO.File]::Open($File, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
        try {
            if ($fs.Length -gt $Offset.Value) {
                $fs.Seek([int64]$Offset.Value, [IO.SeekOrigin]::Begin) | Out-Null
                $reader = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8, $true, 4096, $true)
                $chunk = $reader.ReadToEnd(); $reader.Dispose(); $Offset.Value = $fs.Position
                if (-not [string]::IsNullOrEmpty($chunk)) { Update-MmenuProgressFromChunk $chunk; Write-Host $chunk.TrimEnd() }
            }
        } finally { $fs.Dispose() }
    }

function Write-MmenuRealProgressLine {
        param([string]$Label,[int]$Elapsed,[int]$ProcessId,[int]$Tick)
        $parts=@()
        $nativeAge=[int][Math]::Floor(((Get-Date)-$script:MmenuLastNativeProgressUtc).TotalSeconds)
        $showByteProgress = ($Label -eq 'tar-import')
        if($showByteProgress -and $script:MmenuContextTotalBytes -gt 0){
            if($script:MmenuContextDoneBytes -ge $script:MmenuContextTotalBytes){
                $parts += ('context-stream-complete={0}/{1}; docker-import-finalizing-no-native-percent' -f (Format-MmenuMB $script:MmenuContextDoneBytes),(Format-MmenuMB $script:MmenuContextTotalBytes))
            } else {
                $pct=[Math]::Min([double]99.99,[Math]::Round(100.0*[double]$script:MmenuContextDoneBytes/[Math]::Max([double]1,[double]$script:MmenuContextTotalBytes),2))
                $parts += ('context={0}/{1} {2}%' -f (Format-MmenuMB $script:MmenuContextDoneBytes),(Format-MmenuMB $script:MmenuContextTotalBytes),$pct)
            }
        }
        if($showByteProgress -and $script:MmenuBuildCurrentBytes -gt 0){
            if($script:MmenuContextTotalBytes -gt 0){
                if($script:MmenuBuildCurrentBytes -ge $script:MmenuContextTotalBytes){
                    $parts += ('build-transfer-complete={0}/{1}; waiting-for-docker-finalize' -f (Format-MmenuMB $script:MmenuBuildCurrentBytes),(Format-MmenuMB $script:MmenuContextTotalBytes))
                } else {
                    $pct=[Math]::Min([double]99.99,[Math]::Round(100.0*[double]$script:MmenuBuildCurrentBytes/[Math]::Max([double]1,[double]$script:MmenuContextTotalBytes),2))
                    $parts += ('build-transfer={0}/{1} {2}%' -f (Format-MmenuMB $script:MmenuBuildCurrentBytes),(Format-MmenuMB $script:MmenuContextTotalBytes),$pct)
                }
            } else {
                $parts += ('build-transfer={0}' -f (Format-MmenuMB $script:MmenuBuildCurrentBytes))
            }
        }
        if($showByteProgress -and $script:MmenuPushLayers.Count -gt 0){
