function Write-MmenuTarStreamerScript {
        param([string]$ScriptPath)
        $py = @'
import os, sys, tarfile, time
root=os.path.abspath(sys.argv[1])
files=[]; total=0; phantom=0
def on_walk_error(e):
    global phantom
    phantom += 1
    print(f"[mmenu][context-warning] unreadable_reserved_or_phantom_path path={getattr(e,'filename',None)!r} error={e}", file=sys.stderr, flush=True)
for dp,dn,fn in os.walk(root, onerror=on_walk_error):
    for n in fn:
        p=os.path.join(dp,n)
        try:
            st=os.lstat(p); total += st.st_size; files.append(p)
        except OSError as e:
            phantom += 1
            print(f"[mmenu][context-warning] unreadable_reserved_or_phantom_path path={p!r} error={e}", file=sys.stderr, flush=True)
print(f"[mmenu][context] archived_bytes=0 total_bytes={total}", file=sys.stderr, flush=True)
if phantom:
    print(f"[mmenu][context-warning] reserved_or_phantom_entries_not_real_readable_files={phantom}", file=sys.stderr, flush=True)
class CountingWriter:
    def __init__(self, raw, total):
        self.raw=raw; self.total=total; self.done=0; self.last=0.0
    def write(self, b):
        n=self.raw.write(b)
        if n is None: n=len(b)
        self.done += n
        now=time.time()
        if now-self.last >= 1.0:
            print(f"[mmenu][context] archived_bytes={self.done} total_bytes={self.total}", file=sys.stderr, flush=True); self.last=now
        return n
    def flush(self):
        return self.raw.flush()
out=CountingWriter(sys.stdout.buffer, total)
with tarfile.open(fileobj=out, mode='w|') as tar:
    for p in files:
        arc=os.path.join('home', os.path.relpath(p, root)).replace('\\','/')
        try:
            tar.add(p, arcname=arc, recursive=False)
        except OSError as e:
            print(f"[mmenu][context-warning] unreadable_reserved_or_phantom_path path={p!r} error={e}", file=sys.stderr, flush=True)
print(f"[mmenu][context] archived_bytes={out.done} total_bytes={total}", file=sys.stderr, flush=True)
'@
        [IO.File]::WriteAllText($ScriptPath,$py,[Text.Encoding]::UTF8)
    }

function Write-MmmenuNewLogBytes {
        param([Parameter(Mandatory=$true)][string]$File,[Parameter(Mandatory=$true)][ref]$Offset)
        if (-not (Test-Path -LiteralPath $File -PathType Leaf)) { return }
        $fs = [IO.File]::Open($File, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
        try {
            if ($fs.Length -gt $Offset.Value) {
                $fs.Seek([int64]$Offset.Value, [IO.SeekOrigin]::Begin) | Out-Null
                $reader = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8, $true, 4096, $true)
                $chunk = $reader.ReadToEnd(); $reader.Dispose(); $Offset.Value = $fs.Position
                if (-not [string]::IsNullOrEmpty($chunk)) { Update-MmmenuProgressFromChunk $chunk; Write-Host $chunk.TrimEnd() }
            }
        } finally { $fs.Dispose() }
    }

function Write-MmmenuRealProgressLine {
