}

function Write-UniSummary {
    $secs = [int](([DateTime]::UtcNow) - $global:UniStart).TotalSeconds
    $m = [math]::Floor($secs / 60); $s = $secs % 60
    Clear-UniLine
    Write-Host ''
    Write-Host ('  NUCLEAR OBLITERATION COMPLETE ({0}m {1}s)' -f $m, $s) -ForegroundColor Green
    Write-Host ('  ' + ('=' * 46))
    Write-Host ('  Processes Killed:      {0}' -f $global:UniStats.Processes)
    Write-Host ('  Services Deleted:      {0}' -f $global:UniStats.Services)
    Write-Host ('  Tasks Deleted:         {0}' -f $global:UniStats.Tasks)
    Write-Host ('  Firewall Rules:        {0}' -f $global:UniStats.Firewall)
    Write-Host ('  Registry Keys:         {0}' -f $global:UniStats.RegKeys)
    Write-Host ('  Registry Values:       {0}' -f $global:UniStats.RegValues)
    Write-Host ('  Env Vars Removed:      {0}' -f $global:UniStats.EnvVars)
    Write-Host ('  Shortcuts Removed:     {0}' -f $global:UniStats.Shortcuts)
    Write-Host ('  Files Deleted:         {0}' -f $global:UniStats.Files)
    Write-Host ('  Dirs Deleted:          {0}' -f $global:UniStats.Dirs)
    if ($global:UniFailed.Count -gt 0) {
        Write-Host ('  FAILED (blocked):     {0}' -f $global:UniFailed.Count) -ForegroundColor Red
        foreach ($f in @($global:UniFailed | Select-Object -Unique)) {
            Write-Host ("    blocked: {0}" -f $f) -ForegroundColor Red
        }
    } else {
        Write-Host '  FAILED (blocked):     0' -ForegroundColor Green
    }
    Write-Host ''
    Write-Host '  No reboot required. Zero leftovers. Back to shell.' -ForegroundColor Green
}

function ws {
    [CmdletBinding()]
    param(
        [Parameter(ValueFromRemainingArguments = $true)]
        [string[]] $Args
    )
    $distro = 'Ubuntu'   # change once if you ever rename
    $user   = 'root'
    $core   = @('-d', $distro, '-u', $user, '--')  # common WSL flags
    if (-not $Args) {
        & "$env:SystemRoot\System32\wsl.exe" @core bash -li
    }
    else {
        $raw     = [string]::Join(' ', $Args)
        $escaped = $raw -replace '"', '\"'  # keep internal quotes intact
        & "$env:SystemRoot\System32\wsl.exe" @core bash -li -c "$escaped"
    }
    if ($LASTEXITCODE -ne $null) { $global:LASTEXITCODE = $LASTEXITCODE }
}

