function global:fixfixfix_legacy_unused {
    [CmdletBinding()]
    param()

    function Invoke-FixFixFixStage {
        param([Parameter(Mandatory)][string]$Label, [Parameter(Mandatory)][string]$Exe, [Parameter(Mandatory)][string[]]$Args)
        $out = Join-Path $env:TEMP ('fixfixfix-' + [guid]::NewGuid().ToString('N') + '.log')
        $err = Join-Path $env:TEMP ('fixfixfix-' + [guid]::NewGuid().ToString('N') + '.err.log')
        $progress = -1
        $offset = 0L
        $started = Get-Date
        try {
            Write-Host ("FIXFIXFIX stage=started name=[{0}]" -f $Label) -ForegroundColor Cyan
            $p = Start-Process -FilePath $Exe -ArgumentList $Args -NoNewWindow -PassThru -RedirectStandardOutput $out -RedirectStandardError $err -ErrorAction Stop
            while (-not $p.HasExited) {
                if (Test-Path -LiteralPath $out) {
                    $stream = [IO.File]::Open($out, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
                    try {
                        if ($stream.Length -gt $offset) {
                            $stream.Position = $offset
                            $reader = New-Object IO.StreamReader($stream, [Text.Encoding]::Default, $true, 4096, $true)
                            $chunk = $reader.ReadToEnd(); $reader.Dispose(); $offset = $stream.Position
                            foreach ($match in [regex]::Matches($chunk, '(?<!\d)(\d{1,3}(?:\.\d+)?)%')) {
                                $next = [int][math]::Floor([double]$match.Groups[1].Value)
                                if ($next -ge 0 -and $next -le 100) { $progress = $next }
                            }
                            foreach ($line in ($chunk -split "[\r\n]+" | Where-Object { $_.Trim() })) { Write-Host ("FIXFIXFIX native=[{0}]" -f $line.Trim()) }
                        }
                    } finally { $stream.Dispose() }
                }
                $elapsed = (Get-Date) - $started
                $elapsedText = '{0:00}:{1:00}:{2:00}' -f [int][math]::Floor($elapsed.TotalHours), $elapsed.Minutes, $elapsed.Seconds
                $status = if ($progress -ge 0) { "real DISM/SFC output: $progress% | elapsed $elapsedText" } else { "waiting for first native progress update | elapsed $elapsedText" }
                Write-Host ("FIXFIXFIX_PROGRESS name=[{0}] status=[{1}]" -f $Label, $status) -ForegroundColor DarkCyan
                Start-Sleep -Milliseconds 500; $p.Refresh()
            }
            $p.WaitForExit(); if ($p.ExitCode -ne 0) { throw "$Label exited with code $($p.ExitCode)" }
            Write-Host ("FIXFIXFIX stage=completed name=[{0}] elapsed_ms={1}" -f $Label, [int]((Get-Date)-$started).TotalMilliseconds) -ForegroundColor Green
        } finally { Remove-Item -LiteralPath $out,$err -Force -ErrorAction SilentlyContinue }
    }
    Invoke-FixFixFixStage -Label 'DISM /RestoreHealth' -Exe (Join-Path $env:SystemRoot 'System32\dism.exe') -Args @('/Online','/Cleanup-Image','/RestoreHealth')
    Invoke-FixFixFixStage -Label 'SFC /scannow' -Exe (Join-Path $env:SystemRoot 'System32\sfc.exe') -Args @('/scannow')
}

