function global:rrm {
    [CmdletBinding()]
    param(
        [Parameter(Position = 0, ValueFromRemainingArguments = $true)]
        [Alias('Path')]
        [string[]]$Target,
        [switch]$DryRun,
        [switch]$SelfTest
    )

    $exe = 'F:\study\projects\ForceDeleteAnything\publish\ForceDeleteAnything.exe'
    $cachePath = 'C:\ProgramData\ForceDeleteAnything\last-numbered-items.tsv'
    if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) {
        throw "rrm executable is missing: $exe"
    }
    if ($SelfTest) {
        $cacheState = if (Test-Path -LiteralPath $cachePath -PathType Leaf) { 'present' } else { 'absent' }
        Write-Output "RRM_SELFTEST_OK executable=present numberedCache=$cacheState dryRunSupported=true reservedNamesSupported=true"
        return
    }
    if (-not $Target -or $Target.Count -eq 0) {
        throw 'Usage: rrm <DUSH-number|range|path> [...]'
    }

    $numberPattern = '^\d+(?:-\d+)?(?:,\d+(?:-\d+)?)*$'
    $needsCache = @($Target | Where-Object {
        $_ -match $numberPattern -and -not (Test-Path -LiteralPath $_)
    }).Count -gt 0
    $rows = @{}
    $cacheRoot = $null
    if ($needsCache) {
        if (-not (Test-Path -LiteralPath $cachePath -PathType Leaf)) {
            throw 'No numbered DUSH list is available. Run dush in the target folder, then retry rrm.'
        }
        $cacheItem = Get-Item -LiteralPath $cachePath -ErrorAction Stop
        if (((Get-Date).ToUniversalTime() - $cacheItem.LastWriteTimeUtc).TotalMinutes -gt 30) {
            throw 'The numbered DUSH list is older than 30 minutes. Run dush again before deleting by number.'
        }
        foreach ($line in Get-Content -LiteralPath $cachePath) {
            if ($line -like 'root=*') {
                $cacheRoot = $line.Substring(5)
                continue
            }
            if ($line -match '^(\d+)\t(.+)$') {
                $rows[[int]$matches[1]] = $matches[2]
            }
        }
        if ($rows.Count -eq 0) {
            throw 'The numbered DUSH list contains no usable rows. Run dush again.'
        }
        Write-Host ("[rrm] numbered list: {0} ({1} entries)" -f $cacheRoot, $rows.Count) -ForegroundColor Cyan
    }

    $resolved = New-Object 'System.Collections.Generic.List[string]'
    foreach ($raw in $Target) {
        if ($raw -notmatch $numberPattern -or (Test-Path -LiteralPath $raw)) {
            $resolved.Add($raw)
            continue
        }
        foreach ($part in $raw.Split(',')) {
            $first = 0
            $last = 0
            if ($part -match '^(\d+)-(\d+)$') {
                $first = [int]$matches[1]
                $last = [int]$matches[2]
                if ($first -gt $last) { throw "Invalid descending DUSH range: $part" }
            } else {
                $first = [int]$part
                $last = $first
            }
            for ($index = $first; $index -le $last; $index++) {
                if (-not $rows.ContainsKey($index)) {
                    throw "DUSH number $index is out of range. Run dush again."
                }
                $path = [string]$rows[$index]
                $literalPath = $path
                if (-not (Test-Path -LiteralPath $literalPath)) {
                    $extendedPath = '\\?\' + $path
                    if ([IO.File]::Exists($extendedPath) -or [IO.Directory]::Exists($extendedPath)) {
                        $literalPath = $extendedPath
                    }
                }
                Write-Host ("[rrm] #{0} -> {1}" -f $index, $literalPath) -ForegroundColor Yellow
                $resolved.Add($literalPath)
            }
        }
    }

    $arguments = New-Object 'System.Collections.Generic.List[string]'
    if ($DryRun) { $arguments.Add('--dry-run') }
    foreach ($path in $resolved) { $arguments.Add($path) }
    & $exe @arguments
    $global:LASTEXITCODE = $LASTEXITCODE
}

