# so a wrong or disconnected default playback endpoint can never silently
# swallow the alert. Falls back to default-device sound, beeps, then BEL.
$wavCandidates = @(
    (Join-Path $env:SystemRoot 'Media\ringout.wav'),
    (Join-Path $env:SystemRoot 'Media\notify.wav'),
    (Join-Path $env:SystemRoot 'Media\ding.wav'),
    (Join-Path $env:SystemRoot 'Media\chimes.wav'),
    (Join-Path $env:SystemRoot 'Media\tada.wav')
)
$wavBytes = $null
foreach ($wav in $wavCandidates) {
