        try {
            $wavBytes = [System.IO.File]::ReadAllBytes($wav)
            break
        } catch { }
    }
}
if ($wavBytes) {
    try {
        if (-not ('ProfileAlert.Api' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace ProfileAlert
{
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Ansi)]
    public struct WAVEOUTCAPS
    {
        public ushort wMid;
        public ushort wPid;
        public uint vDriverVersion;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string szPname;
        public uint dwFormats;
        public ushort wChannels;
        public ushort wReserved1;
        public uint dwSupport;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct WAVEHDR
    {
        public IntPtr lpData;
        public uint dwBufferLength;
        public uint dwBytesRecorded;
        public IntPtr dwUser;
        public uint dwFlags;
        public uint dwLoops;
        public IntPtr lpNext;
        public uint reserved;
    }

    public struct WAVEFORMATEX
    {
        public ushort wFormatTag;
        public ushort nChannels;
        public uint nSamplesPerSec;
        public uint nAvgBytesPerSec;
        public ushort nBlockAlign;
        public ushort wBitsPerSample;
        public ushort cbSize;
    }

    public class DeviceInfo
    {
        public uint Id;
        public string Name;
    }

    public class DeviceResult
    {
        public uint Id;
        public string Name;
        public bool Played;
        public string Error = "";
    }

    public static class Native
    {
        public const uint CALLBACK_NULL = 0x00000000;
        public const uint WHDR_DONE = 0x00000001;

        [DllImport("winmm.dll")]
        public static extern uint waveOutGetNumDevs();

        [DllImport("winmm.dll", CharSet = CharSet.Ansi)]
        public static extern uint waveOutGetDevCaps(uint uDeviceID, ref WAVEOUTCAPS caps, uint cbCaps);

        [DllImport("winmm.dll")]
        public static extern uint waveOutOpen(out IntPtr hwo, uint uDeviceID, ref WAVEFORMATEX lpFormat, IntPtr dwCallback, IntPtr dwInstance, uint dwFlags);

        [DllImport("winmm.dll")]
        public static extern uint waveOutClose(IntPtr hwo);

        [DllImport("winmm.dll")]
        public static extern uint waveOutPrepareHeader(IntPtr hwo, ref WAVEHDR pwh, uint cbwh);

        [DllImport("winmm.dll")]
        public static extern uint waveOutWrite(IntPtr hwo, ref WAVEHDR pwh, uint cbwh);

        [DllImport("winmm.dll")]
        public static extern uint waveOutUnprepareHeader(IntPtr hwo, ref WAVEHDR pwh, uint cbwh);

        [DllImport("winmm.dll")]
        public static extern uint waveOutGetErrorText(uint mmrError, StringBuilder text, uint cchText);
    }

    public static class Api
    {
        public static List<DeviceInfo> GetDevices()
        {
            var list = new List<DeviceInfo>();
            uint n = Native.waveOutGetNumDevs();
            for (uint i = 0; i < n; i++)
            {
                var caps = new WAVEOUTCAPS();
                var info = new DeviceInfo { Id = i };
                if (Native.waveOutGetDevCaps(i, ref caps, (uint)Marshal.SizeOf(caps)) == 0)
                {
                    info.Name = caps.szPname;
                }
                else
                {
                    info.Name = "(unknown)";
                }
                list.Add(info);
            }
            return list;
        }

        public static byte[] ExtractPcm(byte[] wav, out int channels, out int sampleRate, out int bitsPerSample, out int blockAlign)
        {
            channels = 0; sampleRate = 0; bitsPerSample = 0; blockAlign = 0;
            try
            {
                if (wav == null || wav.Length < 44) return null;
                if (wav[0] != (byte)'R' || wav[1] != (byte)'I' || wav[2] != (byte)'F' || wav[3] != (byte)'F') return null;
                if (wav[8] != (byte)'W' || wav[9] != (byte)'A' || wav[10] != (byte)'V' || wav[11] != (byte)'E') return null;

                int pos = 12;
                byte[] pcm = null;
                int fmtTag = 1, nChannels = 2, nRate = 44100, nBits = 16, nBlock = 4;

                while (pos + 8 <= wav.Length)
                {
                    string id = Encoding.ASCII.GetString(wav, pos, 4);
                    uint size = BitConverter.ToUInt32(wav, pos + 4);
                    int dataStart = pos + 8;
                    if (id == "fmt ")
                    {
                        if (dataStart + 16 <= wav.Length)
                        {
                            fmtTag = BitConverter.ToUInt16(wav, dataStart);
                            nChannels = BitConverter.ToUInt16(wav, dataStart + 2);
                            nRate = BitConverter.ToInt32(wav, dataStart + 4);
                            nBits = BitConverter.ToUInt16(wav, dataStart + 14);
                            nBlock = (ushort)(nChannels * (nBits / 8));
                            if (fmtTag == 0xFFFE && dataStart + 40 <= wav.Length)
                            {
                                ushort sub = BitConverter.ToUInt16(wav, dataStart + 24);
                                if (sub == 1) fmtTag = 1;
                            }
                        }
                    }
                    else if (id == "data")
                    {
                        int len = (int)size;
                        if (dataStart + len > wav.Length) len = wav.Length - dataStart;
                        pcm = new byte[len];
                        Array.Copy(wav, dataStart, pcm, 0, len);
                    }
                    pos = dataStart + (int)size;
                    if ((size & 1) == 1) pos++;
                }

                if (pcm == null) return null;
                channels = nChannels; sampleRate = nRate; bitsPerSample = nBits; blockAlign = nBlock;
                return pcm;
            }
            catch { return null; }
        }

        private static string ErrText(uint err)
        {
            var sb = new StringBuilder(256);
            Native.waveOutGetErrorText(err, sb, 256);
            return sb.ToString() + " (" + err + ")";
        }

        private static bool PlayOnDevice(uint deviceId, byte[] pcm, int channels, int rate, int bits, int blockAlign, int waitTimeoutMs, out string error)
        {
            error = "";
            var fmt = new WAVEFORMATEX();
            fmt.wFormatTag = 1;
            fmt.nChannels = (ushort)channels;
            fmt.nSamplesPerSec = (uint)rate;
            fmt.wBitsPerSample = (ushort)bits;
            fmt.nBlockAlign = (ushort)blockAlign;
            fmt.nAvgBytesPerSec = (uint)(rate * blockAlign);
            fmt.cbSize = 0;

            IntPtr h;
            uint err = Native.waveOutOpen(out h, deviceId, ref fmt, IntPtr.Zero, IntPtr.Zero, Native.CALLBACK_NULL);
            if (err != 0) { error = ErrText(err); return false; }
            try
            {
                var hdr = new WAVEHDR();
                var gch = GCHandle.Alloc(pcm, GCHandleType.Pinned);
                hdr.lpData = gch.AddrOfPinnedObject();
                hdr.dwBufferLength = (uint)pcm.Length;
                try
                {
                    err = Native.waveOutPrepareHeader(h, ref hdr, (uint)Marshal.SizeOf(hdr));
                    if (err != 0) { error = ErrText(err); return false; }
                    err = Native.waveOutWrite(h, ref hdr, (uint)Marshal.SizeOf(hdr));
                    if (err != 0) { error = ErrText(err); return false; }
                    int waited = 0;
                    while ((hdr.dwFlags & Native.WHDR_DONE) == 0)
                    {
                        Thread.Sleep(15);
                        waited += 15;
                        if (waited > waitTimeoutMs) { error = "timeout"; break; }
                    }
                    return true;
                }
                finally
                {
                    Native.waveOutUnprepareHeader(h, ref hdr, (uint)Marshal.SizeOf(hdr));
                    gch.Free();
                }
            }
            finally
            {
                Native.waveOutClose(h);
            }
        }

        // Play a WAV on every live output device in parallel. Returns a summary string.
        public static string PlayOnAll(byte[] wav, int waitTimeoutMs)
        {
            int channels, rate, bits, blockAlign;
            byte[] pcm = ExtractPcm(wav, out channels, out rate, out bits, out blockAlign);
            if (pcm == null) return "no-pcm-data";

            var devices = GetDevices();
            if (devices.Count == 0) return "no-devices";

            var results = new List<DeviceResult>();
            var tasks = new List<Task>();
            foreach (var d in devices)
            {
                int idx = results.Count;
                results.Add(new DeviceResult { Id = d.Id, Name = d.Name });
                tasks.Add(Task.Run(() =>
                {
                    string err;
                    bool ok = PlayOnDevice(results[idx].Id, pcm, channels, rate, bits, blockAlign, waitTimeoutMs, out err);
                    results[idx].Played = ok;
                    results[idx].Error = err;
                }));
            }
            Task.WaitAll(tasks.ToArray());

            var sb = new StringBuilder();
            int played = 0;
            foreach (var r in results)
            {
                if (r.Played) { played++; sb.AppendLine(r.Id + ": " + r.Name + " PLAYED"); }
                else sb.AppendLine(r.Id + ": " + r.Name + " FAILED: " + r.Error);
            }
            sb.Insert(0, "PLAYED_DEVICES=" + played + Environment.NewLine);
            return sb.ToString();
        }
    }
}
'@ -Language CSharp
        }
        $summary = [ProfileAlert.Api]::PlayOnAll($wavBytes, 15000)
        if ($summary -match 'PLAYED_DEVICES=([1-9][0-9]*)') {
            return
        }
    } catch { }
    try {
        (New-Object System.Media.SoundPlayer $wav).PlaySync()
        return
    } catch { }
}
try {
    1..3 | ForEach-Object { [console]::beep(800, 400); Start-Sleep -Milliseconds 150 }
    return
} catch { }
try { [System.Media.SystemSounds]::Asterisk.Play() } catch { }
try { [console]::Write(([string][char]7) * 3) } catch { }
}

