    # --- Pagefile ---
    $pfPath = Join-Path $env:SystemDrive 'pagefile.sys'
    $memKey = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'
    $currentPF = (Get-ItemProperty -Path $memKey -Name PagingFiles -EA 0).PagingFiles
    if ($currentPF -and $currentPF -ne '') {
        Write-Host 'Clearing pagefile registry setting...' -ForegroundColor Yellow
        Set-ItemProperty -Path $memKey -Name PagingFiles -Value '' -EA 0
        if (Test-Path $pfPath) {
            $pfSize = (Get-Item $pfPath -Force -EA 0).Length
            $freed += $pfSize
            Write-Host '  Pagefile will be cleared on next reboot. (Current size: $([math]::Round($pfSize/1GB,2)) GB)' -ForegroundColor Yellow
        } else {
            Write-Host '  Pagefile already cleared.' -ForegroundColor Green
        }
    } else {
        Write-Host '  Pagefile already minimized.' -ForegroundColor Green
    }
    if ($freed -gt 0) {
        Write-Host "Potential freed: $([math]::Round($freed/1GB,2)) GB" -ForegroundColor Green
    }
    Write-Host '=== Done ===' -ForegroundColor Cyan
}

