l}else{$last=$line;$errors++;$err=$p.StandardError.ReadLineAsync()}};if(($sw.Elapsed.TotalSeconds-$lastUi)-ge 1){$lastUi=$sw.Elapsed.TotalSeconds;$rate=if($sw.Elapsed.TotalSeconds){$done/$sw.Elapsed.TotalSeconds}else{0};$pct=[Math]::Min(99.99,100*$done/[Math]::Max(1,$total));$eta=if($rate -gt 0){([TimeSpan]::FromSeconds(($total-$done)/$rate)).ToString('dd\.hh\:mm\:ss')}else{'calculating'};$idle=[Math]::Floor(($sw.Elapsed-$lastFileAt).TotalSeconds);$shown=if($last.Length -gt 90){'...'+$last.Substring($last.Length-87)}else{$last};Write-Progress -Activity 'ClamAV scanning C:\ only — no remediation' -Status ('{0:N2}% | {1:N0}/{2:N0} files | {3:N1}/sec | ETA {4} | last completed file {5}s ago | {6}' -f $pct,$done,$total,$rate,$eta,$idle,$shown) -PercentComplete ([int]$pct)}};$p.WaitForExit();Write-Progress -Activity 'ClamAV scanning C:\ only — no remediation' -Completed;if($found.Count){Write-Host "`nDETECTIONS ($($found.Count)):" -ForegroundColor Red;$found|ForEach-Object{Write-Host $_ -ForegroundColor Red};Write-Host "`nSuggestion: do not delete or run detected files; review each result before remediation." -ForegroundColor Yellow}else{Write-Host "`nNo ClamAV detections on C:\." -ForegroundColor Green};Write-Host "Files processed: $done/$total | Scan errors: $errors | Elapsed: $($sw.Elapsed.ToString('dd\.hh\:mm\:ss')) | Remediation: none performed."} }

