function getwim {
    # Download the official Windows 11 English x64 ISO (latest release, e.g. 25H2)
    # to F:\isos\Win11_24H2_English_x64.iso via pbatard's Fido, which resolves
    # Microsoft's current download link. Fido saves the ISO in the folder it runs
    # from, so we launch it from a temp staging directory.
    $isoDir = 'F:\isos'
    $isoPath = Join-Path $isoDir 'Win11_24H2_English_x64.iso'
    New-Item -ItemType Directory -Path $isoDir -Force | Out-Null

    if (Test-Path -LiteralPath $isoPath -PathType Leaf) {
        $existing = Get-Item -LiteralPath $isoPath
        if ($existing.Length -gt 1GB) {
            Write-Host "getwim: ISO already present: $isoPath ($([math]::Round($existing.Length / 1GB, 2)) GB)" -ForegroundColor Green
            return
        }
        Write-Host "getwim: existing ISO at $isoPath looks incomplete - re-downloading." -ForegroundColor Yellow
        Remove-Item -LiteralPath $isoPath -Force
    }

    $fidoDir = Join-Path $env:TEMP 'getwim'
    New-Item -ItemType Directory -Path $fidoDir -Force | Out-Null
    $staging = Join-Path $fidoDir 'iso'
    New-Item -ItemType Directory -Path $staging -Force | Out-Null

    # If a fresh Windows ISO already landed somewhere (e.g. a previous Fido run
    # saved it to the working directory), reuse it instead of downloading again.
    $originalCwd = (Get-Location).Path
    $found = $null
    foreach ($probeDir in @($originalCwd, 'F:\', $isoDir, (Join-Path $env:USERPROFILE 'Downloads'))) {
        if (-not (Test-Path -LiteralPath $probeDir -PathType Container)) { continue }
        $candidate = Get-ChildItem -LiteralPath $probeDir -Filter '*.iso' -File -ErrorAction SilentlyContinue |
            Where-Object { $_.Length -gt 1GB -and $_.Name -match '^Win11_.*_English_x64.*\.iso$' } |
            Sort-Object LastWriteTime -Descending | Select-Object -First 1
        if ($candidate) { $found = $candidate; break }
    }
    if ($found) {
        Move-Item -LiteralPath $found.FullName -Destination $isoPath -Force
        Write-Host "getwim: reused existing ISO $($found.FullName) -> $isoPath ($([math]::Round($found.Length / 1GB, 2)) GB)" -ForegroundColor Green
        return
    }

    $fidoScript = Join-Path $fidoDir 'Fido.ps1'
    Write-Host 'getwim: fetching Fido (official Microsoft ISO downloader)...' -ForegroundColor Cyan
    Invoke-WebRequest -UseBasicParsing -Uri 'https://raw.githubusercontent.com/pbatard/Fido/master/Fido.ps1' -OutFile $fidoScript -ErrorAction Stop
    $tokens = $null
    $errors = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($fidoScript, [ref]$tokens, [ref]$errors)
    if ($errors.Count -gt 0) {
        throw "getwim: downloaded Fido.ps1 did not parse: $($errors[0].Message)"
    }

    Write-Host 'getwim: downloading the latest Windows 11 English x64 ISO (~8 GB, this takes a while)...' -ForegroundColor Cyan
    try {
        Push-Location -LiteralPath $staging
        & $fidoScript -Win 11 -Rel Latest -Ed Pro -Lang English -Arch x64
    } finally {
        Pop-Location
    }

    $iso = Get-ChildItem -LiteralPath $staging -Filter '*.iso' -File -ErrorAction SilentlyContinue |
        Sort-Object Length -Descending | Select-Object -First 1
    if (-not $iso -or $iso.Length -lt 1GB) {
        throw "getwim: no ISO was produced. If Fido printed an error above, the BITS service may be disabled - run 'Set-Service -Name BITS -StartupType Automatic; Start-Service BITS' and try again."
    }
    Move-Item -LiteralPath $iso.FullName -Destination $isoPath -Force
    Write-Host "getwim: done -> $isoPath ($([math]::Round($iso.Length / 1GB, 2)) GB, source: $($iso.Name))" -ForegroundColor Green
}

# Restored current skill/getamd2 and upgraded fff2 to the bounded live-progress repair engine.
function skill {
[CmdletBinding()]
param(
    [Parameter(Position = 0, ValueFromRemainingArguments = $true)]
    [string[]]$Name,
    [switch]$NoElevate
)
$patterns = @()
foreach ($raw in @($Name | Where-Object { $_ })) {
    $t = ([string]$raw).Trim().Trim('"').Trim("'")
    if (-not $t) { continue }
    $base = [System.IO.Path]::GetFileNameWithoutExtension(([System.IO.Path]::GetFileName($t)))
    if ([string]::IsNullOrWhiteSpace($base)) { $base = $t }
    $base = $base.Trim().ToLowerInvariant()
    if ($base -and $base -notin $patterns) { $patterns += $base }
}
if ($patterns.Count -eq 0) { Write-Host 'skill: no app name given.  Usage: skill <app> [<app> ...]' -ForegroundColor Yellow; return }
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
$alreadyElevated = $env:SKILL_ELEVATED -eq '1'
$protected = @('system','registry','memcompression','smss','csrss','wininit','winlogon','lsass','services','svchost','powershell','conhost')
$taskkill = Join-Path $env:SystemRoot 'System32\taskkill.exe'
$scExe = Join-Path $env:SystemRoot 'System32\sc.exe'

$killedCount = 0

# Count processes before kill
$beforePids = @()
try {
    foreach ($pat in $patterns) {
        Get-Process -ErrorAction SilentlyContinue | Where-Object {
            $_.Id -ne $PID -and -not $protected.Contains(($_.ProcessName.ToLower() -replace '\.exe$','')) -and (
                $_.ProcessName.ToLower() -like "*$pat*" -or ($pat.Length -ge 3 -and $_.ProcessName.ToLower().Contains($pat))
            )
        } | ForEach-Object { $beforePids += $_.Id }
    }
} catch {}
$beforeUnique = $beforePids | Select-Object -Unique
$beforeCount = $beforeUnique.Count

# Immediate aggressive kill
foreach ($pat in $patterns) {
    foreach ($tp in @($pat, "${pat}*", "*${pat}*")) {
        & $taskkill /F /T /IM $tp *> $null
    }
    try {
        Get-Process -ErrorAction SilentlyContinue | Where-Object {
            $_.Id -ne $PID -and -not $protected.Contains(($_.ProcessName.ToLower() -replace '\.exe$','')) -and (
                $_.ProcessName.ToLower() -like "*$pat*" -or ($pat.Length -ge 3 -and $_.ProcessName.ToLower().Contains($pat))
            )
        } | ForEach-Object { try { Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue } catch {} }
    } catch {}
}

# Second pass
Start-Sleep -Milliseconds 30
foreach ($pat in $patterns) {
    foreach ($tp in @("${pat}*", "*${pat}*")) {
        & $taskkill /F /T /IM $tp *> $null
    }
}

# Services
foreach ($svc in Get-Service -ErrorAction SilentlyContinue) {
    $svcText = ($svc.Name + ' ' + $svc.DisplayName).ToLowerInvariant()
    foreach ($pat in $patterns) {
        if ($pat.Length -ge 2 -and $svcText.Contains($pat)) { & $scExe stop $svc.Name 2>$null; break }
    }
}

# Count after kill
$afterCount = 0
try {
    foreach ($pat in $patterns) {
        Get-Process -ErrorAction SilentlyContinue | Where-Object {
            $_.Id -ne $PID -and -not $protected.Contains(($_.ProcessName.ToLower() -replace '\.exe$','')) -and (
                $_.ProcessName.ToLower() -like "*$pat*" -or ($pat.Length -ge 3 -and $_.ProcessName.ToLower().Contains($pat))
            )
        } | ForEach-Object { $afterCount++ }
    }
} catch {}
$killedCount = $beforeCount - $afterCount
if ($killedCount -lt 0) { $killedCount = 0 }
Write-Host $killedCount

# Elevation if needed
if ($killedCount -eq 0 -and -not $isAdmin -and -not $alreadyElevated -and -not $NoElevate) {
    $argLine = @($patterns | ForEach-Object { "'" + $_.Replace("'", "''") + "'" }) -join ' '
    $moduleManifest = Join-Path $env:USERPROFILE 'Documents\WindowsPowerShell\Modules\CodexProfileFunctions\CodexProfileFunctions.psd1'
    if (-not (Test-Path -LiteralPath $moduleManifest)) { $moduleManifest = 'F:\backup\windowsapps\Modules\CodexProfileFunctions\CodexProfileFunctions.psd1' }
    $inner = "`$env:SKILL_ELEVATED='1'; Import-Module '$moduleManifest' -DisableNameChecking -Force -ErrorAction Stop; Initialize-CodexProfileFunctions; skill -NoElevate $argLine"
    $encoded = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($inner))
    try { Start-Process powershell.exe -Verb RunAs -ArgumentList '-WindowStyle','Hidden','-NoProfile','-ExecutionPolicy','Bypass','-EncodedCommand',$encoded 2>$null } catch {}
}
}

