function global:ccspacefast {
    [CmdletBinding()]
    param(
        [switch]$SelfTest,
        [int]$PerTargetTimeoutSeconds = 120
    )
    $targets = @(
        $env:TEMP,
        (Join-Path $env:LOCALAPPDATA 'Temp')
    ) | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Container) } | Select-Object -Unique
    if ($SelfTest) {
        Write-Host ("CCSPACEFAST_SELFTEST_OK targets={0} heartbeat_ms=250 timeout_s={1}" -f $targets.Count, $PerTargetTimeoutSeconds) -ForegroundColor Green
        return
    }
    $started = Get-Date
    $before = try { [int64](Get-PSDrive -Name C -ErrorAction Stop).Free } catch { [int64]0 }
    $completed = 0
    foreach ($target in $targets) {
        Write-Host ("CCSPACEFAST_PROGRESS stage=starting target=[{0}] completed={1}/{2} elapsed_ms={3}" -f $target, $completed, $targets.Count, [int]((Get-Date)-$started).TotalMilliseconds) -ForegroundColor Cyan
        $job = Start-Job -ArgumentList $target -ScriptBlock {
            param($TargetPath)
            Get-ChildItem -LiteralPath $TargetPath -Force -ErrorAction SilentlyContinue | ForEach-Object {
                Microsoft.PowerShell.Management\Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        $deadline = (Get-Date).AddSeconds($PerTargetTimeoutSeconds)
        try {
            while ($job.State -in @('Running','NotStarted')) {
                if ((Get-Date) -ge $deadline) {
                    Stop-Job -Job $job -ErrorAction SilentlyContinue
                    Write-Host ("CCSPACEFAST_PROGRESS stage=timeout target=[{0}] timeout_s={1}" -f $target, $PerTargetTimeoutSeconds) -ForegroundColor Yellow
                    break
                }
                Write-Host ("CCSPACEFAST_PROGRESS stage=cleaning target=[{0}] completed={1}/{2} elapsed_ms={3}" -f $target, $completed, $targets.Count, [int]((Get-Date)-$started).TotalMilliseconds) -ForegroundColor DarkCyan
                Start-Sleep -Milliseconds 250
                $job = Get-Job -Id $job.Id
            }
            Receive-Job -Job $job -ErrorAction SilentlyContinue | Out-Null
        } finally {
            Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
        }
        $completed++
    }
    $after = try { [int64](Get-PSDrive -Name C -ErrorAction Stop).Free } catch { $before }
    Write-Host ("CCSPACEFAST_OK completed={0}/{1} freed_mb={2:N2} elapsed_ms={3}" -f $completed, $targets.Count, ([math]::Max(0,$after-$before)/1MB), [int]((Get-Date)-$started).TotalMilliseconds) -ForegroundColor Green
}

