# Keep the built-in Copy-Item cmdlet intact; this is the former clipboard helper.
function global:copytext {
    [CmdletBinding()]
    param(
        [Parameter(ValueFromPipeline = $true, Position = 0)]
        [AllowEmptyString()]
        [string[]]$InputObject
    )
    begin { $lines = New-Object 'System.Collections.Generic.List[string]' }
    process { foreach ($line in @($InputObject)) { if ($null -ne $line) { $lines.Add([string]$line) } } }
    end {
        if ($lines.Count -eq 0) {
            Write-Host 'copytext: nothing to copy.' -ForegroundColor Yellow
            return
        }
        Microsoft.PowerShell.Management\Set-Clipboard -Value ($lines -join [Environment]::NewLine)
        Write-Host 'Copied to clipboard.' -ForegroundColor Green
    }
}

# Run the complete generated UNI script so its shared state is initialized in
