# Direct native dispatch keeps first-call and cached-query latency minimal.
function global:dush {
    $exe = 'F:\study\Dev_Toolchain\programming\python\apps\systemTools\sizes\dush.exe'
    if (-not [System.IO.File]::Exists($exe)) { throw "dush executable missing: $exe" }
    & $exe @args
    $exitCode = $LASTEXITCODE
