function global:Initialize-ProfileSystemRestore {
    [CmdletBinding()]
    param([switch]$SelfTest)
    $required = 'VSS','swprv'
    if ($SelfTest) {
        $states = $required | ForEach-Object { Get-Service -Name $_ -ErrorAction Stop }
        Write-Output ("SYSTEM_RESTORE_SELFTEST_OK services={0}" -f (($states | ForEach-Object { "$($_.Name):$($_.StartType)" }) -join ','))
        return
    }
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw 'System Restore setup requires an elevated PowerShell session.'
    }
    Remove-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\SystemRestore' -Name 'DisableSR','DisableConfig' -ErrorAction SilentlyContinue
    Remove-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' -Name 'DisableSR' -ErrorAction SilentlyContinue
    foreach ($name in @('VSS','swprv','SdrSvc')) {
        $service = Get-Service -Name $name -ErrorAction SilentlyContinue
        if ($service -and $service.StartType -eq 'Disabled') { Set-Service -Name $name -StartupType Manual -ErrorAction Stop }
    }
    Enable-ComputerRestore -Drive 'C:\' -ErrorAction Stop
    $enableResult = ([WmiClass]'root\default:SystemRestore').Enable('C:\')
    if ($null -ne $enableResult -and [int]$enableResult.ReturnValue -ne 0) {
        throw "System Restore provider enable failed with code $($enableResult.ReturnValue)."
    }
    foreach ($name in $required) {
        Start-Service -Name $name -ErrorAction Stop
        $service = Get-Service -Name $name -ErrorAction Stop
        if ($service.Status -ne 'Running') { throw "System Restore service '$name' did not start." }
    }
}

function global:lback {
    [CmdletBinding()]
    param([switch]$SelfTest)
    if ($SelfTest) { Initialize-ProfileSystemRestore -SelfTest; Write-Output 'LBACK_SELFTEST_OK'; return }
    Initialize-ProfileSystemRestore
    $points = @(Get-ComputerRestorePoint -ErrorAction Stop | Sort-Object SequenceNumber -Descending)
    if ($points.Count -eq 0) { Write-Host 'No restore points exist yet.' -ForegroundColor Yellow }
    else {
        $i=0
        $points | ForEach-Object {
            $t=[Management.ManagementDateTimeConverter]::ToDateTime($_.CreationTime)
            [PSCustomObject]@{ Order=++$i; Seq=$_.SequenceNumber; Created=$t.ToString('yyyy-MM-dd HH:mm:ss'); Description=$_.Description }
        } | Format-Table -AutoSize
    }
    Write-Host ''
    Write-Host '=== Shadow Storage (total disk used by all backups) ===' -ForegroundColor Green
    & "$env:SystemRoot\System32\vssadmin.exe" list shadowstorage | Select-String 'For volume|Used Shadow|Maximum Shadow'
}

function global:back {
    [CmdletBinding()]
    param([switch]$SelfTest)
    if ($SelfTest) { Initialize-ProfileSystemRestore -SelfTest; Write-Output 'BACK_SELFTEST_OK truthfulVerification=true'; return }
    Write-Host '=== WINDOWS BACKUP - REAL-TIME PROGRESS ===' -ForegroundColor Green
    Write-Host 'BACK_PROGRESS step=1/4 action=enable-system-restore' -ForegroundColor Cyan
    Initialize-ProfileSystemRestore
    Write-Host 'BACK_PROGRESS step=2/4 action=verify-provider' -ForegroundColor Cyan
    $null = Get-ComputerRestorePoint -ErrorAction Stop
    $description = 'MANUAL BACKUP - ' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
    Write-Host 'BACK_PROGRESS step=3/4 action=create-restore-point' -ForegroundColor Cyan
    Checkpoint-Computer -Description $description -RestorePointType MODIFY_SETTINGS -ErrorAction Stop
    Write-Host 'BACK_PROGRESS step=4/4 action=verify-restore-point' -ForegroundColor Cyan
    $point = Get-ComputerRestorePoint -ErrorAction Stop | Where-Object { $_.Description -eq $description } | Select-Object -First 1
    if (-not $point) { throw "Restore point creation was not verified: $description" }
    Write-Host ("BACK_OK sequence={0} description=[{1}]" -f $point.SequenceNumber,$point.Description) -ForegroundColor Green
}


function global:rest {
$sr=[WmiClass]"root\default:SystemRestore";$l=Get-ComputerRestorePoint|Sort-Object SequenceNumber -Descending|Select-Object -First 1;$sr.Restore($l.SequenceNumber);Restart-Computer -Force
}
function global:ConvertTo-HermesMenuOneWordName {
    param([Parameter(ValueFromPipeline = $true, Position = 0)][AllowNull()][object]$Value)
    process {
        $text = [string]$Value
        if ([string]::IsNullOrWhiteSpace($text)) { return '' }
        ($text -replace '[^\p{L}\p{Nd}]+', '').ToLowerInvariant()
    }
}

function global:Rename-HermesMenuDestinationPath {
    param(
        [Parameter(Mandatory = $true, Position = 0)][string]$Path,
        [Parameter(Mandatory = $true, Position = 1)][string]$Name
    )
    if (-not (Test-Path -LiteralPath $Path)) {
        throw "Path not found: $Path"
    }
    $parent = Split-Path -Path $Path -Parent
    if ([string]::IsNullOrWhiteSpace($parent)) {
        throw "Cannot determine parent for path: $Path"
    }
    $safeName = ConvertTo-HermesMenuOneWordName $Name
    if ([string]::IsNullOrWhiteSpace($safeName)) {
        throw "Destination name resolves to empty string: $Name"
    }
    $destination = Join-Path $parent $safeName
    if ($destination -ieq $Path) { return $Path }
    Rename-Item -LiteralPath $Path -NewName $safeName -Force
    return $destination
}

function global:Test-HermesDockerCommanderProfile {
    [CmdletBinding()]
    param([switch]$SkipDockerCliProbe)

    $failures = New-Object 'Collections.Generic.List[string]'
    $required = @(
        'docker','menu','mmenu','mmmenu','qqq','gdbooster','gccleaner',
        'Set-DockerHyperV','rmdocker','dkill','dkill2','dkill3','dkill4','dkill5',
        'redocker','rredocker','Invoke-HermesDockerPreserveRedocker'
    ) + @(1..30 | ForEach-Object { "docker$_" })
    foreach ($name in $required) {
        if (-not (Get-Command -Name $name -ErrorAction SilentlyContinue)) {
            [void]$failures.Add("missing command: $name")
        }
    }

    if (-not $SkipDockerCliProbe) {
        try {
            $dockerVersion = & docker version --format '{{.Server.Version}}' 2>$null
            if ($LASTEXITCODE -ne 0 -or [string]::IsNullOrWhiteSpace(($dockerVersion | Out-String))) {
                [void]$failures.Add('Docker engine is not ready')
            }
        } catch { [void]$failures.Add("Docker engine probe failed: $($_.Exception.Message)") }
    }

    foreach ($probe in @(
        { qqq -SelfTest },
        { Set-DockerHyperV -SelfTest },
        { redocker -SelfTest },
        { rredocker -SelfTest },
        { dkill -SelfTest }
    )) {
        try { & $probe | Out-Host }
        catch { [void]$failures.Add($_.Exception.Message) }
    }

    if ($failures.Count -gt 0) {
        $failures | ForEach-Object { Write-Host "[docker-profile][FAIL] $_" -ForegroundColor Red }
        throw "Docker profile self-test failed with $($failures.Count) issue(s)."
    }
    Write-Host 'DOCKER_PROFILE_SELFTEST_OK routes=current-preservation-safe qqq=docker-container numbered=30' -ForegroundColor Green
}

function global:rws {
    [CmdletBinding()]
    param(
        [string]$Distribution = 'Ubuntu',
        [string]$InstallRoot = 'C:\wsl2\ubuntu',
        [string]$ArchivePath = 'F:\backup\linux\wsl\ubuntu.tar',
        [switch]$Force,
        [switch]$SelfTest
    )
    $wsl = Join-Path $env:SystemRoot 'System32\wsl.exe'
    if ($SelfTest) {
        Write-Output ("RWS_SELFTEST_OK wsl={0} archive={1} mutex=true alwaysRestore=true" -f (Test-Path -LiteralPath $wsl -PathType Leaf),(Test-Path -LiteralPath $ArchivePath -PathType Leaf))
        return
    }
    if (-not (Test-Path -LiteralPath $wsl -PathType Leaf)) { throw "WSL executable not found: $wsl" }
    if (-not (Test-Path -LiteralPath $ArchivePath -PathType Leaf)) { throw "WSL archive not found: $ArchivePath" }
    $mutex = New-Object Threading.Mutex($false, 'Global\CodexProfile-RwsRestore')
    $hasMutex = $false
    try {
        try { $hasMutex = $mutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $hasMutex = $true }
        if (-not $hasMutex) { Write-Host 'RWS_BUSY another restore is already active; no second operation started.' -ForegroundColor Yellow; return }

        $activeOperation = {
            @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
                $_.Name -ieq 'wsl.exe' -and $_.CommandLine -match '(?i)--(?:import|unregister)\b'
            })
        }
        $deadline = [DateTime]::UtcNow.AddMinutes(15)
        while (@(& $activeOperation).Count -gt 0) {
            if ([DateTime]::UtcNow -ge $deadline) { throw 'Timed out waiting for the active WSL registration operation.' }
            Write-Host 'RWS_PROGRESS stage=waiting-for-existing-operation' -ForegroundColor DarkCyan
            [Threading.Thread]::Sleep(1000)
        }

        $registry = @(Get-ChildItem 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Lxss' -ErrorAction SilentlyContinue | ForEach-Object {
            Get-ItemProperty $_.PSPath
        } | Where-Object { $_.DistributionName -ieq $Distribution } | Select-Object -First 1)
        $vhd = Join-Path $InstallRoot 'ext4.vhdx'
        Write-Host "RWS_PROGRESS stage=restore-requested distribution='$Distribution' archive='$ArchivePath'" -ForegroundColor Cyan

        $registered = @(& $wsl --list --quiet 2>$null | ForEach-Object { (([string]$_) -replace [char]0,'').Trim() } | Where-Object { $_ })
        if ($registered -contains $Distribution) {
            Write-Host 'RWS_PROGRESS stage=unregistering' -ForegroundColor Cyan
            & $wsl --terminate $Distribution 2>$null
            & $wsl --unregister $Distribution
            if ($LASTEXITCODE -ne 0) { throw "WSL unregister failed with exit code $LASTEXITCODE." }
        }
        $absentDeadline = [DateTime]::UtcNow.AddMinutes(3)
        do {
            $stillRegistered = @(& $wsl --list --quiet 2>$null | ForEach-Object { (([string]$_) -replace [char]0,'').Trim() }) -contains $Distribution
            if (-not $stillRegistered) { break }
            if ([DateTime]::UtcNow -ge $absentDeadline) { throw "WSL unregister did not finish for '$Distribution'." }
            Write-Host 'RWS_PROGRESS stage=waiting-for-unregister' -ForegroundColor DarkCyan
            [Threading.Thread]::Sleep(1000)
        } while ($true)

        if (Test-Path -LiteralPath $InstallRoot) { Remove-Item -LiteralPath $InstallRoot -Recurse -Force -ErrorAction Stop }
        $parent = Split-Path -Parent $InstallRoot
        if (-not (Test-Path -LiteralPath $parent -PathType Container)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
        Write-Host 'RWS_PROGRESS stage=importing' -ForegroundColor Cyan
        $process = Start-Process -FilePath $wsl -ArgumentList @('--import',$Distribution,$InstallRoot,$ArchivePath,'--version','2') -PassThru -NoNewWindow
        $null = $process.Handle
        while (-not $process.HasExited) {
            $bytes = if (Test-Path -LiteralPath $vhd -PathType Leaf) { (Get-Item -LiteralPath $vhd).Length } else { 0 }
            Write-Host ("RWS_PROGRESS stage=importing bytes={0}" -f $bytes) -ForegroundColor DarkCyan
            [Threading.Thread]::Sleep(1000)
            $process.Refresh()
        }
        $process.WaitForExit(); $process.Refresh(); $exitCode = [int]$process.ExitCode
        if ($exitCode -ne 0) { throw "WSL import failed with exit code $exitCode." }
        $verified = @(& $wsl --list --quiet | ForEach-Object { (([string]$_) -replace [char]0,'').Trim() } | Where-Object { $_ })
        if ($verified -notcontains $Distribution -or -not (Test-Path -LiteralPath $vhd -PathType Leaf)) { throw "WSL restore verification failed for '$Distribution'." }
        Write-Host "RWS_OK distribution='$Distribution' root='$InstallRoot' archive='$ArchivePath'" -ForegroundColor Green
    } finally {
        if ($hasMutex) { [void]$mutex.ReleaseMutex() }
        $mutex.Dispose()
    }
}

function global:rwsl {
    [CmdletBinding()]
    param(
        [string]$Distribution = 'Ubuntu',
        [string]$InstallRoot = 'C:\wsl2\ubuntu',
        [string]$ArchivePath = 'F:\backup\linux\wsl\ubuntu.tar',
        [switch]$Force,
        [switch]$SelfTest,
        [Parameter(ValueFromRemainingArguments = $true)][object[]]$Arguments
    )
    if ($SelfTest) { & global:rws -SelfTest; Write-Output 'RWSL_SELFTEST_OK'; return }
    & global:rws -Distribution $Distribution -InstallRoot $InstallRoot -ArchivePath $ArchivePath -Force:$Force
    & "$env:SystemRoot\System32\wsl.exe" -d $Distribution @Arguments
}

function global:wsls {
    [CmdletBinding()]
    param([switch]$SelfTest)
    $active = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -ieq 'wsl.exe' -and $_.CommandLine -match '(?i)--(?:import|unregister)\b' })
    if ($SelfTest) { Write-Output ("WSLS_SELFTEST_OK activeRegistrationOperations={0}" -f $active.Count); return }
    if ($active.Count -gt 0) { Write-Host 'WSLS_BUSY registration is active; shutdown was not attempted.' -ForegroundColor Yellow; return }
    & "$env:SystemRoot\System32\wsl.exe" --shutdown
    if ($LASTEXITCODE -ne 0) { throw "WSL shutdown failed with exit code $LASTEXITCODE." }
    Write-Host 'WSLS_OK shutdown-complete' -ForegroundColor Green
}

# Restored from the latest preserved profile backup.
function global:addcd {
    [CmdletBinding()]
    param()

    $location = Get-Location
    if ($location.Provider.Name -ne 'FileSystem') {
        throw "addcd can only save shortcuts for FileSystem locations. Current provider: '$($location.Provider.Name)'."
    }
    $targetPath = [string]$location.ProviderPath
    if ([string]::IsNullOrWhiteSpace($targetPath)) { throw 'addcd could not resolve the current FileSystem path.' }
    $folderName = Split-Path -Leaf $targetPath.TrimEnd('\')
    if ([string]::IsNullOrWhiteSpace($folderName)) { throw "addcd cannot create a five-letter shortcut for the FileSystem root '$targetPath'." }
    $letters = @([regex]::Matches($folderName, '[A-Za-z]') | ForEach-Object { $_.Value })
    if ($letters.Count -lt 3) { throw "addcd requires a folder name with at least three letters. Current folder: '$folderName'." }
    $functionName = 'cd' + (($letters | Select-Object -First 3) -join '').ToLowerInvariant()
    $escapedTargetPath = $targetPath.Replace("'", "''")
    $shortcutBody = [scriptblock]::Create("Set-Location -LiteralPath '$escapedTargetPath'")
    $existing = Get-Command -Name $functionName -CommandType Function -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($existing) {
        $helper = 'F:\study\Learning\01\01\Shells\powershell\profile-functions\shells\powershell\profile-helpers\Mvfunc\Invoke-mvfunc.ps1'
        $receipt = & $helper -Name $functionName -Replacement $shortcutBody
        $action = 'updated'
    }
    else {
        $helper = 'F:\study\Learning\01\01\Shells\powershell\profile-functions\shells\powershell\profile-helpers\Addfunc\Invoke-addfunc.ps1'
        $receipt = & $helper -Name $functionName -Body $shortcutBody
        $action = 'created'
    }
    # The persistent mutation is rebuilt into the next cache generation. Also
    # install the shortcut in this exact shell so addcd is useful immediately.
    $globalDefinition = [scriptblock]::Create("function global:$functionName { Set-Location -LiteralPath '$escapedTargetPath' }")
    & $globalDefinition
    [pscustomobject]@{ Status='ADDCD_OK'; Action=$action; Name=$functionName; Path=$targetPath; Mutation='PROFILE_FUNCTION_MUTATION_OK' }
}

