# Restored convenience commands from the latest complete profile backup.
function global:ps50 {
    $st = [AppDomain]::CurrentDomain.GetData('CodexProfileFunctions.RuntimeState.6476b887-1198-4d61-897e-f4535f8986ef.v2')
    if ($st -is [hashtable] -and -not [string]::IsNullOrWhiteSpace([string]$st.RuntimeSnapshotPath)) {
        $files = @([string]$st.RuntimeSnapshotPath) + @($st.SupplementalRuntimePaths)
    } else {
        $r = 'C:\Users\micha\Documents\WindowsPowerShell\ProfileSources\ps5-profile-portable'
        $files = @("$r\Microsoft.PowerShell_profile.runtime.ps1", "$r\Microsoft.PowerShell_profile.ps1", "$r\legacy-safe-functions\profile-wrappers.ps1", "$r\legacy-safe-functions\before.ps1")
    }
    $map = @{}
    foreach ($f in $files) {
        if (-not (Test-Path -LiteralPath $f -PathType Leaf)) { continue }
        $t = $null; $e = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile($f, [ref]$t, [ref]$e)
        if (@($e).Count -gt 0) { continue }
        $ast.FindAll({
            param($node)
            if ($node -isnot [System.Management.Automation.Language.FunctionDefinitionAst]) { return $false }
            $parent = $node.Parent
            while ($parent) {
                if ($parent -is [System.Management.Automation.Language.FunctionDefinitionAst]) { return $false }
                $parent = $parent.Parent
            }
            return $true
        }, $true) | ForEach-Object {
            $name = $_.Name -replace '^(?i:global:)', ''
            $map[$name] = [pscustomobject]@{ Name = $name; Lines = $_.Extent.EndLineNumber - $_.Extent.StartLineNumber + 1; File = $f }
        }
    }
    $map.Values | Sort-Object @{ Expression = 'Lines'; Descending = $true }, @{ Expression = 'Name'; Descending = $false } | Select-Object -First 50 | Format-Table -AutoSize
}

