function global:ddown {
    [CmdletBinding()]
    param(
        [switch]$SelfTest,
        [Parameter(ValueFromRemainingArguments = $true)][string[]]$GameNames
    )
    $script = 'F:\study\projects\SystemMonitor\PSProcLasso\Windows\Applications\Gaming\DownloadManagers\qBittorrent\Automation\GameTorrentDownloader\a.ps1'
    if (-not [IO.File]::Exists($script)) { throw "ddown launcher not found: $script" }
    $tokens=$null;$errors=$null
    [void][Management.Automation.Language.Parser]::ParseFile($script,[ref]$tokens,[ref]$errors)
    if ($errors.Count) { throw "ddown launcher parse failed: $($errors[0].Message)" }
    if ($SelfTest) { Write-Output "DDOWN_SELFTEST_OK script=[$script]"; return }
    $ps5 = Join-Path ([Environment]::SystemDirectory) 'WindowsPowerShell\v1.0\powershell.exe'
    & $ps5 -NoLogo -NoProfile -ExecutionPolicy Bypass -File $script @GameNames
    if ($LASTEXITCODE -ne 0) { throw "ddown failed with exit code $LASTEXITCODE" }
}

