function fff2 {
    [CmdletBinding()]
    param(
        [switch]$SkipWindowsRepair,
        [ValidatePattern('^[A-Za-z]:$')][string[]]$Drive,
        [switch]$WhatIf
    )
    $ErrorActionPreference = 'Stop'
    function Test-Fff2Administrator {
        ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
            [Security.Principal.WindowsBuiltInRole]::Administrator)
    }
    function Invoke-Fff2Native([string]$Tool, [string[]]$Options) {
        Write-Host ('[{0}] START {1} {2}' -f (Get-Date -Format o), $Tool, ($Options -join ' ')) -ForegroundColor Cyan
        $start = New-Object Diagnostics.ProcessStartInfo
        $start.FileName = Join-Path $env:SystemRoot ('System32\' + $Tool)
        $start.Arguments = $Options -join ' '
        $start.UseShellExecute = $false
        # No native tool can wait for interactive input. Output remains live.
        $start.RedirectStandardInput = $true
        $process = New-Object Diagnostics.Process
        $process.StartInfo = $start
        try {
            if (-not $process.Start()) { throw "Could not start $Tool" }
            $process.StandardInput.Close()
            $process.WaitForExit()
            $code = $process.ExitCode
            Write-Host ('[{0}] END {1}: exit {2}' -f (Get-Date -Format o), $Tool, $code)
            return $code
        } finally { $process.Dispose() }
    }
    function Test-Fff2Scheduled([string]$Volume) {
        $entries = @((Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name BootExecute).BootExecute)
        $target = [regex]::Escape('\??\' + $Volume)
        return @($entries | Where-Object { $_ -match ('(?i)^autocheck\s+autochk\s+/(?:p|m)\s+' + $target + '\s*$') }).Count -gt 0
    }
    function Request-Fff2BootRepair([string]$Volume) {
        if (-not (Test-Fff2Scheduled $Volume)) {
            $code = Invoke-Fff2Native 'chkntfs.exe' @('/c', $Volume)
            if ($code -ne 0) { throw "Could not schedule $Volume (chkntfs exit $code)." }
            if (-not (Test-Fff2Scheduled $Volume)) { throw "Boot check for $Volume could not be verified." }
        }
        Write-Host "$Volume : PendingRestart - boot check is scheduled." -ForegroundColor Yellow
    }
    $disks = @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' | Sort-Object DeviceID)
    if ($Drive) {
        foreach ($requested in $Drive) {
            if ($requested -notin $disks.DeviceID) { throw "Fixed drive $requested was not found." }
        }
        $disks = @($disks | Where-Object { $_.DeviceID -in $Drive })
    }
    if (-not $disks.Count) { throw 'No fixed drives were found; disk checks cannot run.' }
    # Explicit parameter: the profile's lazy wrapper copies parameters but not
    # CmdletBinding attributes, so a common SupportsShouldProcess switch is lost.
    if ($WhatIf) {
        Write-Host ('What if: Run repairs on {0}; schedule unavailable checks for next restart. SkipWindowsRepair={1}' -f ($disks.DeviceID -join ', '), $SkipWindowsRepair)
        return
    }
    if (-not (Test-Fff2Administrator)) { throw 'Run fff2 in PowerShell as Administrator.' }
    # Avoid overlapping servicing operations and concurrent fff2 boot-schedule writes.
    $mutex = New-Object Threading.Mutex($false, 'Global\Fff2Repair')
    $ownsMutex = $false
    try {
        try { $ownsMutex = $mutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $ownsMutex = $true }
        if (-not $ownsMutex) { throw 'Another fff2 repair is already running.' }
        $busy = @(Get-Process -Name dism,sfc,chkdsk -ErrorAction SilentlyContinue)
        if ($busy.Count) { throw ('A repair is already running: ' + (($busy | ForEach-Object { '{0} (PID {1})' -f $_.Name,$_.Id }) -join ', ')) }
        $results = New-Object 'System.Collections.Generic.List[object]'
        if (-not $SkipWindowsRepair) {
            $steps = @(
                @{ Name = 'Windows image repair'; Tool = 'DISM.exe'; Options = @('/Online','/Cleanup-Image','/RestoreHealth','/NoRestart') },
                @{ Name = 'System file repair'; Tool = 'sfc.exe'; Options = @('/scannow') },
                @{ Name = 'Windows image health'; Tool = 'DISM.exe'; Options = @('/Online','/Cleanup-Image','/CheckHealth','/NoRestart') }
            )
            foreach ($step in $steps) {
                $code = $null
                try {
                    $code = Invoke-Fff2Native $step.Tool $step.Options
                    $status = if ($code -eq 0) { 'Completed' } elseif ($step.Tool -eq 'DISM.exe' -and $code -eq 3010) { 'PendingRestart' } else { 'Failed' }
                    $detail = 'See native output above.'
                } catch { $status = 'Failed'; $detail = $_.Exception.Message }
                $results.Add([pscustomobject]@{ Step = $step.Name; Status = $status; ExitCode = $code; Detail = $detail })
            }
        }
        foreach ($disk in $disks) {
            $code = $null
            try {
                if ($disk.FileSystem -notin @('NTFS','exFAT','FAT32','FAT')) { throw "Unsupported or unreadable filesystem: $($disk.FileSystem)" }
                if (Test-Fff2Scheduled $disk.DeviceID) {
                    $status = 'PendingRestart'; $detail = 'Existing boot check verified; not yet repaired.'
                } else {
                    # FAT/exFAT lack /scan. Very full NTFS volumes cannot create
                    # the snapshot /scan requires; use a snapshot-free check there.
                    $options = @($disk.DeviceID)
                    $onlineScan = $disk.FileSystem -eq 'NTFS' -and ($null -eq $disk.FreeSpace -or $disk.FreeSpace -ge 64MB)
                    if ($onlineScan) { $options += '/scan' }
                    $code = Invoke-Fff2Native 'chkdsk.exe' $options
                    if ($onlineScan -and $code -eq 11) {
                        Write-Host "$($disk.DeviceID) snapshot unavailable; retrying a snapshot-free check."
                        $onlineScan = $false
                        $code = Invoke-Fff2Native 'chkdsk.exe' @($disk.DeviceID)
                    }
                    if ($code -eq 0 -or ($onlineScan -and $code -eq 1)) {
                        $status = 'Completed'
                        $detail = if ($onlineScan) { 'Online disk check completed.' } else { 'Snapshot-free read-only check completed.' }
                    } else {
                        Request-Fff2BootRepair $disk.DeviceID
                        $status = 'PendingRestart'; $detail = "Scan exit $code; boot check verified, repair pending."
                    }
                }
            } catch { $status = 'Failed'; $detail = $_.Exception.Message }
            $results.Add([pscustomobject]@{ Step = $disk.DeviceID; Status = $status; ExitCode = $code; Detail = $detail })
        }
        $failed = @($results | Where-Object Status -eq 'Failed').Count
        $pending = @($results | Where-Object Status -eq 'PendingRestart').Count
        $overall = if ($failed) { 'Incomplete' } elseif ($pending) { 'PendingRestart' } else { 'Completed' }
        $global:Fff2LastResult = [pscustomobject]@{ Status = $overall; Failed = $failed; PendingRestart = $pending; Results = $results.ToArray() }
        $global:LASTEXITCODE = if ($failed) { 1 } elseif ($pending) { 3010 } else { 0 }
        $results | Format-Table Step,Status,ExitCode,Detail -AutoSize -Wrap | Out-Host
        Write-Host "fff2: $overall ($failed failed, $pending pending restart)."
        if ($pending) { Write-Host 'Restart when ready to let Windows run the scheduled checks; rerun fff2 -SkipWindowsRepair afterward to verify.' -ForegroundColor Yellow }
        return $global:Fff2LastResult
    } finally {
        if ($ownsMutex) { $mutex.ReleaseMutex() }
        $mutex.Dispose()
    }
}

