function ffit {
[CmdletBinding()]
param([switch]$CheckOnly)

$ErrorActionPreference = 'Stop'
$vbsScript = 'F:\backup\windowsapps\install\VBS.cmd'
$cmdExe = Join-Path $env:SystemRoot 'System32\cmd.exe'
$dsregExe = Join-Path $env:SystemRoot 'System32\dsregcmd.exe'
$bcdEdit = Join-Path $env:SystemRoot 'System32\bcdedit.exe'
foreach ($requiredPath in @($vbsScript, $cmdExe, $dsregExe, $bcdEdit)) {
    if (-not (Test-Path -LiteralPath $requiredPath -PathType Leaf)) {
        throw "ffit: required path not found: $requiredPath"
    }
}

$registration = @(& $dsregExe /status 2>&1)
$registrationExit = [int]$LASTEXITCODE
if ($registrationExit -ne 0) {
    throw "ffit: Windows Hello status query failed (exit $registrationExit)."
}
$ngcLines = @($registration | Where-Object { $_ -match '^\s*NgcSet\s*:\s*(YES|NO)\s*$' })
if ($ngcLines.Count -ne 1) {
    throw 'ffit: Windows Hello state could not be verified; no changes applied.'
}
$helloEnrolled = [bool]($ngcLines[0] -match ':\s*YES\s*$')
$managed = @($registration | Where-Object { $_ -match '^\s*(AzureAdJoined|DomainJoined)\s*:\s*YES\s*$' }).Count -gt 0

function Get-FfitBcdTarget {
    param([string]$BcdEditPath)

    $firmware = @(& $BcdEditPath /enum firmware /v 2>&1)
    $firmwareExit = [int]$LASTEXITCODE
    $bootDrives = New-Object 'Collections.Generic.List[string]'
    if ($firmwareExit -eq 0) {
        $firmwareText = $firmware -join "`n"
        foreach ($block in ($firmwareText -split '(?m)(?=^Firmware Application)')) {
            if ($block -match '(?is)device\s+partition=([A-Za-z]:)\s*.*?path\s+\\EFI\\Microsoft\\Boot\\bootmgfw\.efi') {
                $drive = $Matches[1].ToUpperInvariant()
                if (-not $bootDrives.Contains($drive)) {
                    [void]$bootDrives.Add($drive)
                }
            }
        }
    }

    foreach ($volume in @(Get-CimInstance Win32_Volume -ErrorAction SilentlyContinue | Where-Object {
        $_.DriveLetter -and $_.FileSystem -eq 'FAT32'
    })) {
        $drive = ([string]$volume.DriveLetter).TrimEnd('\').ToUpperInvariant()
        if ($drive -and -not $bootDrives.Contains($drive)) {
            [void]$bootDrives.Add($drive)
        }
    }

    $systemDrive = [string]$env:SystemDrive
    if ([string]::IsNullOrWhiteSpace($systemDrive)) { $systemDrive = 'C:' }
    $drivePattern = [regex]::Escape($systemDrive.TrimEnd('\'))
    foreach ($drive in $bootDrives) {
        $candidate = Join-Path $drive 'EFI\Microsoft\Boot\BCD'
        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) { continue }

        $all = @(& $BcdEditPath /store $candidate /enum all /v 2>&1)
        $enumExit = [int]$LASTEXITCODE
        if ($enumExit -ne 0) { continue }
        $allText = $all -join "`n"
        $blocks = $allText -split '(?m)(?=^Windows Boot Loader\s*$)'
        foreach ($block in $blocks) {
            $loaderId = $null
            if ($block -match '(?m)^\s*identifier\s+(\{[^}]+\})\s*$') {
                $loaderId = $Matches[1]
            }
            if ($null -eq $loaderId) { continue }
            $hasDevice = $block -match ("(?m)^\s*device\s+partition=" + $drivePattern + '\s*$')
            $hasOsDevice = $block -match ("(?m)^\s*osdevice\s+partition=" + $drivePattern + '\s*$')
            $hasSystemRoot = $block -match '(?m)^\s*systemroot\s+\\Windows\s*$'
            if (-not ($hasDevice -and $hasOsDevice -and $hasSystemRoot)) { continue }

            $loader = @(& $BcdEditPath /store $candidate /enum $loaderId /v 2>&1)
            $loaderExit = [int]$LASTEXITCODE
            if ($loaderExit -ne 0) { continue }
            $hypervisorLaunch = $null
            $vsmLaunch = $null
            foreach ($line in $loader) {
                if ($line -match '^\s*hypervisorlaunchtype\s+(\S+)\s*$') { $hypervisorLaunch = $Matches[1] }
                if ($line -match '^\s*vsmlaunchtype\s+(\S+)\s*$') { $vsmLaunch = $Matches[1] }
            }
            return [pscustomobject]@{
                Store = $candidate
                LoaderId = $loaderId
                HypervisorLaunchType = $hypervisorLaunch
                VsmLaunchType = $vsmLaunch
            }
        }
    }

    throw 'ffit: no usable EFI BCD store containing the running C: Windows loader was found.'
}

$bcd = Get-FfitBcdTarget -BcdEditPath $bcdEdit
$deviceGuard = Get-CimInstance -Namespace 'root\Microsoft\Windows\DeviceGuard' -ClassName Win32_DeviceGuard -ErrorAction SilentlyContinue
$computerSystem = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
$vbsStatus = $null
$hypervisorPresent = $null
if ($deviceGuard) { $vbsStatus = $deviceGuard.VirtualizationBasedSecurityStatus }
if ($computerSystem) { $hypervisorPresent = $computerSystem.HypervisorPresent }
$status = 'ReadyForCompatibilityWorkflow'
if ($helloEnrolled -or $managed) { $status = 'NeedsUserAction' }
$preflight = [pscustomobject]@{
    Status = $status
    WindowsHelloEnrolled = $helloEnrolled
    DomainOrAzureJoined = $managed
    CompatibilityScript = $vbsScript
    BcdStore = $bcd.Store
    BcdLoaderId = $bcd.LoaderId
    BcdHypervisorLaunchType = $bcd.HypervisorLaunchType
    BcdVsmLaunchType = $bcd.VsmLaunchType
    HypervisorPresent = $hypervisorPresent
    VirtualizationBasedSecurityStatus = $vbsStatus
    RequiresRestartAndStartupSelection = $true
}
if ($CheckOnly) { return $preflight }
if ($managed) { throw 'ffit: domain/Azure-joined device detected; review the security policy before changing boot security.' }
if ($helloEnrolled) { throw 'ffit: Windows Hello is enrolled. Confirm password sign-in and remove PIN/biometrics in Sign-in options before running VBS.cmd.' }
if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    throw 'ffit: open PowerShell as Administrator, then run ffit.'
}

$workRoot = 'F:\backup\windowsapps\install\ffit-work'
$patchedScript = $null
$oldTemp = $env:TEMP
$oldTmp = $env:TMP
try {
    New-Item -ItemType Directory -Path $workRoot -Force | Out-Null
    $patchedScript = Join-Path $workRoot ('VBS-ffit-' + [guid]::NewGuid().ToString('N') + '.cmd')
    $sourceText = [IO.File]::ReadAllText($vbsScript)
    $bcdToken = 'bcdedit /store "' + $bcd.Store + '" '
    $patchedText = $sourceText -replace '(?i)\bbcdedit(?=\s)', $bcdToken
    $patchedText = $patchedText -replace '(?i)\{current\}', $bcd.LoaderId
    $patchedText = $patchedText -replace '(?i)bcdedit /store "[^"]+" /set hypervisorlaunchtype', ('bcdedit /store "' + $bcd.Store + '" /set ' + $bcd.LoaderId + ' hypervisorlaunchtype')
    $patchedText = $patchedText -replace '(?i)bcdedit /store "[^"]+" /set vsmlaunchtype', ('bcdedit /store "' + $bcd.Store + '" /set ' + $bcd.LoaderId + ' vsmlaunchtype')
    $patchedBcdCount = [regex]::Matches($patchedText, '(?i)\bbcdedit\s+/store\s+').Count
    if ($patchedBcdCount -lt 10 -or $patchedText -match '(?im)^\s*bcdedit\s+/set\s+hypervisorlaunchtype') {
        throw 'ffit: generated compatibility script did not receive the complete BCD-store patch.'
    }
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [IO.File]::WriteAllText($patchedScript, $patchedText, $utf8NoBom)

    $env:TEMP = $workRoot
    $env:TMP = $workRoot
    Write-Progress -Id 784 -Activity 'FitGirl compatibility workflow' -Status 'Windows Hello and EFI BCD preflight verified' -PercentComplete 10
    Write-Host ('FFIT_PROGRESS stage=efi-bcd-preflight-verified store=' + $bcd.Store + ' loader=' + $bcd.LoaderId) -ForegroundColor Cyan
    Write-Progress -Id 784 -Activity 'FitGirl compatibility workflow' -Status 'Starting corrected VBS compatibility script' -PercentComplete 85
    Write-Host 'FFIT_PROGRESS stage=starting-corrected-vbs-compatibility-script' -ForegroundColor Cyan
    & $cmdExe /d /c "`"$patchedScript`" -qedit"
    $vbsExit = [int]$LASTEXITCODE
    if ($vbsExit -ne 0) { throw "ffit: VBS.cmd failed with exit code $vbsExit." }

    $afterLoader = @(& $bcdEdit /store $bcd.Store /enum $bcd.LoaderId /v 2>&1)
    $afterExit = [int]$LASTEXITCODE
    $hypervisorOff = @($afterLoader | Where-Object { $_ -match '^\s*hypervisorlaunchtype\s+off\s*$' }).Count -gt 0
    if ($afterExit -ne 0 -or -not $hypervisorOff) {
        throw 'ffit: compatibility script exited, but the correct EFI BCD loader was not staged with hypervisorlaunchtype=Off.'
    }
    Write-Progress -Id 784 -Activity 'FitGirl compatibility workflow' -Status 'Boot change staged; restart still required' -PercentComplete 100
    Write-Host ('FFIT_PENDING_RESTART bcd_store=' + $bcd.Store + ' loader=' + $bcd.LoaderId + ' hypervisorlaunchtype=Off') -ForegroundColor Green
    Write-Host 'FFIT_WORKFLOW_EXITED: restart and startup selection are still required before the disabled state can be verified.' -ForegroundColor Yellow
}
finally {
    if ($null -eq $oldTemp) { Remove-Item Env:TEMP -ErrorAction SilentlyContinue } else { $env:TEMP = $oldTemp }
    if ($null -eq $oldTmp) { Remove-Item Env:TMP -ErrorAction SilentlyContinue } else { $env:TMP = $oldTmp }
    if ($patchedScript -and (Test-Path -LiteralPath $patchedScript -PathType Leaf)) {
        Remove-Item -LiteralPath $patchedScript -Force -ErrorAction SilentlyContinue
    }
    Write-Progress -Id 784 -Activity 'FitGirl compatibility workflow' -Completed
}
}



function OC {
[CmdletBinding()]
param(
    [Parameter(ValueFromRemainingArguments = $true)]
    [string[]]$Arguments
)

$scriptPath = 'F:\backup\windowsapps\installed\OpenCodeRuntime\Invoke-OpenCodeCli.ps1'
if (-not (Test-Path -LiteralPath $scriptPath -PathType Leaf)) {
    throw "OpenCode F: launcher is missing: $scriptPath. Run GETOC2 first."
}

& $scriptPath @Arguments
}

function GETOC2 {
[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'

$runtimeRoot = 'F:\backup\windowsapps\installed\OpenCodeRuntime'
$nodeRuntimeCandidates = @(
    'F:\backup\windowsapps\installed\Codex-MultiSession-Monitor\runtime\node',
    'F:\backup\windowsapps\installed\Omniroute\runtime'
)

$nodeExe = $null
$npmCmd = $null
foreach ($runtimeDirectory in $nodeRuntimeCandidates) {
    $candidateNode = Join-Path $runtimeDirectory 'node.exe'
    $candidateNpm = Join-Path $runtimeDirectory 'npm.cmd'
    if ((Test-Path -LiteralPath $candidateNode -PathType Leaf) -and
        (Test-Path -LiteralPath $candidateNpm -PathType Leaf)) {
        $nodeExe = $candidateNode
        $npmCmd = $candidateNpm
        break
    }
}
if (-not $nodeExe -or -not $npmCmd) {
    throw "GETOC2: no complete Node.js/npm runtime was found on F:. Checked: $($nodeRuntimeCandidates -join '; ')"
}

$npmPrefix = Join-Path $runtimeRoot 'npm-global'
$dataRoot = Join-Path $runtimeRoot 'data'
$npmCache = Join-Path $runtimeRoot 'npm-cache'
$npmUserConfig = Join-Path $runtimeRoot 'npmrc'
$nodeDirectory = Split-Path -Parent $nodeExe
$managedDirectories = @(
    $runtimeRoot,
    $npmPrefix,
    $dataRoot,
    $npmCache,
    (Join-Path $dataRoot 'browser'),
    (Join-Path $dataRoot 'config')
)
foreach ($directory in $managedDirectories) {
    if (-not (Test-Path -LiteralPath $directory -PathType Container)) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }
}

$userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
$userPathParts = @()
if ($userPath) {
    $userPathParts = @($userPath -split ';' | Where-Object {
        -not [string]::IsNullOrWhiteSpace($_)
    })
}
$wantedUserPathParts = @($npmPrefix, $nodeDirectory)
$dedupedUserPathParts = New-Object 'System.Collections.Generic.List[string]'
foreach ($part in ($wantedUserPathParts + $userPathParts)) {
    if (-not [string]::IsNullOrWhiteSpace($part) -and
        -not $dedupedUserPathParts.Contains($part.TrimEnd('\'))) {
        [void]$dedupedUserPathParts.Add($part.TrimEnd('\'))
    }
}
$newUserPath = $dedupedUserPathParts -join ';'
if ($newUserPath -ne $userPath) {
    [Environment]::SetEnvironmentVariable('Path', $newUserPath, 'User')
}

$processEnvironmentNames = @(
    'PATH',
    'npm_config_prefix',
    'npm_config_cache',
    'npm_config_userconfig'
)
$oldProcessEnvironment = @{}
foreach ($name in $processEnvironmentNames) {
    $oldProcessEnvironment[$name] = [Environment]::GetEnvironmentVariable($name, 'Process')
}

$processPathParts = @($npmPrefix, $nodeDirectory)
if ($env:Path) {
    $processPathParts += @($env:Path -split ';' | Where-Object {
        -not [string]::IsNullOrWhiteSpace($_)
    })
}
[Environment]::SetEnvironmentVariable('PATH', ($processPathParts -join ';'), 'Process')
[Environment]::SetEnvironmentVariable('npm_config_prefix', $npmPrefix, 'Process')
[Environment]::SetEnvironmentVariable('npm_config_cache', $npmCache, 'Process')
[Environment]::SetEnvironmentVariable('npm_config_userconfig', $npmUserConfig, 'Process')

function Test-GetOc2OpenCode {
    param([Parameter(Mandatory = $true)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return $null
    }
    try {
        $versionOutput = @(& $Path '--version' 2>$null)
        $exitCode = $LASTEXITCODE
        $version = if ($versionOutput.Count -gt 0) { [string]$versionOutput[0] } else { '' }
        if ($exitCode -eq 0 -and $version.Trim() -match '^\d+\.\d+\.\d+') {
            return [pscustomobject]@{ Path = $Path; Version = $version.Trim() }
        }
    }
    catch {
    }
    return $null
}

function Resolve-GetOc2OpenCode {
    $candidatePaths = @(
        (Join-Path $npmPrefix 'opencode.cmd'),
        (Join-Path $npmPrefix 'opencode.exe'),
        (Join-Path $npmPrefix 'node_modules\opencode-ai\node_modules\opencode-windows-x64\bin\opencode.exe'),
        (Join-Path $npmPrefix 'node_modules\opencode-ai\node_modules\opencode-windows-x64-baseline\bin\opencode.exe'),
        (Join-Path $npmPrefix 'node_modules\opencode-ai\node_modules\opencode-windows-arm64\bin\opencode.exe')
    )
    foreach ($candidate in $candidatePaths) {
        $probe = Test-GetOc2OpenCode -Path $candidate
        if ($probe) {
            return $probe
        }
    }
    return $null
}

try {
    Write-Output 'GETOC2_PROGRESS stage=starting'
    $openCodeProbe = Resolve-GetOc2OpenCode
    if (-not $openCodeProbe) {
        Write-Output 'GETOC2_PROGRESS stage=installing-opencode'
        & $npmCmd install -g opencode-ai --silent
        $installExitCode = $LASTEXITCODE
        if ($installExitCode -ne 0) {
            throw "GETOC2: OpenCode installation failed with exit code $installExitCode."
        }
        $openCodeProbe = Resolve-GetOc2OpenCode
    }
    if (-not $openCodeProbe) {
        throw 'GETOC2: installed OpenCode has no working Windows binary in the F: runtime.'
    }
    Write-Output "GETOC2_PROGRESS stage=opencode-ready path=$($openCodeProbe.Path) version=$($openCodeProbe.Version)"

    $npmRootOutput = @(& $npmCmd root -g 2>$null)
    if ($LASTEXITCODE -ne 0 -or $npmRootOutput.Count -eq 0) {
        throw 'GETOC2: npm could not resolve the F: global package root.'
    }
    $npmRoot = ([string]$npmRootOutput[0]).Trim()
    if (-not $npmRoot -or $npmRoot -notlike 'F:\*') {
        throw "GETOC2: npm returned a non-F: global root: $npmRoot"
    }

    $packageName = '@different-ai/opencode-browser'
    $packageVersion = '4.6.1'
    $packageRoot = Join-Path $npmRoot '@different-ai\opencode-browser'
    $packageJsonPath = Join-Path $packageRoot 'package.json'
    $browserPluginReady = $false
    if (Test-Path -LiteralPath $packageJsonPath -PathType Leaf) {
        try {
            $packageJson = Get-Content -LiteralPath $packageJsonPath -Raw | ConvertFrom-Json
            $browserPluginReady = (
                [string]$packageJson.version -eq $packageVersion -and
                (Test-Path -LiteralPath (Join-Path $packageRoot 'bin\broker.cjs') -PathType Leaf) -and
                (Test-Path -LiteralPath (Join-Path $packageRoot 'bin\native-host.cjs') -PathType Leaf) -and
                (Test-Path -LiteralPath (Join-Path $packageRoot 'extension\manifest.json') -PathType Leaf)
            )
        }
        catch {
            $browserPluginReady = $false
        }
    }
    if (-not $browserPluginReady) {
        Write-Output 'GETOC2_PROGRESS stage=installing-browser-plugin'
        & $npmCmd install -g "$packageName@$packageVersion" --silent
        $pluginInstallExitCode = $LASTEXITCODE
        if ($pluginInstallExitCode -ne 0) {
            throw "GETOC2: browser plugin installation failed with exit code $pluginInstallExitCode."
        }
    }
    if (-not (Test-Path -LiteralPath $packageRoot -PathType Container)) {
        throw "GETOC2: browser plugin root is missing: $packageRoot"
    }

    $base = Join-Path $dataRoot 'browser'
    $extensionDestination = Join-Path $base 'extension'
    $hostName = 'com.opencode.browser_automation'
    $wrapper = Join-Path $base 'host-wrapper.cmd'
    $nativeManifest = Join-Path $base "$hostName.json"
    $configDir = Join-Path $dataRoot 'config'
    $configPath = Join-Path $configDir 'opencode.json'
    $buildPromptPath = Join-Path $configDir 'build-prompt.txt'
    New-Item -ItemType Directory -Force -Path $base, $extensionDestination, $configDir | Out-Null

    Copy-Item -Recurse -Force (Join-Path $packageRoot 'extension\*') $extensionDestination
    $brokerSource = Join-Path $packageRoot 'bin\broker.cjs'
    $hostSource = Join-Path $packageRoot 'bin\native-host.cjs'
    foreach ($requiredFile in @($brokerSource, $hostSource)) {
        if (-not (Test-Path -LiteralPath $requiredFile -PathType Leaf)) {
            throw "GETOC2: required browser plugin file is missing: $requiredFile"
        }
    }
    Copy-Item -Force $brokerSource (Join-Path $base 'broker.cjs')
    Copy-Item -Force $hostSource (Join-Path $base 'native-host.cjs')
    $wrapperText = '@echo off' + [Environment]::NewLine + '"' + $nodeExe + '" "' + (Join-Path $base 'native-host.cjs') + '"' + [Environment]::NewLine
    [IO.File]::WriteAllText($wrapper, $wrapperText, [Text.Encoding]::ASCII)

    $manifestPath = Join-Path $packageRoot 'extension\manifest.json'
    $manifestObject = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
    if ([string]::IsNullOrWhiteSpace($manifestObject.key)) {
        throw 'GETOC2: browser extension manifest.key is missing.'
    }
    $keyBytes = [Convert]::FromBase64String(($manifestObject.key -replace '\s', ''))
    $hash = [Security.Cryptography.SHA256]::Create().ComputeHash($keyBytes)[0..15]
    $extensionId = ($hash | ForEach-Object {
        $high = [int]($_ -shr 4)
        $low = [int]($_ -band 15)
        ([char]([int](97 + $high))).ToString() + ([char]([int](97 + $low))).ToString()
    }) -join ''
    $nativeManifestObject = [pscustomobject]@{
        name = $hostName
        description = 'OpenCode Browser native messaging host'
        path = $wrapper
        type = 'stdio'
        allowed_origins = @("chrome-extension://$extensionId/")
    }
    $nativeManifestJson = $nativeManifestObject | ConvertTo-Json -Depth 5
    [IO.File]::WriteAllText($nativeManifest, $nativeManifestJson, [Text.Encoding]::ASCII)

    $regExe = Join-Path $env:SystemRoot 'System32\reg.exe'
    foreach ($registryRoot in @(
        'HKCU\Software\Google\Chrome\NativeMessagingHosts',
        'HKCU\Software\Chromium\NativeMessagingHosts',
        'HKCU\Software\BraveSoftware\Brave-Browser\NativeMessagingHosts',
        'HKCU\Software\Microsoft\Edge\NativeMessagingHosts'
    )) {
        & $regExe add "$registryRoot\$hostName" /ve /t REG_SZ /d $nativeManifest /f | Out-Null
        if ($LASTEXITCODE -ne 0) {
            throw "GETOC2: failed to register native messaging host under $registryRoot."
        }
    }

    function Test-OcProperty {
        param([object]$Object, [string]$Name)
        return ($null -ne $Object -and $null -ne $Object.PSObject -and $null -ne $Object.PSObject.Properties[$Name])
    }

    $config = if (Test-Path -LiteralPath $configPath -PathType Leaf) {
        try { Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json } catch { [pscustomobject]@{} }
    }
    else {
        [pscustomobject]@{}
    }
    if ($null -eq $config -or $config -isnot [psobject]) {
        $config = [pscustomobject]@{}
    }
    if (-not (Test-OcProperty -Object $config -Name '$schema')) {
        $config | Add-Member -NotePropertyName '$schema' -NotePropertyValue 'https://opencode.ai/config.json' -Force
    }
    $plugins = @()
    if (Test-OcProperty -Object $config -Name 'plugin') {
        if ($config.plugin -is [Array]) {
            $plugins = @($config.plugin)
        }
        elseif ($null -ne $config.plugin -and [string]$config.plugin -ne '') {
            $plugins = @([string]$config.plugin)
        }
    }
    if ($plugins -notcontains $packageName) {
        $plugins += $packageName
    }
    if (Test-OcProperty -Object $config -Name 'plugin') {
        $config.plugin = $plugins
    }
    else {
        $config | Add-Member -NotePropertyName plugin -NotePropertyValue $plugins -Force
    }
    $configJson = $config | ConvertTo-Json -Depth 10
    [IO.File]::WriteAllText($configPath, $configJson, (New-Object Text.UTF8Encoding($false)))

    if (-not (Test-Path -LiteralPath $buildPromptPath -PathType Leaf)) {
        $prompt = @'
# Build Agent Rules

You are the build agent. Turn requests into real, working, verified code.

1. Test every file you create or modify.
2. Report the full path of every file changed.
3. Do not leave broken or half-finished work.
4. Keep Windows PowerShell 5.1 compatibility.
'@
        [IO.File]::WriteAllText($buildPromptPath, $prompt, (New-Object Text.UTF8Encoding($false)))
    }

    Write-Output 'GETOC2_OK'
    Write-Output "GETOC2_DONE: OpenCode and browser plugin installed in F: (bin=$npmPrefix data=$dataRoot)"
}
finally {
    foreach ($name in $processEnvironmentNames) {
        [Environment]::SetEnvironmentVariable($name, $oldProcessEnvironment[$name], 'Process')
    }
}
}

function clu {
[CmdletBinding()]
param(
    [switch]$Json,
    [switch]$Quiet,
    [switch]$Refresh
)

$scriptPath = 'F:\backup\windowsapps\installed\ToolRuntime\clu\clu.ps1'
if (-not (Test-Path -LiteralPath $scriptPath -PathType Leaf)) {
    throw "Codex clu runtime missing on F: $scriptPath"
}

& $scriptPath -Json:$Json -Quiet:$Quiet -Refresh:$Refresh
}
